#[derive(Debug, Parser, PartialEq, Eq)]
#[command(
    name = "cokacmux",
    version,
    about = "TUI session browser for local coding agents",
    long_about = "cokacmux - TUI session browser for local coding agents",
    after_long_help = CLI_AFTER_LONG_HELP
)]
struct CokacmuxCli {
    /// Enable debug logs.
    #[arg(long, global = true)]
    debug: bool,

    /// Enable high-volume trace logs.
    #[arg(long, global = true)]
    trace: bool,

    /// Headless sanity check without entering the TUI.
    #[arg(long)]
    check: bool,

    #[command(subcommand)]
    command: Option<CliCommand>,
}

#[derive(Debug, Clone, PartialEq, Eq, Subcommand)]
enum CliCommand {
    /// Start a managed terminal command in the background.
    Start {
        /// Stable label shown in the live terminal list.
        name: String,

        /// Working directory for the command.
        #[arg(long, value_name = "PATH", default_value = ".")]
        cwd: PathBuf,

        /// Command and arguments to run. Put these after `--`.
        #[arg(value_name = "COMMAND", required = true, num_args = 1.., last = true)]
        command: Vec<String>,
    },

    /// Terminate cokacmux processes and remove ~/.cokacmux/{agents,debug}.
    Killall,

    /// Terminate cokacmux processes and remove ~/.cokacmux.
    Reset,

    /// Manage cokacmux agent processes.
    Agents {
        #[command(subcommand)]
        command: AgentsCliCommand,
    },
}

#[derive(Debug, Clone, PartialEq, Eq, Subcommand)]
enum AgentsCliCommand {
    /// Terminate cokacmux agent processes and remove runtime/debug files.
    Killall,
}

/// Poll a concrete start-lock file while another live cokacmux client is
/// starting the same daemon. A live owner is never evicted merely because the
/// wait elapsed, but callers receive a bounded error instead of hanging a
/// worker forever.
const AGENT_DAEMON_START_LOCK_POLL_MS: u64 = 50;
const AGENT_DAEMON_START_LOCK_WAIT_TIMEOUT_MS: u64 = 30_000;
const AGENT_DAEMON_START_TIMEOUT_MS: u64 = 3_000;
const AGENT_ATTACH_WRITE_TIMEOUT_MS: u64 = 3_000;
/// Bound the second half of the attach handshake. A timeout only abandons
/// this client connection; it is never evidence that the daemon or its PTY
/// child died.
const AGENT_ATTACH_ACK_TIMEOUT_MS: u64 = 3_000;
/// Bound a discovery identity query to a live daemon socket. This is an I/O
/// timeout for non-responsive or older daemons, not a startup race delay: a
/// timeout preserves the runtime files instead of declaring the process dead.
const AGENT_IDENTITY_QUERY_TIMEOUT_MS: u64 = 1_000;
/// Accepted daemon connections wait this long for an attach request before
/// being dropped. Liveness probes connect and close without attaching.
const DAEMON_PENDING_ATTACH_TIMEOUT_MS: u64 = 3_000;
/// Upper bound on connections waiting for their attach request; beyond this
/// the oldest pending connection is evicted.
const DAEMON_PENDING_CONNS_MAX: usize = 8;
/// An unauthenticated peer must not make the daemon allocate without bound
/// before it supplies a newline and reaches token validation.
const DAEMON_REQUEST_FRAME_MAX_BYTES: usize = 2 * 1024 * 1024;
/// A continuously writing peer must yield the daemon output/PTY loop after a
/// bounded amount of socket work in one iteration.
const DAEMON_REQUEST_READ_BUDGET_BYTES: usize = 64 * 1024;
/// `Vec<u8>` uses a JSON number array on the wire, whose worst-case expansion
/// is roughly four bytes per input byte. Keep chunks comfortably below the
/// authenticated request-frame cap while preserving FIFO byte order.
const AGENT_INPUT_REQUEST_CHUNK_BYTES: usize = 256 * 1024;
/// New daemons acknowledge input only after the PTY writer completes
/// write_all + flush. Keep an independent client-side copy until that
/// acknowledgement so a stalled or failed PTY write cannot silently discard
/// already-reported input.
/// This covers the daemon's 4 MiB worker queue plus 4 MiB pending FIFO while
/// keeping paste preflight and memory use bounded.
const AGENT_CLIENT_UNACKNOWLEDGED_INPUT_MAX_BYTES: usize = 8 * 1024 * 1024;
const AGENT_CLIENT_UNACKNOWLEDGED_INPUT_MAX_FRAMES: usize = 4_096;
const AGENT_GLOBAL_UNACKNOWLEDGED_INPUT_MAX_BYTES: usize = 32 * 1024 * 1024;
const AGENT_GLOBAL_UNACKNOWLEDGED_INPUT_MAX_FRAMES: usize = 16_384;
/// Terminal input produced while the focused process is changing owners cannot
/// be sent to the still-visible old client. Retain it until the requested
/// target is active, with the same per-client bounds used by the
/// acknowledged-input recovery queue.
const DEFERRED_AGENT_INPUT_MAX_BYTES: usize = AGENT_CLIENT_UNACKNOWLEDGED_INPUT_MAX_BYTES;
const DEFERRED_AGENT_INPUT_MAX_EVENTS: usize = AGENT_CLIENT_UNACKNOWLEDGED_INPUT_MAX_FRAMES;
const DEFERRED_AGENT_KEY_ACCOUNTED_BYTES: usize = 16;
const DAEMON_INPUT_DEDUPE_CLIENTS_MAX: usize = 32;
/// The PTY master may block forever when a child stops reading stdin. Keep
/// writes on one FIFO worker and bound queued input to roughly 4 MiB.
const DAEMON_PTY_INPUT_QUEUE_MAX_JOBS: usize = 16;
const DAEMON_PTY_INPUT_PENDING_MAX_BYTES: usize = 4 * 1024 * 1024;
const AGENT_RUNTIME_SMALL_FILE_MAX_BYTES: usize = 1_024;
/// Metadata is intentionally small JSON, but it contains user-controlled
/// cwd/command strings. Bound reads so a corrupted runtime entry cannot make
/// discovery or cleanup allocate without limit.
const AGENT_RUNTIME_META_MAX_BYTES: usize = 256 * 1024;
const AGENT_AUXILIARY_REGISTRY_MAX_BYTES: usize = 1024 * 1024;
/// Queue depth for the per-daemon disk writer thread (pty log appends +
/// meta snapshots). At the 8KB PTY read size this absorbs roughly 4MB of
/// output before jobs start being dropped, which covers tens of seconds of
/// disk stall without ever blocking the output pump.
const DAEMON_DISK_QUEUE_MAX_JOBS: usize = 512;
/// Retry a failed lifecycle-critical metadata publication on the dedicated
/// disk writer without blocking the daemon output pump. Readiness is driven by
/// a successful write acknowledgement, never by this interval.
const DAEMON_STARTUP_META_RETRY_MS: u64 = 500;
/// Bound PTY reader buffering to roughly 1 MiB (128 × 8 KiB reads). When the
/// daemon loop falls behind, blocking this dedicated reader naturally applies
/// terminal backpressure instead of growing memory without limit.
const AGENT_PTY_OUTPUT_QUEUE_MAX_CHUNKS: usize = 128;
/// Give up writing to a peer socket after this long without progress. A
/// healthy peer drains within milliseconds; one that stays full this long is
/// gone or wedged, and blocking the pump on it would freeze the agent pane.
const AGENT_STREAM_WRITE_STALL_TIMEOUT_MS: u64 = 10_000;
/// Upper bound on the daemon→client outbound queue (serialized event
/// bytes). A client that lets this much pile up has its queued output
/// frames discarded — with accounting — and is resynced from the live
/// screen snapshot once it drains; the daemon loop itself never sleeps on
/// a slow peer. Control frames (attach handshake, exit notices, snapshots)
/// are never discarded.
const DAEMON_CLIENT_OUTBOUND_DISCARD_BYTES: usize = 512 * 1024;
/// After a discard, the resync snapshot is queued once the outbound queue
/// has drained below this, so it reaches the client promptly instead of
/// behind a long backlog.
const DAEMON_CLIENT_OUTBOUND_RESYNC_BYTES: usize = 16 * 1024;
/// Control frames cannot be discarded without violating acknowledgements or
/// exit ordering. Drop the connection once one full maximum-sized frame plus
/// one in-flight replacement can no longer fit in a fixed memory budget.
const DAEMON_CLIENT_OUTBOUND_HARD_BYTES: usize = 2 * AGENT_CLIENT_FRAME_MAX_BYTES;
/// After waitpid reports the child dead, wait for the dedicated PTY reader to
/// observe EOF and drain every queued chunk. The timeout is only a bound for a
/// broken platform reader; ordinary completion is driven by channel closure.
const DAEMON_FINAL_OUTPUT_DRAIN_TIMEOUT_MS: u64 = 2_000;
/// On child exit the daemon flushes the queued exit notice for at most
/// this long before cleaning up its runtime files; a peer that cannot
/// drain by then learns of the exit from the socket EOF instead.
const DAEMON_EXIT_FLUSH_TIMEOUT_MS: u64 = 2_000;
/// A filesystem write can remain blocked well after the managed child has
/// exited.  The daemon must not become a permanent, live-looking ghost while
/// joining its disk writer.  On expiry we preserve runtime files and let
/// process exit stop the writer; the next definitive-death sweep removes the
/// stale files.
const DAEMON_DISK_SHUTDOWN_TIMEOUT_MS: u64 = 1_000;
/// Exact runtime cleanup runs off the daemon loop because a stalled
/// filesystem must not keep a childless, live-looking daemon around forever.
const DAEMON_RUNTIME_CLEANUP_TIMEOUT_MS: u64 = 1_000;
/// Runtime repair must never remain permanently pending after a filesystem or
/// endpoint operation stalls. One replacement may run alongside one abandoned
/// observation; late results still release capacity and can be applied.
const DAEMON_RUNTIME_REPAIR_WATCHDOG_TIMEOUT_MS: u64 = 60_000;
const DAEMON_RUNTIME_REPAIR_MAX_OUTSTANDING: usize = 2;
#[cfg(windows)]
const WINDOWS_PROCESS_IDENTITY_TIMEOUT_MS: u64 = 2_000;
#[cfg(all(unix, not(target_os = "linux")))]
const PROCESS_PROBE_COMMAND_TIMEOUT_MS: u64 = 2_000;
const PROGRAM_RESOLVE_COMMAND_TIMEOUT_MS: u64 = 5_000;
const COKACDIR_DOWNLOAD_TIMEOUT_MS: u64 = 120_000;
const COKACDIR_VERSION_TIMEOUT_MS: u64 = 10_000;
/// Bounded cleanup for short-lived owned helper processes and setup-failure
/// regression tests. PTY setup itself now completes before the child starts.
const AGENT_SETUP_FAILURE_CLEANUP_TIMEOUT_MS: u64 = 1_000;
const AGENT_SETUP_FAILURE_CLEANUP_POLL_MS: u64 = 10;
/// Bound explicit user-requested termination: Unix uses this grace period
/// before escalating from SIGTERM to SIGKILL, while Windows uses it to confirm
/// exit after `TerminateProcess`. It is never used to infer ordinary liveness.
const PROCESS_TERMINATE_GRACE_MS: u64 = 1_000;
#[cfg(unix)]
const PROCESS_TERMINATE_POLL_MS: u64 = 10;
#[cfg(windows)]
const WINDOWS_PROCESS_GROUP_TERMINATE_TIMEOUT_MS: u64 = 2_000;
const AGENT_STATE_POLL_INTERVAL_MS: u64 = 500;
const UI_ANIMATION_TICK_MS: u64 = STARTUP_SPINNER_TICK_MS as u64;
const AGENT_EXIT_REQUEST_OVERLAY_TIMEOUT_MS: u64 = 15_000;
const AGENT_EXIT_INPUT_LINE_LIMIT: usize = 256;
const LIVE_SHELL_DISCOVERY_INTERVAL_MS: u64 = 10_000;
const LIVE_SHELL_DISCOVERY_SLOW_LOG_MS: u64 = 2_000;
const LIVE_SHELL_DISCOVERY_SLOW_LOG_INTERVAL_MS: u64 = 10_000;
/// A blocked filesystem/process probe must not leave either background
/// refresh permanently pending.  Keep this above the 30-second low-spec
/// stall design point so recovery does not multiply work during an ordinary
/// slow disk episode.  Expiry preserves all cached runtime state and merely
/// permits a fresh observation attempt.
const BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS: u64 = 60_000;
/// At most one replacement may run alongside one abandoned observation of
/// the same kind. If both are stuck, cached state remains available but no
/// third thread is created until a late result/failure proves that one of the
/// earlier threads returned and releases capacity.
const BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND: usize = 2;
/// If the OS cannot create a replacement runtime worker, retry slowly instead
/// of attempting a thread spawn on every 500ms housekeeping tick.
const RUNTIME_WORKER_RESTART_RETRY_MS: u64 = 10_000;
const PENDING_RUNTIME_ACTION_SLOW_LOG_MS: u64 = 2_000;
const PENDING_RUNTIME_ACTION_SLOW_LOG_INTERVAL_MS: u64 = 10_000;
const AGENT_BUSY_GRACE_MS: u64 = 3_000;
const AGENT_ACTIVITY_META_WRITE_INTERVAL_MS: u64 = 750;
const NEW_AGENT_BACKING_PROBE_INTERVAL_MS: u64 = 5_000;
const MAIN_EVENT_DRAIN_LIMIT: usize = 64;
const MAIN_EVENT_DRAIN_BUDGET_MS: u64 = 8;
const AGENT_CLIENT_OUTPUT_DRAIN_BYTES: usize = 16 * 1024;
/// Stop the socket reader around 2 MiB of queued terminal bytes. This lets
/// kernel socket backpressure reach the daemon, whose outbound queue already
/// has discard-and-snapshot resynchronization semantics.
const AGENT_CLIENT_OUTPUT_BUFFER_MAX_BYTES: usize = 2 * 1024 * 1024;
const AGENT_CLIENT_FRAME_MAX_BYTES: usize = 16 * 1024 * 1024;
const BRACKETED_PASTE_INPUT_START: &[u8] = b"\x1b[200~";
const BRACKETED_PASTE_INPUT_END: &[u8] = b"\x1b[201~";
const BRACKETED_PASTE_MODE_PARAM: u32 = 2004;
const BRACKETED_PASTE_MODE_SCAN_TAIL_BYTES: usize = 128;
const PERF_LOG_THRESHOLD_MS: u128 = 50;
const UI_STALL_LOG_THRESHOLD_MS: u64 = 2_000;
const UI_STALL_LOG_COOLDOWN_MS: u64 = 2_000;
/// How often the keybindings watcher thread checks the file's mtime. The
/// check used to run on the UI thread on every keystroke, which froze the
