#[derive(Debug, Clone, Default)]
struct SessionList(Arc<Vec<SessionInfo>>);

impl SessionList {
    fn snapshot(&self) -> Arc<Vec<SessionInfo>> {
        Arc::clone(&self.0)
    }

    #[cfg(test)]
    fn push(&mut self, info: SessionInfo) {
        Arc::get_mut(&mut self.0)
            .expect("tests must not mutate a shared session snapshot")
            .push(info);
    }

    #[cfg(test)]
    fn reverse(&mut self) {
        Arc::get_mut(&mut self.0)
            .expect("tests must not mutate a shared session snapshot")
            .reverse();
    }
}

#[derive(Debug, Clone)]
struct ScopedSessionSnapshot {
    all: Arc<Vec<SessionInfo>>,
    scope: SessionScope,
    total: usize,
}

impl ScopedSessionSnapshot {
    fn capture(sessions: &SessionList, scope: SessionScope) -> Self {
        let all = sessions.snapshot();
        let total = all.iter().filter(|info| scope.includes(info)).count();
        Self { all, scope, total }
    }

    fn cloned_sessions(&self) -> Vec<SessionInfo> {
        self.all
            .iter()
            .filter(|info| self.scope.includes(info))
            .cloned()
            .collect()
    }
}

impl From<Vec<SessionInfo>> for SessionList {
    fn from(sessions: Vec<SessionInfo>) -> Self {
        Self(Arc::new(sessions))
    }
}

impl std::ops::Deref for SessionList {
    type Target = Vec<SessionInfo>;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

