fn load_persisted_agent_auxiliaries() -> HashMap<AgentKey, PersistedAgentAuxiliaryEntry> {
    let Some(path) = agent_auxiliary_registry_path() else {
        debug_log(
            "agent_auxiliary_registry_load_skipped",
            serde_json::json!({ "reason": "config_dir_unavailable" }),
        );
        return HashMap::new();
    };
    let content = match read_runtime_text_bounded(&path, AGENT_AUXILIARY_REGISTRY_MAX_BYTES) {
        Ok(content) => content,
        Err(e) if e.kind() == ErrorKind::NotFound => return HashMap::new(),
        Err(e) => {
            debug_log(
                "agent_auxiliary_registry_load_failed",
                serde_json::json!({
                    "path": path.display().to_string(),
                    "error": e.to_string(),
                }),
            );
            return HashMap::new();
        }
    };
    let registry = match serde_json::from_str::<PersistedAgentAuxiliaryRegistry>(&content) {
        Ok(registry) => registry,
        Err(e) => {
            debug_log(
                "agent_auxiliary_registry_parse_failed",
                serde_json::json!({
                    "path": path.display().to_string(),
                    "error": e.to_string(),
                    "content_sample": truncate_width(&content, 512),
                }),
            );
            return HashMap::new();
        }
    };
    let mut entries = HashMap::new();
    for entry in registry.entries {
        entries.insert(entry.agent.clone(), entry);
    }
    debug_log(
        "agent_auxiliary_registry_loaded",
        serde_json::json!({
            "path": path.display().to_string(),
            "version": registry.version,
            "entries": persisted_agent_auxiliary_entries_debug_value(&entries),
        }),
    );
    entries
}

fn save_persisted_agent_auxiliaries(
    entries: &HashMap<AgentKey, PersistedAgentAuxiliaryEntry>,
) -> io::Result<()> {
    let Some(path) = agent_auxiliary_registry_path() else {
        return Ok(());
    };
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
        #[cfg(unix)]
        fs::set_permissions(parent, fs::Permissions::from_mode(0o700))?;
    }
    if entries.is_empty() {
        match fs::remove_file(&path) {
            Ok(()) => {}
            Err(e) if e.kind() == ErrorKind::NotFound => {}
            Err(e) => return Err(e),
        }
        return Ok(());
    }
    let mut sorted = entries.values().cloned().collect::<Vec<_>>();
    sorted.sort_by(|left, right| {
        (left.agent.provider.as_str(), left.agent.session_id.as_str()).cmp(&(
            right.agent.provider.as_str(),
            right.agent.session_id.as_str(),
        ))
    });
    let registry = PersistedAgentAuxiliaryRegistry {
        version: 1,
        entries: sorted,
    };
    let content = serde_json::to_string_pretty(&registry)
        .map_err(|e| io::Error::new(ErrorKind::InvalidData, e))?;
    let tmp_path = path.with_extension("json.tmp");
    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == ErrorKind::NotFound => {}
        Err(error) => return Err(error),
    }
    if let Err(error) = write_private_runtime_file_new(&tmp_path, content.as_bytes()) {
        let _ = fs::remove_file(&tmp_path);
        return Err(error);
    }
    if let Err(error) = replace_runtime_file_atomically(&tmp_path, &path) {
        let _ = fs::remove_file(&tmp_path);
        return Err(error);
    }
    Ok(())
}

#[derive(Clone)]
struct PersistedAgentAuxiliaryRegistryWriter {
    wake_tx: SyncSender<()>,
    pending: Arc<Mutex<Option<PersistedAgentAuxiliaryRegistryWrite>>>,
    next_seq: Arc<AtomicU64>,
    processed_seq: Arc<AtomicU64>,
    saved_seq: Arc<AtomicU64>,
}

struct PersistedAgentAuxiliaryRegistryWrite {
    seq: u64,
    entries: HashMap<AgentKey, PersistedAgentAuxiliaryEntry>,
    reason: &'static str,
}

fn run_persisted_agent_auxiliary_registry_writer(
    wake_rx: Receiver<()>,
    pending: Arc<Mutex<Option<PersistedAgentAuxiliaryRegistryWrite>>>,
    processed_seq: Arc<AtomicU64>,
    saved_seq: Arc<AtomicU64>,
) {
    loop {
        let job = pending.lock().ok().and_then(|mut pending| pending.take());
        if let Some(job) = job {
            let result = save_persisted_agent_auxiliaries(&job.entries);
            match result {
                Ok(()) => {
                    saved_seq.fetch_max(job.seq, Ordering::Release);
                    debug_log(
                        "agent_auxiliary_registry_saved",
                        serde_json::json!({
                            "seq": job.seq,
                            "reason": job.reason,
                            "entries": persisted_agent_auxiliary_entries_debug_value(&job.entries),
                        }),
                    );
                }
                Err(error) => debug_log(
                    "agent_auxiliary_registry_save_failed",
                    serde_json::json!({
                        "reason": job.reason,
                        "seq": job.seq,
                        "error": error.to_string(),
                        "entries": persisted_agent_auxiliary_entries_debug_value(&job.entries),
                    }),
                ),
            }
            processed_seq.fetch_max(job.seq, Ordering::Release);
            continue;
        }
        if wake_rx.recv().is_err() {
            return;
        }
    }
}

fn persisted_agent_auxiliary_registry_writer(
) -> io::Result<&'static PersistedAgentAuxiliaryRegistryWriter> {
    static WRITER: OnceLock<io::Result<PersistedAgentAuxiliaryRegistryWriter>> = OnceLock::new();
    WRITER
        .get_or_init(|| {
            let (wake_tx, wake_rx) = mpsc::sync_channel(1);
            let pending = Arc::new(Mutex::new(None));
            let worker_pending = Arc::clone(&pending);
            let next_seq = Arc::new(AtomicU64::new(0));
            let processed_seq = Arc::new(AtomicU64::new(0));
            let saved_seq = Arc::new(AtomicU64::new(0));
            let worker_processed_seq = Arc::clone(&processed_seq);
            let worker_saved_seq = Arc::clone(&saved_seq);
            thread::Builder::new()
                .name("cokacmux-agent-aux-registry-writer".to_string())
                .spawn(move || {
                    run_persisted_agent_auxiliary_registry_writer(
                        wake_rx,
                        worker_pending,
                        worker_processed_seq,
                        worker_saved_seq,
                    )
                })?;
            Ok(PersistedAgentAuxiliaryRegistryWriter {
                wake_tx,
                pending,
                next_seq,
                processed_seq,
                saved_seq,
            })
        })
        .as_ref()
        .map_err(|error| io::Error::new(error.kind(), error.to_string()))
}

fn queue_persisted_agent_auxiliary_registry_save(
    entries: &HashMap<AgentKey, PersistedAgentAuxiliaryEntry>,
    reason: &'static str,
) -> io::Result<bool> {
    let writer = persisted_agent_auxiliary_registry_writer()?;
    let seq = writer.next_seq.fetch_add(1, Ordering::AcqRel) + 1;
    let coalesced = writer
        .pending
        .lock()
        .map_err(|_| io::Error::other("agent auxiliary registry pending lock was poisoned"))?
        .replace(PersistedAgentAuxiliaryRegistryWrite {
            seq,
            entries: entries.clone(),
            reason,
        })
        .is_some();
    match writer.wake_tx.try_send(()) {
        Ok(()) | Err(mpsc::TrySendError::Full(())) => Ok(coalesced),
        Err(mpsc::TrySendError::Disconnected(())) => {
            if let Ok(mut pending) = writer.pending.lock() {
                pending.take();
            }
            Err(io::Error::new(
                ErrorKind::BrokenPipe,
                "agent auxiliary registry writer disconnected",
            ))
        }
    }
}

fn flush_persisted_agent_auxiliary_registry_writer(timeout: Duration) -> bool {
    let Ok(writer) = persisted_agent_auxiliary_registry_writer() else {
        return false;
    };
    let target_seq = writer.next_seq.load(Ordering::Acquire);
    if target_seq == 0 {
        return true;
    }
    let deadline = Instant::now() + timeout;
    loop {
        let processed = writer.processed_seq.load(Ordering::Acquire);
        if processed >= target_seq {
            return writer.saved_seq.load(Ordering::Acquire) >= target_seq;
        }
        let now = Instant::now();
        if now >= deadline {
            return false;
        }
        thread::sleep(
            deadline
                .saturating_duration_since(now)
                .min(Duration::from_millis(10)),
        );
    }
}

