/// Run one attach job to completion. Everything here may block on the
/// filesystem or on process spawn, which is exactly why it runs on a worker
/// thread instead of the UI thread.
#[allow(clippy::too_many_arguments)]
fn run_attach_job(
    info: SessionInfo,
    cols: u16,
    rows: u16,
    kind: AttachJobKind,
    run_prechecks: bool,
    prompt_for_saved_data: bool,
    settings: Settings,
    main_tx: Sender<MainEvent>,
    reader_id: u64,
) -> AttachWorkOutcome {
    let started_at = Instant::now();
    let key = AgentKey::new(&info);
    let debug_info = info.clone();
    debug_log(
        "attach_worker_job_start",
        serde_json::json!({
            "reader_id": reader_id,
            "info": session_info_debug_value(&info),
            "key": agent_key_debug_value(&key),
            "cols": cols,
            "rows": rows,
            "kind": attach_job_kind_debug_value(kind),
            "run_prechecks": run_prechecks,
            "prompt_for_saved_data": prompt_for_saved_data,
        }),
    );
    if run_prechecks {
        let launch_mode = match kind {
            AttachJobKind::OrStart { launch_mode } => launch_mode,
            AttachJobKind::Existing => AgentLaunchMode::Normal,
        };
        if live_agent_meta_snapshot(&key).is_none() {
            if prompt_for_saved_data {
                match session::data::snapshot_for_session(&info) {
                    Ok(Some(snapshot)) => {
                        let outcome = AttachWorkOutcome::NeedsRestorePrompt {
                            snapshot,
                            launch_mode,
                        };
                        debug_log_attach_worker_job_done(
                            &info,
                            &key,
                            cols,
                            rows,
                            kind,
                            run_prechecks,
                            prompt_for_saved_data,
                            reader_id,
                            started_at,
                            &outcome,
                        );
                        return outcome;
                    }
                    Ok(None) => {}
                    Err(e) => {
                        debug_log(
                            "attach_data_restore_check_failed",
                            serde_json::json!({
                                "provider": key.provider.as_str(),
                                "session_id": &key.session_id,
                                "error": e.to_string(),
                            }),
                        );
                    }
                }
            }
            match missing_session_launch_cwd(&info) {
                Ok(Some(path)) => {
                    let outcome = AttachWorkOutcome::NeedsCreateCwd { path, launch_mode };
                    debug_log_attach_worker_job_done(
                        &info,
                        &key,
                        cols,
                        rows,
                        kind,
                        run_prechecks,
                        prompt_for_saved_data,
                        reader_id,
                        started_at,
                        &outcome,
                    );
                    return outcome;
                }
                Ok(None) => {}
                Err(e) => {
                    debug_log(
                        "attach_launch_cwd_invalid",
                        serde_json::json!({
                            "provider": key.provider.as_str(),
                            "session_id": &key.session_id,
                            "cwd": &info.cwd,
                            "error": e.to_string(),
                        }),
                    );
                    let outcome = AttachWorkOutcome::Failed {
                        stage: AttachFailStage::CwdCheck,
                        message: e.to_string(),
                        error_kind: None,
                    };
                    debug_log_attach_worker_job_done(
                        &info,
                        &key,
                        cols,
                        rows,
                        kind,
                        run_prechecks,
                        prompt_for_saved_data,
                        reader_id,
                        started_at,
                        &outcome,
                    );
                    return outcome;
                }
            }
        }
        if let Err(e) = prepare_agent_session(&info, &settings) {
            debug_log(
                "attach_prepare_failed",
                serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                    "error": e.to_string(),
                }),
            );
            let outcome = AttachWorkOutcome::Failed {
                stage: AttachFailStage::Prepare,
                message: e.to_string(),
                error_kind: None,
            };
            debug_log_attach_worker_job_done(
                &info,
                &key,
                cols,
                rows,
                kind,
                run_prechecks,
                prompt_for_saved_data,
                reader_id,
                started_at,
                &outcome,
            );
            return outcome;
        }
    }
    let attach_result = match kind {
        AttachJobKind::OrStart { launch_mode } => {
            AgentClient::attach_or_start(info, cols, rows, main_tx, reader_id, launch_mode)
        }
        AttachJobKind::Existing => {
            AgentClient::attach_existing(info, cols, rows, main_tx, reader_id)
                .map(|agent| (agent, false))
        }
    };
    let outcome = match attach_result {
        Ok((agent, started)) => AttachWorkOutcome::Attached { agent, started },
        Err(e) => AttachWorkOutcome::Failed {
            stage: AttachFailStage::Attach,
            error_kind: e
                .downcast_ref::<io::Error>()
                .map(|io_error| io_error.kind()),
            message: e.to_string(),
        },
    };
    debug_log_attach_worker_job_done(
        &debug_info,
        &key,
        cols,
        rows,
        kind,
        run_prechecks,
        prompt_for_saved_data,
        reader_id,
        started_at,
        &outcome,
    );
    outcome
}

// Keep the attach completion log aligned one-to-one with the worker inputs.
#[allow(clippy::too_many_arguments)]
fn debug_log_attach_worker_job_done(
    info: &SessionInfo,
    key: &AgentKey,
    cols: u16,
    rows: u16,
    kind: AttachJobKind,
    run_prechecks: bool,
    prompt_for_saved_data: bool,
    reader_id: u64,
    started_at: Instant,
    outcome: &AttachWorkOutcome,
) {
    debug_log(
        "attach_worker_job_done",
        serde_json::json!({
            "reader_id": reader_id,
            "info": session_info_debug_value(info),
            "key": agent_key_debug_value(key),
            "cols": cols,
            "rows": rows,
            "kind": attach_job_kind_debug_value(kind),
            "run_prechecks": run_prechecks,
            "prompt_for_saved_data": prompt_for_saved_data,
            "elapsed_ms": started_at.elapsed().as_millis(),
            "outcome": attach_work_outcome_debug_value(outcome),
        }),
    );
}

#[cfg(test)]
fn should_remove_dead_live_shell_after_notfound<F>(
    key: &AgentKey,
    mut live_meta_snapshot: F,
) -> bool
where
    F: FnMut(&AgentKey) -> Option<AgentMetaSnapshot>,
{
    live_meta_snapshot(key).is_none()
}

struct VerifiedMissingLiveShell {
    info: SessionInfo,
    state: AgentListState,
    meta: AgentMetaSnapshot,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentMetaLivenessKind {
    Verified,
    Possible,
}

impl AgentMetaLivenessKind {
    fn label(self) -> &'static str {
        match self {
            AgentMetaLivenessKind::Verified => "verified",
            AgentMetaLivenessKind::Possible => "possible",
        }
    }
}

fn agent_meta_info_and_state_for_key(
    key: &AgentKey,
    fallback_info: Option<&SessionInfo>,
    meta: &AgentMetaSnapshot,
    current_pid: u32,
    current_client_instance_id: Option<&str>,
    now_epoch_ms: u64,
) -> Option<(SessionInfo, AgentListState)> {
    if agent_key_from_meta(meta).as_ref() != Some(key) {
        return None;
    }
    let info = session_info_from_agent_meta_snapshot(meta)
        .filter(|info| AgentKey::new(info) == *key)
        .or_else(|| {
            fallback_info
                .cloned()
                .filter(|info| AgentKey::new(info) == *key)
        })?;
    let state =
        meta.list_state_with_client_identity(current_pid, current_client_instance_id, now_epoch_ms);
    Some((info, state))
}

fn verified_missing_live_shell_from_meta<F>(
    key: &AgentKey,
    fallback_info: &SessionInfo,
    current_pid: u32,
    current_client_instance_id: Option<&str>,
    now_epoch_ms: u64,
    live_meta_snapshot: &mut F,
) -> Option<VerifiedMissingLiveShell>
where
    F: FnMut(&AgentKey) -> Option<AgentMetaSnapshot>,
{
    let meta = live_meta_snapshot(key)?;
    let (info, state) = agent_meta_info_and_state_for_key(
        key,
        Some(fallback_info),
        &meta,
        current_pid,
        current_client_instance_id,
        now_epoch_ms,
    )?;
    Some(VerifiedMissingLiveShell { info, state, meta })
}

fn run_new_session_prepare(
    seq: u64,
    kind: NewSessionKind,
    raw_cwd: String,
    provider: Provider,
    launch_mode: AgentLaunchMode,
    cols: u16,
    rows: u16,
) -> NewSessionPrepareResult {
    let started = Instant::now();
    debug_log(
        "new_session_prepare_worker_start",
        serde_json::json!({
            "seq": seq,
            "kind": kind.as_str(),
            "raw_cwd": &raw_cwd,
            "provider": provider.as_str(),
            "launch_mode": launch_mode.as_str(),
            "cols": cols,
            "rows": rows,
        }),
    );
    let outcome = normalize_launch_cwd(&raw_cwd);
    let result = NewSessionPrepareResult {
        seq,
        kind,
        raw_cwd,
        provider,
        launch_mode,
        cols,
        rows,
        outcome,
        queued_at_epoch_ms: current_epoch_ms(),
        elapsed_ms: started.elapsed().as_millis(),
    };
    debug_log(
        "new_session_prepare_worker_done",
        new_session_prepare_result_debug_value(&result),
    );
    result
}

