struct App {
    settings: Settings,
    keybindings: KeyBindings,
    keybindings_path: Option<PathBuf>,
    keybindings_mtime: Option<SystemTime>,
    sessions: SessionList,
    /// Live shell daemons discovered via `~/.cokacmux/agents/` meta scan.
    /// Shells are not in `sessions` (they have no on-disk storage), but they
    /// participate in the agents sidebar so the user can switch between
    /// shells and real agents with Alt+↑/↓ or Ctrl+Shift+↑/↓.
    live_shells: Vec<SessionInfo>,
    clone_links: Vec<session::clone_tree::CloneLink>,
    agent_states: HashMap<AgentKey, AgentListState>,
    new_agent_backing_aliases: HashMap<AgentKey, AgentKey>,
    new_agent_backing_probe_after: HashMap<AgentKey, Instant>,
    last_agent_state_poll: Instant,
    last_live_shell_discovery: Instant,
    list_state: ListState,
    session_view: SessionViewMode,
    // Deliberately transient: each process starts with the safe TopLevel view.
    session_scope: SessionScope,
    provider_filter: ProviderFilter,
    text_filter: String,
    text_filter_matches: HashSet<AgentKey>,
    search_seq: u64,
    search_pending: Option<SearchPending>,
    ai_search_seq: u64,
    ai_search_pending: Option<AiSearchPending>,
    ai_search_draining_seq: Option<u64>,
    ai_search_results: Option<AiSearchResults>,
    ai_title_seq: u64,
    ai_title_pending: Option<AiTitlePending>,
    data_task_seq: u64,
    data_task: Option<DataTaskPending>,
    input_mode: InputMode,
    notice_overlay: Option<NoticeDialog>,
    preview_cache: HashMap<PreviewKey, PreviewEntry>,
    preview_cache_order: VecDeque<PreviewKey>,
    preview_requested: Option<(PreviewKey, u64)>,
    preview_seq: u64,
    preview_tx: Sender<PreviewRequest>,
    preview_rx: Receiver<PreviewResult>,
    preview_mode: Mode,
    preview_scroll: u16,
    preview_page_height: u16,
    focus: FocusPane,
    agent_focus: AgentFocusPane,
    agent_focus_by_agent: HashMap<AgentKey, AgentFocusPane>,
    status: String,
    active_agent: Option<AgentClient>,
    agent_aux: Option<AgentAuxPane>,
    hidden_agent_aux: Vec<AgentAuxPane>,
    agent_aux_parent_infos: HashMap<AgentKey, SessionInfo>,
    persisted_agent_aux: HashMap<AgentKey, PersistedAgentAuxiliaryEntry>,
    persist_agent_auxiliary_registry: bool,
    agent_aux_width: Option<u16>,
    should_quit: bool,
    /// Sender installed by `run()` after the channel exists. Cloned and
    /// handed to each agent reader thread on attach so they can forward
    /// `AgentDaemonEvent`s back to the main loop.
    main_tx: Option<Sender<MainEvent>>,
    /// Runtime discovery/probing worker. The UI thread only sends small
    /// snapshot requests and applies returned results.
    runtime_tx: Option<Sender<AgentRuntimeRefreshRequest>>,
    /// Set only after a runtime worker is known to have stalled/disconnected.
    /// `None` distinguishes normal pre-run construction from a worker that
    /// should be recreated by a later housekeeping refresh.
    runtime_worker_restart_after: Option<Instant>,
    /// Requests whose worker was detached by the watchdog but has not yet
    /// reported a result/failure. This is capacity accounting only; membership
    /// never means that a daemon is dead or that runtime files may be removed.
    runtime_abandoned_worker_seqs: HashSet<u64>,
    runtime_refresh_seq: u64,
    runtime_refresh_applied_seq: u64,
    runtime_refresh_pending: bool,
    runtime_refresh_started_at: Option<Instant>,
    runtime_refresh_pending_discover_live_shells: bool,
    runtime_refresh_queued: bool,
    runtime_refresh_queued_discover_live_shells: bool,
    pending_runtime_action: Option<PendingRuntimeAction>,
    pending_runtime_action_last_slow_log_at: Option<Instant>,
    live_shell_discovery_seq: u64,
    live_shell_discovery_pending: bool,
    live_shell_discovery_started_at: Option<Instant>,
    live_shell_discovery_last_slow_log_at: Option<Instant>,
    /// Same bounded-capacity accounting as `runtime_abandoned_worker_seqs`
    /// for the one-thread-per-scan live discovery path.
    live_shell_discovery_abandoned_seqs: HashSet<u64>,
    /// Monotonic id for attach jobs; results carrying an older seq are
    /// stale and dropped.
    attach_seq: u64,
    /// The attach job currently running on the worker thread, if any.
    attach_in_flight: Option<AttachInFlight>,
    /// Attach target that owns terminal input arriving after the initiating
    /// UI command. Main switches always capture; auxiliary attaches capture
    /// only when they will receive focus on completion.
    attach_terminal_input_target: Option<(u64, DeferredAgentInputTarget)>,
    /// Newest attach request received while one was in flight (latest wins).
    queued_attach: Option<AttachJob>,
    /// Raw terminal input that reached the forwarding boundary after a
    /// focus-changing attach was requested but before its new connection
    /// became active. Each event carries the intended target so a failed or
    /// superseded attach is discarded rather than misrouted to another PTY.
    deferred_agent_input: VecDeque<DeferredAgentInput>,
    deferred_agent_input_bytes: usize,
    deferred_agent_input_rejected_events: usize,
    deferred_agent_input_rejected_bytes: usize,
    agent_kill_seq: u64,
    agent_kill_pending: Option<AgentKillPending>,
    /// Keeps the agent workspace visible after Ctrl+K removed the current
    /// client but before the next verified live agent finishes attaching.
    /// This is a UI transition only; the terminated client is never retained
    /// or treated as live.
    agent_kill_replacement: Option<AgentKillReplacement>,
    killall_seq: u64,
    killall_pending: Option<KillAllPending>,
    new_session_launch_seq: u64,
    new_session_launch: Option<NewSessionLaunchPending>,
    /// First-seen order of agents-sidebar entries. Keeps the sidebar from
    /// shuffling as sessions reorder by activity or discovery rescans the
    /// runtime dir; new agents append, departed agents free their slot.
    agent_sidebar_order: Vec<AgentKey>,
    last_ui_stall_log_at: Option<Instant>,
    ui_stall_log_count: u64,
    session_refresh_seq: u64,
    session_refresh_pending: bool,
    session_refresh_started_at: Option<Instant>,
    session_refresh_show_overlay: bool,
    session_refresh_restore_key: Option<AgentKey>,
    session_refresh_preserve_status: Option<String>,
    /// Monotonic id assigned to each agent reader thread. Used to ignore
    /// late events from a thread whose AgentClient has already been
    /// dropped/replaced.
    next_reader_id: u64,
    /// When true the sessions list is rendered even if an active agent or a
    /// Ctrl+K replacement workspace exists — i.e. the user toggled to the
    /// sessions view via Ctrl+] / Ctrl+[ while the daemon connection remains
    /// alive or is being replaced. The next Ctrl+] / Ctrl+[ flips back without
    /// starting another attach.
    show_sessions_view: bool,
}

#[derive(Debug, Clone, Copy)]
struct VisibleSessionRow<'a> {
    info: &'a SessionInfo,
    depth: usize,
}

fn sync_plain_pty_tool_info_from_live_shells(
    agent: &mut AgentClient,
    live_shells: &[SessionInfo],
    scope: &'static str,
) {
    if !is_plain_pty_tool_session_info(&agent.info) {
        return;
    }
    let key = AgentKey::new(&agent.info);
    let Some(info) = live_shells
        .iter()
        .find(|info| AgentKey::new(info) == key)
        .cloned()
    else {
        return;
    };
    if agent.info.cwd == info.cwd
        && agent.info.source == info.source
        && agent.info.updated_at_epoch_s == info.updated_at_epoch_s
        && agent.info.title == info.title
    {
        return;
    }
    if DEBUG_ENABLED.load(Ordering::Relaxed) {
        debug_log(
            "pty_tool_info_synced",
            serde_json::json!({
                "scope": scope,
                "key": agent_key_debug_value(&key),
                "before": session_info_debug_value(&agent.info),
                "after": session_info_debug_value(&info),
            }),
        );
    }
    agent.info = info;
}

