    fn sessions_pane_width(&self, total_width: u16) -> u16 {
        sessions_pane_width(
            total_width,
            self.settings.cokacmux.sessions_pane_width,
            self.settings.cokacmux.sessions_pane_percent,
        )
    }

    fn agent_sidebar_config_width(&self) -> u16 {
        if !self.settings.cokacmux.agent_sidebar_visible {
            return 0;
        }
        self.settings.cokacmux.agent_sidebar_width
    }

    fn sync_agent_viewports(&mut self, total_width: u16, terminal_rows: u16) -> AgentViewports {
        let viewports = agent_viewports_for_terminal(
            total_width,
            terminal_rows,
            self.agent_sidebar_config_width(),
            self.agent_aux.is_some(),
            self.agent_aux_width,
        );
        let active_before = self
            .active_agent
            .as_ref()
            .map(|agent| (agent.pty_size.cols, agent.pty_size.rows));
        let auxiliary_before = self
            .agent_aux
            .as_ref()
            .map(|aux| (aux.agent.pty_size.cols, aux.agent.pty_size.rows));
        if let Some(agent) = self.active_agent.as_mut() {
            agent.resize(viewports.main.pty_cols, viewports.main.pty_rows);
        }
        if let (Some(aux), Some(viewport)) = (self.agent_aux.as_mut(), viewports.auxiliary) {
            aux.agent.resize(viewport.pty_cols, viewport.pty_rows);
        }
        let active_after = self
            .active_agent
            .as_ref()
            .map(|agent| (agent.pty_size.cols, agent.pty_size.rows));
        let auxiliary_after = self
            .agent_aux
            .as_ref()
            .map(|aux| (aux.agent.pty_size.cols, aux.agent.pty_size.rows));
        if DEBUG_ENABLED.load(Ordering::Relaxed)
            && (TRACE_ENABLED.load(Ordering::Relaxed)
                || active_before != active_after
                || auxiliary_before != auxiliary_after)
        {
            debug_log(
                "agent_viewports_synced",
                serde_json::json!({
                    "terminal_cols": total_width,
                    "terminal_rows": terminal_rows,
                    "sidebar_width": self.agent_sidebar_config_width(),
                    "auxiliary_visible": self.agent_aux.is_some(),
                    "agent_aux_width": self.agent_aux_width,
                    "viewports": agent_viewports_debug_value(viewports),
                    "active_before": active_before.map(|(cols, rows)| serde_json::json!({ "cols": cols, "rows": rows })),
                    "active_after": active_after.map(|(cols, rows)| serde_json::json!({ "cols": cols, "rows": rows })),
                    "auxiliary_before": auxiliary_before.map(|(cols, rows)| serde_json::json!({ "cols": cols, "rows": rows })),
                    "auxiliary_after": auxiliary_after.map(|(cols, rows)| serde_json::json!({ "cols": cols, "rows": rows })),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
        }
        viewports
    }

    fn sync_active_agent_viewport(
        &mut self,
        total_width: u16,
        terminal_rows: u16,
    ) -> AgentViewport {
        self.sync_agent_viewports(total_width, terminal_rows).main
    }

    fn on_keybindings_reloaded(&mut self, reload: KeybindingsReload) {
        if let Some(keybindings) = reload.keybindings {
            self.keybindings = keybindings;
        }
        self.status = reload.status;
    }

    fn begin_settings(&mut self, return_to: AiTitleSettingsReturn) {
        self.input_mode = InputMode::Settings {
            state: SettingsState::new(&self.settings.cokacmux),
            return_to,
        };
        self.status = "settings.".into();
        debug_log(
            "settings_open",
            serde_json::json!({
                "provider": ai_title_provider_label(self.settings.cokacmux.ai.provider),
            }),
        );
    }

    fn save_settings_draft(&mut self, draft: SettingsDraft) -> bool {
        let previous_settings = self.settings.clone();
        let previous_session_view = self.session_view;
        let selected_key = self.current().map(AgentKey::new);
        self.settings.cokacmux.ai.provider = draft.ai_provider;
        self.settings.cokacmux.session_view = draft.session_view;
        self.settings.cokacmux.agent_sidebar_visible = draft.agent_sidebar_visible;
        self.settings.cokacmux.sessions_pane_width = draft.sessions_pane_width;
        self.settings.cokacmux.sessions_pane_percent = draft.sessions_pane_percent.min(100);
        self.settings.cokacmux.agent_sidebar_width = draft.agent_sidebar_width;
        self.settings.cokacmux.agent_programs = draft.agent_programs;
        self.settings.cokacmux.cokacdir_program = Some(draft.cokacdir_program);
        self.settings
            .cokacmux
            .agent_programs
            .normalize_placeholders();
        normalize_program_placeholder(&mut self.settings.cokacmux.cokacdir_program);

        match self.settings.save() {
            Ok(()) => {
                self.session_view = self.settings.cokacmux.session_view;
                if self.session_view != previous_session_view {
                    if let Some(key) = selected_key.as_ref() {
                        self.select_visible_session(key);
                        if self.list_state.selected().is_none() {
                            self.select_first();
                        }
                    } else {
                        self.select_first();
                    }
                    self.preview_scroll = 0;
                    self.focus = FocusPane::Sessions;
                }
                self.status = "settings saved.".into();
                debug_log(
                    "settings_saved",
                    serde_json::json!({
                        "provider": ai_title_provider_label(self.settings.cokacmux.ai.provider),
                        "session_view": self.session_view.label(),
                        "agent_sidebar_visible": self.settings.cokacmux.agent_sidebar_visible,
                    }),
                );
                true
            }
            Err(e) => {
                self.settings = previous_settings;
                self.session_view = previous_session_view;
                self.status = format!("settings save failed: {}", e);
                debug_log(
                    "settings_save_failed",
                    serde_json::json!({
                        "provider": ai_title_provider_label(self.settings.cokacmux.ai.provider),
                        "error": e.to_string(),
                    }),
                );
                false
            }
        }
    }

    fn start_ai_title_generation(&mut self, source: SessionInfo) {
        if self.reject_while_data_task_running("generating an AI title") {
            return;
        }
        if let Some(pending) = self.ai_search_pending.as_ref() {
            self.status = format!(
                "AI search is running with {}; wait before generating a title.",
                pending.provider.as_str()
            );
            debug_log(
                "ai_title_request_ignored",
                serde_json::json!({
                    "reason": "ai_search_pending",
                    "search_seq": pending.seq,
                    "provider": pending.provider.as_str(),
                }),
            );
            return;
        }
        if let Some(search_seq) = self.ai_search_draining_seq {
            self.status =
                "Previous AI search is still cancelling; wait before generating a title.".into();
            debug_log(
                "ai_title_request_ignored",
                serde_json::json!({
                    "reason": "ai_search_draining",
                    "search_seq": search_seq,
                }),
            );
            return;
        }
        if let Some(pending) = self.ai_title_pending.as_ref() {
            self.status = format!(
                "AI title already running with {} for {}",
                pending.provider.as_str(),
                truncate_width(&pending.key.session_id, 14)
            );
            debug_log(
                "ai_title_request_ignored",
                serde_json::json!({
                    "reason": "pending",
                    "seq": pending.seq,
                    "provider": pending.provider.as_str(),
                    "session_id": &pending.key.session_id,
                }),
            );
            return;
        }
        let Some(provider) = self.settings.cokacmux.ai.provider else {
            self.status = "choose an AI title agent first.".into();
            debug_log(
                "ai_title_request_ignored",
                serde_json::json!({
                    "reason": "provider_unconfigured",
                    "source_provider": source.provider.as_str(),
                    "session_id": &source.session_id,
                }),
            );
            return;
        };
        let Some(tx) = self.main_tx.clone() else {
            self.status = "AI title generation unavailable before UI event loop.".into();
            debug_log(
                "ai_title_request_ignored",
                serde_json::json!({
                    "reason": "missing_main_tx",
                    "provider": provider.as_str(),
                    "session_id": &source.session_id,
                }),
            );
            return;
        };

        self.ai_title_seq = self.ai_title_seq.saturating_add(1);
        let seq = self.ai_title_seq;
        let key = AgentKey::new(&source);
        let pending = AiTitlePending {
            seq,
            key: key.clone(),
            provider,
            started_at: Instant::now(),
        };
        let agent_programs = self.settings.cokacmux.agent_programs.clone();
        self.ai_title_pending = Some(pending);
        self.status = format!(
            "generating AI title with {}...",
            ai_title_provider_label(Some(provider))
        );
        debug_log(
            "ai_title_request",
            serde_json::json!({
                "seq": seq,
                "provider": provider.as_str(),
                "source_provider": source.provider.as_str(),
                "session_id": &source.session_id,
                "cwd": &source.cwd,
            }),
        );

        match thread::Builder::new()
            .name("cokacmux-ai-title".to_string())
            .spawn(move || {
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    generate_ai_title_worker(seq, source, provider, agent_programs)
                }));
                let event = match outcome {
                    Ok(result) => MainEvent::AiTitleResult(result),
                    Err(_) => background_worker_panicked(BackgroundWorkerKind::AiTitle, seq),
                };
                let _ = tx.send(event);
            }) {
            Ok(_) => {}
            Err(e) => {
                self.ai_title_pending = None;
                self.status = format!(
                    "AI title worker failed: {}",
                    truncate_width(&e.to_string(), 80)
                );
                debug_log(
                    "ai_title_spawn_failed",
                    serde_json::json!({
                        "seq": seq,
                        "provider": provider.as_str(),
                        "session_id": &key.session_id,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn on_ai_title_worker_result(&mut self, result: AiTitleWorkerResult) {
        let Some(pending) = self.ai_title_pending.as_ref() else {
            debug_log(
                "ai_title_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "reason": "none_pending",
                    "provider": result.provider.as_str(),
                    "session_id": &result.source.session_id,
                }),
            );
            return;
        };
        let result_key = AgentKey::new(&result.source);
        if pending.seq != result.seq
            || pending.key != result_key
            || pending.provider != result.provider
        {
            debug_log(
                "ai_title_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "pending_seq": pending.seq,
                    "reason": "stale",
                    "provider": result.provider.as_str(),
                    "session_id": &result.source.session_id,
                }),
            );
            return;
        }
        self.ai_title_pending = None;

        match result.outcome {
            Ok(title) => {
                let mut applied = false;
                if let InputMode::TitleEdit {
                    source,
                    draft,
                    cursor,
                } = &mut self.input_mode
                {
                    if AgentKey::new(source) == result_key {
                        *draft = title.clone();
                        *cursor = draft.len();
                        applied = true;
                    }
                }
                self.status = if applied {
                    format!(
                        "AI title ready with {}: {}",
                        result.provider.as_str(),
                        truncate_width(&title, 48)
                    )
                } else {
                    format!(
                        "AI title ready for {}; reopen title edit to regenerate",
                        truncate_width(&result.source.session_id, 14)
                    )
                };
                debug_log(
                    "ai_title_result_ok",
                    serde_json::json!({
                        "seq": result.seq,
                        "provider": result.provider.as_str(),
                        "source_provider": result.source.provider.as_str(),
                        "session_id": &result.source.session_id,
                        "title_len": title.chars().count(),
                        "applied": applied,
                        "elapsed_ms": result.elapsed_ms,
                    }),
                );
            }
            Err(error) => {
                let message = ai_title_failure_notice_message(
                    &result.source,
                    result.provider,
                    &error,
                    result.elapsed_ms,
                );
                self.show_notice_overlay("AI title failed", message);
                debug_log(
                    "ai_title_result_failed",
                    serde_json::json!({
                        "seq": result.seq,
                        "provider": result.provider.as_str(),
                        "source_provider": result.source.provider.as_str(),
                        "session_id": &result.source.session_id,
                        "error": error,
                        "elapsed_ms": result.elapsed_ms,
                    }),
                );
            }
        }
    }

    /// Flip the agents sidebar's visibility and persist the change so
    /// the choice survives restarts. The configured width is left alone
    /// so the user's manual resize comes back when they toggle on again.
    fn toggle_agent_sidebar_visible(&mut self) {
        let next = !self.settings.cokacmux.agent_sidebar_visible;
        self.settings.cokacmux.agent_sidebar_visible = next;
        if !next && self.agent_focus == AgentFocusPane::Sidebar {
            self.set_agent_focus(AgentFocusPane::Main);
        }
        self.status = if next {
            "agents sidebar: shown".into()
        } else {
            "agents sidebar: hidden".into()
        };
        if let Err(e) = self.settings.save() {
            debug_log(
                "settings_save_failed",
                serde_json::json!({
                    "field": "agent_sidebar_visible",
                    "error": e.to_string(),
                }),
            );
        }
        debug_log(
            "agent_sidebar_visible_toggle",
            serde_json::json!({ "visible": next }),
        );
    }

    fn current_active_agent_key(&self) -> Option<AgentKey> {
        self.active_agent
            .as_ref()
            .map(|agent| AgentKey::new(&agent.info))
    }

    fn agent_workspace_info(&self) -> Option<&SessionInfo> {
        self.active_agent
            .as_ref()
            .map(|agent| &agent.info)
            .or_else(|| {
                self.agent_kill_replacement
                    .as_ref()
                    .map(|replacement| &replacement.target)
            })
    }

    fn abandon_agent_kill_replacement_for(&mut self, key: &AgentKey, reason: &'static str) {
        let matches = self
            .agent_kill_replacement
            .as_ref()
            .is_some_and(|replacement| AgentKey::new(&replacement.target) == *key);
        if !matches {
            return;
        }
        self.agent_kill_replacement = None;
        if self.active_agent.is_none() {
            self.show_sessions_view = true;
            self.agent_focus = AgentFocusPane::Main;
        }
        debug_log(
            "agent_kill_replacement_abandoned",
            serde_json::json!({
                "reason": reason,
                "key": agent_key_debug_value(key),
                "show_sessions_view": self.show_sessions_view,
                "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
            }),
        );
    }

    fn route_after_active_agent_kill(&mut self, next_info: Option<&SessionInfo>) {
        if let Some(target) = next_info {
            self.agent_kill_replacement = Some(AgentKillReplacement {
                target: target.clone(),
            });
            self.show_sessions_view = false;
        } else {
            self.agent_kill_replacement = None;
            self.show_sessions_view = true;
            self.agent_focus = AgentFocusPane::Main;
        }
    }

    fn remember_current_agent_focus(&mut self) {
        let Some(key) = self.current_active_agent_key() else {
            return;
        };
        self.agent_focus_by_agent.insert(key, self.agent_focus);
    }

    fn set_agent_focus(&mut self, focus: AgentFocusPane) {
        let previous = self.agent_focus;
        self.agent_focus = focus;
        self.remember_current_agent_focus();
        debug_log(
            "agent_focus_set",
            serde_json::json!({
                "previous": format!("{:?}", previous),
                "next": format!("{:?}", focus),
                "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "auxiliary_open": self.agent_aux.is_some(),
                "remembered_focus_entries": self.agent_focus_by_agent.len(),
            }),
        );
    }

    fn ensure_agent_sidebar_visible_for_focus(&mut self, reason: &'static str) {
        if self.settings.cokacmux.agent_sidebar_visible {
            return;
        }
        self.settings.cokacmux.agent_sidebar_visible = true;
        if let Err(e) = self.settings.save() {
            debug_log(
                "settings_save_failed",
                serde_json::json!({
                    "field": "agent_sidebar_visible",
                    "reason": reason,
                    "error": e.to_string(),
                }),
            );
        }
    }

    fn valid_agent_focus_for_current(&self, focus: AgentFocusPane) -> AgentFocusPane {
        match focus {
            AgentFocusPane::Auxiliary if self.agent_aux.is_none() => AgentFocusPane::Main,
            other => other,
        }
    }

    fn restore_agent_focus_for_active_agent(&mut self, fallback: AgentFocusPane) {
        let requested = self
            .current_active_agent_key()
            .and_then(|key| self.agent_focus_by_agent.get(&key).copied())
            .unwrap_or(fallback);
        let focus = self.valid_agent_focus_for_current(requested);
        if focus == AgentFocusPane::Sidebar {
            self.ensure_agent_sidebar_visible_for_focus("agent_focus_restore");
        }
        self.agent_focus = focus;
        if requested == focus || requested != AgentFocusPane::Auxiliary {
            self.remember_current_agent_focus();
        }
        debug_log(
            "agent_focus_restored",
            serde_json::json!({
                "requested": format!("{:?}", requested),
                "fallback": format!("{:?}", fallback),
                "applied": format!("{:?}", focus),
                "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "auxiliary_open": self.agent_aux.is_some(),
                "remembered_focus_entries": self.agent_focus_by_agent.len(),
            }),
        );
    }

    fn focus_agent_sidebar(&mut self) {
        if !self.settings.cokacmux.agent_sidebar_visible {
            self.settings.cokacmux.agent_sidebar_visible = true;
            if let Err(e) = self.settings.save() {
                debug_log(
                    "settings_save_failed",
                    serde_json::json!({
                        "field": "agent_sidebar_visible",
                        "error": e.to_string(),
                    }),
                );
            }
            self.status = "focus: agents sidebar shown".into();
        } else {
            self.status = "focus: agents sidebar".into();
        }
        self.set_agent_focus(AgentFocusPane::Sidebar);
    }

    fn focus_main_agent(&mut self) {
        self.set_agent_focus(AgentFocusPane::Main);
        self.status = "focus: agent".into();
    }

    fn focus_auxiliary_agent(&mut self) {
        if let Some(aux) = self.agent_aux.as_ref() {
            let label = aux.kind.label();
            self.set_agent_focus(AgentFocusPane::Auxiliary);
            self.status = format!("focus: right {}", label);
        } else {
            self.status = "right panel is not open.".into();
        }
    }

    fn cycle_agent_focus_pane(&mut self, delta: i32) {
        let mut panes = Vec::new();
        if self.settings.cokacmux.agent_sidebar_visible {
            panes.push(AgentFocusPane::Sidebar);
        }
        panes.push(AgentFocusPane::Main);
        if self.agent_aux.is_some() {
            panes.push(AgentFocusPane::Auxiliary);
        }
        let main_index = panes
            .iter()
            .position(|pane| *pane == AgentFocusPane::Main)
            .unwrap_or(0);
        let current_index = panes
            .iter()
            .position(|pane| *pane == self.agent_focus)
            .unwrap_or(main_index);
        let next_index = next_agent_candidate_index(panes.len(), current_index, delta, true);
        debug_log(
            "agent_focus_cycle",
            serde_json::json!({
                "delta": delta,
                "current_index": current_index,
                "next_index": next_index,
                "panes": panes.iter().map(|pane| format!("{:?}", pane)).collect::<Vec<_>>(),
                "current": format!("{:?}", self.agent_focus),
                "next": format!("{:?}", panes[next_index]),
                "auxiliary_open": self.agent_aux.is_some(),
                "sidebar_visible": self.settings.cokacmux.agent_sidebar_visible,
            }),
        );
        match panes[next_index] {
            AgentFocusPane::Sidebar => self.focus_agent_sidebar(),
            AgentFocusPane::Main => self.focus_main_agent(),
            AgentFocusPane::Auxiliary => self.focus_auxiliary_agent(),
        }
    }

    fn active_main_agent_is_coding(&self) -> bool {
        self.active_agent
            .as_ref()
            .is_some_and(|agent| is_coding_agent_session_info(&agent.info))
    }

    fn focused_agent_info(&self) -> Option<&SessionInfo> {
        match self.agent_focus {
            AgentFocusPane::Auxiliary => self.agent_aux.as_ref().map(|aux| &aux.agent.info),
            AgentFocusPane::Sidebar | AgentFocusPane::Main => {
                self.active_agent.as_ref().map(|agent| &agent.info)
            }
        }
    }

    fn close_auxiliary_agent(&mut self, reason: &'static str, terminate: bool) -> Option<AgentKey> {
        let aux = self.agent_aux.take()?;
        self.close_auxiliary_pane(aux, reason, terminate, true)
    }

    fn close_auxiliary_pane(
        &mut self,
        mut aux: AgentAuxPane,
        reason: &'static str,
        terminate: bool,
        update_focus: bool,
    ) -> Option<AgentKey> {
        let key = AgentKey::new(&aux.agent.info);
        let label = live_agent_status_label(&aux.agent.info);
        let info = aux.agent.info.clone();
        let kind = aux.kind;
        let parent = aux.parent.clone();
        let focus_before = self.agent_focus;
        let hidden_before = self.hidden_agent_aux.len();
        let persisted_before = self.persisted_agent_aux.len();
        let termination_result = terminate.then(|| terminate_agent_daemon_for_info(&key, &info));
        let termination_failed = termination_result
            .as_ref()
            .is_some_and(|result| match result {
                Ok(outcome) => outcome.skipped_unverified,
                Err(_) => true,
            });
        if termination_failed {
            self.status = match termination_result
                .as_ref()
                .expect("termination result exists")
            {
                Ok(_) => format!(
                    "close right {} skipped: live process identity could not be verified",
                    label
                ),
                Err(error) => format!("close right {} failed: {}", label, error),
            };
            if update_focus {
                self.agent_aux = Some(aux);
            } else {
                self.hidden_agent_aux.push(aux);
            }
            self.discard_pending_agent_runtime_refresh();
            self.refresh_agent_runtime_states();
            debug_log(
                "agent_auxiliary_close_preserved",
                serde_json::json!({
                    "reason": reason,
                    "update_focus": update_focus,
                    "kind": kind.label(),
                    "parent": agent_key_debug_value(&parent),
                    "key": agent_key_debug_value(&key),
                    "status": &self.status,
                    "termination": termination_result.as_ref().map(|result| match result {
                        Ok(outcome) => serde_json::json!({
                            "ok": true,
                            "daemon_pid": outcome.pid,
                            "child_pid": outcome.child_pid,
                            "skipped_unverified": outcome.skipped_unverified,
                        }),
                        Err(error) => serde_json::json!({
                            "ok": false,
                            "error": error.to_string(),
                        }),
                    }),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return None;
        }

        if update_focus && self.agent_focus == AgentFocusPane::Auxiliary {
            self.set_agent_focus(AgentFocusPane::Main);
        }
        if let Some(Ok(outcome)) = termination_result.as_ref() {
            self.remove_persisted_agent_auxiliary(&key, reason);
            aux.agent.exited = Some(format!("terminated right panel: {}", reason));
            let history_suffix = agent_history_deleted_suffix(outcome.pty_log_deleted);
            self.status = match outcome.pid {
                Some(pid) => format!("closed right {} (pid {}){}", label, pid, history_suffix),
                None => format!("closed right {}{}", label, history_suffix),
            };
        } else {
            self.remember_persisted_agent_auxiliary(kind, &parent, &info, false, reason);
            self.status = format!("right {} hidden", label);
        }
        drop(aux);
        self.live_shells.retain(|info| AgentKey::new(info) != key);
        self.agent_states.remove(&key);
        self.new_agent_backing_aliases.remove(&key);
        self.new_agent_backing_probe_after.remove(&key);
        self.discard_pending_agent_runtime_refresh();
        self.refresh_agent_runtime_states();
        debug_log(
            "agent_auxiliary_closed",
            serde_json::json!({
                "reason": reason,
                "terminate": terminate,
                "update_focus": update_focus,
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "key": agent_key_debug_value(&key),
                "info": session_info_debug_value(&info),
                "status": &self.status,
                "focus_before": format!("{:?}", focus_before),
                "focus_after": format!("{:?}", self.agent_focus),
                "hidden_before": hidden_before,
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_before": persisted_before,
                "persisted_after": self.persisted_agent_aux.len(),
                "termination": termination_result.as_ref().map(|result| match result {
                    Ok(outcome) => serde_json::json!({
                        "ok": true,
                        "daemon_pid": outcome.pid,
                        "child_pid": outcome.child_pid,
                        "pty_log_deleted": outcome.pty_log_deleted,
                        "skipped_unverified": outcome.skipped_unverified,
                    }),
                    Err(e) => serde_json::json!({
                        "ok": false,
                        "error": e.to_string(),
                    }),
                }),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        Some(key)
    }

    fn hide_auxiliary_agent(
        &mut self,
        reason: &'static str,
        visible_on_parent_restore: bool,
    ) -> Option<AgentKey> {
        let aux = self.agent_aux.take()?;
        let key = AgentKey::new(&aux.agent.info);
        let label = live_agent_status_label(&aux.agent.info);
        let kind = aux.kind;
        let parent = aux.parent.clone();
        let focus_before = self.agent_focus;
        let hidden_before = self.hidden_agent_aux.len();
        let persisted_before = self.persisted_agent_aux.len();
        self.remember_active_auxiliary_parent_info(&parent);
        if self.agent_focus == AgentFocusPane::Auxiliary {
            self.set_agent_focus(AgentFocusPane::Main);
        }
        let replaced_hidden = self.remove_hidden_auxiliary_for_parent(kind, &parent);
        self.remember_persisted_agent_auxiliary(
            kind,
            &parent,
            &aux.agent.info,
            visible_on_parent_restore,
            reason,
        );
        self.hidden_agent_aux.push(aux);
        self.status = format!("right {} hidden", label);
        debug_log(
            "agent_auxiliary_hidden",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "key": agent_key_debug_value(&key),
                "visible_on_parent_restore": visible_on_parent_restore,
                "replaced_hidden": replaced_hidden,
                "focus_before": format!("{:?}", focus_before),
                "focus_after": format!("{:?}", self.agent_focus),
                "hidden_before": hidden_before,
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_before": persisted_before,
                "persisted_after": self.persisted_agent_aux.len(),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        Some(key)
    }

    fn take_hidden_auxiliary_agent(
        &mut self,
        kind: AgentAuxKind,
        parent: &AgentKey,
    ) -> Option<AgentAuxPane> {
        let hidden_before = self.hidden_agent_aux_debug_values();
        let index = self
            .hidden_agent_aux
            .iter()
            .position(|aux| aux.kind == kind && self.agent_aux_parent_matches(&aux.parent, parent));
        let Some(index) = index else {
            debug_log(
                "agent_hidden_auxiliary_take_miss",
                serde_json::json!({
                    "kind": kind.label(),
                    "parent": agent_key_debug_value(parent),
                    "hidden": hidden_before,
                }),
            );
            return None;
        };
        let aux = self.hidden_agent_aux.remove(index);
        debug_log(
            "agent_hidden_auxiliary_taken",
            serde_json::json!({
                "kind": kind.label(),
                "parent": agent_key_debug_value(parent),
                "index": index,
                "taken": agent_aux_pane_debug_value(&aux),
                "hidden_before": hidden_before,
                "hidden_after": self.hidden_agent_aux_debug_values(),
            }),
        );
        Some(aux)
    }

    fn hidden_auxiliary_visible_on_parent_restore(&self, aux: &AgentAuxPane) -> bool {
        let key = AgentKey::new(&aux.agent.info);
        self.persisted_agent_aux
            .get(&key)
            .is_none_or(|entry| entry.visible)
    }

    fn take_latest_visible_hidden_auxiliary_agent(
        &mut self,
        parent: &AgentKey,
    ) -> Option<AgentAuxPane> {
        let hidden_before = self.hidden_agent_aux_debug_values();
        let index = self.hidden_agent_aux.iter().rposition(|aux| {
            self.agent_aux_parent_matches(&aux.parent, parent)
                && self.hidden_auxiliary_visible_on_parent_restore(aux)
        });
        let Some(index) = index else {
            debug_log(
                "agent_visible_hidden_auxiliary_take_miss",
                serde_json::json!({
                    "parent": agent_key_debug_value(parent),
                    "hidden": hidden_before,
                    "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            );
            return None;
        };
        let aux = self.hidden_agent_aux.remove(index);
        debug_log(
            "agent_visible_hidden_auxiliary_taken",
            serde_json::json!({
                "parent": agent_key_debug_value(parent),
                "index": index,
                "taken": agent_aux_pane_debug_value(&aux),
                "hidden_before": hidden_before,
                "hidden_after": self.hidden_agent_aux_debug_values(),
            }),
        );
        Some(aux)
    }

    fn remove_hidden_auxiliary_for_parent(
        &mut self,
        kind: AgentAuxKind,
        parent: &AgentKey,
    ) -> usize {
        let hidden = std::mem::take(&mut self.hidden_agent_aux);
        let mut kept = Vec::new();
        let mut removed = 0usize;
        let mut removed_keys = Vec::new();
        for aux in hidden {
            if aux.kind == kind && self.agent_aux_parent_matches(&aux.parent, parent) {
                removed = removed.saturating_add(1);
                removed_keys.push(AgentKey::new(&aux.agent.info));
                let _ = self.release_auxiliary_pane(aux, "hidden_replaced", false);
            } else {
                kept.push(aux);
            }
        }
        self.hidden_agent_aux = kept;
        debug_log(
            "agent_hidden_auxiliaries_removed_for_parent",
            serde_json::json!({
                "kind": kind.label(),
                "parent": agent_key_debug_value(parent),
                "removed": removed,
                "removed_keys": agent_keys_debug_value(&removed_keys),
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_after": self.persisted_agent_aux.len(),
            }),
        );
        removed
    }

    fn release_auxiliary_info_locally(
        &mut self,
        key: &AgentKey,
        info: &SessionInfo,
        activity: AgentActivity,
        reason: &'static str,
    ) {
        self.remove_persisted_agent_auxiliary(key, reason);
        self.remember_live_info_locally(info);
        self.mark_agent_live_locally(key.clone(), activity);
        debug_log(
            "agent_auxiliary_released_live",
            serde_json::json!({
                "reason": reason,
                "key": agent_key_debug_value(key),
                "info": session_info_debug_value(info),
                "activity": activity.label(),
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
                "persisted_after": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
            }),
        );
    }

    fn release_auxiliary_pane(
        &mut self,
        aux: AgentAuxPane,
        reason: &'static str,
        update_focus: bool,
    ) -> AgentKey {
        let key = AgentKey::new(&aux.agent.info);
        let info = aux.agent.info.clone();
        let kind = aux.kind;
        let parent = aux.parent.clone();
        let activity = aux.agent.activity();
        if update_focus && self.agent_focus == AgentFocusPane::Auxiliary {
            self.set_agent_focus(AgentFocusPane::Main);
        }
        self.release_auxiliary_info_locally(&key, &info, activity, reason);
        drop(aux);
        debug_log(
            "agent_auxiliary_pane_released",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "key": agent_key_debug_value(&key),
                "update_focus": update_focus,
                "focus_after": format!("{:?}", self.agent_focus),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        key
    }

    fn release_hidden_auxiliaries_for_parent(
        &mut self,
        parent: &AgentKey,
        reason: &'static str,
    ) -> usize {
        let hidden = std::mem::take(&mut self.hidden_agent_aux);
        let mut kept = Vec::new();
        let mut released = 0usize;
        let mut released_keys = Vec::new();
        for aux in hidden {
            if self.agent_aux_parent_matches(&aux.parent, parent) {
                released = released.saturating_add(1);
                released_keys.push(AgentKey::new(&aux.agent.info));
                let _ = self.release_auxiliary_pane(aux, reason, false);
            } else {
                kept.push(aux);
            }
        }
        self.hidden_agent_aux = kept;
        debug_log(
            "agent_hidden_auxiliaries_released_for_parent",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "released": released,
                "released_keys": agent_keys_debug_value(&released_keys),
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_after": self.persisted_agent_aux.len(),
            }),
        );
        released
    }

    fn terminate_hidden_auxiliaries_for_parent(
        &mut self,
        parent: &AgentKey,
        reason: &'static str,
    ) -> usize {
        let hidden = std::mem::take(&mut self.hidden_agent_aux);
        let mut kept = Vec::new();
        let mut terminated = 0usize;
        let mut terminated_keys = Vec::new();
        for aux in hidden {
            if self.agent_aux_parent_matches(&aux.parent, parent) {
                let key = AgentKey::new(&aux.agent.info);
                if self
                    .close_auxiliary_pane(aux, reason, true, false)
                    .is_some()
                {
                    terminated = terminated.saturating_add(1);
                    terminated_keys.push(key);
                }
            } else {
                kept.push(aux);
            }
        }
        kept.append(&mut self.hidden_agent_aux);
        self.hidden_agent_aux = kept;
        debug_log(
            "agent_hidden_auxiliaries_terminated_for_parent",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "terminated": terminated,
                "terminated_keys": agent_keys_debug_value(&terminated_keys),
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_after": self.persisted_agent_aux.len(),
            }),
        );
        terminated
    }

    fn remember_auxiliary_parent_info(&mut self, info: &SessionInfo) -> AgentKey {
        let key = AgentKey::new(info);
        let previous = self.agent_aux_parent_infos.get(&key).cloned();
        if is_coding_agent_session_info(info) {
            self.agent_aux_parent_infos
                .insert(key.clone(), info.clone());
        }
        debug_log(
            "agent_auxiliary_parent_info_remembered",
            serde_json::json!({
                "key": agent_key_debug_value(&key),
                "info": session_info_debug_value(info),
                "coding_agent": is_coding_agent_session_info(info),
                "previous": previous.as_ref().map(session_info_debug_value),
                "parent_infos_len": self.agent_aux_parent_infos.len(),
            }),
        );
        key
    }

    fn remember_active_auxiliary_parent_info(&mut self, parent: &AgentKey) {
        let Some(info) = self.active_agent.as_ref().map(|agent| agent.info.clone()) else {
            debug_log(
                "agent_auxiliary_parent_info_active_skipped",
                serde_json::json!({
                    "parent": agent_key_debug_value(parent),
                    "reason": "no_active_agent",
                }),
            );
            return;
        };
        let active_key = self.remember_auxiliary_parent_info(&info);
        if active_key != *parent && self.agent_keys_match_or_alias(&active_key, parent) {
            let previous = self.agent_aux_parent_infos.get(parent).cloned();
            self.agent_aux_parent_infos.insert(parent.clone(), info);
            debug_log(
                "agent_auxiliary_parent_info_alias_remembered",
                serde_json::json!({
                    "parent": agent_key_debug_value(parent),
                    "active_key": agent_key_debug_value(&active_key),
                    "previous": previous.as_ref().map(session_info_debug_value),
                    "parent_infos_len": self.agent_aux_parent_infos.len(),
                }),
            );
        } else {
            debug_log(
                "agent_auxiliary_parent_info_alias_skipped",
                serde_json::json!({
                    "parent": agent_key_debug_value(parent),
                    "active_key": agent_key_debug_value(&active_key),
                    "matches_or_alias": self.agent_keys_match_or_alias(&active_key, parent),
                    "parent_infos_len": self.agent_aux_parent_infos.len(),
                }),
            );
        }
    }

    fn agent_info_for_auxiliary_parent_key(&self, key: &AgentKey) -> Option<&SessionInfo> {
        if let Some(agent) = self.active_agent.as_ref() {
            if AgentKey::new(&agent.info) == *key {
                return Some(&agent.info);
            }
        }
        if let Some(info) = self.agent_aux_parent_infos.get(key) {
            return Some(info);
        }
        if let Some(info) = self
            .sessions
            .iter()
            .find(|info| AgentKey::new(info) == *key)
        {
            return Some(info);
        }
        self.live_shells
            .iter()
            .find(|info| AgentKey::new(info) == *key)
    }

    fn remember_persisted_agent_auxiliary(
        &mut self,
        kind: AgentAuxKind,
        parent: &AgentKey,
        info: &SessionInfo,
        visible: bool,
        reason: &'static str,
    ) {
        let key = AgentKey::new(info);
        let parent_info = self.agent_info_for_auxiliary_parent_key(parent).cloned();
        let previous_entry = self.persisted_agent_aux.get(&key).cloned();
        let persisted_before = self.persisted_agent_aux.len();
        debug_log(
            "agent_auxiliary_registry_remember_start",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(parent),
                "parent_info": parent_info.as_ref().map(session_info_debug_value),
                "key": agent_key_debug_value(&key),
                "info": session_info_debug_value(info),
                "visible": visible,
                "previous_entry": previous_entry.as_ref().map(persisted_agent_auxiliary_entry_debug_value),
                "persisted_before": persisted_before,
                "registry_enabled": self.persist_agent_auxiliary_registry,
            }),
        );
        self.remove_persisted_auxiliaries_for_parent_kind_except(
            parent,
            kind,
            Some(&key),
            "parent_auxiliary_kind_replaced",
        );
        let entry = PersistedAgentAuxiliaryEntry {
            agent: key.clone(),
            kind,
            parent: parent.clone(),
            parent_provider: parent_info
                .as_ref()
                .map(|info| info.provider)
                .unwrap_or(parent.provider),
            parent_cwd: parent_info
                .as_ref()
                .map(|info| info.cwd.clone())
                .unwrap_or_default(),
            parent_source: parent_info
                .as_ref()
                .map(|info| info.source.display().to_string())
                .unwrap_or_default(),
            visible,
            updated_at_epoch_s: current_epoch_s(),
        };
        self.persisted_agent_aux.insert(key.clone(), entry.clone());
        if !self.persist_agent_auxiliary_registry {
            debug_log(
                "agent_auxiliary_registry_remembered_memory_only",
                serde_json::json!({
                    "reason": reason,
                    "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                    "persisted_before": persisted_before,
                    "persisted_after": self.persisted_agent_aux.len(),
                }),
            );
            return;
        }
        match queue_persisted_agent_auxiliary_registry_save(&self.persisted_agent_aux, reason) {
            Ok(coalesced) => debug_log(
                "agent_auxiliary_registry_remembered_queued",
                serde_json::json!({
                    "reason": reason,
                    "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                    "persisted_before": persisted_before,
                    "persisted_after": self.persisted_agent_aux.len(),
                    "coalesced": coalesced,
                    "entries": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            ),
            Err(e) => debug_log(
                "agent_auxiliary_registry_save_failed",
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(&key),
                    "error": e.to_string(),
                    "entries": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            ),
        }
    }

    fn persisted_auxiliary_parent_matches_key(
        &self,
        entry: &PersistedAgentAuxiliaryEntry,
        parent: &AgentKey,
    ) -> bool {
        if self.agent_keys_match_or_alias(&entry.parent, parent) {
            return true;
        }
        self.agent_info_for_auxiliary_parent_key(parent)
            .is_some_and(|parent_info| {
                self.persisted_auxiliary_can_match_parent_info(entry, parent_info)
                    && entry.matches_parent_info(parent_info)
            })
    }

    fn remove_persisted_auxiliaries_for_parent_kind_except(
        &mut self,
        parent: &AgentKey,
        kind: AgentAuxKind,
        keep: Option<&AgentKey>,
        reason: &'static str,
    ) {
        let keys = self
            .persisted_agent_aux
            .iter()
            .filter(|(key, entry)| {
                keep != Some(*key)
                    && entry.kind == kind
                    && self.persisted_auxiliary_parent_matches_key(entry, parent)
            })
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        debug_log(
            "agent_auxiliary_registry_parent_kind_replace_candidates",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "kind": kind.label(),
                "keep": keep.map(agent_key_debug_value),
                "keys": agent_keys_debug_value(&keys),
                "count": keys.len(),
                "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
            }),
        );
        for key in keys {
            self.release_persisted_auxiliary_key(&key, reason);
        }
    }

    fn terminate_persisted_auxiliaries_for_parent(
        &mut self,
        parent: &AgentKey,
        reason: &'static str,
    ) -> usize {
        let keys = self
            .persisted_agent_aux
            .iter()
            .filter(|(_, entry)| self.persisted_auxiliary_parent_matches_key(entry, parent))
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        debug_log(
            "agent_auxiliary_registry_parent_terminate_candidates",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "keys": agent_keys_debug_value(&keys),
                "count": keys.len(),
                "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
            }),
        );
        let mut terminated = 0usize;
        for key in keys {
            if self.terminate_persisted_auxiliary_key(&key, reason) {
                terminated = terminated.saturating_add(1);
            }
        }
        terminated
    }

    fn terminate_persisted_auxiliary_key(&mut self, key: &AgentKey, reason: &'static str) -> bool {
        let info = self
            .live_shells
            .iter()
            .find(|info| AgentKey::new(info) == *key)
            .cloned();
        let entry_before = self.persisted_agent_aux.get(key).cloned();
        let visible_before = self.agent_aux.as_ref().map(agent_aux_pane_debug_value);
        let hidden_before = self.hidden_agent_aux_debug_values();
        debug_log(
            "agent_auxiliary_terminate_key_start",
            serde_json::json!({
                "reason": reason,
                "key": agent_key_debug_value(key),
                "entry": entry_before.as_ref().map(persisted_agent_auxiliary_entry_debug_value),
                "live_info": info.as_ref().map(session_info_debug_value),
                "visible_before": visible_before,
                "hidden_before": hidden_before,
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
            }),
        );
        let result = if let Some(info) = info.as_ref() {
            terminate_agent_daemon_for_info(key, info)
        } else {
            terminate_agent_daemon_with_info(key, None)
        };
        let terminated = result
            .as_ref()
            .is_ok_and(|outcome| !outcome.skipped_unverified);
        if terminated {
            self.remove_persisted_agent_auxiliary(key, reason);
            if self
                .agent_aux
                .as_ref()
                .is_some_and(|aux| AgentKey::new(&aux.agent.info) == *key)
            {
                if let Some(mut aux) = self.agent_aux.take() {
                    if self.agent_focus == AgentFocusPane::Auxiliary {
                        self.set_agent_focus(AgentFocusPane::Main);
                    }
                    aux.agent.exited = Some(format!("terminated right panel: {}", reason));
                    drop(aux);
                }
            }
            let hidden = std::mem::take(&mut self.hidden_agent_aux);
            let mut kept = Vec::new();
            for mut aux in hidden {
                if AgentKey::new(&aux.agent.info) == *key {
                    aux.agent.exited = Some(format!("terminated right panel: {}", reason));
                    drop(aux);
                } else {
                    kept.push(aux);
                }
            }
            self.hidden_agent_aux = kept;
            self.live_shells.retain(|info| AgentKey::new(info) != *key);
            self.agent_states.remove(key);
            self.new_agent_backing_aliases.remove(key);
            self.new_agent_backing_probe_after.remove(key);
        } else {
            self.status = match result.as_ref() {
                Ok(_) => "auxiliary kill skipped: live process identity could not be verified"
                    .to_string(),
                Err(error) => format!("auxiliary kill failed: {}", error),
            };
        }
        debug_log(
            if terminated {
                "agent_auxiliary_terminated"
            } else {
                "agent_auxiliary_termination_preserved"
            },
            serde_json::json!({
                "reason": reason,
                "key": agent_key_debug_value(key),
                "result": result.as_ref().ok().map(|outcome| {
                    serde_json::json!({
                        "daemon_pid": outcome.pid,
                        "child_pid": outcome.child_pid,
                        "pty_log_deleted": outcome.pty_log_deleted,
                        "skipped_unverified": outcome.skipped_unverified,
                    })
                }),
                "error": result.as_ref().err().map(|e| e.to_string()),
                "hidden_after": self.hidden_agent_aux_debug_values(),
                "persisted_after": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        terminated
    }

    fn release_persisted_auxiliary_key(&mut self, key: &AgentKey, reason: &'static str) -> bool {
        // UI callers release from the latest in-memory discovery snapshot.
        // Any authoritative filesystem/process revalidation belongs to the
        // runtime/kill workers.
        self.release_persisted_auxiliary_key_with_meta(key, reason, |_| None)
    }

    fn release_persisted_auxiliary_key_with_meta<F>(
        &mut self,
        key: &AgentKey,
        reason: &'static str,
        mut meta_snapshot: F,
    ) -> bool
    where
        F: FnMut(&AgentKey) -> Option<(AgentMetaSnapshot, AgentMetaLivenessKind)>,
    {
        let Some(entry) = self.persisted_agent_aux.get(key).cloned() else {
            debug_log(
                "agent_auxiliary_release_key_miss",
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(key),
                    "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            );
            return false;
        };
        let existing_live_info = self
            .live_shells
            .iter()
            .find(|info| AgentKey::new(info) == *key)
            .cloned();
        let meta_live = meta_snapshot(key).and_then(|(meta, liveness)| {
            let (info, state) = agent_meta_info_and_state_for_key(
                key,
                None,
                &meta,
                std::process::id(),
                Some(agent_client_instance_id()),
                current_epoch_ms(),
            )?;
            Some((info, state, meta, liveness))
        });
        if let Some((info, state, meta, liveness)) = meta_live {
            self.remove_persisted_agent_auxiliary(key, reason);
            self.remember_live_info_locally(&info);
            if is_switchable_agent_state(state) {
                self.agent_states.insert(key.clone(), state);
            } else {
                self.mark_agent_live_locally(key.clone(), state.activity());
            }
            debug_log(
                if liveness == AgentMetaLivenessKind::Verified {
                    "agent_auxiliary_registry_released_verified_live"
                } else {
                    "agent_auxiliary_registry_released_possible_live"
                },
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(key),
                    "liveness": liveness.label(),
                    "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                    "info": session_info_debug_value(&info),
                    "state": agent_list_state_debug_value(state),
                    "meta": agent_meta_snapshot_debug_value(&meta),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return true;
        }
        if let Some(info) = existing_live_info {
            self.release_auxiliary_info_locally(key, &info, AgentActivity::Quiet, reason);
            debug_log(
                "agent_auxiliary_registry_released_known_live",
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(key),
                    "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                    "info": session_info_debug_value(&info),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return true;
        }
        self.remove_persisted_agent_auxiliary(key, reason);
        self.agent_states.remove(key);
        debug_log(
            "agent_auxiliary_registry_removed_without_live_runtime",
            serde_json::json!({
                "reason": reason,
                "key": agent_key_debug_value(key),
                "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        true
    }

    fn release_persisted_auxiliaries_for_parent(
        &mut self,
        parent: &AgentKey,
        reason: &'static str,
    ) -> usize {
        let keys = self
            .persisted_agent_aux
            .iter()
            .filter(|(_, entry)| self.persisted_auxiliary_parent_matches_key(entry, parent))
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        debug_log(
            "agent_auxiliary_registry_parent_release_candidates",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "keys": agent_keys_debug_value(&keys),
                "count": keys.len(),
                "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
            }),
        );
        let mut released = 0usize;
        for key in keys {
            if self.release_persisted_auxiliary_key(&key, reason) {
                released = released.saturating_add(1);
            }
        }
        released
    }

    fn release_auxiliaries_for_parent(&mut self, parent: &AgentKey, reason: &'static str) -> usize {
        let mut released = 0usize;
        if self
            .agent_aux
            .as_ref()
            .is_some_and(|aux| self.agent_aux_parent_matches(&aux.parent, parent))
        {
            if let Some(aux) = self.agent_aux.take() {
                released = released.saturating_add(1);
                let _ = self.release_auxiliary_pane(aux, reason, true);
            }
        }
        released =
            released.saturating_add(self.release_hidden_auxiliaries_for_parent(parent, reason));
        released =
            released.saturating_add(self.release_persisted_auxiliaries_for_parent(parent, reason));
        debug_log(
            "agent_auxiliaries_released_for_parent",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "count": released,
            }),
        );
        released
    }

    fn terminate_auxiliaries_for_parent(
        &mut self,
        parent: &AgentKey,
        reason: &'static str,
    ) -> usize {
        let mut terminated = 0usize;
        if self
            .agent_aux
            .as_ref()
            .is_some_and(|aux| self.agent_aux_parent_matches(&aux.parent, parent))
        {
            if let Some(aux) = self.agent_aux.take() {
                if self.close_auxiliary_pane(aux, reason, true, true).is_some() {
                    terminated = terminated.saturating_add(1);
                }
            }
        }
        terminated =
            terminated.saturating_add(self.terminate_hidden_auxiliaries_for_parent(parent, reason));
        terminated = terminated
            .saturating_add(self.terminate_persisted_auxiliaries_for_parent(parent, reason));
        debug_log(
            "agent_auxiliaries_terminated_for_parent",
            serde_json::json!({
                "reason": reason,
                "parent": agent_key_debug_value(parent),
                "count": terminated,
            }),
        );
        terminated
    }

    fn auxiliary_termination_candidates_for_parent(
        &self,
        parent: &AgentKey,
    ) -> Vec<AuxiliaryKillCandidate> {
        let mut candidates = Vec::new();
        let mut seen = HashSet::new();
        if let Some(aux) = self
            .agent_aux
            .as_ref()
            .filter(|aux| self.agent_aux_parent_matches(&aux.parent, parent))
        {
            let key = AgentKey::new(&aux.agent.info);
            seen.insert(key.clone());
            candidates.push(AuxiliaryKillCandidate {
                key,
                info: Some(aux.agent.info.clone()),
            });
        }
        for aux in &self.hidden_agent_aux {
            if !self.agent_aux_parent_matches(&aux.parent, parent) {
                continue;
            }
            let key = AgentKey::new(&aux.agent.info);
            if seen.insert(key.clone()) {
                candidates.push(AuxiliaryKillCandidate {
                    key,
                    info: Some(aux.agent.info.clone()),
                });
            }
        }
        for (key, entry) in &self.persisted_agent_aux {
            if !self.persisted_auxiliary_parent_matches_key(entry, parent)
                || !seen.insert(key.clone())
            {
                continue;
            }
            let info = self
                .live_shells
                .iter()
                .find(|info| AgentKey::new(info) == *key)
                .cloned();
            candidates.push(AuxiliaryKillCandidate {
                key: key.clone(),
                info,
            });
        }
        candidates
    }

    fn apply_auxiliary_termination_outcomes(
        &mut self,
        outcomes: Vec<AuxiliaryKillWorkerResult>,
        reason: &'static str,
    ) -> AuxiliaryTerminationSummary {
        let mut summary = AuxiliaryTerminationSummary::default();
        for result in outcomes {
            let key = result.key;
            match result.outcome {
                Ok(outcome) if !outcome.skipped_unverified => {
                    if let Some(aux) = self
                        .agent_aux
                        .as_mut()
                        .filter(|aux| AgentKey::new(&aux.agent.info) == key)
                    {
                        aux.agent.exited = Some(format!("terminated right panel: {}", reason));
                        aux.agent.mark_exit_detected();
                    }
                    if self
                        .agent_aux
                        .as_ref()
                        .is_some_and(|aux| AgentKey::new(&aux.agent.info) == key)
                    {
                        let aux = self.agent_aux.take();
                        drop(aux);
                        if self.agent_focus == AgentFocusPane::Auxiliary {
                            self.set_agent_focus(AgentFocusPane::Main);
                        }
                    }
                    for aux in &mut self.hidden_agent_aux {
                        if AgentKey::new(&aux.agent.info) == key {
                            aux.agent.exited = Some(format!("terminated right panel: {}", reason));
                            aux.agent.mark_exit_detected();
                        }
                    }
                    self.hidden_agent_aux
                        .retain(|aux| AgentKey::new(&aux.agent.info) != key);
                    self.remove_persisted_agent_auxiliary(&key, reason);
                    self.live_shells.retain(|info| AgentKey::new(info) != key);
                    self.agent_states.remove(&key);
                    self.new_agent_backing_aliases.remove(&key);
                    self.new_agent_backing_probe_after.remove(&key);
                    summary.terminated = summary.terminated.saturating_add(1);
                    debug_log(
                        "agent_auxiliary_background_terminated",
                        serde_json::json!({
                            "reason": reason,
                            "key": agent_key_debug_value(&key),
                            "daemon_pid": outcome.pid,
                            "child_pid": outcome.child_pid,
                            "pty_log_deleted": outcome.pty_log_deleted,
                        }),
                    );
                }
                Ok(outcome) => {
                    summary.preserved = summary.preserved.saturating_add(1);
                    debug_log(
                        "agent_auxiliary_background_preserved",
                        serde_json::json!({
                            "reason": reason,
                            "key": agent_key_debug_value(&key),
                            "cause": "unverified",
                            "daemon_pid": outcome.pid,
                            "child_pid": outcome.child_pid,
                        }),
                    );
                }
                Err(error) => {
                    summary.preserved = summary.preserved.saturating_add(1);
                    debug_log(
                        "agent_auxiliary_background_preserved",
                        serde_json::json!({
                            "reason": reason,
                            "key": agent_key_debug_value(&key),
                            "cause": "error",
                            "error": error,
                        }),
                    );
                }
            }
        }
        summary
    }

    #[cfg(test)]
    fn persisted_auxiliary_parent_is_live(&self, entry: &PersistedAgentAuxiliaryEntry) -> bool {
        if self.active_agent.as_ref().is_some_and(|agent| {
            let key = AgentKey::new(&agent.info);
            self.agent_keys_match_or_alias(&entry.parent, &key)
                || (self.persisted_auxiliary_can_match_parent_info(entry, &agent.info)
                    && entry.matches_parent_info(&agent.info))
        }) {
            return true;
        }
        if self.agent_states.iter().any(|(key, state)| {
            *state != AgentListState::Idle && self.agent_keys_match_or_alias(&entry.parent, key)
        }) {
            return true;
        }
        if self.live_shells.iter().any(|info| {
            if !is_coding_agent_session_info(info) {
                return false;
            }
            let key = AgentKey::new(info);
            self.agent_keys_match_or_alias(&entry.parent, &key)
                || (self.persisted_auxiliary_can_match_parent_info(entry, info)
                    && entry.matches_parent_info(info))
        }) {
            return true;
        }
        self.sessions.iter().any(|info| {
            if !is_coding_agent_session_info(info)
                || !(self.agent_keys_match_or_alias(&entry.parent, &AgentKey::new(info))
                    || (self.persisted_auxiliary_can_match_parent_info(entry, info)
                        && entry.matches_parent_info(info)))
            {
                return false;
            }
            self.agent_states
                .get(&AgentKey::new(info))
                .is_some_and(|state| *state != AgentListState::Idle)
        })
    }

    fn persisted_auxiliary_can_match_parent_info(
        &self,
        entry: &PersistedAgentAuxiliaryEntry,
        info: &SessionInfo,
    ) -> bool {
        entry.parent_source == NEW_AGENT_SESSION_SOURCE_MARKER
            || entry
                .parent
                .session_id
                .starts_with(NEW_AGENT_SESSION_ID_PREFIX)
            || is_new_agent_session_info(info)
    }

    fn persisted_auxiliary_registry_parent_key(
        entry: &PersistedAgentAuxiliaryEntry,
    ) -> (bool, Provider, String, String, AgentAuxKind) {
        let cwd_scoped = (entry.parent_source == NEW_AGENT_SESSION_SOURCE_MARKER
            || entry
                .parent
                .session_id
                .starts_with(NEW_AGENT_SESSION_ID_PREFIX))
            && !entry.parent_cwd.trim().is_empty();
        if cwd_scoped {
            (
                true,
                entry.parent_provider,
                entry.parent_cwd.clone(),
                String::new(),
                entry.kind,
            )
        } else {
            (
                false,
                entry.parent.provider,
                String::new(),
                entry.parent.session_id.clone(),
                entry.kind,
            )
        }
    }

    fn normalize_persisted_agent_auxiliaries(&mut self, reason: &'static str) -> usize {
        type PersistedAuxiliaryParentKey = (bool, Provider, String, String, AgentAuxKind);
        type PersistedAuxiliaryWinner = (AgentKey, u64, String);
        let mut winners: HashMap<PersistedAuxiliaryParentKey, PersistedAuxiliaryWinner> =
            HashMap::new();
        for (key, entry) in &self.persisted_agent_aux {
            let parent_key = Self::persisted_auxiliary_registry_parent_key(entry);
            let candidate_rank = (entry.updated_at_epoch_s, key.session_id.clone());
            let replace = winners
                .get(&parent_key)
                .is_none_or(|(_, updated_at, session_id)| {
                    candidate_rank > (*updated_at, session_id.clone())
                });
            if replace {
                winners.insert(
                    parent_key,
                    (
                        key.clone(),
                        entry.updated_at_epoch_s,
                        key.session_id.clone(),
                    ),
                );
            }
        }
        let winner_keys = winners
            .values()
            .map(|(key, _, _)| key.clone())
            .collect::<HashSet<_>>();
        let keys = self
            .persisted_agent_aux
            .keys()
            .filter(|key| !winner_keys.contains(*key))
            .cloned()
            .collect::<Vec<_>>();
        debug_log(
            "agent_auxiliary_registry_normalize_candidates",
            serde_json::json!({
                "reason": reason,
                "remove_keys": agent_keys_debug_value(&keys),
                "remove_count": keys.len(),
                "winner_keys": winner_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                "entries": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
            }),
        );
        let mut normalized = 0usize;
        for key in keys {
            if self.release_persisted_auxiliary_key(&key, reason) {
                normalized = normalized.saturating_add(1);
            }
        }
        if normalized > 0 {
            debug_log(
                "agent_auxiliary_registry_normalized",
                serde_json::json!({
                    "reason": reason,
                    "removed": normalized,
                    "remaining": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            );
        }
        normalized
    }

    fn auxiliary_parent_is_live(&self, parent: &AgentKey) -> bool {
        if self.active_agent.as_ref().is_some_and(|agent| {
            self.agent_keys_match_or_alias(&AgentKey::new(&agent.info), parent)
        }) {
            return true;
        }
        if self.agent_states.iter().any(|(key, state)| {
            *state != AgentListState::Idle && self.agent_keys_match_or_alias(key, parent)
        }) {
            return true;
        }
        self.live_shells.iter().any(|info| {
            is_coding_agent_session_info(info)
                && self.agent_keys_match_or_alias(&AgentKey::new(info), parent)
        })
    }

    #[cfg(test)]
    fn release_orphan_persisted_auxiliaries(&mut self, reason: &'static str) -> usize {
        let keys = self
            .persisted_agent_aux
            .iter()
            .filter(|(_, entry)| !self.persisted_auxiliary_parent_is_live(entry))
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        debug_log(
            "agent_auxiliary_orphan_candidates",
            serde_json::json!({
                "reason": reason,
                "keys": agent_keys_debug_value(&keys),
                "count": keys.len(),
                "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "live_shells_len": self.live_shells.len(),
            }),
        );
        let mut released = 0usize;
        for key in keys {
            if self.release_persisted_auxiliary_key(&key, reason) {
                released = released.saturating_add(1);
            }
        }
        if released > 0 {
            debug_log(
                "agent_auxiliary_orphans_released",
                serde_json::json!({
                    "reason": reason,
                    "count": released,
                }),
            );
        }
        released
    }

    #[cfg(test)]
    fn persisted_auxiliary_parent_has_live_runtime(
        &self,
        entry: &PersistedAgentAuxiliaryEntry,
    ) -> bool {
        if let Some(agent) = self.active_agent.as_ref() {
            if self.agent_keys_match_or_alias(&entry.parent, &AgentKey::new(&agent.info))
                || (self.persisted_auxiliary_can_match_parent_info(entry, &agent.info)
                    && entry.matches_parent_info(&agent.info))
            {
                return agent.exited.is_none();
            }
        }
        if self.agent_states.iter().any(|(key, state)| {
            *state != AgentListState::Idle && self.agent_keys_match_or_alias(&entry.parent, key)
        }) {
            return true;
        }
        if self.live_shells.iter().any(|info| {
            if !is_coding_agent_session_info(info) {
                return false;
            }
            let key = AgentKey::new(info);
            (self.agent_keys_match_or_alias(&entry.parent, &key)
                || (self.persisted_auxiliary_can_match_parent_info(entry, info)
                    && entry.matches_parent_info(info)))
                && self
                    .agent_states
                    .get(&key)
                    .copied()
                    .is_none_or(|state| state != AgentListState::Idle)
        }) {
            return true;
        }
        self.sessions.iter().any(|info| {
            if !is_coding_agent_session_info(info)
                || !(self.agent_keys_match_or_alias(&entry.parent, &AgentKey::new(info))
                    || (self.persisted_auxiliary_can_match_parent_info(entry, info)
                        && entry.matches_parent_info(info)))
            {
                return false;
            }
            self.agent_states
                .get(&AgentKey::new(info))
                .is_some_and(|state| *state != AgentListState::Idle)
        })
    }

    #[cfg(test)]
    fn persisted_auxiliary_parent_runtime_is_known(
        &self,
        entry: &PersistedAgentAuxiliaryEntry,
    ) -> bool {
        if self.active_agent.as_ref().is_some_and(|agent| {
            self.agent_keys_match_or_alias(&entry.parent, &AgentKey::new(&agent.info))
                || (self.persisted_auxiliary_can_match_parent_info(entry, &agent.info)
                    && entry.matches_parent_info(&agent.info))
        }) {
            return true;
        }
        if self
            .agent_states
            .keys()
            .any(|key| self.agent_keys_match_or_alias(&entry.parent, key))
        {
            return true;
        }
        if self.live_shells.iter().any(|info| {
            if !is_coding_agent_session_info(info) {
                return false;
            }
            let key = AgentKey::new(info);
            self.agent_keys_match_or_alias(&entry.parent, &key)
                || (self.persisted_auxiliary_can_match_parent_info(entry, info)
                    && entry.matches_parent_info(info))
        }) {
            return true;
        }
        self.sessions.iter().any(|info| {
            self.agent_states.contains_key(&AgentKey::new(info))
                && is_coding_agent_session_info(info)
                && (self.agent_keys_match_or_alias(&entry.parent, &AgentKey::new(info))
                    || (self.persisted_auxiliary_can_match_parent_info(entry, info)
                        && entry.matches_parent_info(info)))
        })
    }

    #[cfg(test)]
    fn release_orphan_persisted_auxiliaries_without_live_runtime(
        &mut self,
        reason: &'static str,
    ) -> usize {
        let keys = self
            .persisted_agent_aux
            .iter()
            .filter(|(_, entry)| {
                self.persisted_auxiliary_parent_runtime_is_known(entry)
                    && !self.persisted_auxiliary_parent_has_live_runtime(entry)
            })
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        debug_log(
            "agent_auxiliary_runtime_orphan_candidates",
            serde_json::json!({
                "reason": reason,
                "keys": agent_keys_debug_value(&keys),
                "count": keys.len(),
                "persisted": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "live_shells_len": self.live_shells.len(),
                "agent_states": agent_state_entries_debug_value(&self.agent_states),
            }),
        );
        let mut released = 0usize;
        for key in keys {
            if self.release_persisted_auxiliary_key(&key, reason) {
                released = released.saturating_add(1);
            }
        }
        if released > 0 {
            debug_log(
                "agent_auxiliary_runtime_orphans_released",
                serde_json::json!({
                    "reason": reason,
                    "count": released,
                }),
            );
        }
        released
    }

    fn remove_persisted_agent_auxiliary(&mut self, key: &AgentKey, reason: &'static str) {
        let Some(entry) = self.persisted_agent_aux.remove(key) else {
            debug_log(
                "agent_auxiliary_registry_remove_miss",
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(key),
                    "remaining": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            );
            return;
        };
        if !self.persist_agent_auxiliary_registry {
            debug_log(
                "agent_auxiliary_registry_removed_memory_only",
                serde_json::json!({
                    "reason": reason,
                    "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                    "remaining": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            );
            return;
        }
        match queue_persisted_agent_auxiliary_registry_save(&self.persisted_agent_aux, reason) {
            Ok(coalesced) => debug_log(
                "agent_auxiliary_registry_removed_queued",
                serde_json::json!({
                    "reason": reason,
                    "entry": persisted_agent_auxiliary_entry_debug_value(&entry),
                    "coalesced": coalesced,
                    "remaining": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
                }),
            ),
            Err(e) => debug_log(
                "agent_auxiliary_registry_save_failed",
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(key),
                    "error": e.to_string(),
                }),
            ),
        }
    }

    fn persisted_auxiliary_matches_active(
        &self,
        entry: &PersistedAgentAuxiliaryEntry,
        active_info: &SessionInfo,
    ) -> bool {
        let active_key = AgentKey::new(active_info);
        if self.agent_keys_match_or_alias(&entry.parent, &active_key) {
            return true;
        }
        self.persisted_auxiliary_can_match_parent_info(entry, active_info)
            && entry.matches_parent_info(active_info)
    }

    fn hidden_agent_aux_debug_values(&self) -> Vec<serde_json::Value> {
        self.hidden_agent_aux
            .iter()
            .map(|aux| {
                serde_json::json!({
                    "kind": aux.kind.label(),
                    "parent": agent_key_debug_value(&aux.parent),
                    "parent_info": self
                        .agent_info_for_auxiliary_parent_key(&aux.parent)
                        .map(session_info_debug_value),
                    "agent": session_info_debug_value(&aux.agent.info),
                    "visible": self.hidden_auxiliary_visible_on_parent_restore(aux),
                    "reader_id": aux.agent.reader_id,
                })
            })
            .collect()
    }

    fn live_auxiliary_restore_candidate_entries_debug_value(
        &self,
        active_info: &SessionInfo,
    ) -> Vec<serde_json::Value> {
        let live_keys = self
            .live_shells
            .iter()
            .map(AgentKey::new)
            .collect::<HashSet<_>>();
        let mut entries = self
            .live_shells
            .iter()
            .filter_map(|info| {
                let kind = auxiliary_kind_for_session_info(info)?;
                let key = AgentKey::new(info);
                let state = self
                    .agent_states
                    .get(&key)
                    .copied()
                    .unwrap_or(AgentListState::Idle);
                let same_cwd = session_cwd_same_folder_cached(&active_info.cwd, &info.cwd);
                let persisted_auxiliary = self.persisted_agent_aux.get(&key);
                let persisted_matches_active = persisted_auxiliary.is_some_and(|entry| {
                    entry.kind == kind && self.persisted_auxiliary_matches_active(entry, active_info)
                });
                let is_auxiliary = self.is_auxiliary_agent_key(&key);
                let switchable = is_switchable_agent_state(state);
                Some(serde_json::json!({
                    "kind": kind.label(),
                    "key": agent_key_debug_value(&key),
                    "state": agent_list_state_debug_value(state),
                    "same_cwd": same_cwd,
                    "persisted_auxiliary": persisted_auxiliary.map(persisted_agent_auxiliary_entry_debug_value),
                    "visible_on_parent_restore": persisted_auxiliary.is_none_or(|entry| entry.visible),
                    "persisted_matches_active": persisted_matches_active,
                    "excluded_auxiliary": is_auxiliary,
                    "candidate": switchable && persisted_matches_active,
                    "source": "live_discovery",
                    "info": session_info_debug_value(info),
                }))
            })
            .collect::<Vec<_>>();
        entries.extend(
            self.persisted_agent_aux
                .values()
                .filter(|entry| !live_keys.contains(&entry.agent))
                .filter(|entry| self.persisted_auxiliary_matches_active(entry, active_info))
                .map(|entry| {
                    let info = session_info_for_persisted_agent_auxiliary(entry);
                    serde_json::json!({
                        "kind": entry.kind.label(),
                        "key": agent_key_debug_value(&entry.agent),
                        "state": "not_discovered",
                        "same_cwd": session_cwd_same_folder_cached(&active_info.cwd, &info.cwd),
                        "persisted_auxiliary": persisted_agent_auxiliary_entry_debug_value(entry),
                        "visible_on_parent_restore": entry.visible,
                        "persisted_matches_active": true,
                        "excluded_auxiliary": true,
                        "candidate": true,
                        "source": "persisted_registry",
                        "info": session_info_debug_value(&info),
                    })
                }),
        );
        entries
    }

    #[cfg(test)]
    fn live_auxiliary_restore_candidate_for_active_agent(
        &self,
        active_info: &SessionInfo,
    ) -> Option<(AgentAuxKind, SessionInfo)> {
        self.live_auxiliary_restore_candidate_for_active_agent_matching(active_info, None, false)
    }

    #[cfg(test)]
    fn live_auxiliary_restore_candidate_for_active_agent_kind(
        &self,
        active_info: &SessionInfo,
        desired_kind: AgentAuxKind,
    ) -> Option<SessionInfo> {
        self.live_auxiliary_restore_candidate_for_active_agent_matching(
            active_info,
            Some(desired_kind),
            false,
        )
        .map(|(_, info)| info)
    }

    fn live_auxiliary_restore_candidate_for_active_agent_matching(
        &self,
        active_info: &SessionInfo,
        desired_kind: Option<AgentAuxKind>,
        visible_on_parent_restore_only: bool,
    ) -> Option<(AgentAuxKind, SessionInfo)> {
        let live_keys = self
            .live_shells
            .iter()
            .map(AgentKey::new)
            .collect::<HashSet<_>>();
        let live_candidates = self.live_shells.iter().filter_map(|info| {
            let kind = auxiliary_kind_for_session_info(info)?;
            if desired_kind.is_some_and(|desired_kind| desired_kind != kind) {
                return None;
            }
            let key = AgentKey::new(info);
            let persisted_auxiliary = self.persisted_agent_aux.get(&key);
            if visible_on_parent_restore_only
                && persisted_auxiliary.is_some_and(|entry| !entry.visible)
            {
                return None;
            }
            let persisted_matches_active = persisted_auxiliary.is_some_and(|entry| {
                entry.kind == kind && self.persisted_auxiliary_matches_active(entry, active_info)
            });
            let persisted_updated_at = persisted_auxiliary
                .map(|entry| entry.updated_at_epoch_s)
                .unwrap_or(0);
            if !persisted_matches_active {
                return None;
            }
            let state = self
                .agent_states
                .get(&key)
                .copied()
                .unwrap_or(AgentListState::Idle);
            if !is_switchable_agent_state(state) {
                return None;
            }
            Some((
                persisted_matches_active,
                persisted_updated_at,
                kind,
                info.clone(),
            ))
        });
        let persisted_candidates = self
            .persisted_agent_aux
            .values()
            .filter(|entry| !visible_on_parent_restore_only || entry.visible)
            .filter(|entry| !live_keys.contains(&entry.agent))
            .filter(|entry| desired_kind.is_none_or(|desired_kind| desired_kind == entry.kind))
            .filter(|entry| self.persisted_auxiliary_matches_active(entry, active_info))
            .map(|entry| {
                (
                    true,
                    entry.updated_at_epoch_s,
                    entry.kind,
                    session_info_for_persisted_agent_auxiliary(entry),
                )
            });
        live_candidates
            .chain(persisted_candidates)
            .max_by_key(|(persisted, persisted_updated_at, _, info)| {
                (
                    *persisted,
                    *persisted_updated_at,
                    info.updated_at_epoch_s,
                    info.session_id.clone(),
                )
            })
            .map(|(_, _, kind, info)| (kind, info))
    }

    fn agent_aux_parent_matches(&self, left: &AgentKey, right: &AgentKey) -> bool {
        if self.agent_keys_match_or_alias(left, right) {
            return true;
        }
        let Some(left_info) = self.agent_info_for_auxiliary_parent_key(left) else {
            return false;
        };
        let Some(right_info) = self.agent_info_for_auxiliary_parent_key(right) else {
            return false;
        };
        coding_agent_auxiliary_parent_infos_match(left_info, right_info)
    }

    fn agent_keys_match_or_alias(&self, left: &AgentKey, right: &AgentKey) -> bool {
        left == right
            || self
                .new_agent_backing_aliases
                .get(left)
                .is_some_and(|alias| alias == right)
            || self
                .new_agent_backing_aliases
                .get(right)
                .is_some_and(|alias| alias == left)
    }

    fn show_auxiliary_agent(
        &mut self,
        mut aux: AgentAuxPane,
        viewport: AgentViewport,
        reason: &'static str,
    ) {
        let label = live_agent_status_label(&aux.agent.info);
        let kind = aux.kind;
        let parent = aux.parent.clone();
        let key = AgentKey::new(&aux.agent.info);
        let focus_before = self.agent_focus;
        let hidden_before = self.hidden_agent_aux.len();
        let persisted_before = self.persisted_agent_aux.len();
        aux.agent.resize(viewport.pty_cols, viewport.pty_rows);
        self.remember_active_auxiliary_parent_info(&parent);
        self.remember_live_info_locally(&aux.agent.info.clone());
        self.remember_persisted_agent_auxiliary(kind, &parent, &aux.agent.info, true, reason);
        self.agent_aux = Some(aux);
        self.set_agent_focus(AgentFocusPane::Auxiliary);
        self.status = format!("right {} shown", label);
        debug_log(
            "agent_auxiliary_shown",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "key": agent_key_debug_value(&key),
                "viewport": agent_viewport_debug_value(viewport),
                "focus_before": format!("{:?}", focus_before),
                "focus_after": format!("{:?}", self.agent_focus),
                "hidden_before": hidden_before,
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_before": persisted_before,
                "persisted_after": self.persisted_agent_aux.len(),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn restore_hidden_auxiliary_for_active_agent(
        &mut self,
        total_width: u16,
        terminal_rows: u16,
        reason: &'static str,
    ) -> bool {
        if self.agent_aux.is_some() || !self.active_main_agent_is_coding() {
            return false;
        }
        let Some(active_info) = self.active_agent.as_ref().map(|agent| agent.info.clone()) else {
            return false;
        };
        let parent = self.remember_auxiliary_parent_info(&active_info);
        let viewports = agent_viewports_for_terminal(
            total_width,
            terminal_rows,
            self.agent_sidebar_config_width(),
            true,
            self.agent_aux_width,
        );
        let Some(aux_viewport) = viewports.auxiliary else {
            debug_log(
                "agent_auxiliary_restore_skipped",
                serde_json::json!({
                    "reason": reason,
                    "parent": agent_key_debug_value(&parent),
                    "terminal_cols": total_width,
                    "terminal_rows": terminal_rows,
                    "cause": "narrow_terminal",
                }),
            );
            return false;
        };
        let Some(mut aux) = self.take_latest_visible_hidden_auxiliary_agent(&parent) else {
            if self.restore_visible_live_auxiliary_for_active_agent(
                &active_info,
                &parent,
                aux_viewport,
                reason,
            ) {
                return true;
            }
            debug_log(
                "agent_auxiliary_restore_skipped",
                serde_json::json!({
                    "reason": reason,
                    "parent": agent_key_debug_value(&parent),
                    "active_info": session_info_debug_value(&active_info),
                    "cause": "no_hidden_match",
                    "hidden": self.hidden_agent_aux_debug_values(),
                    "live_auxiliary_candidates": self.live_auxiliary_restore_candidate_entries_debug_value(&active_info),
                    "aliases": agent_alias_entries_debug_value(&self.new_agent_backing_aliases),
                }),
            );
            return false;
        };
        let kind = aux.kind;
        let previous_parent = aux.parent.clone();
        aux.parent = parent.clone();
        if previous_parent != parent {
            if let Some(focus) = self.agent_focus_by_agent.get(&previous_parent).copied() {
                self.agent_focus_by_agent
                    .entry(parent.clone())
                    .or_insert(focus);
            }
        }
        aux.agent
            .resize(aux_viewport.pty_cols, aux_viewport.pty_rows);
        self.remember_live_info_locally(&aux.agent.info.clone());
        self.agent_aux = Some(aux);
        let _ = self.sync_agent_viewports(total_width, terminal_rows);
        debug_log(
            "agent_auxiliary_restored_for_active",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "previous_parent": agent_key_debug_value(&previous_parent),
                "key": self.agent_aux.as_ref().map(|aux| agent_key_debug_value(&AgentKey::new(&aux.agent.info))),
                "viewport": agent_viewport_debug_value(aux_viewport),
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_after": self.persisted_agent_aux.len(),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        true
    }

    fn restore_visible_live_auxiliary_for_active_agent(
        &mut self,
        active_info: &SessionInfo,
        parent: &AgentKey,
        aux_viewport: AgentViewport,
        reason: &'static str,
    ) -> bool {
        self.restore_live_auxiliary_for_active_agent_matching(
            active_info,
            parent,
            aux_viewport,
            reason,
            None,
            true,
        )
    }

    fn restore_live_auxiliary_kind_for_active_agent(
        &mut self,
        kind: AgentAuxKind,
        active_info: &SessionInfo,
        parent: &AgentKey,
        aux_viewport: AgentViewport,
        reason: &'static str,
    ) -> bool {
        self.restore_live_auxiliary_for_active_agent_matching(
            active_info,
            parent,
            aux_viewport,
            reason,
            Some(kind),
            false,
        )
    }

    fn restore_live_auxiliary_for_active_agent_matching(
        &mut self,
        active_info: &SessionInfo,
        parent: &AgentKey,
        aux_viewport: AgentViewport,
        reason: &'static str,
        desired_kind: Option<AgentAuxKind>,
        visible_on_parent_restore_only: bool,
    ) -> bool {
        let candidate = self.live_auxiliary_restore_candidate_for_active_agent_matching(
            active_info,
            desired_kind,
            visible_on_parent_restore_only,
        );
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "agent_auxiliary_restore_candidates_evaluated",
                serde_json::json!({
                    "reason": reason,
                    "parent": agent_key_debug_value(parent),
                    "active_info": session_info_debug_value(active_info),
                    "desired_kind": desired_kind.map(|kind| kind.label()),
                    "visible_on_parent_restore_only": visible_on_parent_restore_only,
                    "cols": aux_viewport.pty_cols,
                    "rows": aux_viewport.pty_rows,
                    "candidates": self.live_auxiliary_restore_candidate_entries_debug_value(active_info),
                    "selected": candidate.as_ref().map(|(kind, info)| serde_json::json!({
                        "kind": kind.label(),
                        "info": session_info_debug_value(info),
                    })),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
        }
        let Some((kind, info)) = candidate else {
            return false;
        };
        let key = AgentKey::new(&info);
        let cwd_label = truncate_width(&display_cwd_str(&info.cwd), 40);
        self.status = format!("restoring right {} at {}...", kind.label(), cwd_label);
        debug_log(
            "agent_auxiliary_restore_live_start",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(parent),
                "active_info": session_info_debug_value(active_info),
                "candidate": session_info_debug_value(&info),
                "cols": aux_viewport.pty_cols,
                "rows": aux_viewport.pty_rows,
            }),
        );
        self.request_attach(AttachJob {
            info,
            cols: aux_viewport.pty_cols,
            rows: aux_viewport.pty_rows,
            kind: AttachJobKind::Existing,
            run_prechecks: false,
            prompt_for_saved_data: false,
            settings: self.settings.clone(),
            ctx: AttachUiCtx {
                key,
                target: AttachTarget::Auxiliary {
                    kind,
                    parent: parent.clone(),
                },
                status_attached: format!("restored right {} at {}", kind.label(), cwd_label),
                status_started: format!("restored right {} at {}", kind.label(), cwd_label),
                status_err_prefix: format!("right {} restore failed: ", kind.label()),
                status_prepare_err_prefix: format!("right {} restore failed: ", kind.label()),
                focus_auxiliary_on_ready: false,
                main_focus_override_on_ready: None,
                select_visible: false,
                cokacdir_dialog_on_error: false,
                remove_dead_on_notfound: true,
                log_origin: Some(format!("agent_auxiliary_restore:{}", kind.label())),
                ready_event: "agent_auxiliary_restore_live_ready",
                failed_event: "agent_auxiliary_restore_live_failed",
            },
        });
        true
    }

    fn set_auxiliary_agent(&mut self, kind: AgentAuxKind, parent: AgentKey, agent: AgentClient) {
        let key = AgentKey::new(&agent.info);
        let visible_before = self.agent_aux.as_ref().map(agent_aux_pane_debug_value);
        let hidden_before = self.hidden_agent_aux.len();
        let persisted_before = self.persisted_agent_aux.len();
        let focus_before = self.agent_focus;
        if self
            .agent_aux
            .as_ref()
            .is_some_and(|aux| AgentKey::new(&aux.agent.info) != key)
        {
            let _ = self.hide_auxiliary_agent("replace_attached", false);
        } else if self.agent_aux.is_some() {
            let _ = self.agent_aux.take();
        }
        self.remember_active_auxiliary_parent_info(&parent);
        let info = agent.info.clone();
        self.remember_live_info_locally(&info);
        let removed_hidden = self.remove_hidden_auxiliary_for_parent(kind, &parent);
        self.remember_persisted_agent_auxiliary(kind, &parent, &info, true, "set_attached");
        self.agent_aux = Some(AgentAuxPane {
            kind,
            parent: parent.clone(),
            agent,
        });
        debug_log(
            "agent_auxiliary_set_attached",
            serde_json::json!({
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "key": agent_key_debug_value(&key),
                "info": session_info_debug_value(&info),
                "visible_before": visible_before,
                "removed_hidden": removed_hidden,
                "focus_before": format!("{:?}", focus_before),
                "focus_after": format!("{:?}", self.agent_focus),
                "hidden_before": hidden_before,
                "hidden_after": self.hidden_agent_aux.len(),
                "persisted_before": persisted_before,
                "persisted_after": self.persisted_agent_aux.len(),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn toggle_auxiliary_agent_panel(
        &mut self,
        kind: AgentAuxKind,
        total_width: u16,
        terminal_rows: u16,
    ) {
        debug_log(
            "agent_auxiliary_toggle_requested",
            serde_json::json!({
                "kind": kind.label(),
                "terminal_cols": total_width,
                "terminal_rows": terminal_rows,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if !self.active_main_agent_is_coding() {
            self.status = format!(
                "right {} panel is available from Codex, Claude, or OpenCode.",
                kind.label()
            );
            debug_log(
                "agent_auxiliary_toggle_skipped",
                serde_json::json!({
                    "kind": kind.label(),
                    "reason": "active_main_agent_not_coding",
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        }
        let Some(active_info) = self.active_agent.as_ref().map(|agent| agent.info.clone()) else {
            self.status = format!("no active agent for right {} panel.", kind.label());
            debug_log(
                "agent_auxiliary_toggle_skipped",
                serde_json::json!({
                    "kind": kind.label(),
                    "reason": "no_active_agent",
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        };
        let parent = self.remember_auxiliary_parent_info(&active_info);
        let visible_same_panel = self.agent_aux.as_ref().is_some_and(|aux| {
            aux.kind == kind && self.agent_aux_parent_matches(&aux.parent, &parent)
        });
        if visible_same_panel {
            debug_log(
                "agent_auxiliary_toggle_hide_visible",
                serde_json::json!({
                    "kind": kind.label(),
                    "parent": agent_key_debug_value(&parent),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            let _ = self.hide_auxiliary_agent("toggle", false);
            return;
        }

        let viewports = agent_viewports_for_terminal(
            total_width,
            terminal_rows,
            self.agent_sidebar_config_width(),
            true,
            self.agent_aux_width,
        );
        let Some(aux_viewport) = viewports.auxiliary else {
            self.status = "terminal is too narrow for a right panel.".into();
            debug_log(
                "agent_auxiliary_toggle_skipped",
                serde_json::json!({
                    "kind": kind.label(),
                    "reason": "narrow_terminal",
                    "terminal_cols": total_width,
                    "terminal_rows": terminal_rows,
                    "viewports": agent_viewports_debug_value(viewports),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        };
        if let Some(aux) = self.take_hidden_auxiliary_agent(kind, &parent) {
            if self.agent_aux.is_some() {
                let _ = self.hide_auxiliary_agent("switch", false);
            }
            debug_log(
                "agent_auxiliary_toggle_restore_hidden",
                serde_json::json!({
                    "kind": kind.label(),
                    "parent": agent_key_debug_value(&parent),
                    "viewport": agent_viewport_debug_value(aux_viewport),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.show_auxiliary_agent(aux, aux_viewport, "toggle_restore");
            return;
        }

        if self.restore_live_auxiliary_kind_for_active_agent(
            kind,
            &active_info,
            &parent,
            aux_viewport,
            "toggle_restore_live",
        ) {
            if self.agent_aux.is_some() {
                let _ = self.hide_auxiliary_agent("switch", false);
            }
            return;
        }

        let Some(cwd) = self.active_agent_current_cwd() else {
            self.status = format!("no cwd to open right {} panel at.", kind.label());
            debug_log(
                "agent_auxiliary_toggle_skipped",
                serde_json::json!({
                    "kind": kind.label(),
                    "reason": "no_active_cwd",
                    "parent": agent_key_debug_value(&parent),
                    "active_info": session_info_debug_value(&active_info),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        };
        if self.agent_aux.is_some() {
            let _ = self.hide_auxiliary_agent("switch", false);
        }

        let info = match kind {
            AgentAuxKind::Cokacdir => cokacdir_session_info_for_cwd(cwd.clone()),
            AgentAuxKind::Terminal => shell_session_info_for_cwd(cwd.clone()),
        };
        let key = AgentKey::new(&info);
        let cwd_label = truncate_width(&display_cwd_str(&cwd), 40);
        self.status = format!("opening right {} at {}...", kind.label(), cwd_label);
        debug_log(
            "agent_auxiliary_open_start",
            serde_json::json!({
                "kind": kind.label(),
                "cwd": &cwd,
                "cols": aux_viewport.pty_cols,
                "rows": aux_viewport.pty_rows,
            }),
        );
        self.request_attach(AttachJob {
            info,
            cols: aux_viewport.pty_cols,
            rows: aux_viewport.pty_rows,
            kind: AttachJobKind::OrStart {
                launch_mode: AgentLaunchMode::Normal,
            },
            run_prechecks: kind == AgentAuxKind::Cokacdir,
            prompt_for_saved_data: false,
            settings: self.settings.clone(),
            ctx: AttachUiCtx {
                key,
                target: AttachTarget::Auxiliary { kind, parent },
                status_attached: format!("attached right {} at {}", kind.label(), cwd_label),
                status_started: format!("started right {} at {}", kind.label(), cwd_label),
                status_err_prefix: format!("right {} open failed: ", kind.label()),
                status_prepare_err_prefix: format!("right {} prepare failed: ", kind.label()),
                focus_auxiliary_on_ready: true,
                main_focus_override_on_ready: None,
                select_visible: false,
                cokacdir_dialog_on_error: kind == AgentAuxKind::Cokacdir,
                remove_dead_on_notfound: false,
                log_origin: Some(format!("agent_auxiliary:{}", kind.label())),
                ready_event: "agent_auxiliary_open_ready",
                failed_event: "agent_auxiliary_open_failed",
            },
        });
    }

    fn adjust_sessions_pane_width(&mut self, delta: i16, total_width: u16) {
        let (next, limited) = adjusted_sessions_pane_width(
            self.settings.cokacmux.sessions_pane_width,
            total_width,
            self.settings.cokacmux.sessions_pane_percent,
            delta,
        );
        if limited {
            let preview = total_width.saturating_sub(next);
            self.status = format!(
                "layout limit: sessions {} cols, preview {} cols",
                next, preview
            );
            debug_log(
                "sessions_pane_resize_limited",
                serde_json::json!({
                    "next": next,
                    "preview": preview,
                    "total_width": total_width,
                    "delta": delta,
                }),
            );
            return;
        }

        self.settings.cokacmux.sessions_pane_width = Some(next);
        match self.settings.save() {
            Ok(()) => {
                let preview = total_width.saturating_sub(next);
                self.status = format!(
                    "layout saved: sessions {} cols, preview {} cols",
                    next, preview
                );
                debug_log(
                    "sessions_pane_resize_saved",
                    serde_json::json!({
                        "sessions": next,
                        "preview": preview,
                        "total_width": total_width,
                        "delta": delta,
                    }),
                );
            }
            Err(e) => {
                self.status = format!("layout changed, save failed: {}", e);
                debug_log(
                    "sessions_pane_resize_save_failed",
                    serde_json::json!({
                        "sessions": next,
                        "total_width": total_width,
                        "delta": delta,
                        "error": e.to_string(),
                    }),
                );
            }
        }
        self.clear_preview_cache();
    }

    fn adjust_agent_sidebar_width(&mut self, delta: i16, total_width: u16) {
        let was_hidden = !self.settings.cokacmux.agent_sidebar_visible;
        let current_width = if was_hidden {
            0
        } else {
            self.agent_sidebar_config_width()
        };
        let (next, limited) = adjusted_agent_sidebar_width(current_width, total_width, delta);
        if limited {
            self.status = format!("layout limit: agent sidebar {} cols", next);
            debug_log(
                "agent_sidebar_resize_limited",
                serde_json::json!({
                    "next": next,
                    "total_width": total_width,
                    "delta": delta,
                }),
            );
            return;
        }

        self.settings.cokacmux.agent_sidebar_width = next;
        if was_hidden && next > 0 {
            self.settings.cokacmux.agent_sidebar_visible = true;
        }
        match self.settings.save() {
            Ok(()) => {
                self.status = if was_hidden && self.settings.cokacmux.agent_sidebar_visible {
                    format!("layout saved: agent sidebar shown at {} cols", next)
                } else {
                    format!("layout saved: agent sidebar {} cols", next)
                };
                debug_log(
                    "agent_sidebar_resize_saved",
                    serde_json::json!({
                        "next": next,
                        "visible": self.settings.cokacmux.agent_sidebar_visible,
                        "total_width": total_width,
                        "delta": delta,
                    }),
                );
            }
            Err(e) => {
                self.status = format!("layout changed, save failed: {}", e);
                debug_log(
                    "agent_sidebar_resize_save_failed",
                    serde_json::json!({
                        "next": next,
                        "visible": self.settings.cokacmux.agent_sidebar_visible,
                        "total_width": total_width,
                        "delta": delta,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn resize_focused_agent_pane(&mut self, delta: i16, total_width: u16) {
        let left_visible = self.agent_sidebar_config_width() > 0;
        let right_visible = self.agent_aux.is_some();
        match self.agent_focus {
            AgentFocusPane::Sidebar => {
                self.adjust_agent_sidebar_width(delta, total_width);
            }
            AgentFocusPane::Auxiliary => {
                self.adjust_agent_auxiliary_width(-delta, total_width);
            }
            AgentFocusPane::Main => match (left_visible, right_visible) {
                (true, true) => {
                    self.status = "focus a side panel to resize.".into();
                }
                (true, false) => {
                    self.adjust_agent_sidebar_width(delta, total_width);
                }
                (false, true) => {
                    self.adjust_agent_auxiliary_width(-delta, total_width);
                }
                (false, false) => {
                    self.adjust_agent_sidebar_width(delta, total_width);
                }
            },
        }
    }

    fn adjust_agent_auxiliary_width(&mut self, delta: i16, total_width: u16) {
        if self.agent_aux.is_none() {
            self.status = "right panel is not open.".into();
            return;
        }
        let sidebar_width = agent_sidebar_width(total_width, self.agent_sidebar_config_width());
        let content_width = total_width.saturating_sub(sidebar_width);
        let (next, limited) =
            adjusted_agent_auxiliary_width(self.agent_aux_width, content_width, delta);
        if limited {
            self.status = format!("layout limit: right panel {} cols", next);
            debug_log(
                "agent_auxiliary_resize_limited",
                serde_json::json!({
                    "next": next,
                    "content_width": content_width,
                    "total_width": total_width,
                    "delta": delta,
                }),
            );
            return;
        }
        self.agent_aux_width = Some(next);
        self.settings.cokacmux.agent_aux_width = Some(next);
        let main = content_width.saturating_sub(next);
        match self.settings.save() {
            Ok(()) => {
                self.status = format!("layout saved: agent {} cols, right {} cols", main, next);
                debug_log(
                    "agent_auxiliary_resize_saved",
                    serde_json::json!({
                        "next": next,
                        "main": main,
                        "content_width": content_width,
                        "total_width": total_width,
                        "delta": delta,
                    }),
                );
            }
            Err(e) => {
                self.status = format!("layout changed, save failed: {}", e);
                debug_log(
                    "agent_auxiliary_resize_save_failed",
                    serde_json::json!({
                        "next": next,
                        "main": main,
                        "content_width": content_width,
                        "total_width": total_width,
                        "delta": delta,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn refresh(&mut self) {
        debug_log(
            "sessions_refresh_start",
            serde_json::json!({
                "session_view": self.session_view.label(),
                "session_scope": self.session_scope.label(),
                "provider_filter": self.provider_filter.label(),
                "text_filter": &self.text_filter,
            }),
        );
        match session::list_all() {
            Ok(all) => {
                let clone_links = session::clone_tree::load_links().map_err(|e| e.to_string());
                self.apply_session_refresh(all, clone_links);
            }
            Err(e) => {
                self.status = format!("list error: {}", e);
                debug_log(
                    "sessions_refresh_failed",
                    serde_json::json!({
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn request_session_refresh(&mut self) {
        self.request_session_refresh_with_context(Some("refreshing sessions..."), None, None);
    }

    fn request_session_refresh_preserving_status(&mut self) {
        self.request_session_refresh_with_context(None, None, None);
    }

    fn request_session_refresh_with_context(
        &mut self,
        pending_status: Option<&'static str>,
        restore_key: Option<AgentKey>,
        preserve_status: Option<String>,
    ) {
        if self.session_refresh_pending {
            if pending_status.is_some() {
                self.status = "refresh already running".to_string();
            }
            debug_log(
                "sessions_refresh_request_ignored",
                serde_json::json!({
                    "reason": "pending",
                    "seq": self.session_refresh_seq,
                    "preserve_status": preserve_status.is_some(),
                    "restore_key": restore_key.as_ref().map(agent_key_debug_value),
                }),
            );
            return;
        }
        self.session_refresh_seq = self.session_refresh_seq.saturating_add(1);
        let seq = self.session_refresh_seq;
        let Some(tx) = self.main_tx.clone() else {
            self.refresh();
            if let Some(key) = restore_key.as_ref() {
                self.restore_visible_selection(key);
            }
            if let Some(status) = preserve_status {
                self.status = status;
            }
            return;
        };
        self.session_refresh_pending = true;
        self.session_refresh_started_at = Some(Instant::now());
        self.session_refresh_show_overlay = pending_status.is_some();
        self.session_refresh_restore_key = restore_key;
        self.session_refresh_preserve_status = preserve_status;
        if let Some(status) = pending_status {
            self.status = status.to_string();
        }
        debug_log(
            "sessions_refresh_request",
            serde_json::json!({
                "seq": seq,
                "session_view": self.session_view.label(),
                "session_scope": self.session_scope.label(),
                "provider_filter": self.provider_filter.label(),
                "text_filter": &self.text_filter,
                "preserve_status": self.session_refresh_preserve_status.is_some(),
                "restore_key": self.session_refresh_restore_key.as_ref().map(agent_key_debug_value),
            }),
        );
        match thread::Builder::new()
            .name("cokacmux-refresh".to_string())
            .spawn(move || {
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let started = Instant::now();
                    let sessions = session::list_all().map_err(|e| e.to_string());
                    let clone_links = if sessions.is_ok() {
                        session::clone_tree::load_links().map_err(|e| e.to_string())
                    } else {
                        Ok(Vec::new())
                    };
                    SessionRefreshResult {
                        seq,
                        sessions,
                        clone_links,
                        elapsed_ms: started.elapsed().as_millis(),
                        queued_at_epoch_ms: current_epoch_ms(),
                    }
                }));
                let event = match outcome {
                    Ok(result) => MainEvent::SessionRefreshResult(result),
                    Err(_) => background_worker_panicked(BackgroundWorkerKind::SessionRefresh, seq),
                };
                let _ = tx.send(event);
            }) {
            Ok(_) => {}
            Err(e) => {
                self.session_refresh_pending = false;
                self.session_refresh_started_at = None;
                self.session_refresh_show_overlay = false;
                self.session_refresh_restore_key = None;
                self.session_refresh_preserve_status = None;
                self.status = format!(
                    "refresh worker failed: {}",
                    truncate_width(&e.to_string(), 80)
                );
                debug_log(
                    "sessions_refresh_spawn_failed",
                    serde_json::json!({
                        "seq": seq,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn on_session_refresh_result(&mut self, result: SessionRefreshResult) {
        if !self.session_refresh_pending || result.seq != self.session_refresh_seq {
            debug_log(
                "sessions_refresh_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "current_seq": self.session_refresh_seq,
                    "pending": self.session_refresh_pending,
                    "reason": "stale",
                }),
            );
            return;
        }
        self.session_refresh_pending = false;
        self.session_refresh_started_at = None;
        self.session_refresh_show_overlay = false;
        let restore_key = self.session_refresh_restore_key.take();
        let preserve_status = self.session_refresh_preserve_status.take();
        match result.sessions {
            Ok(all) => {
                self.apply_session_refresh(all, result.clone_links);
                let restored_key = restore_key
                    .as_ref()
                    .is_some_and(|key| self.restore_visible_selection(key));
                let preserved_status = preserve_status.is_some();
                if let Some(status) = preserve_status {
                    self.status = status;
                }
                debug_log(
                    "sessions_refresh_async_ok",
                    serde_json::json!({
                        "seq": result.seq,
                        "elapsed_ms": result.elapsed_ms,
                        "sessions": self.sessions.len(),
                        "visible": self.visible().len(),
                        "restored_key": restored_key,
                        "preserved_status": preserved_status,
                    }),
                );
            }
            Err(e) => {
                self.status = format!("list error: {}", e);
                debug_log(
                    "sessions_refresh_failed",
                    serde_json::json!({
                        "seq": result.seq,
                        "elapsed_ms": result.elapsed_ms,
                        "error": e,
                    }),
                );
            }
        }
    }

    fn on_background_worker_failed(&mut self, failure: BackgroundWorkerFailure) {
        let reclaimed_abandoned_worker = match failure.kind {
            BackgroundWorkerKind::RuntimeRefresh => {
                self.reclaim_abandoned_runtime_worker(failure.seq, "panic")
            }
            BackgroundWorkerKind::LiveShellDiscovery => {
                self.reclaim_abandoned_live_shell_discovery(failure.seq, "panic")
            }
            _ => false,
        };
        if reclaimed_abandoned_worker {
            debug_log(
                "background_worker_panicked_after_watchdog_expiry",
                serde_json::json!({
                    "kind": failure.kind.label(),
                    "seq": failure.seq,
                    "cached_live_shells_preserved": self.live_shells.len(),
                    "cached_agent_states_preserved": self.agent_states.len(),
                }),
            );
            return;
        }
        let mut handled = true;
        let mut show_status = true;
        let mut requeued_runtime_refresh = false;
        match failure.kind {
            BackgroundWorkerKind::AiTitle => {
                if self
                    .ai_title_pending
                    .as_ref()
                    .is_some_and(|pending| pending.seq == failure.seq)
                {
                    self.ai_title_pending = None;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::SessionRefresh => {
                if self.session_refresh_pending && self.session_refresh_seq == failure.seq {
                    self.session_refresh_pending = false;
                    self.session_refresh_started_at = None;
                    self.session_refresh_show_overlay = false;
                    self.session_refresh_restore_key = None;
                    self.session_refresh_preserve_status = None;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::Search => {
                if self
                    .search_pending
                    .as_ref()
                    .is_some_and(|pending| pending.seq == failure.seq)
                {
                    self.search_pending = None;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::AiSearch => {
                if self.ai_search_draining_seq == Some(failure.seq) {
                    self.ai_search_draining_seq = None;
                    show_status = false;
                } else if self
                    .ai_search_pending
                    .as_ref()
                    .is_some_and(|pending| pending.seq == failure.seq)
                {
                    self.ai_search_pending = None;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::LiveShellDiscovery => {
                if self.live_shell_discovery_pending && self.live_shell_discovery_seq == failure.seq
                {
                    self.live_shell_discovery_pending = false;
                    self.live_shell_discovery_started_at = None;
                    self.live_shell_discovery_last_slow_log_at = None;
                    self.last_live_shell_discovery = Instant::now();
                    show_status = false;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::RuntimeRefresh => {
                if self.runtime_refresh_pending && self.runtime_refresh_seq == failure.seq {
                    self.runtime_refresh_pending = false;
                    self.runtime_refresh_started_at = None;
                    self.runtime_refresh_pending_discover_live_shells = false;
                    let refresh_queued = self.runtime_refresh_queued;
                    let discover_live_shells = self.runtime_refresh_queued_discover_live_shells;
                    self.runtime_refresh_queued = false;
                    self.runtime_refresh_queued_discover_live_shells = false;
                    show_status = self.pending_runtime_action.is_some();
                    if refresh_queued {
                        self.refresh_agent_runtime_states_with_discovery(discover_live_shells);
                        requeued_runtime_refresh = self.runtime_refresh_pending;
                        if !requeued_runtime_refresh {
                            self.pending_runtime_action = None;
                        }
                    } else {
                        self.pending_runtime_action = None;
                    }
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::NewSessionPrepare => {
                if self
                    .new_session_launch
                    .as_ref()
                    .is_some_and(|pending| pending.seq == failure.seq)
                {
                    self.new_session_launch = None;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::Clone => {
                if self
                    .data_task
                    .as_ref()
                    .is_some_and(|task| task.seq == failure.seq && task.kind == DataTaskKind::Clone)
                {
                    self.data_task = None;
                } else {
                    handled = false;
                }
            }
            BackgroundWorkerKind::Restore => {
                if self.data_task.as_ref().is_some_and(|task| {
                    task.seq == failure.seq && task.kind == DataTaskKind::Restore
                }) {
                    self.data_task = None;
                } else {
                    handled = false;
                }
            }
        }
        if handled && show_status {
            self.status = format!("{} worker panicked", failure.kind.label());
        }
        debug_log(
            "background_worker_panicked",
            serde_json::json!({
                "kind": failure.kind.label(),
                "seq": failure.seq,
                "handled": handled,
                "show_status": show_status,
                "requeued_runtime_refresh": requeued_runtime_refresh,
            }),
        );
    }

    fn apply_session_refresh(
        &mut self,
        all: Vec<SessionInfo>,
        clone_links: std::result::Result<Vec<session::clone_tree::CloneLink>, String>,
    ) {
        let previous_selection = self.current().map(AgentKey::new);
        self.sessions = all.into();
        let clone_tree_error = match clone_links {
            Ok(links) => {
                self.clone_links = links;
                None
            }
            Err(e) => {
                self.clone_links.clear();
                Some(e)
            }
        };
        self.status = if let Some(error) = clone_tree_error {
            format!(
                "{} sessions (clone tree error: {})",
                self.visible().len(),
                error
            )
        } else {
            format!("{} sessions", self.visible().len())
        };
        let restored_previous = previous_selection
            .as_ref()
            .is_some_and(|key| self.restore_visible_selection(key));
        if restored_previous {
            self.preview_scroll = 0;
        } else if !self.visible_rows().is_empty() {
            self.list_state.select(Some(0));
        } else {
            self.list_state.select(None);
        }
        self.clear_preview_cache();
        self.preview_scroll = 0;
        self.refresh_agent_runtime_states();
        debug_log(
            "sessions_refresh_ok",
            serde_json::json!({
                "sessions": self.sessions.len(),
                "visible": self.visible().len(),
                "clone_links": self.clone_links.len(),
                "status": &self.status,
            }),
        );
    }

    fn prepare_sessions_view(&mut self, reason: &str) {
        let selected_key = self.current().map(AgentKey::new);
        let previous_status = self.status.clone();
        let active_agent = self
            .active_agent
            .as_ref()
            .map(|agent| session_info_debug_value(&agent.info));
        debug_log(
            "sessions_view_prepare_start",
            serde_json::json!({
                "reason": reason,
                "selected": selected_key.as_ref().map(|key| serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                })),
                "active_agent": active_agent,
                "show_sessions_view": self.show_sessions_view,
                "agent_states_before": agent_state_entries_debug_value(&self.agent_states),
                "live_shells_before": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
            }),
        );

        let active_backing_key = self.active_agent_backing_key();
        let restore_key = active_backing_key.or_else(|| selected_key.clone());
        let restored_now = restore_key
            .as_ref()
            .is_some_and(|key| self.restore_visible_selection(key));
        if let Some(key) = restore_key.as_ref() {
            debug_log(
                "sessions_view_restore_selection",
                serde_json::json!({
                    "key": agent_key_debug_value(key),
                    "restored": restored_now,
                }),
            );
        }
        self.request_session_refresh_with_context(None, restore_key, Some(previous_status));

        debug_log(
            "sessions_view_prepare_queued",
            serde_json::json!({
                "reason": reason,
                "sessions": self.sessions.len(),
                "visible": self.visible().len(),
                "selected": self.current().map(|info| serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                })),
                "status": &self.status,
                "restored_now": restored_now,
                "agent_states_after": agent_state_entries_debug_value(&self.agent_states),
                "live_shells_after": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                "show_sessions_view": self.show_sessions_view,
            }),
        );
    }

    fn active_agent_backing_key(&self) -> Option<AgentKey> {
        let agent = self.active_agent.as_ref()?;
        if !is_new_agent_session_info(&agent.info) {
            return None;
        }
        let synthetic_key = AgentKey::new(&agent.info);
        self.new_agent_backing_aliases.get(&synthetic_key).cloned()
    }

    fn visible(&self) -> Vec<&SessionInfo> {
        self.visible_rows()
            .into_iter()
            .map(|row| row.info)
            .collect()
    }

    fn visible_rows(&self) -> Vec<VisibleSessionRow<'_>> {
        if let Some(results) = &self.ai_search_results {
            let by_key: HashMap<AgentKey, &SessionInfo> = self
                .sessions
                .iter()
                .map(|info| (AgentKey::new(info), info))
                .collect();
            return results
                .hits
                .iter()
                .filter_map(|hit| by_key.get(&hit.key).copied())
                .filter(|info| self.session_scope.includes(info))
                .filter(|info| self.provider_filter.matches(info.provider))
                .map(|info| VisibleSessionRow { info, depth: 0 })
                .collect();
        }
        let text_filter = (!self.text_filter.is_empty()).then(|| self.text_filter.to_lowercase());
        let text_filter = text_filter.as_deref();
        match self.session_view {
            SessionViewMode::List => self
                .sessions
                .iter()
                .filter(|s| self.matches_session_filters(s, text_filter))
                .map(|info| VisibleSessionRow { info, depth: 0 })
                .collect(),
            SessionViewMode::Tree => {
                let mut visible_ancestor_path = Vec::new();
                session::clone_tree::visible_tree_rows(&self.sessions, &self.clone_links, |info| {
                    self.matches_session_filters(info, text_filter)
                })
                .into_iter()
                .filter_map(|row| {
                    visible_ancestor_path.truncate(row.depth);
                    let depth = visible_ancestor_path
                        .iter()
                        .filter(|visible| **visible)
                        .count();
                    let visible = self.session_scope.includes(row.info);
                    visible_ancestor_path.push(visible);
                    visible.then_some(VisibleSessionRow {
                        info: row.info,
                        depth,
                    })
                })
                .collect()
            }
        }
    }

    fn matches_session_filters(&self, s: &SessionInfo, text_filter: Option<&str>) -> bool {
        if !self.session_scope.includes(s) || !self.provider_filter.matches(s.provider) {
            return false;
        }
        let Some(q) = text_filter else {
            return true;
        };
        s.session_id.to_lowercase().contains(q)
            || s.cwd.to_lowercase().contains(q)
            || s.title.as_deref().unwrap_or("").to_lowercase().contains(q)
            || self.text_filter_matches.contains(&AgentKey::new(s))
    }

    fn hidden_non_root_session_count(&self) -> usize {
        if self.session_scope == SessionScope::All {
            return 0;
        }
        self.sessions
            .iter()
            .filter(|info| info.relation.is_some())
            .count()
    }

    fn has_active_session_search(&self) -> bool {
        !self.text_filter.is_empty() || self.ai_search_results.is_some()
    }

    fn clear_session_search_results(&mut self, reason: &'static str) -> bool {
        if !self.has_active_session_search() {
            return false;
        }
        let had_text_filter = !self.text_filter.is_empty();
        let had_ai_results = self.ai_search_results.is_some();
        self.text_filter.clear();
        self.text_filter_matches.clear();
        self.ai_search_results = None;
        self.focus = FocusPane::Sessions;
        self.select_first();
        let visible = self.visible().len();
        self.status = format!("search cleared: {} sessions", visible);
        debug_log(
            "session_search_clear",
            serde_json::json!({
                "reason": reason,
                "had_text_filter": had_text_filter,
                "had_ai_results": had_ai_results,
                "visible": visible,
            }),
        );
        true
    }

    fn begin_filter(&mut self) {
        let draft = self.text_filter.clone();
        let cursor = draft.len();
        self.input_mode = InputMode::Filter { draft, cursor };
        self.focus = FocusPane::Sessions;
        self.status = "search sessions".into();
        debug_log(
            "filter_begin",
            serde_json::json!({
                "existing_query_len": self.text_filter.chars().count(),
            }),
        );
    }

    fn begin_search_choice(&mut self) {
        self.input_mode = InputMode::SearchChoice {
            selected: SEARCH_CHOICE_TEXT,
        };
        self.focus = FocusPane::Sessions;
        self.status = "choose search mode".into();
        debug_log("search_choice_begin", serde_json::json!({}));
    }

    fn begin_ai_search(&mut self) {
        if self.ai_search_pending.is_some() {
            self.status = "AI search already running.".into();
            return;
        }
        if self.ai_search_draining_seq.is_some() {
            self.status = "Previous AI search is still cancelling.".into();
            return;
        }
        let draft = self
            .ai_search_results
            .as_ref()
            .map(|results| results.query.clone())
            .unwrap_or_default();
        let cursor = draft.len();
        self.input_mode = InputMode::AiSearch { draft, cursor };
        self.focus = FocusPane::Sessions;
        self.status = "AI search sessions".into();
        debug_log(
            "ai_search_begin",
            serde_json::json!({
                "existing_query_len": self.ai_search_results.as_ref().map(|results| results.query.chars().count()).unwrap_or(0),
            }),
        );
    }

    fn cancel_pending_search(&mut self, reason: &'static str) -> bool {
        let Some(pending) = self.search_pending.take() else {
            return false;
        };
        pending.cancel.store(true, Ordering::Relaxed);
        debug_log(
            "filter_search_cancel_requested",
            serde_json::json!({
                "seq": pending.seq,
                "query_len": pending.query.chars().count(),
                "reason": reason,
            }),
        );
        true
    }

    fn cancel_pending_ai_search(&mut self, reason: &'static str) -> bool {
        let Some(pending) = self.ai_search_pending.as_mut() else {
            return false;
        };
        pending.cancel.store(true, Ordering::Relaxed);
        pending.phase = AiSearchPhase::Cancelling;
        if pending.cancel_requested {
            self.status = "AI search is cancelling; waiting for worker.".into();
            debug_log(
                "ai_search_cancel_repeated",
                serde_json::json!({
                    "seq": pending.seq,
                    "provider": pending.provider.as_str(),
                    "query_len": pending.query.chars().count(),
                    "reason": reason,
                }),
            );
        } else {
            pending.cancel_requested = true;
            self.status = "AI search cancellation requested.".into();
            debug_log(
                "ai_search_cancel_requested",
                serde_json::json!({
                    "seq": pending.seq,
                    "provider": pending.provider.as_str(),
                    "query_len": pending.query.chars().count(),
                    "reason": reason,
                }),
            );
        }
        true
    }

    fn start_text_search(&mut self, query: String) {
        let query = query.trim().to_string();
        if query.is_empty() {
            self.text_filter.clear();
            self.text_filter_matches.clear();
            self.ai_search_results = None;
            self.cancel_pending_search("clear");
            self.input_mode = InputMode::Normal;
            self.focus = FocusPane::Sessions;
            self.select_first();
            self.status = format!("search cleared: {} sessions", self.visible().len());
            debug_log("filter_clear", serde_json::json!({}));
            return;
        }

        self.search_seq = self.search_seq.saturating_add(1);
        self.ai_search_results = None;
        let seq = self.search_seq;
        let snapshot = ScopedSessionSnapshot::capture(&self.sessions, self.session_scope);
        let total = snapshot.total;
        let cancel = Arc::new(AtomicBool::new(false));
        self.search_pending = Some(SearchPending {
            seq,
            query: query.clone(),
            started_at: Instant::now(),
            processed: 0,
            total,
            hits: 0,
            load_errors: 0,
            cancel: cancel.clone(),
        });
        self.focus = FocusPane::Sessions;
        self.status = format!("searching \"{}\"...", truncate_width(&query, 24));
        debug_log(
            "filter_search_start",
            serde_json::json!({
                "seq": seq,
                "query_len": query.chars().count(),
                "session_scope": self.session_scope.label(),
                "sessions": total,
            }),
        );

        let Some(tx) = self.main_tx.clone() else {
            let hits = session::search_infos_with_cancel(
                snapshot.cloned_sessions(),
                &query,
                true,
                Some(&cancel),
            )
            .map_err(|e| e.to_string());
            self.on_search_result(SearchWorkerResult {
                seq,
                query,
                hits,
                queued_at_epoch_ms: current_epoch_ms(),
            });
            return;
        };
        let worker_query = query.clone();
        match thread::Builder::new()
            .name("cokacmux-search".to_string())
            .spawn(move || {
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let progress_query = worker_query.clone();
                    let mut report_progress = |progress: session::SearchProgress| {
                        if !should_send_search_progress(progress.processed, progress.total) {
                            return;
                        }
                        let _ = tx.send(MainEvent::SearchProgress(SearchProgressEvent {
                            seq,
                            query: progress_query.clone(),
                            processed: progress.processed,
                            total: progress.total,
                            hits: progress.hits,
                            load_errors: progress.load_errors,
                            queued_at_epoch_ms: current_epoch_ms(),
                        }));
                    };
                    let sessions = snapshot.cloned_sessions();
                    let hits = session::search_infos_with_cancel_and_progress(
                        sessions,
                        &worker_query,
                        true,
                        Some(&cancel),
                        &mut report_progress,
                    )
                    .map_err(|e| e.to_string());
                    SearchWorkerResult {
                        seq,
                        query: worker_query,
                        hits,
                        queued_at_epoch_ms: current_epoch_ms(),
                    }
                }));
                let event = match outcome {
                    Ok(result) => MainEvent::SearchResult(result),
                    Err(_) => background_worker_panicked(BackgroundWorkerKind::Search, seq),
                };
                let _ = tx.send(event);
            }) {
            Ok(_) => {}
            Err(e) => {
                self.search_pending = None;
                self.status = format!(
                    "search worker failed: {}",
                    truncate_width(&e.to_string(), 80)
                );
                debug_log(
                    "filter_search_spawn_failed",
                    serde_json::json!({
                        "seq": seq,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn on_search_result(&mut self, result: SearchWorkerResult) {
        let Some(pending) = self.search_pending.as_ref() else {
            debug_log(
                "filter_search_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "reason": "none_pending",
                }),
            );
            return;
        };
        if pending.seq != result.seq || pending.query != result.query {
            debug_log(
                "filter_search_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "pending_seq": pending.seq,
                    "reason": "stale",
                }),
            );
            return;
        }

        self.search_pending = None;
        match result.hits {
            Ok(hits) => self.finish_text_search(result.query, hits),
            Err(e) => {
                self.status = format!("search failed: {}", truncate_width(&e, 80));
                debug_log(
                    "filter_apply_failed",
                    serde_json::json!({
                        "seq": result.seq,
                        "query_len": result.query.chars().count(),
                        "error": e,
                    }),
                );
            }
        }
    }

    fn on_search_progress(&mut self, event: SearchProgressEvent) {
        let Some(pending) = self.search_pending.as_mut() else {
            debug_log(
                "filter_search_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "reason": "none_pending",
                }),
            );
            return;
        };
        if pending.seq != event.seq || pending.query != event.query {
            debug_log(
                "filter_search_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "pending_seq": pending.seq,
                    "reason": "stale",
                }),
            );
            return;
        }
        if pending.total != event.total {
            debug_log(
                "filter_search_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "reason": "snapshot_total_mismatch",
                    "pending_total": pending.total,
                    "event_total": event.total,
                }),
            );
            return;
        }
        pending.processed = event.processed.min(pending.total);
        pending.hits = event.hits;
        pending.load_errors = event.load_errors;
    }

    fn finish_text_search(&mut self, query: String, hits: Vec<session::SearchHit>) {
        let content_match_count = hits.len();
        self.text_filter = query;
        self.text_filter_matches = hits
            .into_iter()
            .map(|hit| AgentKey::new(&hit.info))
            .collect();
        self.input_mode = InputMode::Normal;
        self.focus = FocusPane::Sessions;
        self.select_first();
        let visible = self.visible().len();
        self.status = format!(
            "search \"{}\": {} sessions",
            truncate_width(&self.text_filter, 24),
            visible
        );
        debug_log(
            "filter_apply",
            serde_json::json!({
                "query_len": self.text_filter.chars().count(),
                "content_matches": content_match_count,
                "visible": visible,
            }),
        );
    }

    fn start_ai_search(&mut self, query: String) {
        if self.reject_while_data_task_running("running AI search") {
            return;
        }
        if let Some(pending) = self.ai_title_pending.as_ref() {
            self.status = format!(
                "AI title is running with {}; wait before searching.",
                pending.provider.as_str()
            );
            debug_log(
                "ai_search_request_ignored",
                serde_json::json!({
                    "reason": "ai_title_pending",
                    "title_seq": pending.seq,
                    "provider": pending.provider.as_str(),
                    "session_id": &pending.key.session_id,
                }),
            );
            return;
        }
        if let Some(pending) = self.ai_search_pending.as_ref() {
            self.status = format!(
                "AI search already running with {} ({}s)",
                pending.provider.as_str(),
                pending.started_at.elapsed().as_secs()
            );
            debug_log(
                "ai_search_request_ignored",
                serde_json::json!({
                    "reason": "pending",
                    "seq": pending.seq,
                    "provider": pending.provider.as_str(),
                }),
            );
            return;
        }
        if let Some(search_seq) = self.ai_search_draining_seq {
            self.status = "Previous AI search is still cancelling.".into();
            debug_log(
                "ai_search_request_ignored",
                serde_json::json!({
                    "reason": "draining",
                    "seq": search_seq,
                }),
            );
            return;
        }
        let query = query.trim().to_string();
        if query.is_empty() {
            self.ai_search_results = None;
            self.input_mode = InputMode::Normal;
            self.focus = FocusPane::Sessions;
            self.select_first();
            self.status = format!("AI search cleared: {} sessions", self.visible().len());
            debug_log("ai_search_clear", serde_json::json!({}));
            return;
        }
        let Some(provider) = self.settings.cokacmux.ai.provider else {
            self.status = "choose an AI agent first: press comma.".into();
            debug_log(
                "ai_search_request_ignored",
                serde_json::json!({
                    "reason": "provider_unconfigured",
                    "query_len": query.chars().count(),
                }),
            );
            return;
        };
        let Some(tx) = self.main_tx.clone() else {
            self.status = "AI search unavailable before UI event loop.".into();
            debug_log(
                "ai_search_request_ignored",
                serde_json::json!({
                    "reason": "missing_main_tx",
                    "provider": provider.as_str(),
                }),
            );
            return;
        };

        self.text_filter.clear();
        self.text_filter_matches.clear();
        self.ai_search_results = None;
        self.select_first();
        self.ai_search_seq = self.ai_search_seq.saturating_add(1);
        let seq = self.ai_search_seq;
        let snapshot = ScopedSessionSnapshot::capture(&self.sessions, self.session_scope);
        let total = snapshot.total;
        let agent_programs = self.settings.cokacmux.agent_programs.clone();
        let cancel = Arc::new(AtomicBool::new(false));
        self.ai_search_pending = Some(AiSearchPending {
            seq,
            query: query.clone(),
            provider,
            phase: AiSearchPhase::Preparing,
            indexed: 0,
            total,
            reused: 0,
            written: 0,
            cancel_requested: false,
            cancel: cancel.clone(),
            started_at: Instant::now(),
        });
        self.input_mode = InputMode::Normal;
        self.focus = FocusPane::Sessions;
        self.status = format!(
            "AI searching sessions with {}...",
            ai_title_provider_label(Some(provider))
        );
        debug_log(
            "ai_search_request",
            serde_json::json!({
                "seq": seq,
                "provider": provider.as_str(),
                "query_len": query.chars().count(),
                "sessions": total,
                "session_scope": self.session_scope.label(),
            }),
        );

        match thread::Builder::new()
            .name("cokacmux-ai-search".to_string())
            .spawn(move || {
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let progress_tx = tx.clone();
                    let sessions = snapshot.cloned_sessions();
                    generate_ai_search_worker(
                        seq,
                        query,
                        sessions,
                        snapshot.scope,
                        provider,
                        agent_programs,
                        Some(progress_tx),
                        cancel,
                    )
                }));
                let event = match outcome {
                    Ok(result) => MainEvent::AiSearchResult(result),
                    Err(_) => background_worker_panicked(BackgroundWorkerKind::AiSearch, seq),
                };
                let _ = tx.send(event);
            }) {
            Ok(_) => {}
            Err(e) => {
                self.ai_search_pending = None;
                self.status = format!(
                    "AI search worker failed: {}",
                    truncate_width(&e.to_string(), 80)
                );
                debug_log(
                    "ai_search_spawn_failed",
                    serde_json::json!({
                        "seq": seq,
                        "provider": provider.as_str(),
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn on_ai_search_progress(&mut self, event: AiSearchProgressEvent) {
        let Some(pending) = self.ai_search_pending.as_mut() else {
            debug_log(
                "ai_search_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "reason": "none_pending",
                    "provider": event.provider.as_str(),
                }),
            );
            return;
        };
        if pending.seq != event.seq
            || pending.query != event.query
            || pending.provider != event.provider
        {
            debug_log(
                "ai_search_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "pending_seq": pending.seq,
                    "reason": "stale",
                    "provider": event.provider.as_str(),
                }),
            );
            return;
        }
        if pending.total != event.total {
            debug_log(
                "ai_search_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "reason": "snapshot_total_mismatch",
                    "provider": event.provider.as_str(),
                    "pending_total": pending.total,
                    "event_total": event.total,
                }),
            );
            return;
        }
        pending.indexed = event.indexed.min(pending.total);
        pending.reused = event.reused;
        pending.written = event.written;
        if !pending.cancel_requested {
            pending.phase = event.phase;
        }
    }

    fn on_ai_search_worker_result(&mut self, result: AiSearchWorkerResult) {
        if self.ai_search_draining_seq == Some(result.seq) {
            self.ai_search_draining_seq = None;
            debug_log(
                "ai_search_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "reason": "scope_changed",
                    "provider": result.provider.as_str(),
                }),
            );
            return;
        }
        let Some(pending) = self.ai_search_pending.as_ref() else {
            debug_log(
                "ai_search_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "reason": "none_pending",
                    "provider": result.provider.as_str(),
                }),
            );
            return;
        };
        if pending.seq != result.seq
            || pending.query != result.query
            || pending.provider != result.provider
        {
            debug_log(
                "ai_search_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "pending_seq": pending.seq,
                    "reason": "stale",
                    "provider": result.provider.as_str(),
                }),
            );
            return;
        }
        self.ai_search_pending = None;

        match result.outcome {
            Ok(outcome) => {
                let known_keys: HashSet<AgentKey> =
                    self.sessions.iter().map(AgentKey::new).collect();
                let mut seen = HashSet::new();
                let hits: Vec<AiSearchHit> = outcome
                    .hits
                    .into_iter()
                    .filter(|hit| known_keys.contains(&hit.key))
                    .filter(|hit| seen.insert(hit.key.clone()))
                    .collect();
                self.text_filter.clear();
                self.text_filter_matches.clear();
                self.ai_search_results = Some(AiSearchResults {
                    query: result.query.clone(),
                    hits,
                });
                self.input_mode = InputMode::Normal;
                self.focus = FocusPane::Sessions;
                self.select_first();
                let visible = self.visible().len();
                self.status = format!(
                    "AI search \"{}\": {} sessions (usable {}, reused {}, wrote {})",
                    truncate_width(&result.query, 24),
                    visible,
                    outcome.indexed,
                    outcome.reused,
                    outcome.written
                );
                debug_log(
                    "ai_search_result_ok",
                    serde_json::json!({
                        "seq": result.seq,
                        "provider": result.provider.as_str(),
                        "query_len": result.query.chars().count(),
                        "visible": visible,
                        "indexed": outcome.indexed,
                        "reused": outcome.reused,
                        "written": outcome.written,
                        "elapsed_ms": result.elapsed_ms,
                    }),
                );
            }
            Err(error) => {
                if ai_search_error_is_cancelled(&error) {
                    self.status = if error == AI_SEARCH_CANCELLED_ERROR {
                        "AI search cancelled.".into()
                    } else {
                        let detail = error.strip_prefix("cancelled. ").unwrap_or(error.as_str());
                        format!("AI search cancelled: {}", truncate_width(detail, 100))
                    };
                    debug_log(
                        "ai_search_result_cancelled",
                        serde_json::json!({
                            "seq": result.seq,
                            "provider": result.provider.as_str(),
                            "query_len": result.query.chars().count(),
                            "elapsed_ms": result.elapsed_ms,
                        }),
                    );
                } else {
                    let message = ai_search_failure_notice_message(
                        &result.query,
                        result.provider,
                        &error,
                        result.elapsed_ms,
                    );
                    self.show_notice_overlay("AI search failed", message);
                    debug_log(
                        "ai_search_result_failed",
                        serde_json::json!({
                            "seq": result.seq,
                            "provider": result.provider.as_str(),
                            "query_len": result.query.chars().count(),
                            "error": error,
                            "elapsed_ms": result.elapsed_ms,
                        }),
                    );
                }
            }
        }
    }

    fn next_data_task_seq(&mut self) -> u64 {
        self.data_task_seq = self.data_task_seq.saturating_add(1);
        self.data_task_seq
    }

    fn data_task_status(&self) -> Option<String> {
        let task = self.data_task.as_ref()?;
        let elapsed = task.started_at.elapsed();
        let label = task
            .notice
            .as_deref()
            .or(task.progress_message.as_deref())
            .unwrap_or(&task.label);
        let mut parts = vec![format!(
            "{} {} ({}s)",
            startup_spinner_frame(elapsed),
            label,
            elapsed.as_secs()
        )];
        if let Some(stats) = task.progress_stats.as_ref() {
            parts.push(copy_stats_summary(stats));
        }
        if let Some(percent) =
            copy_percent_summary(task.progress_stats.as_ref(), task.progress_total.as_ref())
        {
            parts.push(percent);
        }
        if task.cancel_requested {
            parts.push("cancelling".to_string());
        }
        Some(parts.join("  "))
    }

    fn ai_title_status(&self) -> Option<String> {
        let pending = self.ai_title_pending.as_ref()?;
        let elapsed = pending.started_at.elapsed();
        Some(format!(
            "{} AI title with {} for {} ({}s)",
            startup_spinner_frame(elapsed),
            pending.provider.as_str(),
            truncate_width(&pending.key.session_id, 14),
            elapsed.as_secs()
        ))
    }

    fn ai_search_status(&self) -> Option<String> {
        let pending = self.ai_search_pending.as_ref()?;
        let elapsed = pending.started_at.elapsed();
        let progress = ai_search_progress_summary(pending)
            .map(|summary| format!("  {}", summary))
            .unwrap_or_default();
        Some(format!(
            "{} AI search {} with {} for \"{}\"{} ({}s)",
            startup_spinner_frame(elapsed),
            pending.phase.label(),
            pending.provider.as_str(),
            truncate_width(&pending.query, 24),
            progress,
            elapsed.as_secs()
        ))
    }

    fn new_session_launch_status(&self) -> Option<String> {
        let pending = self.new_session_launch.as_ref()?;
        Some(format!(
            "{} {} {} ({}s)",
            startup_spinner_frame(pending.started_at.elapsed()),
            pending.stage.label(),
            new_session_launch_target_label(pending.kind, pending.provider),
            pending.started_at.elapsed().as_secs()
        ))
    }

    fn session_refresh_status(&self) -> Option<String> {
        if !self.session_refresh_pending || !self.session_refresh_show_overlay {
            return None;
        }
        let elapsed = self
            .session_refresh_started_at
            .map(|started| started.elapsed())
            .unwrap_or_default();
        Some(format!(
            "{} refreshing sessions ({}s)",
            startup_spinner_frame(elapsed),
            elapsed.as_secs()
        ))
    }

    fn agent_exit_pending_status(&self) -> Option<String> {
        let (target, request, _) = agent_exit_overlay_context(self)?;
        Some(format!(
            "{} {}: {} ({}s)",
            startup_spinner_frame(request.started_at.elapsed()),
            request.phase.label_for(request.kind),
            target,
            request.started_at.elapsed().as_secs()
        ))
    }

    fn killall_pending_status(&self) -> Option<String> {
        let pending = self.killall_pending.as_ref()?;
        Some(format!(
            "{} turning off all running work ({}s)",
            startup_spinner_frame(pending.started_at.elapsed()),
            pending.started_at.elapsed().as_secs()
        ))
    }

    fn display_status(&self) -> String {
        self.data_task_status()
            .or_else(|| self.new_session_launch_status())
            .or_else(|| self.killall_pending_status())
            .or_else(|| self.agent_exit_pending_status())
            .or_else(|| self.session_refresh_status())
            .or_else(|| self.ai_search_status())
            .or_else(|| self.ai_title_status())
            .unwrap_or_else(|| self.status.clone())
    }

    fn show_notice_dialog(&mut self, title: impl Into<String>, message: impl Into<String>) {
        let title = title.into();
        let message = message.into();
        self.status = message.clone();
        self.input_mode = InputMode::Notice { title, message };
    }

    fn show_notice_overlay(&mut self, title: impl Into<String>, message: impl Into<String>) {
        let title = title.into();
        let message = message.into();
        self.status = message
            .lines()
            .find(|line| !line.trim().is_empty())
            .unwrap_or(&message)
            .trim()
            .to_string();
        self.notice_overlay = Some(NoticeDialog {
            title: title.clone(),
            message: message.clone(),
        });
        debug_log(
            "notice_overlay_show",
            serde_json::json!({
                "title": title,
                "message_len": message.chars().count(),
                "input_mode": input_mode_label(&self.input_mode),
            }),
        );
    }

    fn promote_session_status_notice(&mut self) {
        if !matches!(self.input_mode, InputMode::Normal)
            || !self.show_sessions_view
            || self.notice_overlay.is_some()
            || self.status_is_covered_by_session_overlay()
        {
            return;
        }
        let message = self.status.trim().to_string();
        if !Self::session_status_should_open_notice(&message) {
            return;
        }
        let title = Self::session_status_notice_title(&message).to_string();
        self.input_mode = InputMode::Notice { title, message };
    }

    fn status_is_covered_by_session_overlay(&self) -> bool {
        self.data_task.is_some()
            || self.new_session_launch.is_some()
            || self.attach_in_flight.is_some()
            || self.agent_kill_pending.is_some()
            || self.killall_pending.is_some()
            || self.runtime_refresh_pending
            || self.session_refresh_pending
            || self.search_pending.is_some()
            || self.ai_search_pending.is_some()
            || self.ai_title_pending.is_some()
    }

    fn session_status_should_open_notice(message: &str) -> bool {
        if message.is_empty()
            || message == "loading…"
            || message == "cancelled."
            || is_plain_session_count_status(message)
            || is_routine_attach_success_status(message)
            || is_low_value_confirmation_status(message)
            || message.ends_with("...")
            || message.ends_with('…')
        {
            return false;
        }
        if message.starts_with("focus:")
            || message.starts_with("preview:")
            || message.starts_with("Terminal:")
            || message.starts_with("Codex transcript:")
            || message.starts_with("Claude fullscreen:")
            || message.starts_with("OpenCode:")
            || message.starts_with("right ")
            || message.starts_with("hidden right ")
            || message.starts_with("layout ")
            || message.starts_with("agent ")
            || message == "live agents updated."
            || matches!(
                message,
                "settings."
                    | "search sessions"
                    | "choose search mode"
                    | "AI search sessions"
                    | "choose launch mode."
                    | "editing title."
                    | "choose clone option."
                    | "choose what to start."
                    | "agents sidebar focused."
                    | "path edit cancelled."
                    | "path edit done; Enter saves settings."
            )
            || message.starts_with("settings:")
            || message.starts_with("AI agent:")
            || message.starts_with("editing path;")
        {
            return false;
        }
        Self::session_status_is_error_notice(message)
    }

    fn session_status_notice_title(message: &str) -> &'static str {
        if Self::session_status_is_error_notice(message) {
            "Error"
        } else {
            "Notice"
        }
    }

    fn session_status_is_error_notice(message: &str) -> bool {
        let lower = message.to_lowercase();
        lower.contains("failed")
            || lower.contains("error")
            || lower.contains("cannot")
            || lower.contains("blocked")
            || lower.contains("not installed")
            || lower.contains("not ready")
    }

    fn show_cokacdir_error_dialog(&mut self, message: String) {
        self.show_notice_dialog("cokacdir failed", message);
    }

    fn reject_while_data_task_running(&mut self, action: &str) -> bool {
        let Some(task) = self.data_task.as_mut() else {
            return false;
        };
        let notice = format!("{} in progress; wait before {}", task.kind.label(), action);
        self.status = notice.clone();
        task.notice = Some(notice);
        debug_log(
            "data_task_action_blocked",
            serde_json::json!({
                "seq": task.seq,
                "kind": task.kind.label(),
                "action": action,
            }),
        );
        true
    }

    fn on_data_task_progress(&mut self, event: DataTaskProgressEvent) {
        let Some(task) = self.data_task.as_mut() else {
            debug_log(
                "data_task_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "kind": event.kind.label(),
                    "reason": "none_pending",
                }),
            );
            return;
        };
        if task.seq != event.seq || task.kind != event.kind {
            debug_log(
                "data_task_progress_ignored",
                serde_json::json!({
                    "seq": event.seq,
                    "kind": event.kind.label(),
                    "pending_seq": task.seq,
                    "pending_kind": task.kind.label(),
                    "reason": "stale",
                }),
            );
            return;
        }
        task.progress_message = Some(event.message);
        task.progress_path = event.current_path;
        task.progress_stats = event.stats;
        task.progress_total = event.total;
        if !task.cancel_requested {
            task.notice = None;
        }
    }

    fn handle_data_task_key(&mut self, key: KeyEvent) -> bool {
        if self.data_task.is_none() {
            return false;
        };
        let keybindings = self.keybindings.clone();
        let allow_quit_key = keybindings.matches(KeyAction::GlobalQuit, key);
        let task = self.data_task.as_mut().expect("data_task checked above");
        if task.kind != DataTaskKind::Clone {
            if allow_quit_key {
                return false;
            }
            let notice = format!("{} in progress; wait for worker", task.kind.label());
            task.notice = Some(notice.clone());
            self.status = notice;
            debug_log(
                "data_task_input_blocked",
                serde_json::json!({
                    "seq": task.seq,
                    "kind": task.kind.label(),
                    "key": key_code_label(key),
                    "modifiers": format!("{:?}", key.modifiers),
                }),
            );
            return true;
        }

        let is_plain_esc = key.code == KeyCode::Esc && key.modifiers.is_empty();
        if is_plain_esc {
            if !task.cancel_requested {
                if let Some(cancel_token) = task.cancel_token.as_ref() {
                    cancel_token.store(true, Ordering::Relaxed);
                }
                task.cancel_requested = true;
                let notice = "clone cancellation requested; rolling back when safe".to_string();
                task.notice = Some(notice.clone());
                self.status = notice;
                debug_log(
                    "data_task_cancel_requested",
                    serde_json::json!({
                        "seq": task.seq,
                        "kind": task.kind.label(),
                    }),
                );
            } else {
                let notice = "clone cancellation already requested; waiting for worker".to_string();
                task.notice = Some(notice.clone());
                self.status = notice;
                debug_log(
                    "data_task_cancel_repeated",
                    serde_json::json!({
                        "seq": task.seq,
                        "kind": task.kind.label(),
                    }),
                );
            }
        } else {
            let notice = if task.cancel_requested {
                "clone is cancelling; other actions are locked"
            } else {
                "clone in progress; press Esc to cancel"
            }
            .to_string();
            task.notice = Some(notice.clone());
            self.status = notice;
            debug_log(
                "data_task_input_blocked",
                serde_json::json!({
                    "seq": task.seq,
                    "kind": task.kind.label(),
                    "key": key_code_label(key),
                    "modifiers": format!("{:?}", key.modifiers),
                }),
            );
        }
        true
    }

    fn request_quit(&mut self, reason: &str, force: bool) -> bool {
        if !force && self.reject_while_data_task_running("quitting") {
            debug_log(
                "quit_blocked_by_data_task",
                serde_json::json!({
                    "reason": reason,
                }),
            );
            return false;
        }
        if force {
            if let Some(task) = self.data_task.as_ref() {
                debug_log(
                    "quit_forced_during_data_task",
                    serde_json::json!({
                        "reason": reason,
                        "seq": task.seq,
                        "kind": task.kind.label(),
                    }),
                );
            }
        }
        self.should_quit = true;
        debug_log(
            "quit_requested",
            serde_json::json!({
                "reason": reason,
                "force": force,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        true
    }

    fn agent_state_for(&self, info: &SessionInfo) -> AgentListState {
        let key = AgentKey::new(info);
        let trace_enabled = TRACE_ENABLED.load(Ordering::Relaxed);
        if let Some(agent) = self.active_agent.as_ref() {
            if AgentKey::new(&agent.info) == key {
                let cached_state = self.agent_states.get(&key).copied();
                let client_activity = agent.activity();
                let activity = self
                    .agent_states
                    .get(&key)
                    .map(|state| state.activity())
                    .unwrap_or(AgentActivity::Quiet)
                    .combine(client_activity);
                let result = AgentListState::Attached {
                    mine: true,
                    activity,
                };
                if trace_enabled {
                    trace_log(
                        "agent_state_for_active",
                        serde_json::json!({
                            "key": agent_key_debug_value(&key),
                            "info": session_info_debug_value(info),
                            "cached_state": optional_agent_list_state_debug_value(cached_state),
                            "client_activity": client_activity.label(),
                            "result": agent_list_state_debug_value(result),
                            "show_sessions_view": self.show_sessions_view,
                        }),
                    );
                }
                return result;
            }
        }
        let cached_state = self.agent_states.get(&key).copied();
        let result = cached_state.unwrap_or(AgentListState::Idle);
        if trace_enabled {
            trace_log(
                "agent_state_for",
                serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "info": session_info_debug_value(info),
                    "cached_state": optional_agent_list_state_debug_value(cached_state),
                    "result": agent_list_state_debug_value(result),
                    "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                    "show_sessions_view": self.show_sessions_view,
                    "agent_states_len": self.agent_states.len(),
                    "live_shells_len": self.live_shells.len(),
                }),
            );
        }
        result
    }

    fn poll_agent_runtime_states(&mut self) {
        self.maybe_log_slow_pending_runtime_action();
        self.recover_stalled_background_refreshes();
        if self.last_agent_state_poll.elapsed()
            < Duration::from_millis(AGENT_STATE_POLL_INTERVAL_MS)
        {
            return;
        }
        self.poll_live_shell_discovery();
        self.refresh_agent_runtime_states();
    }

    fn recover_stalled_background_refreshes(&mut self) {
        let timeout = Duration::from_millis(BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS);
        if self.expire_stalled_live_shell_discovery(timeout) {
            // This starts a separate observation only.  The timed-out scan is
            // not cancelled and no cached daemon is removed on timeout.
            self.start_live_shell_discovery();
        }

        let Some(discover_live_shells) = self.expire_stalled_runtime_refresh(timeout) else {
            return;
        };
        if self.try_restart_agent_runtime_worker() {
            self.refresh_agent_runtime_states_with_discovery(discover_live_shells);
            return;
        }

        // A deferred UI action must not survive invisibly and fire during an
        // unrelated later refresh if replacement thread creation failed.
        if self.pending_runtime_action.take().is_some() {
            self.pending_runtime_action_last_slow_log_at = None;
            self.status = "agent runtime refresh timed out; try again".into();
        }
    }

    fn expire_stalled_live_shell_discovery(&mut self, timeout: Duration) -> bool {
        let timed_out = self.live_shell_discovery_pending
            && self
                .live_shell_discovery_started_at
                .is_some_and(|started| started.elapsed() >= timeout);
        if !timed_out {
            return false;
        }

        let expired_seq = self.live_shell_discovery_seq;
        let elapsed_ms = self
            .live_shell_discovery_started_at
            .map(|started| started.elapsed().as_millis());
        self.live_shell_discovery_pending = false;
        self.live_shell_discovery_started_at = None;
        self.live_shell_discovery_last_slow_log_at = None;
        self.last_live_shell_discovery = Instant::now();
        self.live_shell_discovery_abandoned_seqs.insert(expired_seq);
        // Invalidate a result that may still arrive from the detached scan,
        // even if spawning the replacement below fails.
        self.live_shell_discovery_seq = self.live_shell_discovery_seq.saturating_add(1);
        debug_log(
            "live_shell_discovery_watchdog_expired",
            serde_json::json!({
                "expired_seq": expired_seq,
                "next_seq_floor": self.live_shell_discovery_seq,
                "elapsed_ms": elapsed_ms,
                "abandoned_workers": self.live_shell_discovery_abandoned_seqs.len(),
                "max_outstanding_workers": BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND,
                "cached_live_shells_preserved": self.live_shells.len(),
                "cached_agent_states_preserved": self.agent_states.len(),
            }),
        );
        true
    }

    fn expire_stalled_runtime_refresh(&mut self, timeout: Duration) -> Option<bool> {
        let timed_out = self.runtime_refresh_pending
            && self
                .runtime_refresh_started_at
                .is_some_and(|started| started.elapsed() >= timeout);
        if !timed_out {
            return None;
        }

        let expired_seq = self.runtime_refresh_seq;
        let elapsed_ms = self
            .runtime_refresh_started_at
            .map(|started| started.elapsed().as_millis());
        let discover_live_shells = self.runtime_refresh_pending_discover_live_shells
            || self.runtime_refresh_queued_discover_live_shells;
        self.runtime_abandoned_worker_seqs.insert(expired_seq);
        self.runtime_tx = None;
        self.runtime_worker_restart_after = Some(Instant::now());
        self.runtime_refresh_pending = false;
        self.runtime_refresh_started_at = None;
        self.runtime_refresh_pending_discover_live_shells = false;
        self.runtime_refresh_queued = false;
        self.runtime_refresh_queued_discover_live_shells = false;
        self.pending_runtime_action_last_slow_log_at = None;
        debug_log(
            "agent_runtime_refresh_watchdog_expired",
            serde_json::json!({
                "expired_seq": expired_seq,
                "elapsed_ms": elapsed_ms,
                "abandoned_workers": self.runtime_abandoned_worker_seqs.len(),
                "max_outstanding_workers": BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND,
                "retry_discover_live_shells": discover_live_shells,
                "pending_runtime_action_preserved": self.pending_runtime_action.is_some(),
                "cached_live_shells_preserved": self.live_shells.len(),
                "cached_agent_states_preserved": self.agent_states.len(),
            }),
        );
        Some(discover_live_shells)
    }

    fn reclaim_abandoned_runtime_worker(&mut self, seq: u64, completion: &str) -> bool {
        if !self.runtime_abandoned_worker_seqs.remove(&seq) {
            return false;
        }
        if self.runtime_tx.is_none() {
            self.runtime_worker_restart_after = Some(Instant::now());
            self.last_agent_state_poll =
                Instant::now() - Duration::from_millis(AGENT_STATE_POLL_INTERVAL_MS);
        }
        debug_log(
            "agent_runtime_abandoned_worker_reclaimed",
            serde_json::json!({
                "seq": seq,
                "completion": completion,
                "abandoned_workers_remaining": self.runtime_abandoned_worker_seqs.len(),
                "replacement_needed": self.runtime_tx.is_none(),
            }),
        );
        true
    }

    fn reclaim_abandoned_live_shell_discovery(&mut self, seq: u64, completion: &str) -> bool {
        if !self.live_shell_discovery_abandoned_seqs.remove(&seq) {
            return false;
        }
        if !self.live_shell_discovery_pending {
            self.last_live_shell_discovery =
                Instant::now() - Duration::from_millis(LIVE_SHELL_DISCOVERY_INTERVAL_MS);
        }
        debug_log(
            "live_shell_discovery_abandoned_worker_reclaimed",
            serde_json::json!({
                "seq": seq,
                "completion": completion,
                "abandoned_workers_remaining": self.live_shell_discovery_abandoned_seqs.len(),
                "replacement_needed": !self.live_shell_discovery_pending,
            }),
        );
        true
    }

    fn poll_live_shell_discovery(&mut self) {
        if self.live_shell_discovery_pending {
            self.maybe_log_slow_live_shell_discovery();
            return;
        }
        if self.last_live_shell_discovery.elapsed()
            < Duration::from_millis(LIVE_SHELL_DISCOVERY_INTERVAL_MS)
        {
            return;
        }
        self.start_live_shell_discovery();
    }

    fn maybe_log_slow_live_shell_discovery(&mut self) {
        let Some(started_at) = self.live_shell_discovery_started_at else {
            return;
        };
        let elapsed = started_at.elapsed();
        if elapsed < Duration::from_millis(LIVE_SHELL_DISCOVERY_SLOW_LOG_MS) {
            return;
        }
        if self
            .live_shell_discovery_last_slow_log_at
            .is_some_and(|last| {
                last.elapsed() < Duration::from_millis(LIVE_SHELL_DISCOVERY_SLOW_LOG_INTERVAL_MS)
            })
        {
            return;
        }
        self.live_shell_discovery_last_slow_log_at = Some(Instant::now());
        debug_log(
            "live_shell_discovery_still_pending",
            serde_json::json!({
                "seq": self.live_shell_discovery_seq,
                "elapsed_ms": elapsed.as_millis(),
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
            }),
        );
    }

    fn start_live_shell_discovery(&mut self) {
        let Some(tx) = self.main_tx.clone() else {
            return;
        };
        let Some((seq, started_at_epoch_ms)) = self.begin_live_shell_discovery_attempt() else {
            return;
        };
        let baseline_keys = self.live_shells.iter().map(AgentKey::new).collect();

        match thread::Builder::new()
            .name("cokacmux-live-discovery".into())
            .spawn(move || {
                let started = Instant::now();
                let scan = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(
                    discover_live_shell_scan,
                )) {
                    Ok(scan) => scan,
                    Err(_) => {
                        let _ = tx.send(background_worker_panicked(
                            BackgroundWorkerKind::LiveShellDiscovery,
                            seq,
                        ));
                        return;
                    }
                };
                let elapsed_ms = started.elapsed().as_millis();
                let live_shell_count = scan.live_shells.len();
                let live_shell_items = DEBUG_ENABLED.load(Ordering::Relaxed).then(|| {
                    scan.live_shells
                        .iter()
                        .map(session_info_debug_value)
                        .collect::<Vec<_>>()
                });
                let scan_complete = scan.complete;
                let uncertain_stem_count = scan.uncertain_stems.len();
                let result_sent = tx
                    .send(MainEvent::LiveShellDiscoveryResult(
                        LiveShellDiscoveryResult {
                            seq,
                            baseline_keys,
                            live_shells: scan.live_shells,
                            scan_complete,
                            uncertain_stems: scan.uncertain_stems,
                            started_at_epoch_ms,
                            queued_at_epoch_ms: current_epoch_ms(),
                            elapsed_ms,
                        },
                    ))
                    .is_ok();
                debug_log(
                    "live_shell_discovery_worker_result",
                    serde_json::json!({
                        "seq": seq,
                        "elapsed_ms": elapsed_ms,
                        "live_shells": live_shell_count,
                        "scan_complete": scan_complete,
                        "uncertain_stems": uncertain_stem_count,
                        "items": live_shell_items,
                        "result_sent": result_sent,
                    }),
                );
            }) {
            Ok(_) => {}
            Err(e) => {
                self.live_shell_discovery_pending = false;
                self.live_shell_discovery_started_at = None;
                self.live_shell_discovery_last_slow_log_at = None;
                self.last_live_shell_discovery = Instant::now();
                debug_log(
                    "live_shell_discovery_spawn_failed",
                    serde_json::json!({
                        "seq": seq,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn begin_live_shell_discovery_attempt(&mut self) -> Option<(u64, u64)> {
        if self.live_shell_discovery_pending
            || self.live_shell_discovery_abandoned_seqs.len()
                >= BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND
        {
            self.last_live_shell_discovery = Instant::now();
            debug_log(
                "live_shell_discovery_capacity_exhausted",
                serde_json::json!({
                    "pending": self.live_shell_discovery_pending,
                    "abandoned_workers": self.live_shell_discovery_abandoned_seqs.len(),
                    "max_outstanding_workers": BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND,
                }),
            );
            return None;
        }
        self.live_shell_discovery_seq = self.live_shell_discovery_seq.saturating_add(1);
        let seq = self.live_shell_discovery_seq;
        let started_at_epoch_ms = current_epoch_ms();
        self.live_shell_discovery_pending = true;
        self.live_shell_discovery_started_at = Some(Instant::now());
        self.live_shell_discovery_last_slow_log_at = None;
        debug_log(
            "live_shell_discovery_requested",
            serde_json::json!({
                "seq": seq,
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
            }),
        );
        Some((seq, started_at_epoch_ms))
    }

    fn refresh_agent_runtime_states(&mut self) {
        self.refresh_agent_runtime_states_with_discovery(false);
    }

    fn refresh_agent_runtime_states_discovering_live_shells(&mut self) {
        self.refresh_agent_runtime_states_with_discovery(true);
    }

    fn try_restart_agent_runtime_worker(&mut self) -> bool {
        self.try_restart_agent_runtime_worker_with(spawn_replacement_agent_runtime_worker)
    }

    fn try_restart_agent_runtime_worker_with<F>(&mut self, spawn: F) -> bool
    where
        F: FnOnce(Sender<MainEvent>) -> io::Result<Sender<AgentRuntimeRefreshRequest>>,
    {
        if self.runtime_tx.is_some() {
            return true;
        }
        let Some(restart_after) = self.runtime_worker_restart_after else {
            return false;
        };
        let now = Instant::now();
        if restart_after > now {
            return false;
        }
        if self.runtime_abandoned_worker_seqs.len() >= BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND {
            self.runtime_worker_restart_after =
                Some(now + Duration::from_millis(RUNTIME_WORKER_RESTART_RETRY_MS));
            debug_log(
                "agent_runtime_worker_restart_capacity_exhausted",
                serde_json::json!({
                    "abandoned_workers": self.runtime_abandoned_worker_seqs.len(),
                    "max_outstanding_workers": BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND,
                    "retry_ms": RUNTIME_WORKER_RESTART_RETRY_MS,
                }),
            );
            return false;
        }
        let Some(result_tx) = self.main_tx.clone() else {
            return false;
        };

        match spawn(result_tx) {
            Ok(request_tx) => {
                self.runtime_tx = Some(request_tx);
                self.runtime_worker_restart_after = None;
                debug_log(
                    "agent_runtime_worker_restarted",
                    serde_json::json!({
                        "runtime_refresh_seq": self.runtime_refresh_seq,
                    }),
                );
                true
            }
            Err(error) => {
                self.runtime_worker_restart_after =
                    Some(Instant::now() + Duration::from_millis(RUNTIME_WORKER_RESTART_RETRY_MS));
                debug_log(
                    "agent_runtime_worker_restart_failed",
                    serde_json::json!({
                        "runtime_refresh_seq": self.runtime_refresh_seq,
                        "retry_ms": RUNTIME_WORKER_RESTART_RETRY_MS,
                        "error": error.to_string(),
                    }),
                );
                false
            }
        }
    }

    fn refresh_agent_runtime_states_with_discovery(&mut self, discover_live_shells: bool) {
        self.last_agent_state_poll = Instant::now();
        if self.runtime_tx.is_none() {
            let _ = self.try_restart_agent_runtime_worker();
        }
        let Some(tx) = self.runtime_tx.clone() else {
            debug_log(
                "agent_runtime_refresh_fallback_without_worker",
                serde_json::json!({
                    "discover_live_shells": discover_live_shells,
                    "snapshot_before": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.overlay_active_agent_runtime_state();
            apply_cached_new_agent_backing_states(
                &self.live_shells,
                &self.new_agent_backing_aliases,
                &mut self.agent_states,
            );
            debug_log(
                "agent_runtime_refresh_fallback_applied",
                serde_json::json!({
                    "snapshot_after": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        };
        if self.runtime_refresh_pending {
            if self.runtime_refresh_pending_discover_live_shells && discover_live_shells {
                debug_log(
                    "agent_runtime_refresh_covered_by_pending_discovery",
                    serde_json::json!({
                        "seq": self.runtime_refresh_seq,
                        "discover_live_shells": discover_live_shells,
                        "pending_discover_live_shells": self.runtime_refresh_pending_discover_live_shells,
                        "queued_discover_live_shells": self.runtime_refresh_queued_discover_live_shells,
                        "pending_elapsed_ms": self.runtime_refresh_started_at.map(|started| started.elapsed().as_millis()),
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                return;
            }
            self.runtime_refresh_queued = true;
            self.runtime_refresh_queued_discover_live_shells |= discover_live_shells;
            debug_log(
                "agent_runtime_refresh_queued",
                serde_json::json!({
                    "seq": self.runtime_refresh_seq,
                    "discover_live_shells": discover_live_shells,
                    "queued_discover_live_shells": self.runtime_refresh_queued_discover_live_shells,
                    "pending_elapsed_ms": self.runtime_refresh_started_at.map(|started| started.elapsed().as_millis()),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        }

        self.runtime_refresh_seq = self.runtime_refresh_seq.saturating_add(1);
        let seq = self.runtime_refresh_seq;
        let request = self.agent_runtime_refresh_request(seq, discover_live_shells);
        match tx.send(request) {
            Ok(()) => {
                self.runtime_refresh_pending = true;
                self.runtime_refresh_started_at = Some(self.last_agent_state_poll);
                self.runtime_refresh_pending_discover_live_shells = discover_live_shells;
                debug_log(
                    "agent_runtime_refresh_requested",
                    serde_json::json!({
                        "seq": seq,
                        "discover_live_shells": discover_live_shells,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
            }
            Err(e) => {
                self.runtime_tx = None;
                self.runtime_worker_restart_after = Some(Instant::now());
                self.runtime_refresh_pending = false;
                self.runtime_refresh_started_at = None;
                self.runtime_refresh_pending_discover_live_shells = false;
                self.runtime_refresh_queued = false;
                self.runtime_refresh_queued_discover_live_shells = false;
                if self.pending_runtime_action.take().is_some() {
                    self.pending_runtime_action_last_slow_log_at = None;
                    self.status = "agent runtime refresh worker stopped; try again".into();
                }
                debug_log(
                    "agent_runtime_refresh_request_failed",
                    serde_json::json!({
                        "seq": seq,
                        "discover_live_shells": discover_live_shells,
                        "error": e.to_string(),
                    }),
                );
            }
        }
    }

    fn agent_runtime_refresh_request(
        &self,
        seq: u64,
        discover_live_shells: bool,
    ) -> AgentRuntimeRefreshRequest {
        let debug_enabled = DEBUG_ENABLED.load(Ordering::Relaxed);
        AgentRuntimeRefreshRequest {
            seq,
            current_pid: std::process::id(),
            discover_live_shells,
            previous_states: self.agent_states.clone(),
            previous_live_shells: self.live_shells.clone(),
            active_info: self.active_agent.as_ref().map(|agent| agent.info.clone()),
            show_sessions_view: self.show_sessions_view,
            provider_session_count: self.sessions.len(),
            session_keys: if debug_enabled {
                self.sessions.iter().map(AgentKey::new).collect()
            } else {
                Vec::new()
            },
            new_agent_backing_aliases: self.new_agent_backing_aliases.clone(),
            new_agent_backing_probe_after: self.new_agent_backing_probe_after.clone(),
        }
    }

    fn maybe_log_ui_stall(
        &mut self,
        event_kind: &'static str,
        reason: &'static str,
        queued_at_epoch_ms: Option<u64>,
        observed_at_epoch_ms: u64,
        queued_latency_ms: Option<u64>,
    ) {
        let Some(latency_ms) = queued_latency_ms else {
            return;
        };
        if !is_ui_stall_latency_ms(latency_ms) {
            return;
        }
        if self
            .last_ui_stall_log_at
            .is_some_and(|last| last.elapsed() < Duration::from_millis(UI_STALL_LOG_COOLDOWN_MS))
        {
            return;
        }

        self.last_ui_stall_log_at = Some(Instant::now());
        self.ui_stall_log_count = self.ui_stall_log_count.saturating_add(1);
        let pending_runtime_action = match self.pending_runtime_action.as_ref() {
            Some(PendingRuntimeAction::LaunchSelected { .. }) => Some("launch_selected"),
            Some(PendingRuntimeAction::RestoreLive { .. }) => Some("restore_live"),
            Some(PendingRuntimeAction::SwitchActive { .. }) => Some("switch_active"),
            None => None,
        };
        let runtime_refresh_pending_elapsed_ms = self
            .runtime_refresh_started_at
            .map(|started_at| started_at.elapsed().as_millis());
        let stalled_since_epoch_ms =
            queued_at_epoch_ms.unwrap_or_else(|| observed_at_epoch_ms.saturating_sub(latency_ms));

        stall_log(
            "ui_stall_detected",
            serde_json::json!({
                "count": self.ui_stall_log_count,
                "kind": event_kind,
                "reason": reason,
                "queued_latency_ms": latency_ms,
                "threshold_ms": UI_STALL_LOG_THRESHOLD_MS,
                "queued_at_epoch_ms": queued_at_epoch_ms,
                "observed_at_epoch_ms": observed_at_epoch_ms,
                "stalled_since_epoch_ms": stalled_since_epoch_ms,
                "agent_view": self.is_agent_view(),
                "show_sessions_view": self.show_sessions_view,
                "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "runtime_refresh_pending": self.runtime_refresh_pending,
                "runtime_refresh_queued": self.runtime_refresh_queued,
                "runtime_refresh_seq": self.runtime_refresh_seq,
                "runtime_refresh_pending_elapsed_ms": runtime_refresh_pending_elapsed_ms,
                "pending_runtime_action": pending_runtime_action,
                "attach_in_flight": self.attach_in_flight.as_ref().map(|attach| {
                    serde_json::json!({
                        "seq": attach.seq,
                        "provider": attach.key.provider.as_str(),
                        "session_id": &attach.key.session_id,
                        "elapsed_ms": attach.started_at.elapsed().as_millis(),
                    })
                }),
                "queued_attach": self.queued_attach.as_ref().map(|job| {
                    serde_json::json!({
                        "provider": job.ctx.key.provider.as_str(),
                        "session_id": &job.ctx.key.session_id,
                    })
                }),
                "sessions_len": self.sessions.len(),
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
            }),
        );
    }

    fn on_runtime_state_result(&mut self, result: AgentRuntimeRefreshResult) {
        let reclaimed_abandoned_worker =
            self.reclaim_abandoned_runtime_worker(result.seq, "result");
        if !self.runtime_refresh_pending || result.seq != self.runtime_refresh_seq {
            debug_log(
                "agent_runtime_refresh_result_ignored",
                serde_json::json!({
                    "seq": result.seq,
                    "current_seq": self.runtime_refresh_seq,
                    "pending": self.runtime_refresh_pending,
                    "reclaimed_abandoned_worker": reclaimed_abandoned_worker,
                    "reason": "stale_or_abandoned_worker",
                    "cached_live_shells_preserved": self.live_shells.len(),
                    "cached_agent_states_preserved": self.agent_states.len(),
                }),
            );
            return;
        }
        self.runtime_refresh_pending = false;
        self.runtime_refresh_started_at = None;
        self.runtime_refresh_pending_discover_live_shells = false;
        let refresh_queued = self.runtime_refresh_queued;
        let refresh_queued_discover_live_shells = self.runtime_refresh_queued_discover_live_shells;
        self.runtime_refresh_queued = false;
        self.runtime_refresh_queued_discover_live_shells = false;
        let result_seq = result.seq;
        debug_log(
            "agent_runtime_refresh_result_received",
            serde_json::json!({
                "seq": result_seq,
                "applied_seq": self.runtime_refresh_applied_seq,
                "refresh_queued": refresh_queued,
                "refresh_queued_discover_live_shells": refresh_queued_discover_live_shells,
                "discover_live_shells": result.discover_live_shells,
                "live_shells_len": result.live_shells.len(),
                "agent_states_len": result.agent_states.len(),
                "snapshot_before": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        let continue_pending_action = !refresh_queued
            || (result.discover_live_shells && !refresh_queued_discover_live_shells);
        if result.seq < self.runtime_refresh_applied_seq {
            debug_log(
                "agent_runtime_refresh_result_stale",
                serde_json::json!({
                    "seq": result.seq,
                    "applied_seq": self.runtime_refresh_applied_seq,
                }),
            );
        } else {
            self.apply_agent_runtime_refresh_result_with_pending(result, continue_pending_action);
        }
        if refresh_queued && !self.runtime_refresh_pending {
            debug_log(
                "agent_runtime_refresh_requeue_after_result",
                serde_json::json!({
                    "seq": result_seq,
                    "reason": "queued_while_result_pending",
                    "discover_live_shells": refresh_queued_discover_live_shells,
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.refresh_agent_runtime_states_with_discovery(refresh_queued_discover_live_shells);
        } else if refresh_queued {
            self.runtime_refresh_queued = true;
            self.runtime_refresh_queued_discover_live_shells |= refresh_queued_discover_live_shells;
        }
        debug_log(
            "agent_runtime_refresh_result_done",
            serde_json::json!({
                "seq": result_seq,
                "runtime_refresh_pending": self.runtime_refresh_pending,
                "runtime_refresh_queued": self.runtime_refresh_queued,
                "applied_seq": self.runtime_refresh_applied_seq,
                "snapshot_after": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn on_live_shell_discovery_result(&mut self, result: LiveShellDiscoveryResult) {
        // The discovery worker already performed all filesystem/process
        // probing. Result application on the UI thread is memory-only.
        self.on_live_shell_discovery_result_with_meta(result, |_| None);
    }

    fn on_live_shell_discovery_result_with_meta<F>(
        &mut self,
        result: LiveShellDiscoveryResult,
        mut live_meta_snapshot: F,
    ) where
        F: FnMut(&AgentKey) -> Option<AgentMetaSnapshot>,
    {
        let reclaimed_abandoned_worker =
            self.reclaim_abandoned_live_shell_discovery(result.seq, "result");
        if !self.live_shell_discovery_pending || result.seq != self.live_shell_discovery_seq {
            debug_log(
                "live_shell_discovery_result_stale",
                serde_json::json!({
                    "seq": result.seq,
                    "current_seq": self.live_shell_discovery_seq,
                    "pending": self.live_shell_discovery_pending,
                    "reclaimed_abandoned_worker": reclaimed_abandoned_worker,
                    "elapsed_ms": result.elapsed_ms,
                    "reason": "stale_or_abandoned_worker",
                    "cached_live_shells_preserved": self.live_shells.len(),
                    "cached_agent_states_preserved": self.agent_states.len(),
                }),
            );
            return;
        }
        self.live_shell_discovery_pending = false;
        self.live_shell_discovery_started_at = None;
        self.live_shell_discovery_last_slow_log_at = None;
        self.last_live_shell_discovery = Instant::now();

        let previous_live_shells = self.live_shells.clone();
        let previous_keys: HashSet<AgentKey> =
            previous_live_shells.iter().map(AgentKey::new).collect();
        let baseline_keys = result.baseline_keys;
        let scan_complete = result.scan_complete;
        let uncertain_stems = result.uncertain_stems;
        let mut next_live_shells = result.live_shells;
        let mut seen: HashSet<AgentKey> = next_live_shells.iter().map(AgentKey::new).collect();
        let mut preserved_keys = Vec::new();
        let mut missing_decisions = Vec::new();
        for info in previous_live_shells {
            let key = AgentKey::new(&info);
            if seen.contains(&key) {
                missing_decisions.push(serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "info": session_info_debug_value(&info),
                    "decision": "already_discovered",
                    "state": optional_agent_list_state_debug_value(self.agent_states.get(&key).copied()),
                }));
                continue;
            }
            if !baseline_keys.contains(&key) {
                seen.insert(key.clone());
                preserved_keys.push(key.clone());
                missing_decisions.push(serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "info": session_info_debug_value(&info),
                    "decision": "preserved_newer_than_scan",
                    "state": optional_agent_list_state_debug_value(self.agent_states.get(&key).copied()),
                }));
                next_live_shells.push(info);
                continue;
            }
            if let Some(verified) = verified_missing_live_shell_from_meta(
                &key,
                &info,
                std::process::id(),
                Some(agent_client_instance_id()),
                current_epoch_ms(),
                &mut live_meta_snapshot,
            ) {
                if verified.state != AgentListState::Idle {
                    self.agent_states.insert(key.clone(), verified.state);
                }
                seen.insert(key.clone());
                preserved_keys.push(key.clone());
                missing_decisions.push(serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "info": session_info_debug_value(&info),
                    "verified_info": session_info_debug_value(&verified.info),
                    "decision": "preserved_missing_verified_runtime",
                    "state": optional_agent_list_state_debug_value(self.agent_states.get(&key).copied()),
                    "verified_state": agent_list_state_debug_value(verified.state),
                    "verified_meta": agent_meta_snapshot_debug_value(&verified.meta),
                }));
                next_live_shells.push(verified.info);
                continue;
            }
            let stem = agent_file_stem(&key);
            let absence_is_definitive = scan_complete && !uncertain_stems.contains(&stem);
            if !absence_is_definitive {
                seen.insert(key.clone());
                preserved_keys.push(key.clone());
                missing_decisions.push(serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "info": session_info_debug_value(&info),
                    "decision": "preserved_missing_scan_unknown",
                    "state": optional_agent_list_state_debug_value(self.agent_states.get(&key).copied()),
                    "scan_complete": scan_complete,
                    "stem_uncertain": uncertain_stems.contains(&stem),
                }));
                next_live_shells.push(info);
            } else {
                missing_decisions.push(serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "info": session_info_debug_value(&info),
                    "decision": "removed_definitive_runtime_absence",
                    "state": optional_agent_list_state_debug_value(self.agent_states.get(&key).copied()),
                    "scan_complete": scan_complete,
                }));
            }
        }
        let mut active_preserved = None;
        let mut client_held_infos = Vec::new();
        if let Some(agent) = self
            .active_agent
            .as_ref()
            .filter(|agent| agent.exited.is_none())
        {
            client_held_infos.push(agent.info.clone());
        }
        if let Some(aux) = self
            .agent_aux
            .as_ref()
            .filter(|aux| aux.agent.exited.is_none())
        {
            client_held_infos.push(aux.agent.info.clone());
        }
        client_held_infos.extend(
            self.hidden_agent_aux
                .iter()
                .filter(|aux| aux.agent.exited.is_none())
                .map(|aux| aux.agent.info.clone()),
        );
        let mut client_held_preserved = Vec::new();
        for info in client_held_infos {
            let held_key = AgentKey::new(&info);
            if !seen.insert(held_key.clone()) {
                continue;
            }
            if self
                .active_agent
                .as_ref()
                .is_some_and(|agent| AgentKey::new(&agent.info) == held_key)
            {
                active_preserved = Some(held_key.clone());
            }
            client_held_preserved.push(held_key);
            next_live_shells.push(info);
        }
        let next_keys = seen;
        let removed_keys = previous_keys
            .difference(&next_keys)
            .cloned()
            .collect::<Vec<_>>();
        for key in &removed_keys {
            self.remove_persisted_agent_auxiliary(key, "live_shell_removed");
            self.agent_states.remove(key);
            self.new_agent_backing_aliases.remove(key);
            self.new_agent_backing_probe_after.remove(key);
        }

        let added_keys = next_keys
            .difference(&previous_keys)
            .cloned()
            .collect::<Vec<_>>();
        self.live_shells = next_live_shells;
        self.sync_active_plain_pty_tool_info_from_live_shells();
        self.overlay_active_agent_runtime_state();
        apply_cached_new_agent_backing_states(
            &self.live_shells,
            &self.new_agent_backing_aliases,
            &mut self.agent_states,
        );
        // Registry normalization that needs liveness probes belongs to a
        // worker result, never this UI result handler. Conservatively retain
        // uncertain relationships until such a result arrives.
        let normalized_auxiliaries = 0usize;
        let orphaned_auxiliaries = 0usize;

        debug_log(
            "live_shell_discovery_applied",
            serde_json::json!({
                "seq": result.seq,
                "elapsed_ms": result.elapsed_ms,
                "started_at_epoch_ms": result.started_at_epoch_ms,
                "queued_latency_ms": current_epoch_ms().saturating_sub(result.queued_at_epoch_ms),
                "scan_complete": scan_complete,
                "uncertain_stems": uncertain_stems.iter().collect::<Vec<_>>(),
                "baseline_keys": baseline_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                "previous_count": previous_keys.len(),
                "next_count": self.live_shells.len(),
                "added": added_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                "removed": removed_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                "preserved_missing": preserved_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                "active_preserved": active_preserved.as_ref().map(agent_key_debug_value),
                "client_held_preserved": client_held_preserved.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                "missing_decisions": missing_decisions,
                "normalized_auxiliaries": normalized_auxiliaries,
                "orphaned_auxiliaries_released": orphaned_auxiliaries,
                "next_live_shells": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                "agent_states": agent_state_entries_debug_value(&self.agent_states),
                "persisted_agent_auxiliaries": persisted_agent_auxiliary_entries_debug_value(&self.persisted_agent_aux),
            }),
        );

        if self.runtime_refresh_pending {
            self.runtime_refresh_queued = true;
        } else {
            self.refresh_agent_runtime_states();
        }
    }

    /// Abandon any in-flight/queued attach. The worker cannot be stopped,
    /// but clearing `attach_in_flight` makes its late result arrive as
    /// stale, so it gets dropped instead of overriding what the user just
    /// did (e.g. an explicit detach must not be undone by an attach that
    /// resolves a second later).
    fn cancel_pending_attach(&mut self, reason: &'static str) {
        if self.attach_in_flight.is_none() && self.queued_attach.is_none() {
            self.attach_terminal_input_target = None;
            self.discard_deferred_agent_input(reason);
            return;
        }
        let cancelled_in_flight = self
            .attach_in_flight
            .as_ref()
            .map(|attach| attach.key.clone());
        let cancelled_queued = self.queued_attach.as_ref().map(|job| job.ctx.key.clone());
        debug_log(
            "attach_cancelled",
            serde_json::json!({
                "reason": reason,
                "in_flight": self.attach_in_flight.as_ref().map(|attach| {
                    serde_json::json!({
                        "seq": attach.seq,
                        "provider": attach.key.provider.as_str(),
                        "session_id": &attach.key.session_id,
                    })
                }),
                "queued": self.queued_attach.as_ref().map(|job| {
                    serde_json::json!({
                        "provider": job.ctx.key.provider.as_str(),
                        "session_id": &job.ctx.key.session_id,
                    })
                }),
            }),
        );
        self.attach_in_flight = None;
        self.attach_terminal_input_target = None;
        self.queued_attach = None;
        self.discard_deferred_agent_input(reason);
        if let Some(key) = cancelled_in_flight.as_ref() {
            self.abandon_agent_kill_replacement_for(key, reason);
        }
        if let Some(key) = cancelled_queued.as_ref() {
            self.abandon_agent_kill_replacement_for(key, reason);
        }
    }

    /// Queue an attach job. Jobs run one at a time on a worker thread so
    /// the UI never blocks on filesystem checks, daemon spawn, or socket
    /// connect; while one is in flight the newest request waits in
    /// `queued_attach` (latest wins, so key bursts settle on the final
    /// target instead of replaying every intermediate hop).
    fn request_attach(&mut self, job: AttachJob) {
        debug_log(
            "attach_request_received",
            serde_json::json!({
                "job": attach_job_debug_value(&job),
                "in_flight": self.attach_in_flight.as_ref().map(attach_in_flight_debug_value),
                "queued": self.queued_attach.as_ref().map(attach_job_debug_value),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if self.attach_in_flight.is_some() {
            self.status = format!(
                "attach in progress; queued {}",
                live_agent_status_label(&job.info)
            );
            debug_log(
                "attach_request_queued",
                serde_json::json!({
                    "job": attach_job_debug_value(&job),
                    "in_flight": self.attach_in_flight.as_ref().map(attach_in_flight_debug_value),
                    "replaced_queued": self.queued_attach.is_some(),
                    "previous_queued": self.queued_attach.as_ref().map(attach_job_debug_value),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.mark_new_session_launch_attach_queued(&job.ctx.key);
            self.queued_attach = Some(job);
            return;
        }
        self.start_attach_job(job);
    }

    fn mark_new_session_launch_attach_key(&mut self, seq: u64, key: AgentKey) {
        if let Some(pending) = self
            .new_session_launch
            .as_mut()
            .filter(|pending| pending.seq == seq)
        {
            pending.attach_key = Some(key);
            pending.stage = NewSessionLaunchStage::Starting;
        }
    }

    fn mark_new_session_launch_attach_queued(&mut self, key: &AgentKey) {
        if let Some(pending) = self
            .new_session_launch
            .as_mut()
            .filter(|pending| pending.attach_key.as_ref() == Some(key))
        {
            pending.stage = NewSessionLaunchStage::Queued;
        }
    }

    fn mark_new_session_launch_attach_started(&mut self, key: &AgentKey) {
        if let Some(pending) = self
            .new_session_launch
            .as_mut()
            .filter(|pending| pending.attach_key.as_ref() == Some(key))
        {
            pending.stage = NewSessionLaunchStage::Starting;
        }
    }

    fn finish_new_session_launch_for_key(&mut self, key: &AgentKey, reason: &'static str) {
        let should_clear = self
            .new_session_launch
            .as_ref()
            .and_then(|pending| pending.attach_key.as_ref())
            == Some(key);
        if should_clear {
            debug_log(
                "new_session_launch_done",
                serde_json::json!({
                    "reason": reason,
                    "key": agent_key_debug_value(key),
                    "pending": self
                        .new_session_launch
                        .as_ref()
                        .map(new_session_launch_pending_debug_value),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.new_session_launch = None;
        }
    }

    fn sync_new_session_launch_after_attach_request(&mut self, seq: u64, key: &AgentKey) {
        let Some(pending) = self
            .new_session_launch
            .as_mut()
            .filter(|pending| pending.seq == seq && pending.attach_key.as_ref() == Some(key))
        else {
            return;
        };
        if self
            .attach_in_flight
            .as_ref()
            .is_some_and(|attach| attach.key == *key)
        {
            pending.stage = NewSessionLaunchStage::Starting;
        } else if self
            .queued_attach
            .as_ref()
            .is_some_and(|job| job.ctx.key == *key)
        {
            pending.stage = NewSessionLaunchStage::Queued;
        } else {
            self.new_session_launch = None;
        }
    }

    fn start_attach_job(&mut self, job: AttachJob) {
        if self.main_tx.is_none() {
            let failed_key = job.ctx.key.clone();
            self.status = format!(
                "cannot attach {}; event loop is not ready",
                live_agent_status_label(&job.info)
            );
            debug_log(
                "attach_job_start_skipped",
                serde_json::json!({
                    "reason": "missing_main_tx",
                    "job": attach_job_debug_value(&job),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.abandon_agent_kill_replacement_for(&failed_key, "attach_start_missing_event_loop");
            return;
        }
        debug_log(
            "attach_job_starting",
            serde_json::json!({
                "next_seq": self.attach_seq.saturating_add(1),
                "job": attach_job_debug_value(&job),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        let result_tx = self.main_tx.clone().expect("main_tx checked above");
        let (main_tx, reader_id) = self.agent_attach_handles();
        self.attach_seq = self.attach_seq.saturating_add(1);
        let seq = self.attach_seq;
        let AttachJob {
            info,
            cols,
            rows,
            kind,
            run_prechecks,
            prompt_for_saved_data,
            settings,
            ctx,
        } = job;
        self.attach_terminal_input_target =
            (ctx.target.is_main_agent() || ctx.focus_auxiliary_on_ready).then(|| {
                (
                    seq,
                    DeferredAgentInputTarget {
                        key: ctx.key.clone(),
                        attach_target: ctx.target.clone(),
                    },
                )
            });
        self.attach_in_flight = Some(AttachInFlight {
            seq,
            key: ctx.key.clone(),
            target: ctx.target.clone(),
            started_at: Instant::now(),
        });
        self.mark_new_session_launch_attach_started(&ctx.key);
        self.status = format!("attaching {}...", live_agent_status_label(&info));
        let attach_key_for_pending = ctx.key.clone();
        debug_log(
            "attach_job_started",
            serde_json::json!({
                "seq": seq,
                "reader_id": reader_id,
                "info": session_info_debug_value(&info),
                "cols": cols,
                "rows": rows,
                "kind": attach_job_kind_debug_value(kind),
                "run_prechecks": run_prechecks,
                "prompt_for_saved_data": prompt_for_saved_data,
                "ctx": attach_ui_ctx_debug_value(&ctx),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        let spawn_result = thread::Builder::new()
            .name("cokacmux-attach".into())
            .spawn(move || {
                let started = Instant::now();
                let result_info = info.clone();
                // A panic inside the job must still produce a result event;
                // otherwise `attach_in_flight` would stay set forever and
                // every later attach would queue behind it.
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    run_attach_job(
                        info,
                        cols,
                        rows,
                        kind,
                        run_prechecks,
                        prompt_for_saved_data,
                        settings,
                        main_tx,
                        reader_id,
                    )
                }))
                .unwrap_or_else(|_| AttachWorkOutcome::Failed {
                    stage: AttachFailStage::Attach,
                    message: "attach worker panicked".to_string(),
                    error_kind: None,
                });
                let _ = result_tx.send(MainEvent::AttachResult(Box::new(AttachWorkerResult {
                    seq,
                    info: result_info,
                    cols,
                    rows,
                    ctx,
                    outcome,
                    queued_at_epoch_ms: current_epoch_ms(),
                    elapsed_ms: started.elapsed().as_millis(),
                })));
            });
        if let Err(e) = spawn_result {
            self.attach_in_flight = None;
            self.attach_terminal_input_target = None;
            self.finish_new_session_launch_for_key(
                &attach_key_for_pending,
                "attach_worker_spawn_failed",
            );
            self.status = format!("attach failed: {}", e);
            debug_log(
                "attach_worker_spawn_failed",
                serde_json::json!({
                    "seq": seq,
                    "reader_id": reader_id,
                    "error": e.to_string(),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.abandon_agent_kill_replacement_for(
                &attach_key_for_pending,
                "attach_worker_spawn_failed",
            );
        }
    }

    fn on_attach_result(&mut self, result: Box<AttachWorkerResult>) {
        let result = *result;
        let in_flight_seq = self.attach_in_flight.as_ref().map(|attach| attach.seq);
        debug_log(
            "attach_result_received",
            serde_json::json!({
                "seq": result.seq,
                "in_flight_seq": in_flight_seq,
                "result": attach_worker_result_debug_value(&result),
                "queued_latency_ms": current_epoch_ms().saturating_sub(result.queued_at_epoch_ms),
                "in_flight": self.attach_in_flight.as_ref().map(attach_in_flight_debug_value),
                "queued": self.queued_attach.as_ref().map(attach_job_debug_value),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if in_flight_seq != Some(result.seq) {
            // Dropping the outcome also drops any AgentClient it carries,
            // which detaches its daemon connection cleanly.
            self.cleanup_stale_auxiliary_attach_result(&result, "stale_seq");
            debug_log(
                "attach_result_stale",
                serde_json::json!({
                    "seq": result.seq,
                    "in_flight_seq": in_flight_seq,
                    "provider": result.ctx.key.provider.as_str(),
                    "session_id": &result.ctx.key.session_id,
                    "result": attach_worker_result_debug_value(&result),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        }
        self.finish_new_session_launch_for_key(&result.ctx.key, "attach_result");
        self.attach_in_flight = None;
        self.attach_terminal_input_target = None;
        if let Some(queued) = self.queued_attach.take() {
            let replacement_was_superseded =
                self.agent_kill_replacement
                    .as_ref()
                    .is_some_and(|replacement| {
                        AgentKey::new(&replacement.target) == result.ctx.key
                            && result.ctx.target.is_main_agent()
                    });
            let result_seq = result.seq;
            let result_provider = result.ctx.key.provider;
            let result_session_id = result.ctx.key.session_id.clone();
            let queued_provider = queued.ctx.key.provider;
            let queued_session_id = queued.ctx.key.session_id.clone();
            if queued.ctx.target.is_main_agent() {
                if replacement_was_superseded {
                    if let Some(replacement) = self.agent_kill_replacement.as_mut() {
                        replacement.target = queued.info.clone();
                    }
                }
                self.hide_superseded_auxiliary_attach_result(result, "superseded_by_main_attach");
            } else {
                if replacement_was_superseded {
                    self.abandon_agent_kill_replacement_for(
                        &result.ctx.key,
                        "replacement_superseded_by_auxiliary_attach",
                    );
                }
                self.cleanup_stale_auxiliary_attach_result(&result, "superseded");
                drop(result);
            }
            debug_log(
                "attach_result_superseded",
                serde_json::json!({
                    "seq": result_seq,
                    "provider": result_provider.as_str(),
                    "session_id": result_session_id,
                    "next_provider": queued_provider.as_str(),
                    "next_session_id": queued_session_id,
                    "next_job": attach_job_debug_value(&queued),
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.start_attach_job(queued);
            return;
        }
        let AttachWorkerResult {
            info,
            cols,
            rows,
            ctx,
            outcome,
            elapsed_ms,
            ..
        } = result;
        let is_agent_kill_replacement = ctx.target.is_main_agent()
            && self
                .agent_kill_replacement
                .as_ref()
                .is_some_and(|replacement| AgentKey::new(&replacement.target) == ctx.key);
        match outcome {
            AttachWorkOutcome::Attached { agent, started } => {
                let reader_id = agent.reader_id;
                self.status = if started {
                    ctx.status_started
                } else {
                    ctx.status_attached
                };
                // An explicit Ctrl+] / Ctrl+[ during the replacement wins.
                // Ordinary replacement completion keeps the agent workspace.
                if !is_agent_kill_replacement || !self.show_sessions_view {
                    self.show_sessions_view = false;
                }
                // The terminal may have resized while the attach worker was
                // connecting. Resolve layout against the current dimensions,
                // not the stale geometry captured when the job started.
                let (terminal_cols, terminal_rows) = crossterm::terminal::size().unwrap_or((
                    cols.max(80),
                    rows.saturating_add(AGENT_STATUS_HEIGHT).max(24),
                ));
                match ctx.target {
                    AttachTarget::MainAgent => {
                        let fallback_focus = self.valid_agent_focus_for_current(self.agent_focus);
                        self.set_active_agent(agent);
                        self.mark_agent_attached_locally(ctx.key.clone());
                        self.discard_pending_agent_runtime_refresh();
                        if ctx.select_visible {
                            self.select_visible_session(&ctx.key);
                        }
                        self.refresh_agent_runtime_states();
                        let _ = self.restore_hidden_auxiliary_for_active_agent(
                            terminal_cols,
                            terminal_rows,
                            "main_agent_attached",
                        );
                        if let Some(focus_override) = ctx.main_focus_override_on_ready {
                            let focus = self.valid_agent_focus_for_current(focus_override);
                            if focus == AgentFocusPane::Sidebar {
                                self.ensure_agent_sidebar_visible_for_focus("agent_focus_override");
                            }
                            self.set_agent_focus(focus);
                        } else {
                            self.restore_agent_focus_for_active_agent(fallback_focus);
                        }
                        if is_agent_kill_replacement {
                            self.agent_kill_replacement = None;
                        }
                    }
                    AttachTarget::Auxiliary { kind, parent } => {
                        let active_parent = self
                            .active_agent
                            .as_ref()
                            .map(|agent| AgentKey::new(&agent.info));
                        if active_parent.as_ref() == Some(&parent)
                            && self.active_main_agent_is_coding()
                        {
                            self.set_auxiliary_agent(kind, parent, agent);
                            if ctx.focus_auxiliary_on_ready {
                                self.set_agent_focus(AgentFocusPane::Auxiliary);
                            } else {
                                self.restore_agent_focus_for_active_agent(AgentFocusPane::Main);
                            }
                            self.mark_agent_attached_locally(ctx.key.clone());
                            self.discard_pending_agent_runtime_refresh();
                            self.refresh_agent_runtime_states();
                        } else {
                            let stale_info = agent.info.clone();
                            let stale_key = AgentKey::new(&stale_info);
                            let stale_activity = agent.activity();
                            let parent_live = self.auxiliary_parent_is_live(&parent);
                            if parent_live {
                                self.remember_persisted_agent_auxiliary(
                                    kind,
                                    &parent,
                                    &stale_info,
                                    true,
                                    "stale_preserved",
                                );
                                self.remember_live_info_locally(&stale_info);
                                self.mark_agent_live_locally(stale_key.clone(), stale_activity);
                            } else {
                                self.release_auxiliary_info_locally(
                                    &stale_key,
                                    &stale_info,
                                    stale_activity,
                                    "stale_released",
                                );
                            }
                            drop(agent);
                            self.status = format!(
                                "detached stale right {} panel; kept running",
                                kind.label()
                            );
                            self.discard_pending_agent_runtime_refresh();
                            self.refresh_agent_runtime_states();
                            debug_log(
                                "agent_auxiliary_open_stale",
                                serde_json::json!({
                                    "kind": kind.label(),
                                    "requested_parent": agent_key_debug_value(&parent),
                                    "active_parent": active_parent.as_ref().map(agent_key_debug_value),
                                    "parent_live": parent_live,
                                    "preserved_live": true,
                                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                                }),
                            );
                        }
                    }
                }
                // Installing an auxiliary changes the main pane's width too;
                // synchronize both PTYs before replaying any input that was
                // serialized behind this attach.
                let _ = self.sync_agent_viewports(terminal_cols, terminal_rows);
                let replay_result =
                    self.agent_client_mut_by_reader_id(reader_id)
                        .and_then(|agent| {
                            let summary = agent.unacknowledged_input_summary()?;
                            Some((summary, agent.replay_unacknowledged_input()))
                        });
                if let Some(((frames, bytes), result)) = replay_result {
                    match result {
                        Ok(report) => {
                            self.status = if report.replayed_frames > 0 {
                                format!(
                                    "reconnected {}; replaying {} retained input bytes in {} frame(s){}",
                                    live_agent_status_label(&info),
                                    report.replayed_bytes,
                                    report.replayed_frames,
                                    if report.unavailable_frames > 0 {
                                        format!(
                                            "; {} bytes belonged to the previous daemon and were not sent",
                                            report.unavailable_bytes
                                        )
                                    } else {
                                        String::new()
                                    }
                                )
                            } else {
                                format!(
                                    "{} retained input bytes belonged to the previous daemon and were not sent",
                                    report.unavailable_bytes
                                )
                            };
                        }
                        Err(error) => {
                            self.status = format!(
                                "{} retained input bytes in {} frame(s) were not replayed: {}",
                                bytes, frames, error
                            );
                        }
                    }
                }
                // Drain any output the reader thread queued before this
                // result was applied; its notification may have been ignored
                // while the previous agent was still active.
                self.schedule_agent_output_available(reader_id);
                debug_log(
                    ctx.ready_event,
                    serde_json::json!({
                        "provider": ctx.key.provider.as_str(),
                        "session_id": &ctx.key.session_id,
                        "started": started,
                        "origin": ctx.log_origin,
                        "attach_elapsed_ms": elapsed_ms,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
            }
            AttachWorkOutcome::NeedsRestorePrompt {
                snapshot,
                launch_mode,
            } => {
                // Never stomp a dialog the user opened while the job ran.
                if matches!(self.input_mode, InputMode::Normal) {
                    self.prompt_restore_cloned_session_data(
                        info,
                        snapshot,
                        cols,
                        rows,
                        launch_mode,
                    );
                } else {
                    self.status = format!(
                        "saved folder data found for {}; retry to restore",
                        truncate_width(&ctx.key.session_id, 14)
                    );
                }
                debug_log(
                    "attach_result_needs_restore_prompt",
                    serde_json::json!({
                        "provider": ctx.key.provider.as_str(),
                        "session_id": &ctx.key.session_id,
                        "launch_mode": launch_mode.as_str(),
                        "input_mode": input_mode_label(&self.input_mode),
                        "status": &self.status,
                        "attach_elapsed_ms": elapsed_ms,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                if is_agent_kill_replacement {
                    self.abandon_agent_kill_replacement_for(
                        &ctx.key,
                        "replacement_needs_restore_prompt",
                    );
                }
            }
            AttachWorkOutcome::NeedsCreateCwd { path, launch_mode } => {
                let path_for_log = path.display().to_string();
                if matches!(self.input_mode, InputMode::Normal) {
                    self.prompt_create_missing_launch_cwd(info, path, cols, rows, launch_mode);
                } else {
                    self.status = format!(
                        "launch folder missing for {}; retry to create it",
                        truncate_width(&ctx.key.session_id, 14)
                    );
                }
                debug_log(
                    "attach_result_needs_create_cwd",
                    serde_json::json!({
                        "provider": ctx.key.provider.as_str(),
                        "session_id": &ctx.key.session_id,
                        "path": path_for_log,
                        "launch_mode": launch_mode.as_str(),
                        "input_mode": input_mode_label(&self.input_mode),
                        "status": &self.status,
                        "attach_elapsed_ms": elapsed_ms,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                if is_agent_kill_replacement {
                    self.abandon_agent_kill_replacement_for(
                        &ctx.key,
                        "replacement_needs_create_cwd",
                    );
                }
            }
            AttachWorkOutcome::Failed {
                stage,
                message,
                error_kind,
            } => {
                let daemon_gone = ctx.remove_dead_on_notfound
                    && matches!(stage, AttachFailStage::Attach)
                    && error_kind == Some(ErrorKind::NotFound);
                let daemon_gone_removed =
                    daemon_gone && self.remove_dead_live_shell_if_not_unreachable_live(&ctx.key);
                self.status = match stage {
                    AttachFailStage::Prepare => {
                        format!("{}{}", ctx.status_prepare_err_prefix, message)
                    }
                    _ => format!("{}{}", ctx.status_err_prefix, message),
                };
                if ctx.cokacdir_dialog_on_error {
                    self.show_cokacdir_error_dialog(self.status.clone());
                }
                if matches!(stage, AttachFailStage::Attach) {
                    self.refresh_agent_runtime_states_discovering_live_shells();
                } else {
                    self.refresh_agent_runtime_states();
                }
                debug_log(
                    ctx.failed_event,
                    serde_json::json!({
                        "provider": ctx.key.provider.as_str(),
                        "session_id": &ctx.key.session_id,
                        "stage": format!("{:?}", stage),
                        "error": message,
                        "origin": ctx.log_origin,
                        "daemon_gone": daemon_gone,
                        "daemon_gone_removed": daemon_gone_removed,
                        "unreachable_live_preserved": daemon_gone && !daemon_gone_removed,
                        "attach_elapsed_ms": elapsed_ms,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                if is_agent_kill_replacement {
                    self.abandon_agent_kill_replacement_for(&ctx.key, "replacement_attach_failed");
                }
            }
        }
    }

    fn cleanup_stale_auxiliary_attach_result(
        &mut self,
        result: &AttachWorkerResult,
        reason: &'static str,
    ) {
        let AttachTarget::Auxiliary { kind, parent } = &result.ctx.target else {
            return;
        };
        let AttachWorkOutcome::Attached { agent, .. } = &result.outcome else {
            return;
        };
        let info = agent.info.clone();
        let key = AgentKey::new(&info);
        let activity = agent.activity();
        let parent_live = self.auxiliary_parent_is_live(parent);
        if parent_live {
            self.remember_persisted_agent_auxiliary(*kind, parent, &info, true, reason);
            self.remember_live_info_locally(&info);
            self.mark_agent_live_locally(key.clone(), activity);
        } else {
            self.release_auxiliary_info_locally(&key, &info, activity, reason);
        }
        self.discard_pending_agent_runtime_refresh();
        self.refresh_agent_runtime_states();
        debug_log(
            "agent_auxiliary_attach_preserved",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "requested_parent": agent_key_debug_value(parent),
                "key": agent_key_debug_value(&key),
                "parent_live": parent_live,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn hide_superseded_auxiliary_attach_result(
        &mut self,
        result: AttachWorkerResult,
        reason: &'static str,
    ) {
        let AttachWorkerResult { ctx, outcome, .. } = result;
        let AttachTarget::Auxiliary { kind, parent } = ctx.target else {
            drop(outcome);
            return;
        };
        let AttachWorkOutcome::Attached { agent, .. } = outcome else {
            return;
        };
        let key = AgentKey::new(&agent.info);
        let info = agent.info.clone();
        self.remember_active_auxiliary_parent_info(&parent);
        self.remember_live_info_locally(&info);
        self.release_hidden_auxiliaries_for_parent(&parent, reason);
        self.remember_persisted_agent_auxiliary(kind, &parent, &info, true, reason);
        self.hidden_agent_aux.push(AgentAuxPane {
            kind,
            parent: parent.clone(),
            agent,
        });
        debug_log(
            "agent_auxiliary_hidden_after_superseded_attach",
            serde_json::json!({
                "reason": reason,
                "kind": kind.label(),
                "parent": agent_key_debug_value(&parent),
                "key": agent_key_debug_value(&key),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn remove_dead_live_shell_if_not_unreachable_live(&mut self, key: &AgentKey) -> bool {
        debug_log(
            "dead_live_shell_remove_deferred_to_runtime_worker",
            serde_json::json!({
                "key": agent_key_debug_value(key),
            }),
        );
        false
    }

    /// Drop a daemon proven dead (its socket file is gone) from the live
    /// runtime caches so it stops appearing as a switchable agents-list
    /// entry. Mirrors the cleanup done for shells removed by discovery.
    fn remove_dead_live_shell(&mut self, key: &AgentKey) {
        debug_log(
            "dead_live_shell_remove_start",
            serde_json::json!({
                "key": agent_key_debug_value(key),
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
                "persisted_agent_auxiliaries_len": self.persisted_agent_aux.len(),
                "new_agent_backing_aliases_len": self.new_agent_backing_aliases.len(),
            }),
        );
        self.remove_persisted_agent_auxiliary(key, "dead_live_shell");
        self.live_shells.retain(|info| AgentKey::new(info) != *key);
        self.agent_states.remove(key);
        self.new_agent_backing_aliases.remove(key);
        self.new_agent_backing_probe_after.remove(key);
        debug_log(
            "dead_live_shell_remove_done",
            serde_json::json!({
                "key": agent_key_debug_value(key),
                "live_shells_len": self.live_shells.len(),
                "agent_states_len": self.agent_states.len(),
                "persisted_agent_auxiliaries_len": self.persisted_agent_aux.len(),
                "new_agent_backing_aliases_len": self.new_agent_backing_aliases.len(),
            }),
        );
    }

    fn discard_pending_agent_runtime_refresh(&mut self) {
        let pending_before =
            pending_runtime_action_debug_value(self.pending_runtime_action.as_ref());
        let was_refresh_pending = self.runtime_refresh_pending;
        let previous_applied_seq = self.runtime_refresh_applied_seq;
        let previous_queued = self.runtime_refresh_queued;
        let previous_pending_discover_live_shells =
            self.runtime_refresh_pending_discover_live_shells;
        let previous_queued_discover_live_shells = self.runtime_refresh_queued_discover_live_shells;
        self.pending_runtime_action = None;
        self.pending_runtime_action_last_slow_log_at = None;
        if self.runtime_refresh_pending {
            self.runtime_refresh_applied_seq = self
                .runtime_refresh_applied_seq
                .max(self.runtime_refresh_seq.saturating_add(1));
            self.runtime_refresh_queued = true;
            self.runtime_refresh_queued_discover_live_shells |=
                self.runtime_refresh_pending_discover_live_shells;
        }
        debug_log(
            "agent_runtime_refresh_discard_pending",
            serde_json::json!({
                "was_refresh_pending": was_refresh_pending,
                "runtime_refresh_seq": self.runtime_refresh_seq,
                "applied_seq_before": previous_applied_seq,
                "applied_seq_after": self.runtime_refresh_applied_seq,
                "queued_before": previous_queued,
                "queued_after": self.runtime_refresh_queued,
                "pending_discover_live_shells_before": previous_pending_discover_live_shells,
                "queued_discover_live_shells_before": previous_queued_discover_live_shells,
                "queued_discover_live_shells_after": self.runtime_refresh_queued_discover_live_shells,
                "pending_runtime_action_before": pending_before,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn agent_runtime_refresh_in_flight(&self) -> bool {
        self.runtime_refresh_pending || self.runtime_refresh_queued
    }

    fn set_pending_runtime_action(&mut self, action: PendingRuntimeAction) {
        self.pending_runtime_action = Some(action);
        self.pending_runtime_action_last_slow_log_at = None;
    }

    fn maybe_log_slow_pending_runtime_action(&mut self) {
        if self.pending_runtime_action.is_none() {
            self.pending_runtime_action_last_slow_log_at = None;
            return;
        }
        let Some(started_at) = self.runtime_refresh_started_at else {
            return;
        };
        let elapsed = started_at.elapsed();
        if elapsed < Duration::from_millis(PENDING_RUNTIME_ACTION_SLOW_LOG_MS) {
            return;
        }
        if self
            .pending_runtime_action_last_slow_log_at
            .is_some_and(|last| {
                last.elapsed() < Duration::from_millis(PENDING_RUNTIME_ACTION_SLOW_LOG_INTERVAL_MS)
            })
        {
            return;
        }
        self.pending_runtime_action_last_slow_log_at = Some(Instant::now());
        debug_log(
            "pending_runtime_action_still_waiting",
            serde_json::json!({
                "runtime_refresh_seq": self.runtime_refresh_seq,
                "runtime_refresh_pending": self.runtime_refresh_pending,
                "runtime_refresh_queued": self.runtime_refresh_queued,
                "runtime_refresh_pending_discover_live_shells": self.runtime_refresh_pending_discover_live_shells,
                "runtime_refresh_queued_discover_live_shells": self.runtime_refresh_queued_discover_live_shells,
                "elapsed_ms": elapsed.as_millis(),
                "pending_runtime_action": pending_runtime_action_debug_value(self.pending_runtime_action.as_ref()),
            }),
        );
    }

    fn apply_agent_runtime_refresh_result_with_pending(
        &mut self,
        result: AgentRuntimeRefreshResult,
        continue_pending_action: bool,
    ) {
        let seq = result.seq;
        let discover_live_shells = result.discover_live_shells;
        let pending_before =
            pending_runtime_action_debug_value(self.pending_runtime_action.as_ref());
        self.runtime_refresh_applied_seq = self.runtime_refresh_applied_seq.max(seq);
        let previous_live_shells_len = self.live_shells.len();
        self.apply_runtime_refresh_live_shells(result.live_shells, discover_live_shells);
        let live_shells_preserved =
            !discover_live_shells && previous_live_shells_len > 0 && !self.live_shells.is_empty();
        self.sync_active_plain_pty_tool_info_from_live_shells();
        self.agent_states = result.agent_states;
        self.new_agent_backing_aliases = result.new_agent_backing_aliases;
        self.new_agent_backing_probe_after = result.new_agent_backing_probe_after;
        self.overlay_active_agent_runtime_state();
        apply_cached_new_agent_backing_states(
            &self.live_shells,
            &self.new_agent_backing_aliases,
            &mut self.agent_states,
        );
        // Liveness-sensitive registry release is not performed while applying
        // a UI event. Explicit exit/kill outcomes update the registry, while
        // uncertain runtime absence is conservatively preserved.
        let orphaned_auxiliaries = 0usize;
        if self.pending_runtime_action.is_none()
            && (self.status == "checking live agents..."
                || self.status.starts_with("checking live state for "))
        {
            self.status = "live agents updated.".into();
        }
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "agent_runtime_refresh_applied_summary",
                serde_json::json!({
                    "seq": seq,
                    "discover_live_shells": discover_live_shells,
                    "continue_pending_action": continue_pending_action,
                    "live_shells_preserved": live_shells_preserved,
                    "live_shells_len": self.live_shells.len(),
                    "agent_states_len": self.agent_states.len(),
                    "orphaned_auxiliaries_released": orphaned_auxiliaries,
                    "live_shells": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                    "agent_states": agent_state_entries_debug_value(&self.agent_states),
                    "new_agent_backing_aliases": agent_alias_entries_debug_value(&self.new_agent_backing_aliases),
                    "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                    "show_sessions_view": self.show_sessions_view,
                    "pending_before": pending_before,
                    "status": &self.status,
                }),
            );
        }
        if continue_pending_action {
            self.continue_pending_runtime_action();
        } else if self.pending_runtime_action.is_some() {
            debug_log(
                "pending_runtime_action_waiting_for_queued_refresh",
                serde_json::json!({
                    "seq": seq,
                    "pending_runtime_action": pending_runtime_action_debug_value(self.pending_runtime_action.as_ref()),
                    "live_shells_len": self.live_shells.len(),
                    "agent_states_len": self.agent_states.len(),
                }),
            );
        }
        if TRACE_ENABLED.load(Ordering::Relaxed) {
            trace_log(
                "agent_runtime_refresh_applied",
                serde_json::json!({
                    "seq": seq,
                    "agent_states_len": self.agent_states.len(),
                    "states": agent_state_entries_debug_value(&self.agent_states),
                    "new_agent_backing_aliases": agent_alias_entries_debug_value(&self.new_agent_backing_aliases),
                    "live_shells_len": self.live_shells.len(),
                    "show_sessions_view": self.show_sessions_view,
                    "pending": self.runtime_refresh_pending,
                    "queued": self.runtime_refresh_queued,
                }),
            );
        }
    }

    fn apply_runtime_refresh_live_shells(
        &mut self,
        refreshed_live_shells: Vec<SessionInfo>,
        discover_live_shells: bool,
    ) {
        let debug_enabled = DEBUG_ENABLED.load(Ordering::Relaxed);
        if discover_live_shells {
            let mut next_by_key = refreshed_live_shells
                .into_iter()
                .map(|info| (AgentKey::new(&info), info))
                .collect::<HashMap<_, _>>();
            for agent in self
                .active_agent
                .as_ref()
                .into_iter()
                .chain(self.agent_aux.as_ref().map(|aux| &aux.agent))
                .chain(self.hidden_agent_aux.iter().map(|aux| &aux.agent))
                .filter(|agent| agent.exited.is_none())
            {
                next_by_key
                    .entry(AgentKey::new(&agent.info))
                    .or_insert_with(|| agent.info.clone());
            }
            let mut refreshed_live_shells = next_by_key.into_values().collect::<Vec<_>>();
            refreshed_live_shells.sort_by(|left, right| {
                left.provider
                    .as_str()
                    .cmp(right.provider.as_str())
                    .then_with(|| left.session_id.cmp(&right.session_id))
            });
            if debug_enabled {
                debug_log(
                    "agent_runtime_refresh_live_shells_replace",
                    serde_json::json!({
                        "previous_len": self.live_shells.len(),
                        "next_len": refreshed_live_shells.len(),
                        "previous": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                        "next": refreshed_live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                    }),
                );
            }
            self.live_shells = refreshed_live_shells;
            return;
        }

        let mut refreshed_by_key: HashMap<AgentKey, SessionInfo> = refreshed_live_shells
            .into_iter()
            .map(|info| (AgentKey::new(&info), info))
            .collect();
        let refreshed_keys = refreshed_by_key.keys().cloned().collect::<Vec<_>>();
        let active_keys = self
            .active_agent
            .as_ref()
            .into_iter()
            .chain(self.agent_aux.as_ref().map(|aux| &aux.agent))
            .chain(self.hidden_agent_aux.iter().map(|aux| &aux.agent))
            .map(|agent| AgentKey::new(&agent.info))
            .collect::<HashSet<_>>();
        let active_keys_for_log = active_keys.iter().cloned().collect::<Vec<_>>();
        let mut updated_keys = Vec::new();
        let mut preserved_existing_keys = Vec::new();
        let mut active_added_keys = Vec::new();
        let mut skipped_refreshed_keys = Vec::new();

        for info in self.live_shells.iter_mut() {
            let key = AgentKey::new(info);
            if let Some(refreshed) = refreshed_by_key.remove(&key) {
                updated_keys.push(key);
                *info = refreshed;
            } else {
                preserved_existing_keys.push(key);
            }
        }

        for (key, info) in refreshed_by_key {
            if active_keys.contains(&key) {
                active_added_keys.push(key);
                self.live_shells.push(info);
            } else {
                skipped_refreshed_keys.push(key);
            }
        }
        if debug_enabled {
            debug_log(
                "agent_runtime_refresh_live_shells_merged",
                serde_json::json!({
                    "refreshed_keys": refreshed_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                    "active_keys": active_keys_for_log.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                    "updated": updated_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                    "preserved_existing_without_refresh": preserved_existing_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                    "active_added": active_added_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                    "skipped_refreshed_not_active": skipped_refreshed_keys.iter().map(agent_key_debug_value).collect::<Vec<_>>(),
                    "live_shells_len": self.live_shells.len(),
                    "live_shells": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                }),
            );
        }
    }

    fn continue_pending_runtime_action(&mut self) {
        let Some(action) = self.pending_runtime_action.take() else {
            return;
        };
        self.pending_runtime_action_last_slow_log_at = None;
        debug_log(
            "pending_runtime_action_continue",
            pending_runtime_action_debug_value(Some(&action)),
        );
        match action {
            PendingRuntimeAction::LaunchSelected { info, cols, rows } => {
                if self.reject_while_data_task_running("launching an agent") {
                    return;
                }
                self.resolve_agent_launch(info, cols, rows, false);
            }
            PendingRuntimeAction::RestoreLive {
                selected_key,
                cols,
                rows,
            } => {
                self.resolve_restore_live_agent(selected_key.as_ref(), cols, rows, false);
            }
            PendingRuntimeAction::SwitchActive {
                current_key,
                delta,
                wrap,
                cols,
                rows,
                focus_override,
            } => {
                self.resolve_switch_active_agent(
                    current_key,
                    delta,
                    wrap,
                    cols,
                    rows,
                    false,
                    focus_override,
                );
            }
        }
    }

    fn overlay_active_agent_runtime_state(&mut self) {
        let overlays = self
            .active_agent
            .as_ref()
            .into_iter()
            .chain(self.agent_aux.as_ref().map(|aux| &aux.agent))
            .map(|agent| (AgentKey::new(&agent.info), agent.activity()))
            .collect::<Vec<_>>();
        for (key, client_activity) in overlays {
            let previous_state = self.agent_states.get(&key).copied();
            let activity = previous_state
                .map(|state| state.activity())
                .unwrap_or(AgentActivity::Quiet)
                .combine(client_activity);
            let overlay_state = AgentListState::Attached {
                mine: true,
                activity,
            };
            self.agent_states.insert(key.clone(), overlay_state);
            if TRACE_ENABLED.load(Ordering::Relaxed) {
                trace_log(
                    "agent_runtime_refresh_active_overlay",
                    serde_json::json!({
                        "key": agent_key_debug_value(&key),
                        "previous_state": optional_agent_list_state_debug_value(previous_state),
                        "client_activity": client_activity.label(),
                        "overlay_state": agent_list_state_debug_value(overlay_state),
                    }),
                );
            }
        }
    }

    fn sync_active_plain_pty_tool_info_from_live_shells(&mut self) {
        let live_shells = self.live_shells.clone();
        if let Some(agent) = self.active_agent.as_mut() {
            sync_plain_pty_tool_info_from_live_shells(agent, &live_shells, "active");
        }
        if let Some(aux) = self.agent_aux.as_mut() {
            sync_plain_pty_tool_info_from_live_shells(&mut aux.agent, &live_shells, "auxiliary");
        }
        for aux in self.hidden_agent_aux.iter_mut() {
            sync_plain_pty_tool_info_from_live_shells(
                &mut aux.agent,
                &live_shells,
                "hidden_auxiliary",
            );
        }
    }

    fn mark_agent_attached_locally(&mut self, key: AgentKey) {
        let debug_key = key.clone();
        let previous_state = self.agent_states.insert(
            key,
            AgentListState::Attached {
                mine: true,
                activity: AgentActivity::Quiet,
            },
        );
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "agent_state_mark_attached_locally",
                serde_json::json!({
                    "key": agent_key_debug_value(&debug_key),
                    "previous_state": optional_agent_list_state_debug_value(previous_state),
                    "agent_states_len": self.agent_states.len(),
                }),
            );
        }
    }

    fn mark_agent_live_locally(&mut self, key: AgentKey, activity: AgentActivity) {
        let debug_key = key.clone();
        let previous_state = self
            .agent_states
            .insert(key, AgentListState::Live { activity });
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "agent_state_mark_live_locally",
                serde_json::json!({
                    "key": agent_key_debug_value(&debug_key),
                    "activity": activity.label(),
                    "previous_state": optional_agent_list_state_debug_value(previous_state),
                    "agent_states_len": self.agent_states.len(),
                }),
            );
        }
    }

    fn remember_live_info_locally(&mut self, info: &SessionInfo) {
        let key = AgentKey::new(info);
        let is_provider_session = self
            .sessions
            .iter()
            .any(|session| AgentKey::new(session) == key);
        if is_provider_session
            && !is_plain_pty_tool_session_info(info)
            && !is_new_agent_session_info(info)
        {
            return;
        }
        let mut replaced = false;
        if let Some(existing) = self
            .live_shells
            .iter_mut()
            .find(|existing| AgentKey::new(existing) == key)
        {
            *existing = info.clone();
            replaced = true;
        } else {
            self.live_shells.push(info.clone());
        }
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "live_shell_remembered_locally",
                serde_json::json!({
                    "key": agent_key_debug_value(&key),
                    "replaced": replaced,
                    "live_shells_len": self.live_shells.len(),
                    "info": session_info_debug_value(info),
                }),
            );
        }
    }

    fn block_live_coding_agent_cwd_conflict(&mut self, info: &SessionInfo) -> bool {
        if !is_coding_agent_session_info(info) || info.cwd.trim().is_empty() {
            return false;
        }
        let target_key = AgentKey::new(info);
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "agent_launch_cwd_conflict_check_start",
                serde_json::json!({
                    "target": session_info_debug_value(info),
                    "target_key": agent_key_debug_value(&target_key),
                    "cached_state": optional_agent_list_state_debug_value(self.agent_states.get(&target_key).copied()),
                    "cwd_peers": self.live_coding_agent_cwd_peer_entries_debug_value(info),
                    "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                    "agent_states": agent_state_entries_debug_value(&self.agent_states),
                    "live_shells": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                }),
            );
        }
        if let Some(conflict) = self.live_coding_agent_cwd_conflict(info) {
            self.status = coding_agent_cwd_conflict_message(info, &conflict);
            debug_log(
                "agent_launch_blocked_cwd_conflict",
                serde_json::json!({
                    "source": "app_state",
                    "target": session_info_debug_value(info),
                    "conflict": session_info_debug_value(&conflict),
                    "target_key": agent_key_debug_value(&target_key),
                    "conflict_key": agent_key_debug_value(&AgentKey::new(&conflict)),
                }),
            );
            return true;
        }
        // Authoritative runtime/meta/lock validation runs in the attach,
        // restore, and daemon-start workers. The main/UI thread only consults
        // its latest in-memory snapshot so a slow disk or OS probe cannot
        // freeze keyboard navigation.
        false
    }

    fn live_coding_agent_cwd_conflict(&mut self, target: &SessionInfo) -> Option<SessionInfo> {
        let states = self.agent_states.clone();
        self.live_coding_agent_cwd_conflict_with_runtime_and_meta(
            target,
            move |key| states.get(key).copied().unwrap_or(AgentListState::Idle),
            |_| None,
        )
    }

    #[cfg(test)]
    fn live_coding_agent_cwd_conflict_with_runtime<F>(
        &mut self,
        target: &SessionInfo,
        runtime_state: F,
    ) -> Option<SessionInfo>
    where
        F: FnMut(&AgentKey) -> AgentListState,
    {
        self.live_coding_agent_cwd_conflict_with_runtime_and_meta(
            target,
            runtime_state,
            live_agent_meta_snapshot,
        )
    }

    fn live_coding_agent_cwd_conflict_with_runtime_and_meta<F, G>(
        &mut self,
        target: &SessionInfo,
        mut runtime_state: F,
        mut live_meta_snapshot: G,
    ) -> Option<SessionInfo>
    where
        F: FnMut(&AgentKey) -> AgentListState,
        G: FnMut(&AgentKey) -> Option<AgentMetaSnapshot>,
    {
        let target_key = AgentKey::new(target);
        if let Some(active_info) = self
            .active_agent
            .as_ref()
            .filter(|agent| agent.exited.is_none())
            .map(|agent| agent.info.clone())
        {
            if live_coding_agent_info_conflicts(target, &target_key, &active_info) {
                return Some(active_info);
            }
        }

        let candidates = self
            .sessions
            .iter()
            .chain(self.live_shells.iter())
            .cloned()
            .collect::<Vec<_>>();
        for candidate in candidates {
            let candidate_key = AgentKey::new(&candidate);
            if candidate_key == target_key
                || !live_coding_agent_info_conflicts(target, &target_key, &candidate)
            {
                continue;
            }
            let Some(cached_state) = self
                .agent_states
                .get(&candidate_key)
                .copied()
                .filter(|state| *state != AgentListState::Idle)
            else {
                continue;
            };

            let observed_state = runtime_state(&candidate_key);
            if observed_state == AgentListState::Idle {
                if let Some(verified) = verified_missing_live_shell_from_meta(
                    &candidate_key,
                    &candidate,
                    std::process::id(),
                    Some(agent_client_instance_id()),
                    current_epoch_ms(),
                    &mut live_meta_snapshot,
                ) {
                    let verified_state = verified.state;
                    self.remember_live_info_locally(&verified.info);
                    if verified_state != AgentListState::Idle {
                        self.agent_states
                            .insert(candidate_key.clone(), verified_state);
                    }
                    debug_log(
                        "agent_launch_preserved_verified_cwd_conflict",
                        serde_json::json!({
                            "target": session_info_debug_value(target),
                            "candidate": session_info_debug_value(&candidate),
                            "verified_info": session_info_debug_value(&verified.info),
                            "target_key": agent_key_debug_value(&target_key),
                            "candidate_key": agent_key_debug_value(&candidate_key),
                            "cached_state": agent_list_state_debug_value(cached_state),
                            "observed_state": agent_list_state_debug_value(observed_state),
                            "verified_state": agent_list_state_debug_value(verified_state),
                            "verified_meta": agent_meta_snapshot_debug_value(&verified.meta),
                        }),
                    );
                    return Some(verified.info);
                }
                self.remove_dead_live_shell(&candidate_key);
                debug_log(
                    "agent_launch_ignored_stale_cwd_conflict",
                    serde_json::json!({
                        "target": session_info_debug_value(target),
                        "candidate": session_info_debug_value(&candidate),
                        "cached_state": agent_list_state_debug_value(cached_state),
                    }),
                );
                continue;
            }

            self.agent_states
                .insert(candidate_key.clone(), observed_state);
            debug_log(
                "agent_launch_observed_live_cwd_conflict",
                serde_json::json!({
                    "target": session_info_debug_value(target),
                    "candidate": session_info_debug_value(&candidate),
                    "target_key": agent_key_debug_value(&target_key),
                    "candidate_key": agent_key_debug_value(&candidate_key),
                    "cached_state": agent_list_state_debug_value(cached_state),
                    "observed_state": agent_list_state_debug_value(observed_state),
                }),
            );
            return Some(candidate);
        }
        None
    }

    fn set_active_agent(&mut self, agent: AgentClient) {
        let previous_focus = self.agent_focus;
        let previous_key = self.current_active_agent_key();
        let incoming_info = agent.info.clone();
        let incoming_key = AgentKey::new(&incoming_info);
        let had_visible_auxiliary = self.agent_aux.is_some();
        let hidden_auxiliaries_before = self.hidden_agent_aux.len();
        let persisted_auxiliaries_before = self.persisted_agent_aux.len();
        debug_log(
            "active_agent_set_start",
            serde_json::json!({
                "previous_key": previous_key.as_ref().map(agent_key_debug_value),
                "previous_focus": format!("{:?}", previous_focus),
                "incoming": session_info_debug_value(&incoming_info),
                "incoming_key": agent_key_debug_value(&incoming_key),
                "had_visible_auxiliary": had_visible_auxiliary,
                "hidden_auxiliaries": hidden_auxiliaries_before,
                "persisted_auxiliaries": persisted_auxiliaries_before,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        self.remember_current_agent_focus();
        if self.agent_aux.is_some() {
            let _ = self.hide_auxiliary_agent("main_agent_replaced", true);
        }
        if let Some(key) = previous_key.clone() {
            self.agent_focus_by_agent.insert(key, previous_focus);
        }
        if let Some(old_agent) = self.active_agent.take() {
            let old_info = old_agent.info.clone();
            let old_key = AgentKey::new(&old_info);
            let old_activity = old_agent.activity();
            self.remember_live_info_locally(&old_info);
            self.remember_auxiliary_parent_info(&old_info);
            self.mark_agent_live_locally(old_key, old_activity);
            drop(old_agent);
        }
        let info = agent.info.clone();
        self.remember_live_info_locally(&info);
        self.remember_auxiliary_parent_info(&info);
        self.active_agent = Some(agent);
        debug_log(
            "active_agent_set_done",
            serde_json::json!({
                "previous_key": previous_key.as_ref().map(agent_key_debug_value),
                "incoming_key": agent_key_debug_value(&incoming_key),
                "active": session_info_debug_value(&info),
                "focus": format!("{:?}", self.agent_focus),
                "remembered_focus": self.agent_focus_by_agent.get(&incoming_key).map(|focus| format!("{:?}", focus)),
                "hidden_auxiliaries_before": hidden_auxiliaries_before,
                "hidden_auxiliaries_after": self.hidden_agent_aux.len(),
                "persisted_auxiliaries_before": persisted_auxiliaries_before,
                "persisted_auxiliaries_after": self.persisted_agent_aux.len(),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
    }

    fn live_agent_restore_candidates(&self) -> Vec<SessionInfo> {
        let mut candidates: Vec<SessionInfo> = self
            .sessions
            .iter()
            .chain(self.live_shells.iter())
            .filter(|info| {
                let key = AgentKey::new(info);
                if self.is_auxiliary_agent_key(&key) {
                    return false;
                }
                if self.is_backing_key_for_new_agent(&key) {
                    return false;
                }
                self.agent_states
                    .get(&key)
                    .copied()
                    .is_some_and(is_switchable_agent_state)
            })
            .cloned()
            .collect();
        let mut seen: HashSet<AgentKey> = HashSet::new();
        candidates.retain(|info| seen.insert(AgentKey::new(info)));
        candidates
    }

    #[cfg(test)]
    fn live_agent_restore_candidate(&self) -> Option<SessionInfo> {
        let selected_key = self.current().map(AgentKey::new);
        self.live_agent_restore_candidate_for(selected_key.as_ref())
    }

    fn live_agent_restore_candidate_for(
        &self,
        selected_key: Option<&AgentKey>,
    ) -> Option<SessionInfo> {
        if let Some(selected_key) = selected_key {
            if let Some(info) = self.synthetic_new_agent_for_backing_key(selected_key) {
                return Some(info.clone());
            }
        }
        let candidates = self.live_agent_restore_candidates();
        if candidates.is_empty() {
            return None;
        }
        if let Some(selected_key) = selected_key {
            if let Some(info) = candidates
                .iter()
                .find(|info| AgentKey::new(info) == *selected_key)
            {
                return Some(info.clone());
            }
        }
        candidates.into_iter().next()
    }

    fn live_agent_restore_candidate_entries_debug_value(
        &self,
        selected_key: Option<&AgentKey>,
    ) -> Vec<serde_json::Value> {
        let mut entries = Vec::new();
        for (source, info) in self
            .sessions
            .iter()
            .map(|info| ("sessions", info))
            .chain(self.live_shells.iter().map(|info| ("live_shells", info)))
        {
            let key = AgentKey::new(info);
            let state = self
                .agent_states
                .get(&key)
                .copied()
                .unwrap_or(AgentListState::Idle);
            let is_auxiliary = self.is_auxiliary_agent_key(&key);
            let is_new_agent_backing = self.is_backing_key_for_new_agent(&key);
            let switchable = is_switchable_agent_state(state);
            let persisted_auxiliary = self.persisted_agent_aux.get(&key);
            entries.push(serde_json::json!({
                "source": source,
                "key": agent_key_debug_value(&key),
                "selected": selected_key == Some(&key),
                "state": agent_list_state_debug_value(state),
                "switchable": switchable,
                "persisted_auxiliary": persisted_auxiliary.map(persisted_agent_auxiliary_entry_debug_value),
                "excluded_auxiliary": is_auxiliary,
                "excluded_new_agent_backing": is_new_agent_backing,
                "candidate": switchable && !is_auxiliary && !is_new_agent_backing,
                "info": session_info_debug_value(info),
            }));
        }
        entries
    }

    fn live_coding_agent_cwd_peer_entries_debug_value(
        &self,
        target: &SessionInfo,
    ) -> Vec<serde_json::Value> {
        let target_key = AgentKey::new(target);
        self.sessions
            .iter()
            .map(|info| ("sessions", info))
            .chain(self.live_shells.iter().map(|info| ("live_shells", info)))
            .filter(|(_, candidate)| {
                is_coding_agent_session_info(candidate)
                    && session_cwd_same_folder_cached(&target.cwd, &candidate.cwd)
            })
            .map(|(source, candidate)| {
                let key = AgentKey::new(candidate);
                let cached_state = self
                    .agent_states
                    .get(&key)
                    .copied()
                    .unwrap_or(AgentListState::Idle);
                serde_json::json!({
                    "source": source,
                    "key": agent_key_debug_value(&key),
                    "target_key": key == target_key,
                    "cached_state": agent_list_state_debug_value(cached_state),
                    "switchable": is_switchable_agent_state(cached_state),
                    "info": session_info_debug_value(candidate),
                })
            })
            .collect()
    }

    fn is_auxiliary_agent_key(&self, key: &AgentKey) -> bool {
        self.persisted_agent_aux.contains_key(key)
            || self
                .agent_aux
                .as_ref()
                .is_some_and(|aux| AgentKey::new(&aux.agent.info) == *key)
            || self
                .hidden_agent_aux
                .iter()
                .any(|aux| AgentKey::new(&aux.agent.info) == *key)
            || self.attach_in_flight.as_ref().is_some_and(|attach| {
                matches!(attach.target, AttachTarget::Auxiliary { .. }) && attach.key == *key
            })
            || self.queued_attach.as_ref().is_some_and(|job| {
                matches!(job.ctx.target, AttachTarget::Auxiliary { .. }) && job.ctx.key == *key
            })
    }

    fn synthetic_new_agent_for_backing_key(&self, backing_key: &AgentKey) -> Option<&SessionInfo> {
        self.live_shells.iter().find(|info| {
            if !is_new_agent_session_info(info) {
                return false;
            }
            let synthetic_key = AgentKey::new(info);
            self.new_agent_backing_aliases
                .get(&synthetic_key)
                .is_some_and(|candidate| candidate == backing_key)
        })
    }

    fn is_backing_key_for_new_agent(&self, key: &AgentKey) -> bool {
        self.synthetic_new_agent_for_backing_key(key).is_some()
    }

    fn runtime_info_for_selected_agent(&self, info: &SessionInfo) -> SessionInfo {
        let key = AgentKey::new(info);
        self.synthetic_new_agent_for_backing_key(&key)
            .cloned()
            .unwrap_or_else(|| info.clone())
    }

    fn live_agent_switch_candidate_entries_debug_value(
        &self,
        current_key: &AgentKey,
    ) -> Vec<serde_json::Value> {
        let backing_keys: HashSet<AgentKey> = self
            .live_shells
            .iter()
            .filter(|info| is_new_agent_session_info(info))
            .filter_map(|info| {
                self.new_agent_backing_aliases
                    .get(&AgentKey::new(info))
                    .cloned()
            })
            .collect();
        let mut seen = HashSet::new();
        let mut entries = Vec::new();
        for (source, info) in self
            .sessions
            .iter()
            .map(|info| ("sessions", info))
            .chain(self.live_shells.iter().map(|info| ("live_shells", info)))
        {
            let key = AgentKey::new(info);
            let duplicate = !seen.insert(key.clone());
            let state = self.agent_states.get(&key).copied();
            let current = &key == current_key;
            let backing_for_new_agent = backing_keys.contains(&key);
            let auxiliary = self.is_auxiliary_agent_key(&key);
            let excluded_auxiliary = !current && auxiliary;
            let switchable = state.is_some_and(is_switchable_agent_state);
            let candidate = !duplicate
                && !backing_for_new_agent
                && !excluded_auxiliary
                && (current || switchable);
            entries.push(serde_json::json!({
                "source": source,
                "key": agent_key_debug_value(&key),
                "current": current,
                "duplicate": duplicate,
                "state": optional_agent_list_state_debug_value(state),
                "switchable": switchable,
                "is_auxiliary": auxiliary,
                "excluded_auxiliary": excluded_auxiliary,
                "excluded_backing_for_new_agent": backing_for_new_agent,
                "candidate": candidate,
                "info": session_info_debug_value(info),
            }));
        }
        if let Some(active_agent) = self.active_agent.as_ref() {
            let active_key = AgentKey::new(&active_agent.info);
            let active_key_value = agent_key_debug_value(&active_key);
            if &active_key == current_key
                && !entries.iter().any(|entry| {
                    entry
                        .get("key")
                        .is_some_and(|value| value == &active_key_value)
                })
            {
                entries.push(serde_json::json!({
                    "source": "active_agent_fallback",
                    "key": agent_key_debug_value(&active_key),
                    "current": true,
                    "duplicate": false,
                    "state": optional_agent_list_state_debug_value(self.agent_states.get(&active_key).copied()),
                    "switchable": true,
                    "is_auxiliary": self.is_auxiliary_agent_key(&active_key),
                    "excluded_auxiliary": false,
                    "excluded_backing_for_new_agent": false,
                    "candidate": true,
                    "info": session_info_debug_value(&active_agent.info),
                }));
            }
        }
        entries
    }

    fn agent_sidebar_candidates(&mut self) -> Vec<SessionInfo> {
        let Some(current_info) = self.agent_workspace_info().cloned() else {
            return Vec::new();
        };
        let current_key = AgentKey::new(&current_info);
        // Hoisted out of the filter: probing aliases per entry would rescan
        // `live_shells` (with key clones) for every session on every frame.
        let backing_keys: HashSet<&AgentKey> = self
            .live_shells
            .iter()
            .filter(|info| is_new_agent_session_info(info))
            .filter_map(|info| self.new_agent_backing_aliases.get(&AgentKey::new(info)))
            .collect();
        // Pool = discovered agent sessions ∪ live shell daemons. Keep entries
        // that are either the current pane or have a concrete
        // non-idle state. Visibility is deliberately broader than
        // switchability: foreign-attached and exact-orphan processes must
        // remain visible even though neither can be attached here.
        let mut candidates: Vec<SessionInfo> = self
            .sessions
            .iter()
            .chain(self.live_shells.iter())
            .filter(|info| {
                let key = AgentKey::new(info);
                if backing_keys.contains(&key) {
                    return false;
                }
                if key != current_key && self.is_auxiliary_agent_key(&key) {
                    return false;
                }
                key == current_key
                    || self
                        .agent_states
                        .get(&key)
                        .copied()
                        .is_some_and(is_listed_agent_state)
            })
            .cloned()
            .collect();
        // Defensive dedupe — a key should appear at most once.
        let mut seen: HashSet<AgentKey> = HashSet::new();
        candidates.retain(|info| seen.insert(AgentKey::new(info)));
        if !candidates
            .iter()
            .any(|info| AgentKey::new(info) == current_key)
        {
            candidates.insert(0, current_info);
        }
        // The pool's natural order is unstable: sessions reorder by
        // updated_at as agents work, and live shells arrive in directory
        // scan order. Pin every entry to its first-seen position instead so
        // the sidebar never shuffles under the user; new agents append at
        // the bottom, entries that left the pool free their slot.
        let mut position: HashMap<AgentKey, usize> = self
            .agent_sidebar_order
            .iter()
            .enumerate()
            .map(|(index, key)| (key.clone(), index))
            .collect();
        for info in &candidates {
            let key = AgentKey::new(info);
            if !position.contains_key(&key) {
                position.insert(key.clone(), self.agent_sidebar_order.len());
                self.agent_sidebar_order.push(key);
            }
        }
        // Keep a slot while the agent still exists anywhere in runtime
        // tracking: a transient eligibility flicker (e.g. a brief state gap
        // during an attach handoff or a meta read race) must not cost an
        // entry its position — otherwise it reappears at the bottom and
        // looks like it vanished from where the user was navigating. Slots
        // are freed only when the agent is gone from runtime state and the
        // shell list entirely (ghost heal, discovery prune, daemon exit).
        // Borrow-based membership checks: the registry is small, so direct
        // scans beat building owned key sets every frame.
        let agent_states = &self.agent_states;
        let live_shells = &self.live_shells;
        self.agent_sidebar_order.retain(|key| {
            candidates
                .iter()
                .any(|info| info.provider == key.provider && info.session_id == key.session_id)
                || agent_states.contains_key(key)
                || live_shells
                    .iter()
                    .any(|info| info.provider == key.provider && info.session_id == key.session_id)
        });
        candidates.sort_by_key(|info| {
            position
                .get(&AgentKey::new(info))
                .copied()
                .unwrap_or(usize::MAX)
        });
        candidates
    }

    fn live_agent_switch_candidates(&mut self) -> Vec<SessionInfo> {
        let Some(current_key) = self.current_active_agent_key() else {
            return Vec::new();
        };
        self.agent_sidebar_candidates()
            .into_iter()
            .filter(|info| {
                let key = AgentKey::new(info);
                key == current_key
                    || self
                        .agent_states
                        .get(&key)
                        .copied()
                        .is_some_and(is_switchable_agent_state)
            })
            .collect()
    }

    fn select_visible_session(&mut self, key: &AgentKey) {
        let selected = self
            .visible()
            .iter()
            .position(|info| AgentKey::new(info) == *key);
        if let Some(index) = selected {
            self.list_state.select(Some(index));
            self.preview_scroll = 0;
            debug_log(
                "session_select_visible",
                serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                    "index": index,
                    "visible": self.visible().len(),
                }),
            );
        } else {
            self.list_state.select(None);
            debug_log(
                "session_select_visible_missing",
                serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                    "visible": self.visible().len(),
                }),
            );
        }
    }

    fn current(&self) -> Option<&SessionInfo> {
        let vis = self.visible();
        let i = self.list_state.selected()?;
        vis.get(i).copied()
    }

    fn restore_visible_selection(&mut self, key: &AgentKey) -> bool {
        let selected = self
            .visible_rows()
            .iter()
            .position(|row| AgentKey::new(row.info) == *key);
        let Some(index) = selected else {
            return false;
        };
        self.list_state.select(Some(index));
        self.preview_scroll = 0;
        debug_log(
            "session_restore_visible_selection",
            serde_json::json!({
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "index": index,
                "visible": self.visible().len(),
            }),
        );
        true
    }

    fn move_selection(&mut self, delta: i32) {
        let len = self.visible().len();
        let before = self.list_state.selected();
        self.list_state.select(clamped_selection_index(
            len,
            self.list_state.selected(),
            delta,
        ));
        self.preview_scroll = 0;
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "session_selection_move",
                serde_json::json!({
                    "delta": delta,
                    "before": before,
                    "after": self.list_state.selected(),
                    "visible": len,
                }),
            );
        }
    }

    fn select_first(&mut self) {
        let before = self.list_state.selected();
        if !self.visible().is_empty() {
            self.list_state.select(Some(0));
        } else {
            self.list_state.select(None);
        }
        self.preview_scroll = 0;
        debug_log(
            "session_select_first",
            serde_json::json!({
                "before": before,
                "after": self.list_state.selected(),
                "visible": self.visible().len(),
            }),
        );
    }

    fn select_last(&mut self) {
        let n = self.visible().len();
        let before = self.list_state.selected();
        if n > 0 {
            self.list_state.select(Some(n - 1));
        } else {
            self.list_state.select(None);
        }
        self.preview_scroll = 0;
        debug_log(
            "session_select_last",
            serde_json::json!({
                "before": before,
                "after": self.list_state.selected(),
                "visible": n,
            }),
        );
    }

    fn toggle_focus(&mut self) {
        let before = self.focus;
        self.focus = match self.focus {
            FocusPane::Sessions => FocusPane::Preview,
            FocusPane::Preview => FocusPane::Sessions,
        };
        debug_log(
            "focus_toggle",
            serde_json::json!({
                "before": format!("{:?}", before),
                "after": format!("{:?}", self.focus),
            }),
        );
    }

    fn toggle_session_view(&mut self) {
        let selected_key = self.current().map(AgentKey::new);
        let before = self.session_view;
        self.session_view = self.session_view.toggle();
        if let Some(key) = selected_key.as_ref() {
            self.select_visible_session(key);
            if self.list_state.selected().is_none() {
                self.select_first();
            }
        } else {
            self.select_first();
        }
        self.preview_scroll = 0;
        self.focus = FocusPane::Sessions;
        self.settings.cokacmux.session_view = self.session_view;
        self.status = match self.settings.save() {
            Ok(()) => format!("session view saved: {}", self.session_view.label()),
            Err(e) => format!(
                "session view changed: {} (save failed: {})",
                self.session_view.label(),
                e
            ),
        };
        debug_log(
            "session_view_toggle",
            serde_json::json!({
                "before": before.label(),
                "after": self.session_view.label(),
                "selected": selected_key.as_ref().map(|key| serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                })),
                "selected_index": self.list_state.selected(),
                "status": &self.status,
            }),
        );
    }

    fn toggle_session_scope(&mut self) {
        let selected = self.current().cloned();
        let selected_key = selected.as_ref().map(AgentKey::new);
        let before = self.session_scope;
        let after = before.toggle();
        let parent_key = selected
            .as_ref()
            .and_then(|info| nearest_visible_scope_parent_key(&self.sessions, info, after));
        let cancelled_text_search = self.cancel_pending_search("session_scope_toggle");
        let cancelled_ai_search = self.cancel_pending_ai_search("session_scope_toggle");
        if cancelled_ai_search {
            // The cancellation flag remains owned by the worker. Dropping the pending
            // record makes any racing old-scope result stale and therefore unable to
            // repopulate the newly scoped list. The drain sequence keeps another AI
            // task from touching the cache until that worker has actually exited.
            self.ai_search_draining_seq =
                self.ai_search_pending.as_ref().map(|pending| pending.seq);
            self.ai_search_pending = None;
        }
        let cleared_text_filter = !self.text_filter.is_empty();
        let cleared_ai_results = self.ai_search_results.is_some();
        self.text_filter.clear();
        self.text_filter_matches.clear();
        self.ai_search_results = None;
        self.input_mode = InputMode::Normal;
        self.session_scope = after;

        let restored_selected = selected_key
            .as_ref()
            .is_some_and(|key| self.restore_visible_selection(key));
        let restored_parent = !restored_selected
            && parent_key
                .as_ref()
                .is_some_and(|key| self.restore_visible_selection(key));
        if !restored_selected && !restored_parent {
            self.select_first();
        }
        self.preview_scroll = 0;
        self.focus = FocusPane::Sessions;
        let visible = self.visible().len();
        let hidden = self.hidden_non_root_session_count();
        self.status = format!(
            "session scope for this run: {} ({} visible, {} hidden)",
            self.session_scope.label(),
            visible,
            hidden
        );
        debug_log(
            "session_scope_toggle",
            serde_json::json!({
                "before": before.label(),
                "after": self.session_scope.label(),
                "visible": visible,
                "hidden_non_root": hidden,
                "selected": selected_key.as_ref().map(agent_key_debug_value),
                "parent_found": parent_key.is_some(),
                "restored_selected": restored_selected,
                "restored_parent": restored_parent,
                "cleared_text_filter": cleared_text_filter,
                "cleared_ai_results": cleared_ai_results,
                "cancelled_text_search": cancelled_text_search,
                "cancelled_ai_search": cancelled_ai_search,
                "ai_search_draining_seq": self.ai_search_draining_seq,
                "status": &self.status,
            }),
        );
    }

    fn show_summary_preview(&mut self) {
        let before = self.preview_mode;
        self.preview_mode = Mode::Summary;
        if before != self.preview_mode {
            self.preview_scroll = 0;
        }
        self.focus = FocusPane::Preview;
        self.status = "preview: summary".to_string();
        debug_log(
            "preview_summary_show",
            serde_json::json!({
                "before": preview_mode_label(before),
                "after": preview_mode_label(self.preview_mode),
            }),
        );
    }

    fn scroll_preview(&mut self, delta: i32) {
        let before = self.preview_scroll;
        let next = (self.preview_scroll as i32 + delta).max(0);
        self.preview_scroll = next.min(u16::MAX as i32) as u16;
        debug_log(
            "preview_scroll",
            serde_json::json!({
                "delta": delta,
                "before": before,
                "after": self.preview_scroll,
            }),
        );
    }

    fn scroll_preview_page(&mut self, pages: i32) {
        let page = self.preview_page_height.max(1) as i32;
        self.scroll_preview(page * pages);
    }

    fn preview_top(&mut self) {
        self.preview_scroll = 0;
        debug_log("preview_top", serde_json::json!({}));
    }

    fn preview_bottom(&mut self) {
        self.preview_scroll = u16::MAX;
        debug_log("preview_bottom", serde_json::json!({}));
    }

    fn poll_preview_results(&mut self) {
        while let Ok(result) = self.preview_rx.try_recv() {
            let stale_same_key = self
                .preview_requested
                .as_ref()
                .map(|(key, seq)| key == &result.key && result.seq < *seq)
                .unwrap_or(false);
            if stale_same_key {
                debug_log(
                    "preview_result_stale",
                    serde_json::json!({
                        "seq": result.seq,
                        "provider": result.key.provider.as_str(),
                        "session_id": &result.key.session_id,
                        "mode": preview_mode_label(result.key.mode),
                    }),
                );
                continue;
            }

            let completes_request = self
                .preview_requested
                .as_ref()
                .map(|(key, seq)| key == &result.key && *seq == result.seq)
                .unwrap_or(false);
            self.cache_preview(
                result.key.clone(),
                result.text,
                result.wrap_width,
                result.lines,
            );
            if completes_request {
                self.preview_requested = None;
            }
            debug_log(
                "preview_result_cached",
                serde_json::json!({
                    "seq": result.seq,
                    "provider": result.key.provider.as_str(),
                    "session_id": &result.key.session_id,
                    "mode": preview_mode_label(result.key.mode),
                    "wrap_width": result.wrap_width,
                    "lines": self.preview_cache.get(&result.key).map(|entry| entry.lines.len()),
                    "completes_request": completes_request,
                }),
            );
        }
    }

    fn request_preview(&mut self, info: SessionInfo, key: PreviewKey, width: usize) {
        let provider = info.provider;
        let session_id = info.session_id.clone();
        let mode = key.mode;
        if self.preview_cache.contains_key(&key) {
            if TRACE_ENABLED.load(Ordering::Relaxed) {
                trace_log(
                    "preview_request_cache_hit",
                    serde_json::json!({
                        "provider": key.provider.as_str(),
                        "session_id": &key.session_id,
                        "mode": preview_mode_label(key.mode),
                        "width": width,
                    }),
                );
            }
            return;
        }
        if self
            .preview_requested
            .as_ref()
            .map(|(requested_key, _)| requested_key == &key)
            .unwrap_or(false)
        {
            if TRACE_ENABLED.load(Ordering::Relaxed) {
                trace_log(
                    "preview_request_already_pending",
                    serde_json::json!({
                        "provider": key.provider.as_str(),
                        "session_id": &key.session_id,
                        "mode": preview_mode_label(key.mode),
                        "width": width,
                    }),
                );
            }
            return;
        }

        self.preview_seq = self.preview_seq.wrapping_add(1);
        let seq = self.preview_seq;
        let request = PreviewRequest {
            seq,
            key: key.clone(),
            info,
            width: width.max(1),
            wake_tx: self.main_tx.clone(),
        };
        if self.preview_tx.send(request).is_ok() {
            self.preview_requested = Some((key, seq));
            debug_log(
                "preview_request_sent",
                serde_json::json!({
                    "seq": seq,
                    "provider": provider.as_str(),
                    "session_id": &session_id,
                    "mode": preview_mode_label(mode),
                    "width": width.max(1),
                }),
            );
        } else {
            let text = "preview worker stopped".to_string();
            let lines = wrap_preview_lines(&text, width);
            self.cache_preview(key, text, width.max(1), lines);
            self.preview_requested = None;
            debug_log(
                "preview_request_worker_stopped",
                serde_json::json!({
                    "seq": seq,
                    "provider": provider.as_str(),
                    "session_id": &session_id,
                    "width": width.max(1),
                }),
            );
        }
    }

    fn cache_preview(
        &mut self,
        key: PreviewKey,
        text: String,
        wrap_width: usize,
        lines: Vec<String>,
    ) {
        let started = Instant::now();
        let line_count = lines.len();
        self.preview_cache_order.retain(|existing| existing != &key);
        self.preview_cache_order.push_back(key.clone());
        self.preview_cache
            .insert(key, PreviewEntry::new(text, wrap_width, lines));
        while self.preview_cache_order.len() > PREVIEW_CACHE_LIMIT {
            if let Some(old) = self.preview_cache_order.pop_front() {
                self.preview_cache.remove(&old);
                debug_log(
                    "preview_cache_evict",
                    serde_json::json!({
                        "provider": old.provider.as_str(),
                        "session_id": &old.session_id,
                        "mode": preview_mode_label(old.mode),
                    }),
                );
            }
        }
        debug_log(
            "preview_cache_store",
            serde_json::json!({
                "provider": self.preview_cache_order.back().map(|key| key.provider.as_str()),
                "session_id": self.preview_cache_order.back().map(|key| key.session_id.as_str()),
                "wrap_width": wrap_width,
                "lines": line_count,
                "entries": self.preview_cache_order.len(),
                "elapsed_ms": started.elapsed().as_millis(),
            }),
        );
    }

    fn clear_preview_cache(&mut self) {
        let entries = self.preview_cache.len();
        self.preview_cache.clear();
        self.preview_cache_order.clear();
        self.preview_requested = None;
        debug_log(
            "preview_cache_clear",
            serde_json::json!({
                "entries": entries,
            }),
        );
    }

    fn drop_cached_preview(&mut self, key: &PreviewKey) {
        let removed = self.preview_cache.remove(key).is_some();
        self.preview_cache_order.retain(|existing| existing != key);
        debug_log(
            "preview_cache_drop",
            serde_json::json!({
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "mode": preview_mode_label(key.mode),
                "removed": removed,
            }),
        );
    }

    fn ensure_wrapped_preview(&mut self, key: &PreviewKey, width: usize) -> Option<usize> {
        let entry = self.preview_cache.get_mut(key)?;
        let width = width.max(1);
        if entry.wrap_width != width {
            let before = entry.wrap_width;
            entry.lines = wrap_preview_lines(&entry.text, width);
            entry.summary_style_states = preview_summary_style_states_for_lines(&entry.lines);
            entry.wrap_width = width;
            debug_log(
                "preview_rewrap",
                serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                    "mode": preview_mode_label(key.mode),
                    "before_width": before,
                    "after_width": width,
                    "lines": entry.lines.len(),
                }),
            );
        }
        Some(entry.lines.len())
    }

    fn preview_needs_scrollbar(
        &mut self,
        key: &PreviewKey,
        width: usize,
        height: usize,
    ) -> Option<bool> {
        let entry = self.preview_cache.get_mut(key)?;
        let width = width.max(1);
        if let Some(probe) = entry.scrollbar_probe {
            if probe.width == width && probe.height == height {
                return Some(probe.needed);
            }
        }
        let line_count = if entry.wrap_width == width {
            entry.lines.len()
        } else {
            wrap_preview_line_count(&entry.text, width)
        };
        let needed = width > 1 && line_count > height;
        entry.scrollbar_probe = Some(PreviewScrollbarProbe {
            width,
            height,
            needed,
        });
        Some(needed)
    }

    fn preview_visible_lines(&self, key: &PreviewKey, start: usize, height: usize) -> Vec<String> {
        self.preview_cache
            .get(key)
            .map(|entry| {
                entry
                    .lines
                    .iter()
                    .skip(start)
                    .take(height)
                    .cloned()
                    .collect()
            })
            .unwrap_or_default()
    }

    fn preview_summary_style_state_before(
        &self,
        key: &PreviewKey,
        start: usize,
    ) -> PreviewSummaryStyleState {
        self.preview_cache
            .get(key)
            .and_then(|entry| {
                entry
                    .summary_style_states
                    .get(start)
                    .copied()
                    .or_else(|| entry.summary_style_states.last().copied())
            })
            .unwrap_or_default()
    }

    /// Reap the active agent if its reader thread (or daemon) signaled
    /// exit. Events themselves arrive via the main-loop channel — this
    /// method no longer pulls from the socket; it only reacts to flags
    /// the channel-driven `process_agent_event` already set.
    fn poll_agent_sessions(&mut self) {
        let pending_kill_key = self
            .agent_kill_pending
            .as_ref()
            .map(|pending| pending.key.clone());
        if let Some(agent) = self.active_agent.as_mut() {
            if let Some(exit_status) = agent.exited.clone() {
                let active_key = AgentKey::new(&agent.info);
                if pending_kill_key.as_ref() == Some(&active_key) {
                    return;
                }
                let provider = agent.info.provider;
                let session_id = agent.info.session_id.clone();
                let reader_id = agent.reader_id;
                if agent.drain_pending_output(AGENT_CLIENT_OUTPUT_DRAIN_BYTES) {
                    self.schedule_agent_output_available(reader_id);
                    return;
                }
                let exited_label = live_agent_status_label(&agent.info);
                let cols = agent.pty_size.cols;
                let rows = agent.pty_size.rows;
                // Auto-switch to the next live agent only while the agent pane
                // is the visible view, and never over a user-initiated attach
                // already in flight or queued — a background exit must not
                // steal where the user is navigating.
                let next_info = if self.is_agent_view()
                    && self.attach_in_flight.is_none()
                    && self.queued_attach.is_none()
                {
                    self.next_agent_after_current()
                } else {
                    None
                };
                self.active_agent = None;
                let exited_key = AgentKey {
                    provider,
                    session_id: session_id.clone(),
                };
                let released_auxiliaries =
                    self.release_auxiliaries_for_parent(&exited_key, "main_agent_exit");
                self.agent_states.remove(&exited_key);
                self.live_shells
                    .retain(|info| AgentKey::new(info) != exited_key);
                self.agent_focus_by_agent.remove(&exited_key);
                self.agent_focus = AgentFocusPane::Main;
                self.discard_pending_agent_runtime_refresh();
                self.status = format!(
                    "{} agent {} exited ({})",
                    provider.as_str(),
                    truncate_width(&session_id, 14),
                    exit_status
                );
                debug_log(
                    "active_agent_exit_reaped",
                    serde_json::json!({
                        "provider": provider.as_str(),
                        "session_id": &session_id,
                        "exit_status": exit_status,
                        "reader_id": reader_id,
                        "auto_switch": next_info.as_ref().map(session_info_debug_value),
                        "released_auxiliaries": released_auxiliaries,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                self.request_session_refresh_preserving_status();
                self.refresh_agent_runtime_states();
                if let Some(next_info) = next_info {
                    self.attach_after_agent_exit(
                        next_info,
                        cols,
                        rows,
                        provider,
                        &session_id,
                        &exited_label,
                    );
                }
                return;
            }
        }

        if let Some(aux) = self.agent_aux.as_mut() {
            if let Some(exit_status) = aux.agent.exited.clone() {
                let key = AgentKey::new(&aux.agent.info);
                if pending_kill_key.as_ref() == Some(&key) {
                    return;
                }
                let label = live_agent_status_label(&aux.agent.info);
                let reader_id = aux.agent.reader_id;
                if aux
                    .agent
                    .drain_pending_output(AGENT_CLIENT_OUTPUT_DRAIN_BYTES)
                {
                    self.schedule_agent_output_available(reader_id);
                    return;
                }
                self.agent_aux = None;
                if self.agent_focus == AgentFocusPane::Auxiliary {
                    self.set_agent_focus(AgentFocusPane::Main);
                }
                self.remove_persisted_agent_auxiliary(&key, "auxiliary_exited");
                self.live_shells.retain(|info| AgentKey::new(info) != key);
                self.agent_states.remove(&key);
                self.status = format!("right {} exited ({})", label, exit_status);
                debug_log(
                    "agent_auxiliary_exit_reaped",
                    serde_json::json!({
                        "label": label,
                        "key": agent_key_debug_value(&key),
                        "exit_status": exit_status,
                        "reader_id": reader_id,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                self.refresh_agent_runtime_states();
            }
        }

        let mut exited_hidden = None;
        for index in 0..self.hidden_agent_aux.len() {
            if let Some(exit_status) = self.hidden_agent_aux[index].agent.exited.clone() {
                let reader_id = self.hidden_agent_aux[index].agent.reader_id;
                if self.hidden_agent_aux[index]
                    .agent
                    .drain_pending_output(AGENT_CLIENT_OUTPUT_DRAIN_BYTES)
                {
                    self.schedule_agent_output_available(reader_id);
                    return;
                }
                let label = live_agent_status_label(&self.hidden_agent_aux[index].agent.info);
                let key = AgentKey::new(&self.hidden_agent_aux[index].agent.info);
                exited_hidden = Some((index, label, key, exit_status));
                break;
            }
        }
        if let Some((index, label, key, exit_status)) = exited_hidden {
            let aux = self.hidden_agent_aux.remove(index);
            drop(aux);
            self.remove_persisted_agent_auxiliary(&key, "hidden_auxiliary_exited");
            self.live_shells.retain(|info| AgentKey::new(info) != key);
            self.agent_states.remove(&key);
            self.status = format!("hidden right {} exited ({})", label, exit_status);
            debug_log(
                "hidden_agent_auxiliary_exit_reaped",
                serde_json::json!({
                    "label": label,
                    "key": agent_key_debug_value(&key),
                    "exit_status": exit_status,
                    "hidden_index": index,
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            self.refresh_agent_runtime_states();
        }

        self.recover_disconnected_agent_connection();
    }

    /// Replace one socket client whose reader/writer ended without changing
    /// the daemon/session lifetime model. Explicit daemon `Exited`/`Error`
    /// events are handled above; this path preserves live-shell and auxiliary
    /// registry entries and merely opens a fresh client connection.
    fn recover_disconnected_agent_connection(&mut self) {
        if self.main_tx.is_none() || self.attach_in_flight.is_some() || self.queued_attach.is_some()
        {
            return;
        }

        // A forced kill commonly closes the daemon socket before the kill
        // worker reports completion. Treating that EOF as an ordinary
        // connection loss races the worker: we drop the current client and
        // try to reconnect to the process that is being terminated, exposing
        // the sessions view in the gap. Keep the matching client mounted until
        // the kill result chooses the real replacement (or reports failure).
        let pending_kill_connection_ended =
            self.agent_kill_pending.as_ref().is_some_and(|pending| {
                self.active_agent
                    .as_ref()
                    .into_iter()
                    .chain(self.agent_aux.as_ref().map(|aux| &aux.agent))
                    .chain(self.hidden_agent_aux.iter().map(|aux| &aux.agent))
                    .any(|agent| {
                        agent.exited.is_none()
                            && agent.connection_ended.is_some()
                            && AgentKey::new(&agent.info) == pending.key
                    })
            });
        if pending_kill_connection_ended {
            return;
        }

        if self
            .active_agent
            .as_ref()
            .is_some_and(|agent| agent.exited.is_none() && agent.connection_ended.is_some())
        {
            let reader_id = self.active_agent.as_ref().map(|agent| agent.reader_id);
            if self
                .active_agent
                .as_ref()
                .is_some_and(AgentClient::has_pending_output)
            {
                if let Some(reader_id) = reader_id {
                    self.schedule_agent_output_available(reader_id);
                }
                return;
            }
            let agent = self
                .active_agent
                .take()
                .expect("active agent checked above");
            let info = agent.info.clone();
            let key = AgentKey::new(&info);
            let cols = agent.pty_size.cols;
            let rows = agent.pty_size.rows;
            let activity = agent.activity();
            let reason = agent.connection_ended.clone();
            self.remember_live_info_locally(&info);
            self.remember_auxiliary_parent_info(&info);
            self.mark_agent_live_locally(key.clone(), activity);
            drop(agent);
            debug_log(
                "agent_connection_reconnect_start",
                serde_json::json!({
                    "target": "main",
                    "key": agent_key_debug_value(&key),
                    "reason": reason,
                    "cols": cols,
                    "rows": rows,
                }),
            );
            self.attach_existing_live_agent(info, cols, rows, "connection_recovery");
            return;
        }

        if self
            .agent_aux
            .as_ref()
            .is_some_and(|aux| aux.agent.exited.is_none() && aux.agent.connection_ended.is_some())
        {
            let reader_id = self.agent_aux.as_ref().map(|aux| aux.agent.reader_id);
            if self
                .agent_aux
                .as_ref()
                .is_some_and(|aux| aux.agent.has_pending_output())
            {
                if let Some(reader_id) = reader_id {
                    self.schedule_agent_output_available(reader_id);
                }
                return;
            }
            let aux = self.agent_aux.take().expect("auxiliary checked above");
            let info = aux.agent.info.clone();
            let key = AgentKey::new(&info);
            let cols = aux.agent.pty_size.cols;
            let rows = aux.agent.pty_size.rows;
            let activity = aux.agent.activity();
            let reason = aux.agent.connection_ended.clone();
            let focus_on_ready = self.agent_focus == AgentFocusPane::Auxiliary;
            self.remember_live_info_locally(&info);
            self.mark_agent_live_locally(key.clone(), activity);
            drop(aux.agent);
            debug_log(
                "agent_connection_reconnect_start",
                serde_json::json!({
                    "target": "auxiliary",
                    "kind": aux.kind.label(),
                    "parent": agent_key_debug_value(&aux.parent),
                    "key": agent_key_debug_value(&key),
                    "reason": reason,
                    "cols": cols,
                    "rows": rows,
                }),
            );
            self.request_auxiliary_connection_recovery(
                aux.kind,
                aux.parent,
                info,
                cols,
                rows,
                focus_on_ready,
            );
            return;
        }

        let Some(index) = self
            .hidden_agent_aux
            .iter()
            .position(|aux| aux.agent.exited.is_none() && aux.agent.connection_ended.is_some())
        else {
            return;
        };
        if self.hidden_agent_aux[index].agent.has_pending_output() {
            self.schedule_agent_output_available(self.hidden_agent_aux[index].agent.reader_id);
            return;
        }
        // A hidden auxiliary does not need to hold a client connection. Keep
        // its persisted relationship and live-shell entry; normal parent
        // restoration will attach a fresh client when it becomes visible.
        let aux = self.hidden_agent_aux.remove(index);
        let info = aux.agent.info.clone();
        let key = AgentKey::new(&info);
        let activity = aux.agent.activity();
        let reason = aux.agent.connection_ended.clone();
        self.remember_live_info_locally(&info);
        self.mark_agent_live_locally(key.clone(), activity);
        drop(aux.agent);
        debug_log(
            "hidden_agent_connection_released_for_reconnect",
            serde_json::json!({
                "kind": aux.kind.label(),
                "parent": agent_key_debug_value(&aux.parent),
                "key": agent_key_debug_value(&key),
                "reason": reason,
                "persisted": self.persisted_agent_aux.contains_key(&key),
            }),
        );
    }

    fn request_auxiliary_connection_recovery(
        &mut self,
        kind: AgentAuxKind,
        parent: AgentKey,
        info: SessionInfo,
        cols: u16,
        rows: u16,
        focus_on_ready: bool,
    ) {
        let key = AgentKey::new(&info);
        self.request_attach(AttachJob {
            info,
            cols,
            rows,
            kind: AttachJobKind::Existing,
            run_prechecks: false,
            prompt_for_saved_data: false,
            settings: self.settings.clone(),
            ctx: AttachUiCtx {
                key,
                target: AttachTarget::Auxiliary { kind, parent },
                status_attached: format!("reconnected right {}", kind.label()),
                status_started: format!("reconnected right {}", kind.label()),
                status_err_prefix: format!("right {} reconnect failed: ", kind.label()),
                status_prepare_err_prefix: format!("right {} reconnect failed: ", kind.label()),
                focus_auxiliary_on_ready: focus_on_ready,
                main_focus_override_on_ready: None,
                select_visible: false,
                cokacdir_dialog_on_error: false,
                remove_dead_on_notfound: false,
                log_origin: Some(format!("connection_recovery:{}", kind.label())),
                ready_event: "agent_auxiliary_reconnect_ready",
                failed_event: "agent_auxiliary_reconnect_failed",
            },
        });
    }

    /// Allocate the next reader id and return a clone of the main-loop
    /// sender so we can build a new `AgentClient`. Must be called from a
    /// context where `main_tx` has been installed (i.e. inside `run`).
    fn agent_attach_handles(&mut self) -> (Sender<MainEvent>, u64) {
        let tx = self
            .main_tx
            .clone()
            .expect("main_tx not installed before agent attach");
        let id = self.next_reader_id;
        self.next_reader_id = self.next_reader_id.saturating_add(1);
        (tx, id)
    }

    fn schedule_agent_output_available(&self, reader_id: u64) {
        if let Some(tx) = self.main_tx.clone() {
            let queued_at_epoch_ms = current_epoch_ms();
            let send_result = tx.send(MainEvent::AgentOutputAvailable {
                reader_id,
                queued_at_epoch_ms,
            });
            let send_ok = send_result.is_ok();
            let send_error = send_result.err().map(|e| e.to_string());
            debug_log(
                "agent_output_available_scheduled",
                serde_json::json!({
                    "reader_id": reader_id,
                    "queued_at_epoch_ms": queued_at_epoch_ms,
                    "ok": send_ok,
                    "error": send_error,
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
        } else {
            debug_log(
                "agent_output_available_schedule_skipped",
                serde_json::json!({
                    "reader_id": reader_id,
                    "reason": "main_tx_missing",
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
        }
    }

    fn agent_client_mut_by_reader_id(&mut self, reader_id: u64) -> Option<&mut AgentClient> {
        if self
            .active_agent
            .as_ref()
            .is_some_and(|agent| agent.reader_id == reader_id)
        {
            return self.active_agent.as_mut();
        }
        if self
            .agent_aux
            .as_ref()
            .is_some_and(|aux| aux.agent.reader_id == reader_id)
        {
            return self.agent_aux.as_mut().map(|aux| &mut aux.agent);
        }
        if let Some(index) = self
            .hidden_agent_aux
            .iter()
            .position(|aux| aux.agent.reader_id == reader_id)
        {
            return Some(&mut self.hidden_agent_aux[index].agent);
        }
        None
    }

    /// Apply a `MainEvent::AgentEvent` to the active agent if it still
    /// matches `reader_id`. Late events from a replaced agent are silently
    /// dropped.
    fn on_agent_event(&mut self, reader_id: u64, event: AgentDaemonEvent) {
        let event_debug = DEBUG_ENABLED
            .load(Ordering::Relaxed)
            .then(|| agent_daemon_event_debug_value(&event));
        let (agent_info, terminal_event, should_schedule_output) = {
            let Some(agent) = self.agent_client_mut_by_reader_id(reader_id) else {
                debug_log(
                    "agent_event_ignored",
                    serde_json::json!({
                        "reader_id": reader_id,
                        "reason": "reader_not_current",
                        "event": event_debug,
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                return;
            };
            let agent_info = agent.info.clone();
            let terminal_event = matches!(
                &event,
                AgentDaemonEvent::Exited { .. } | AgentDaemonEvent::Error { .. }
            );
            agent.process_agent_event(event);
            let should_schedule_output = terminal_event && agent.has_pending_output();
            (agent_info, terminal_event, should_schedule_output)
        };
        debug_log(
            "agent_event_processed",
            serde_json::json!({
                "reader_id": reader_id,
                "event": event_debug,
                "agent": session_info_debug_value(&agent_info),
                "terminal_event": terminal_event,
                "scheduled_output": should_schedule_output,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if should_schedule_output {
            self.schedule_agent_output_available(reader_id);
        }
    }

    fn on_agent_output_available(&mut self, reader_id: u64) {
        let has_more = {
            let Some(agent) = self.agent_client_mut_by_reader_id(reader_id) else {
                debug_log(
                    "agent_output_available_ignored",
                    serde_json::json!({
                        "reader_id": reader_id,
                        "reason": "reader_not_current",
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                return;
            };
            agent.drain_pending_output(AGENT_CLIENT_OUTPUT_DRAIN_BYTES)
        };
        if TRACE_ENABLED.load(Ordering::Relaxed) {
            trace_log(
                "agent_output_available_processed",
                serde_json::json!({
                    "reader_id": reader_id,
                    "has_more": has_more,
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
        }
        if has_more {
            self.schedule_agent_output_available(reader_id);
        }
    }

    /// Apply a reader-thread exit signal. Losing the client socket is not
    /// proof that the daemon or its PTY child exited; park the connection for
    /// asynchronous runtime verification and reattach instead of setting the
    /// terminal `exited` flag.
    fn on_agent_reader_ended(&mut self, reader_id: u64, reason: String) {
        let (agent_info, should_schedule_output, unacknowledged_input) = {
            let Some(agent) = self.agent_client_mut_by_reader_id(reader_id) else {
                debug_log(
                    "agent_reader_ended_ignored",
                    serde_json::json!({
                        "reader_id": reader_id,
                        "reason": reason,
                        "ignore_reason": "reader_not_current",
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                return;
            };
            let agent_info = agent.info.clone();
            let mut should_schedule_output = false;
            if agent.exited.is_none() && agent.connection_ended.is_none() {
                agent.connection_ended = Some(
                    agent.connection_end_reason_with_unacknowledged_input(format!(
                        "reader ended: {}",
                        reason
                    )),
                );
                if agent.has_pending_output() {
                    should_schedule_output = true;
                }
            }
            (
                agent_info,
                should_schedule_output,
                agent.unacknowledged_input_summary(),
            )
        };
        debug_log(
            "agent_reader_ended_processed",
            serde_json::json!({
                "reader_id": reader_id,
                "reason": reason,
                "agent": session_info_debug_value(&agent_info),
                "unacknowledged_input": unacknowledged_input.map(|(frames, bytes)| serde_json::json!({
                    "frames": frames,
                    "bytes": bytes,
                })),
                "scheduled_output": should_schedule_output,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if should_schedule_output {
            self.schedule_agent_output_available(reader_id);
        }
        self.status = match unacknowledged_input {
            Some((frames, bytes)) => format!(
                "{} connection interrupted; retained {} unconfirmed input bytes in {} frame(s)",
                live_agent_status_label(&agent_info),
                bytes,
                frames
            ),
            None => format!(
                "{} connection interrupted; reconnecting...",
                live_agent_status_label(&agent_info)
            ),
        };
        self.refresh_agent_runtime_states_discovering_live_shells();
    }

    /// Apply a writer-thread exit signal. Like reader EOF, this proves only
    /// that the current socket cannot carry requests; preserve runtime and
    /// auxiliary state until definitive discovery and reconnect it.
    fn on_agent_writer_ended(&mut self, reader_id: u64, reason: String) {
        let (agent_info, should_schedule_output, unacknowledged_input) = {
            let Some(agent) = self.agent_client_mut_by_reader_id(reader_id) else {
                debug_log(
                    "agent_writer_ended_ignored",
                    serde_json::json!({
                        "reader_id": reader_id,
                        "reason": reason,
                        "ignore_reason": "reader_not_current",
                        "snapshot": app_runtime_snapshot_debug_value(self, false),
                    }),
                );
                return;
            };
            let agent_info = agent.info.clone();
            let mut should_schedule_output = false;
            if agent.exited.is_none() && agent.connection_ended.is_none() {
                agent.connection_ended = Some(
                    agent.connection_end_reason_with_unacknowledged_input(format!(
                        "writer ended: {}",
                        reason
                    )),
                );
                if agent.has_pending_output() {
                    should_schedule_output = true;
                }
            }
            (
                agent_info,
                should_schedule_output,
                agent.unacknowledged_input_summary(),
            )
        };
        debug_log(
            "agent_writer_ended_processed",
            serde_json::json!({
                "reader_id": reader_id,
                "reason": reason,
                "agent": session_info_debug_value(&agent_info),
                "unacknowledged_input": unacknowledged_input.map(|(frames, bytes)| serde_json::json!({
                    "frames": frames,
                    "bytes": bytes,
                })),
                "scheduled_output": should_schedule_output,
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if should_schedule_output {
            self.schedule_agent_output_available(reader_id);
        }
        self.status = match unacknowledged_input {
            Some((frames, bytes)) => format!(
                "{} connection interrupted; retained {} unconfirmed input bytes in {} frame(s)",
                live_agent_status_label(&agent_info),
                bytes,
                frames
            ),
            None => format!(
                "{} connection interrupted; reconnecting...",
                live_agent_status_label(&agent_info)
            ),
        };
        self.refresh_agent_runtime_states_discovering_live_shells();
    }

    /// Open a shell pane at the cwd of the currently focused session. The
    /// shell runs through the same AgentClient/daemon infrastructure as the
    /// real agents (PTY + vt100 + Unix socket), keyed by a unique synthetic
    /// session id. Ctrl+] / Ctrl+[ switches back to the sessions screen, Ctrl+K kills.
    /// Returns the cwd that should be used when the user spawns a new
    /// shell pane while an agent is in the active view. For real agents
    /// it's the session's cwd; for shell panes it's the *live* cwd as
    /// recorded by the daemon's most recent meta write (so `cd ..` inside
    /// the shell is reflected when Ctrl+N is pressed again from there).
    fn active_agent_current_cwd(&self) -> Option<String> {
        let agent = self.active_agent.as_ref()?;
        if is_plain_pty_tool_session_info(&agent.info) {
            let key = AgentKey::new(&agent.info);
            for shell in &self.live_shells {
                if AgentKey::new(shell) == key && !shell.cwd.is_empty() {
                    return Some(shell.cwd.clone());
                }
            }
        }
        if agent.info.cwd.is_empty() {
            None
        } else {
            Some(agent.info.cwd.clone())
        }
    }

    /// Common shell-spawn path: build a new shell `SessionInfo` at `cwd`,
    /// install it as the active agent, and switch to the agents view.
    fn open_shell_at_cwd(
        &mut self,
        cwd: String,
        cols: u16,
        rows: u16,
        origin_tag: &str,
        main_focus_override_on_ready: Option<AgentFocusPane>,
    ) -> Option<AgentKey> {
        if cwd.is_empty() {
            self.status = "no cwd to open a shell at.".into();
            return None;
        }
        let info = shell_session_info_for_cwd(cwd.clone());
        let key = AgentKey::new(&info);
        debug_log(
            "shell_open_start",
            serde_json::json!({
                "session_id": &info.session_id,
                "cwd": &cwd,
                "origin": origin_tag,
            }),
        );
        let cwd_label = truncate_width(&display_cwd_str(&cwd), 40);
        self.request_attach(AttachJob {
            info,
            cols,
            rows,
            kind: AttachJobKind::OrStart {
                launch_mode: AgentLaunchMode::Normal,
            },
            run_prechecks: false,
            prompt_for_saved_data: false,
            settings: self.settings.clone(),
            ctx: AttachUiCtx {
                key: key.clone(),
                target: AttachTarget::MainAgent,
                status_attached: format!("attached shell at {}", cwd_label),
                status_started: format!("started shell at {}", cwd_label),
                status_err_prefix: "shell open failed: ".to_string(),
                status_prepare_err_prefix: "shell open failed: ".to_string(),
                focus_auxiliary_on_ready: false,
                main_focus_override_on_ready,
                select_visible: false,
                cokacdir_dialog_on_error: false,
                remove_dead_on_notfound: false,
                log_origin: Some(origin_tag.to_string()),
                ready_event: "shell_open_ok",
                failed_event: "shell_open_failed",
            },
        });
        Some(key)
    }

    fn begin_new_session_from_focused(&mut self) {
        let cwd = self
            .current()
            .map(|info| info.cwd.clone())
            .filter(|cwd| !cwd.is_empty())
            .or_else(process_cwd_string)
            .unwrap_or_default();
        let provider = self
            .current()
            .map(|info| info.provider)
            .unwrap_or(Provider::Codex);
        self.begin_new_session(cwd, provider, "sessions");
    }

    fn begin_new_session_from_active_agent(&mut self) {
        let cwd = self
            .active_agent_current_cwd()
            .or_else(process_cwd_string)
            .unwrap_or_default();
        let provider = self
            .active_agent
            .as_ref()
            .map(|agent| agent.info.provider)
            .filter(|_| {
                self.active_agent
                    .as_ref()
                    .is_some_and(|agent| !is_plain_pty_tool_session_info(&agent.info))
            })
            .unwrap_or(Provider::Codex);
        self.begin_new_session(cwd, provider, "agent");
    }

    fn begin_new_session(&mut self, cwd: String, provider: Provider, origin: &str) {
        if self.reject_while_data_task_running("opening a new session") {
            return;
        }
        debug_log(
            "new_session_open",
            serde_json::json!({
                "origin": origin,
                "cwd": &cwd,
                "provider": provider.as_str(),
            }),
        );
        let cwd_cursor = cwd.len();
        self.status = "choose what to start.".into();
        let provider_options =
            available_agent_provider_options(&self.settings.cokacmux.agent_programs);
        let provider =
            normalize_agent_provider_selection(provider, &provider_options).unwrap_or(provider);
        self.input_mode = InputMode::NewSession {
            selected: NEW_SESSION_FIELD_KIND,
            kind: NewSessionKind::Terminal,
            cwd,
            cwd_cursor,
            cwd_completion: NewSessionPathCompletion::default(),
            provider,
            provider_options,
            launch_mode: AgentLaunchMode::Normal,
        };
    }

    fn start_new_session_from_modal(
        &mut self,
        kind: NewSessionKind,
        cwd: String,
        provider: Provider,
        launch_mode: AgentLaunchMode,
        cols: u16,
        rows: u16,
    ) -> bool {
        if self.reject_while_data_task_running("starting a new session") {
            return false;
        }
        if kind == NewSessionKind::CodingAgent
            && !agent_provider_available(provider, &self.settings.cokacmux.agent_programs)
        {
            self.status = format!("{} agent is not installed.", provider.as_str());
            debug_log(
                "new_session_provider_unavailable",
                serde_json::json!({
                    "provider": provider.as_str(),
                }),
            );
            return false;
        }
        if cwd.trim().is_empty() {
            self.status = "folder path is required.".into();
            debug_log(
                "new_session_cwd_empty",
                serde_json::json!({
                    "kind": kind.as_str(),
                    "provider": provider.as_str(),
                    "launch_mode": launch_mode.as_str(),
                    "status": &self.status,
                }),
            );
            return false;
        }
        self.new_session_launch_seq = self.new_session_launch_seq.saturating_add(1);
        let seq = self.new_session_launch_seq;
        self.new_session_launch = Some(NewSessionLaunchPending {
            seq,
            kind,
            raw_cwd: cwd.clone(),
            provider,
            launch_mode,
            started_at: Instant::now(),
            stage: NewSessionLaunchStage::Preparing,
            attach_key: None,
        });
        self.status = format!(
            "preparing {}...",
            new_session_launch_target_label(kind, provider)
        );
        debug_log(
            "new_session_prepare_start",
            serde_json::json!({
                "seq": seq,
                "kind": kind.as_str(),
                "cwd": &cwd,
                "provider": provider.as_str(),
                "launch_mode": launch_mode.as_str(),
                "cols": cols,
                "rows": rows,
            }),
        );
        let Some(tx) = self.main_tx.clone() else {
            let result = run_new_session_prepare(seq, kind, cwd, provider, launch_mode, cols, rows);
            self.on_new_session_prepare_result(Box::new(result));
            return true;
        };
        match thread::Builder::new()
            .name("cokacmux-new-session".into())
            .spawn(move || {
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    run_new_session_prepare(seq, kind, cwd, provider, launch_mode, cols, rows)
                }));
                let event = match outcome {
                    Ok(result) => MainEvent::NewSessionPrepareResult(Box::new(result)),
                    Err(_) => {
                        background_worker_panicked(BackgroundWorkerKind::NewSessionPrepare, seq)
                    }
                };
                let _ = tx.send(event);
            }) {
            Ok(_) => true,
            Err(e) => {
                self.new_session_launch = None;
                self.status = format!("new session worker failed: {}", e);
                debug_log(
                    "new_session_prepare_worker_spawn_failed",
                    serde_json::json!({
                        "seq": seq,
                        "kind": kind.as_str(),
                        "provider": provider.as_str(),
                        "launch_mode": launch_mode.as_str(),
                        "error": e.to_string(),
                    }),
                );
                false
            }
        }
    }

    // The boxed payload keeps MainEvent compact; unboxing at this boundary would churn callers.
    #[allow(clippy::boxed_local)]
    fn on_new_session_prepare_result(&mut self, result: Box<NewSessionPrepareResult>) {
        let result = *result;
        let pending_seq = self.new_session_launch.as_ref().map(|pending| pending.seq);
        debug_log(
            "new_session_prepare_result_received",
            serde_json::json!({
                "pending_seq": pending_seq,
                "result": new_session_prepare_result_debug_value(&result),
                "snapshot": app_runtime_snapshot_debug_value(self, false),
            }),
        );
        if pending_seq != Some(result.seq) {
            debug_log(
                "new_session_prepare_result_stale",
                serde_json::json!({
                    "seq": result.seq,
                    "pending_seq": pending_seq,
                    "snapshot": app_runtime_snapshot_debug_value(self, false),
                }),
            );
            return;
        }
        let cwd = match result.outcome {
            Ok(cwd) => cwd,
            Err(message) => {
                self.new_session_launch = None;
                self.status = message.clone();
                if matches!(self.input_mode, InputMode::Normal) {
                    let provider_options =
                        available_agent_provider_options(&self.settings.cokacmux.agent_programs);
                    let provider =
                        normalize_agent_provider_selection(result.provider, &provider_options)
                            .unwrap_or(result.provider);
                    let cwd_cursor = result.raw_cwd.len();
                    self.input_mode = InputMode::NewSession {
                        selected: NEW_SESSION_FIELD_CWD,
                        kind: result.kind,
                        cwd: result.raw_cwd,
                        cwd_cursor,
                        cwd_completion: NewSessionPathCompletion::default(),
                        provider,
                        provider_options,
                        launch_mode: result.launch_mode,
                    };
                }
                debug_log(
                    "new_session_normalize_cwd_failed",
                    serde_json::json!({
                        "seq": result.seq,
                        "kind": result.kind.as_str(),
                        "provider": result.provider.as_str(),
                        "launch_mode": result.launch_mode.as_str(),
                        "status": &self.status,
                        "elapsed_ms": result.elapsed_ms,
                    }),
                );
                return;
            }
        };
        debug_log(
            "new_session_start",
            serde_json::json!({
                "seq": result.seq,
                "kind": result.kind.as_str(),
                "cwd": &cwd,
                "provider": result.provider.as_str(),
                "launch_mode": result.launch_mode.as_str(),
                "cols": result.cols,
                "rows": result.rows,
                "prepare_elapsed_ms": result.elapsed_ms,
            }),
        );
        let main_focus_override_on_ready = Some(AgentFocusPane::Main);
        match result.kind {
            NewSessionKind::Terminal => {
                if let Some(key) = self.open_shell_at_cwd(
                    cwd,
                    result.cols,
                    result.rows,
                    "new_session:terminal",
                    main_focus_override_on_ready,
                ) {
                    self.mark_new_session_launch_attach_key(result.seq, key.clone());
                    self.sync_new_session_launch_after_attach_request(result.seq, &key);
                } else {
                    self.new_session_launch = None;
                }
            }
            NewSessionKind::CokacDir => {
                let info = cokacdir_session_info_for_cwd(cwd.clone());
                let key = AgentKey::new(&info);
                self.mark_new_session_launch_attach_key(result.seq, key.clone());
                debug_log(
                    "cokacdir_open_start",
                    serde_json::json!({
                        "session_id": &info.session_id,
                        "cwd": &cwd,
                    }),
                );
                self.attach_agent_without_data_restore_prompt_with_main_focus_override(
                    info,
                    result.cols,
                    result.rows,
                    AgentLaunchMode::Normal,
                    main_focus_override_on_ready,
                );
                self.sync_new_session_launch_after_attach_request(result.seq, &key);
            }
            NewSessionKind::CodingAgent => {
                let info = new_agent_session_info(result.provider, cwd.clone());
                let key = AgentKey::new(&info);
                if self.block_live_coding_agent_cwd_conflict(&info) {
                    self.new_session_launch = None;
                    debug_log(
                        "new_session_launch_done",
                        serde_json::json!({
                            "reason": "cwd_conflict",
                            "key": agent_key_debug_value(&key),
                            "snapshot": app_runtime_snapshot_debug_value(self, false),
                        }),
                    );
                    return;
                }
                self.mark_new_session_launch_attach_key(result.seq, key.clone());
                debug_log(
                    "new_agent_open_start",
                    serde_json::json!({
                        "provider": result.provider.as_str(),
                        "session_id": &info.session_id,
                        "cwd": &cwd,
                        "launch_mode": result.launch_mode.as_str(),
                    }),
                );
                self.attach_agent_with_main_focus_override(
                    info,
                    result.cols,
                    result.rows,
                    result.launch_mode,
                    main_focus_override_on_ready,
                );
                self.sync_new_session_launch_after_attach_request(result.seq, &key);
                debug_log(
                    "new_agent_open_after_attach",
                    serde_json::json!({
                        "provider": result.provider.as_str(),
                        "cwd": &cwd,
                        "launch_mode": result.launch_mode.as_str(),
                        "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                        "show_sessions_view": self.show_sessions_view,
                        "agent_states": agent_state_entries_debug_value(&self.agent_states),
                    }),
                );
            }
        }
    }

    fn begin_agent_launch(&mut self, cols: u16, rows: u16) {
        if self.reject_while_data_task_running("launching an agent") {
            return;
        }
        let Some(info) = self.current().cloned() else {
            self.status = "no session selected.".into();
            return;
        };
        if self.main_tx.is_some() {
            self.refresh_agent_runtime_states();
        }
        self.resolve_agent_launch(info, cols, rows, true);
    }

    fn resolve_agent_launch(&mut self, info: SessionInfo, cols: u16, rows: u16, allow_defer: bool) {
        let runtime_info = self.runtime_info_for_selected_agent(&info);
        let key = AgentKey::new(&runtime_info);
        let cached_state = self
            .agent_states
            .get(&key)
            .copied()
            .unwrap_or(AgentListState::Idle);
        if DEBUG_ENABLED.load(Ordering::Relaxed) {
            debug_log(
                "agent_launch_resolve_start",
                serde_json::json!({
                    "selected": session_info_debug_value(&info),
                    "runtime_info": session_info_debug_value(&runtime_info),
                    "runtime_key": agent_key_debug_value(&key),
                    "allow_defer": allow_defer,
                    "cols": cols,
                    "rows": rows,
                    "cached_state": agent_list_state_debug_value(cached_state),
                    "runtime_refresh_pending": self.runtime_refresh_pending,
                    "runtime_refresh_queued": self.runtime_refresh_queued,
                    "runtime_refresh_seq": self.runtime_refresh_seq,
                    "live_shell_discovery_pending": self.live_shell_discovery_pending,
                    "live_shell_discovery_seq": self.live_shell_discovery_seq,
                    "active_agent": self.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                    "agent_states": agent_state_entries_debug_value(&self.agent_states),
                    "live_shells": self.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                    "new_agent_backing_aliases": agent_alias_entries_debug_value(&self.new_agent_backing_aliases),
                    "cwd_lock": coding_agent_cwd_lock_probe_debug_value(&runtime_info),
                    "meta_conflict_including_target_key": live_coding_agent_cwd_meta_conflict_including_target_key(&runtime_info).map(|info| session_info_debug_value(&info)),
                    "cwd_peers": self.live_coding_agent_cwd_peer_entries_debug_value(&runtime_info),
                }),
            );
        }
        if self
            .active_agent
            .as_ref()
            .is_some_and(|agent| AgentKey::new(&agent.info) == key)
        {
            self.show_sessions_view = false;
            self.status = format!(
                "switched to active {}",
                live_agent_status_label(&runtime_info)
            );
            debug_log(
                "agent_launch_switch_active",
                serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                }),
            );
            return;
        }
        match cached_state {
            AgentListState::Live { .. } | AgentListState::Attached { mine: true, .. } => {
                self.attach_existing_live_agent(runtime_info, cols, rows, "agent_launch_live");
                return;
            }
            AgentListState::Attached { mine: false, .. } => {
                self.status = format!(
                    "{} is already attached in another cokacmux process.",
                    live_agent_status_label(&runtime_info)
                );
                debug_log(
                    "agent_launch_blocked_foreign_attached",
                    serde_json::json!({
                        "provider": key.provider.as_str(),
                        "session_id": &key.session_id,
                    }),
                );
                return;
            }
            AgentListState::Orphaned { child_pid } => {
                self.status = format!(
                    "{} process {} is still running, but its cokacmux daemon is gone; terminate it before relaunching.",
                    live_agent_status_label(&runtime_info),
                    child_pid,
                );
                debug_log(
                    "agent_launch_blocked_orphaned",
                    serde_json::json!({
                        "provider": key.provider.as_str(),
                        "session_id": &key.session_id,
                        "child_pid": child_pid,
                    }),
                );
                return;
            }
            AgentListState::OrphanedGroup { child_pgid } => {
                self.status = format!(
                    "{} process group/tree rooted at {} is still running, but its cokacmux daemon is gone; terminate it before relaunching.",
                    live_agent_status_label(&runtime_info),
                    child_pgid,
                );
                debug_log(
                    "agent_launch_blocked_orphaned_group",
                    serde_json::json!({
                        "provider": key.provider.as_str(),
                        "session_id": &key.session_id,
                        "child_pgid": child_pgid,
                    }),
                );
                return;
            }
            AgentListState::Idle => {}
        }
        if allow_defer && self.agent_runtime_refresh_in_flight() {
            self.set_pending_runtime_action(PendingRuntimeAction::LaunchSelected {
                info: info.clone(),
                cols,
                rows,
            });
            self.status = format!(
                "checking live state for {}...",
                live_agent_status_label(&runtime_info)
            );
            debug_log(
                "agent_launch_deferred_runtime_refresh",
                serde_json::json!({
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                    "cached_state": agent_list_state_debug_value(cached_state),
                    "runtime_refresh_pending": self.runtime_refresh_pending,
                    "runtime_refresh_queued": self.runtime_refresh_queued,
                    "pending_runtime_action": pending_runtime_action_debug_value(self.pending_runtime_action.as_ref()),
                }),
            );
            return;
        }
        if self.block_live_coding_agent_cwd_conflict(&runtime_info) {
            return;
        }
        let key = AgentKey::new(&info);
        debug_log(
            "agent_launch_mode_open",
            serde_json::json!({
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
            }),
        );
        self.focus = FocusPane::Sessions;
        self.status = "choose launch mode.".into();
        self.input_mode = InputMode::AgentLaunch {
            source: info,
            selected: 0,
        };
    }

    fn attach_existing_live_agent(
        &mut self,
        info: SessionInfo,
        cols: u16,
        rows: u16,
        origin: &str,
    ) {
        let key = AgentKey::new(&info);
        let label = live_agent_status_label(&info);
        let should_select_visible = should_select_visible_session_for_live_info(&info);
        debug_log(
            "attach_existing_live_agent_start",
            serde_json::json!({
                "origin": origin,
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "cols": cols,
                "rows": rows,
            }),
        );
        if self.main_tx.is_none() {
            self.status = format!("cannot switch to live {}; event loop is not ready", label);
            debug_log(
                "attach_existing_live_agent_unavailable",
                serde_json::json!({
                    "origin": origin,
                    "provider": key.provider.as_str(),
                    "session_id": &key.session_id,
                }),
            );
            return;
        }
        self.request_attach(AttachJob {
            info,
            cols,
            rows,
            kind: AttachJobKind::Existing,
            run_prechecks: false,
            prompt_for_saved_data: false,
            settings: self.settings.clone(),
            ctx: AttachUiCtx {
                key,
                target: AttachTarget::MainAgent,
                status_attached: format!("switched to live {}", label),
                status_started: format!("switched to live {}", label),
                status_err_prefix: format!("switch to live {} failed: ", label),
                status_prepare_err_prefix: format!("switch to live {} failed: ", label),
                focus_auxiliary_on_ready: false,
                main_focus_override_on_ready: None,
                select_visible: should_select_visible,
                cokacdir_dialog_on_error: false,
                remove_dead_on_notfound: false,
                log_origin: Some(origin.to_string()),
                ready_event: "attach_existing_live_agent_ready",
                failed_event: "attach_existing_live_agent_failed",
            },
        });
    }

