#[cfg(windows)]
struct WindowsOwnedHandle(WinHandle);

#[cfg(windows)]
impl Drop for WindowsOwnedHandle {
    fn drop(&mut self) {
        if !self.0.is_null() {
            unsafe {
                windows_close_handle(self.0);
            }
        }
    }
}

