fn agent_scroll_render_source(agent: &AgentClient) -> &'static str {
    if agent.parser.screen().scrollback() == 0 && agent.history_scroll_offset > 0 {
        "history"
    } else {
        "parser"
    }
}

fn apply_scrollback_delta(current: usize, delta: i32) -> usize {
    if delta >= 0 {
        current.saturating_add(delta as usize)
    } else {
        current.saturating_sub((-delta) as usize)
    }
}

fn child_scroll_action_label(action: AgentScrollAction) -> &'static str {
    match action {
        AgentScrollAction::Lines(delta) if delta > 0 => "line up",
        AgentScrollAction::Lines(delta) if delta < 0 => "line down",
        AgentScrollAction::Pages(delta) if delta > 0 => "page up",
        AgentScrollAction::Pages(delta) if delta < 0 => "page down",
        AgentScrollAction::Top => "top",
        AgentScrollAction::Bottom => "bottom",
        AgentScrollAction::Lines(_) | AgentScrollAction::Pages(_) => "none",
    }
}

fn codex_transcript_scroll_key(action: AgentScrollAction) -> Option<KeyEvent> {
    let code = match action {
        AgentScrollAction::Lines(delta) if delta > 0 => KeyCode::Up,
        AgentScrollAction::Lines(delta) if delta < 0 => KeyCode::Down,
        AgentScrollAction::Pages(delta) if delta > 0 => KeyCode::PageUp,
        AgentScrollAction::Pages(delta) if delta < 0 => KeyCode::PageDown,
        AgentScrollAction::Top => KeyCode::Home,
        AgentScrollAction::Bottom => KeyCode::End,
        AgentScrollAction::Lines(_) | AgentScrollAction::Pages(_) => return None,
    };
    Some(KeyEvent::new(code, KeyModifiers::NONE))
}

fn codex_child_scroll_delegated_keys(
    action: AgentScrollAction,
    original: KeyEvent,
    overlay_assumed_open: bool,
) -> Option<Vec<KeyEvent>> {
    codex_transcript_scroll_key(action)?;
    let mut keys = vec![original];
    if !overlay_assumed_open {
        keys.push(original);
    }
    Some(keys)
}

fn claude_child_scroll_key(action: AgentScrollAction) -> Option<KeyEvent> {
    let (code, modifiers) = match action {
        AgentScrollAction::Pages(delta) if delta > 0 => (KeyCode::PageUp, KeyModifiers::NONE),
        AgentScrollAction::Pages(delta) if delta < 0 => (KeyCode::PageDown, KeyModifiers::NONE),
        AgentScrollAction::Top => (KeyCode::Home, KeyModifiers::CONTROL),
        AgentScrollAction::Bottom => (KeyCode::End, KeyModifiers::CONTROL),
        AgentScrollAction::Lines(_) | AgentScrollAction::Pages(_) => return None,
    };
    Some(KeyEvent::new(code, modifiers))
}

fn opencode_child_scroll_key(action: AgentScrollAction) -> Option<KeyEvent> {
    let code = match action {
        AgentScrollAction::Pages(delta) if delta > 0 => KeyCode::PageUp,
        AgentScrollAction::Pages(delta) if delta < 0 => KeyCode::PageDown,
        AgentScrollAction::Lines(_)
        | AgentScrollAction::Pages(_)
        | AgentScrollAction::Top
        | AgentScrollAction::Bottom => return None,
    };
    Some(KeyEvent::new(code, KeyModifiers::NONE))
}

fn codex_transcript_overlay_state_after_forwarded_key(agent: &AgentClient, key: KeyEvent) -> bool {
    codex_transcript_overlay_state_after_key(
        agent.info.provider,
        agent.codex_transcript_overlay_assumed_open,
        key,
    )
}

fn codex_transcript_overlay_state_after_key(
    provider: Provider,
    current_open: bool,
    key: KeyEvent,
) -> bool {
    if provider != Provider::Codex
        || !matches!(key.kind, KeyEventKind::Press | KeyEventKind::Repeat)
    {
        return current_open;
    }
    if current_open && (is_plain_char_key(key, 'q') || is_ctrl_char_key(key, 'c')) {
        return false;
    }
    current_open
}

fn is_plain_char_key(key: KeyEvent, expected: char) -> bool {
    matches!(
        key.code,
        KeyCode::Char(c) if c.eq_ignore_ascii_case(&expected)
    ) && key.modifiers.is_empty()
}

fn is_ctrl_char_key(key: KeyEvent, expected: char) -> bool {
    matches!(
        key.code,
        KeyCode::Char(c) if c.eq_ignore_ascii_case(&expected)
    ) && key.modifiers.contains(KeyModifiers::CONTROL)
        && !key.modifiers.contains(KeyModifiers::ALT)
}

#[cfg(test)]
fn is_agent_scrollback_key(key: KeyEvent) -> Option<AgentScrollAction> {
    agent_scrollback_key(&KeyBindings::default(), key)
}

fn agent_scrollback_key(bindings: &KeyBindings, key: KeyEvent) -> Option<AgentScrollAction> {
    if bindings.matches(KeyAction::AgentScrollLineUp, key) {
        Some(AgentScrollAction::Lines(1))
    } else if bindings.matches(KeyAction::AgentScrollLineDown, key) {
        Some(AgentScrollAction::Lines(-1))
    } else if bindings.matches(KeyAction::AgentScrollPageUp, key) {
        Some(AgentScrollAction::Pages(1))
    } else if bindings.matches(KeyAction::AgentScrollPageDown, key) {
        Some(AgentScrollAction::Pages(-1))
    } else if bindings.matches(KeyAction::AgentScrollTop, key) {
        Some(AgentScrollAction::Top)
    } else if bindings.matches(KeyAction::AgentScrollBottom, key) {
        Some(AgentScrollAction::Bottom)
    } else {
        None
    }
}

