fn render_agent_client_pane(
    f: &mut ratatui::Frame,
    agent: &mut AgentClient,
    area: Rect,
    frame_title: Option<&str>,
    focused: bool,
) -> AgentRenderOutcome {
    let content_area = if let Some(title) = frame_title {
        fill_area(f.buffer_mut(), area, Style::default().bg(AGENT_DEFAULT_BG));
        let border_color = if focused {
            THEME_BORDER_ACTIVE
        } else {
            THEME_BORDER
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(border_color).bg(AGENT_DEFAULT_BG))
            .style(Style::default().bg(AGENT_DEFAULT_BG))
            .title(title.to_string());
        f.render_widget(block, area);
        pane_inner(area)
    } else {
        area
    };

    let (agent_screen_rows, agent_screen_cols) = agent_screen_size_for_area(content_area);
    agent.resize(agent_screen_cols, agent_screen_rows);
    // Output is already in the parser — the reader thread pushed it via
    // process_agent_event before this draw was scheduled. No socket read
    // happens on the render path.
    let screen_size = agent.parser.screen().size();
    if screen_size != (agent_screen_rows, agent_screen_cols) {
        debug_log(
            "agent_parser_size_corrected",
            serde_json::json!({
                "provider": agent.info.provider.as_str(),
                "session_id": &agent.info.session_id,
                "screen_rows": screen_size.0,
                "screen_cols": screen_size.1,
                "area_rows": content_area.height,
                "area_cols": content_area.width,
                "target_rows": agent_screen_rows,
                "target_cols": agent_screen_cols,
            }),
        );
        agent
            .parser
            .screen_mut()
            .set_size(agent_screen_rows, agent_screen_cols);
    }

    let (cursor, scrollback_offset, render_source, parser_scrollback, history_scroll_offset) = {
        let startup_spinner_started_at = agent.startup_spinner_started_at();
        let screen = agent.parser.screen();
        let history_scroll_offset = agent.history_scroll_offset;
        let parser_scrollback = screen.scrollback();
        let render_source = if parser_scrollback == 0 && history_scroll_offset > 0 {
            "history"
        } else {
            "parser"
        };
        let scrollback_offset = if parser_scrollback > 0 {
            parser_scrollback
        } else {
            history_scroll_offset
        };
        let cursor = if startup_spinner_started_at.is_some()
            || screen.hide_cursor()
            || scrollback_offset > 0
            || !focused
        {
            None
        } else {
            let (row, col) = screen.cursor_position();
            if row < content_area.height && col < content_area.width {
                Some((content_area.x + col, content_area.y + row))
            } else {
                None
            }
        };
        let buf = f.buffer_mut();
        fill_area(buf, content_area, Style::default().bg(AGENT_DEFAULT_BG));
        if render_source == "history" {
            let lines = agent
                .screen_history
                .visible_lines(history_scroll_offset, content_area.height as usize);
            render_plain_agent_history(buf, content_area, &lines, focused);
        } else {
            render_vt100_screen(buf, screen, content_area, focused);
        }
        if let Some(started_at) = startup_spinner_started_at {
            render_agent_startup_spinner(buf, content_area, &agent.info, started_at, focused);
        }
        (
            cursor,
            scrollback_offset,
            render_source,
            parser_scrollback,
            history_scroll_offset,
        )
    };

    let visible = screen_has_visible_content(agent.parser.screen());
    debug_log(
        "agent_render_pane",
        serde_json::json!({
            "provider": agent.info.provider.as_str(),
            "session_id": &agent.info.session_id,
            "input_area": rect_debug_value(area),
            "content_area": rect_debug_value(content_area),
            "framed": frame_title.is_some(),
            "frame_title": frame_title,
            "focused": focused,
            "cursor": cursor.map(|(x, y)| serde_json::json!({
                "x": x,
                "y": y,
            })),
            "render_source": render_source,
            "visible": visible,
            "scrollback_offset": scrollback_offset,
            "parser_scrollback": parser_scrollback,
            "history_scroll_offset": history_scroll_offset,
            "screen_rows": agent_screen_rows,
            "screen_cols": agent_screen_cols,
            "pty_rows": agent.pty_size.rows,
            "pty_cols": agent.pty_size.cols,
            "screen_history_lines": agent.screen_history.len(),
            "startup_spinner": agent.startup_spinner_started_at().is_some(),
        }),
    );

    if DEBUG_ENABLED.load(Ordering::Relaxed)
        && (scrollback_offset > 0 || TRACE_ENABLED.load(Ordering::Relaxed))
    {
        let visible_rows = content_area.height as usize;
        let max_rows = visible_rows.clamp(1, 120);
        let rendered_window = if render_source == "history" {
            debug_history_window_value(
                &agent.screen_history,
                agent.history_scroll_offset,
                visible_rows.max(1),
                max_rows,
            )
        } else {
            let parser_scrollback = agent.parser.screen().scrollback();
            debug_visible_lines_at_scrollback(&mut agent.parser, parser_scrollback, max_rows)
        };
        // `rendered_window` is this event's diagnostic payload; the generic
        // state dump is redundant with it and only captured under trace.
        let state = TRACE_ENABLED
            .load(Ordering::Relaxed)
            .then(|| debug_agent_client_state_value(agent, visible_rows.max(1), max_rows));
        debug_log(
            "agent_render",
            serde_json::json!({
                "provider": agent.info.provider.as_str(),
                "session_id": &agent.info.session_id,
                "area_x": content_area.x,
                "area_y": content_area.y,
                "area_width": content_area.width,
                "area_height": content_area.height,
                "framed": frame_title.is_some(),
                "focused": focused,
                "render_source": render_source,
                "scrollback_offset": scrollback_offset,
                "rendered_window": rendered_window,
                "state": state,
            }),
        );
    }

    AgentRenderOutcome {
        cursor,
        scrollback_offset,
        command_line: agent.command_line.clone(),
        info: agent.info.clone(),
        input_area: area,
        content_area,
        framed: frame_title.is_some(),
        focused,
        render_source,
        visible,
        parser_scrollback,
        history_scroll_offset,
        screen_rows: agent_screen_rows,
        screen_cols: agent_screen_cols,
    }
}

fn main_agent_content_area(area: Rect) -> Rect {
    if area.height == 0 {
        return area;
    }
    Rect::new(
        area.x,
        area.y.saturating_add(1),
        area.width,
        area.height.saturating_sub(1),
    )
}

fn main_agent_title(info: &SessionInfo) -> String {
    if is_plain_pty_tool_session_info(info) {
        return live_agent_status_label(info);
    }
    info.title
        .as_deref()
        .filter(|title| !title.trim().is_empty())
        .map(|title| title.to_string())
        .unwrap_or_else(|| live_agent_status_label(info))
}

fn main_agent_title_bar_style(focused: bool) -> Style {
    if focused {
        Style::default()
            .fg(THEME_FG_STRONG)
            .bg(THEME_SELECTED_BG)
            .add_modifier(Modifier::BOLD)
    } else {
        main_agent_title_bar_inactive_style()
    }
}

fn main_agent_title_bar_inactive_style() -> Style {
    Style::default().fg(THEME_FG_DIM).bg(THEME_STATUS_BG)
}

fn agent_sidebar_highlight_style(focused: bool) -> Style {
    if focused {
        theme_selected_style()
    } else {
        main_agent_title_bar_inactive_style()
    }
}

fn render_main_agent_title_bar(
    f: &mut ratatui::Frame,
    area: Rect,
    info: &SessionInfo,
    focused: bool,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let bar_area = Rect::new(area.x, area.y, area.width, 1);
    let style = main_agent_title_bar_style(focused);
    fill_area(f.buffer_mut(), bar_area, style);
    let title = truncate_width(
        &main_agent_title(info),
        area.width.saturating_sub(2) as usize,
    );
    f.buffer_mut().set_stringn(
        area.x.saturating_add(1),
        area.y,
        title,
        area.width.saturating_sub(1) as usize,
        style,
    );
}

fn render_agent_kill_replacement_pane(
    f: &mut ratatui::Frame,
    area: Rect,
    info: &SessionInfo,
    focused: bool,
) {
    f.render_widget(Clear, area);
    render_main_agent_title_bar(f, area, info, focused);
    let content_area = main_agent_content_area(area);
    let style = agent_pane_style_for_focus(
        Style::default().fg(THEME_FG_DIM).bg(AGENT_DEFAULT_BG),
        focused,
    );
    fill_area(f.buffer_mut(), content_area, style);
    if content_area.width == 0 || content_area.height == 0 {
        return;
    }
    let message = truncate_width(
        &format!("Connecting to {}…", live_agent_status_label(info)),
        content_area.width.saturating_sub(2) as usize,
    );
    f.buffer_mut().set_stringn(
        content_area.x.saturating_add(1),
        content_area.y,
        message,
        content_area.width.saturating_sub(1) as usize,
        style,
    );
}

fn ui_agent(f: &mut ratatui::Frame, app: &mut App) {
    let area = f.area();
    let main_area = Rect::new(
        area.x,
        area.y,
        area.width,
        area.height.saturating_sub(AGENT_STATUS_HEIGHT),
    );
    let status_area = Rect::new(
        area.x,
        area.y + main_area.height,
        area.width,
        AGENT_STATUS_HEIGHT.min(area.height),
    );

    let workspace_info = app.agent_workspace_info().cloned();
    let workspace_key = workspace_info.as_ref().map(AgentKey::new);
    let auxiliary_visible = app.active_agent.is_some() && app.agent_aux.is_some();
    let layout = agent_pane_layout_for_area(
        main_area,
        app.agent_sidebar_config_width(),
        auxiliary_visible,
        app.agent_aux_width,
    );
    debug_log(
        "ui_agent_layout",
        serde_json::json!({
            "area": rect_debug_value(area),
            "main_area": rect_debug_value(main_area),
            "status_area": rect_debug_value(status_area),
            "layout": agent_pane_layout_debug_value(layout),
            "agent_focus": format!("{:?}", app.agent_focus),
            "agent_sidebar_width": app.agent_sidebar_config_width(),
            "agent_aux_width": app.agent_aux_width,
            "auxiliary_visible": auxiliary_visible,
            "active_agent": app.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
            "kill_replacement": app.agent_kill_replacement.as_ref().map(|replacement| session_info_debug_value(&replacement.target)),
            "agent_aux": app.agent_aux.as_ref().map(agent_aux_pane_debug_value),
        }),
    );

    if workspace_info.is_none() {
        f.render_widget(Clear, area);
        debug_log(
            "ui_agent_render_done",
            serde_json::json!({
                "reason": "no_active_agent",
                "area": rect_debug_value(area),
                "layout": agent_pane_layout_debug_value(layout),
                "snapshot": app_runtime_snapshot_debug_value(app, false),
            }),
        );
        return;
    }

    let main_outcome = if let Some(agent) = app.active_agent.as_mut() {
        let main_focused = app.agent_focus == AgentFocusPane::Main;
        render_main_agent_title_bar(f, layout.main, &agent.info, main_focused);
        Some(render_agent_client_pane(
            f,
            agent,
            main_agent_content_area(layout.main),
            None,
            main_focused,
        ))
    } else {
        render_agent_kill_replacement_pane(
            f,
            layout.main,
            workspace_info
                .as_ref()
                .expect("agent workspace info checked above"),
            app.agent_focus == AgentFocusPane::Main,
        );
        None
    };

    let auxiliary_outcome =
        if let (Some(aux), Some(aux_area)) = (app.agent_aux.as_mut(), layout.auxiliary) {
            Some(render_agent_client_pane(
                f,
                &mut aux.agent,
                aux_area,
                Some(aux.kind.title()),
                app.agent_focus == AgentFocusPane::Auxiliary,
            ))
        } else {
            None
        };

    let focused_cursor = match app.agent_focus {
        AgentFocusPane::Main => main_outcome.as_ref().and_then(|outcome| outcome.cursor),
        AgentFocusPane::Auxiliary => auxiliary_outcome
            .as_ref()
            .and_then(|outcome| outcome.cursor),
        AgentFocusPane::Sidebar => None,
    };

    let buf = f.buffer_mut();
    fill_area(buf, status_area, theme_status_style());
    let agent_help_items = agent_help_items(&app.keybindings);
    f.render_widget(
        help_line_from_items_with_bg(
            &agent_help_items,
            status_area.width as usize,
            THEME_STATUS_BG,
        ),
        status_area,
    );

    app.poll_agent_runtime_states();
    let mut sidebar_candidates_len = None;
    if let (Some(sidebar_area), Some(workspace_key)) = (layout.sidebar, workspace_key.as_ref()) {
        let candidates = app.agent_sidebar_candidates();
        sidebar_candidates_len = Some(candidates.len());
        f.render_widget(Clear, sidebar_area);
        draw_agent_sidebar(
            f,
            app,
            sidebar_area,
            &candidates,
            workspace_key,
            app.agent_focus == AgentFocusPane::Sidebar,
        );
    }

    let modal_drawn = draw_input_modal(f, area, app);
    let ai_search_overlay_drawn = if modal_drawn {
        false
    } else {
        draw_ai_search_pending_overlay(f, area, app.ai_search_pending.as_ref())
    };
    let new_session_overlay_drawn = if modal_drawn || ai_search_overlay_drawn {
        false
    } else {
        draw_new_session_launch_overlay(f, area, app.new_session_launch.as_ref())
    };
    let attach_overlay_drawn =
        if modal_drawn || ai_search_overlay_drawn || new_session_overlay_drawn {
            false
        } else {
            draw_attach_progress_overlay(f, area, app)
        };
    let agent_exit_overlay_drawn = if modal_drawn
        || ai_search_overlay_drawn
        || new_session_overlay_drawn
        || attach_overlay_drawn
    {
        false
    } else {
        draw_agent_exit_pending_overlay(f, area, app)
    };
    let runtime_refresh_overlay_drawn = if modal_drawn
        || ai_search_overlay_drawn
        || new_session_overlay_drawn
        || attach_overlay_drawn
        || agent_exit_overlay_drawn
    {
        false
    } else {
        draw_runtime_refresh_pending_overlay(f, area, app)
    };
    let session_refresh_overlay_drawn = if modal_drawn
        || ai_search_overlay_drawn
        || new_session_overlay_drawn
        || attach_overlay_drawn
        || agent_exit_overlay_drawn
        || runtime_refresh_overlay_drawn
    {
        false
    } else {
        draw_session_refresh_pending_overlay(f, area, app)
    };
    let mut cursor_set = None;
    if !modal_drawn
        && !ai_search_overlay_drawn
        && !new_session_overlay_drawn
        && !attach_overlay_drawn
        && !agent_exit_overlay_drawn
        && !runtime_refresh_overlay_drawn
        && !session_refresh_overlay_drawn
    {
        if let Some(cursor) = focused_cursor {
            f.set_cursor_position(cursor);
            cursor_set = Some(cursor);
        }
    }
    debug_log(
        "ui_agent_render_done",
        serde_json::json!({
            "reason": "rendered",
            "area": rect_debug_value(area),
            "main_area": rect_debug_value(main_area),
            "status_area": rect_debug_value(status_area),
            "layout": agent_pane_layout_debug_value(layout),
            "agent_focus": format!("{:?}", app.agent_focus),
            "main": main_outcome.as_ref().map(agent_render_outcome_debug_value),
            "auxiliary": auxiliary_outcome.as_ref().map(agent_render_outcome_debug_value),
            "focused_cursor": focused_cursor.map(|(x, y)| serde_json::json!({
                "x": x,
                "y": y,
            })),
            "cursor_set": cursor_set.map(|(x, y)| serde_json::json!({
                "x": x,
                "y": y,
            })),
            "modal_drawn": modal_drawn,
            "ai_search_overlay_drawn": ai_search_overlay_drawn,
            "new_session_overlay_drawn": new_session_overlay_drawn,
            "attach_overlay_drawn": attach_overlay_drawn,
            "agent_exit_overlay_drawn": agent_exit_overlay_drawn,
            "runtime_refresh_overlay_drawn": runtime_refresh_overlay_drawn,
            "session_refresh_overlay_drawn": session_refresh_overlay_drawn,
            "sidebar_drawn": layout.sidebar.is_some() && workspace_key.is_some(),
            "sidebar_candidates_len": sidebar_candidates_len,
            "status": app.display_status(),
            "snapshot": app_runtime_snapshot_debug_value(app, false),
        }),
    );
}

fn draw_input_modal(f: &mut ratatui::Frame, area: Rect, app: &App) -> bool {
    if let Some(notice) = app.notice_overlay.as_ref() {
        draw_notice_modal(f, area, &notice.title, &notice.message);
        return true;
    }
    if draw_killall_pending_overlay(f, area, app.killall_pending.as_ref()) {
        return true;
    }
    if let InputMode::KillAllConfirm { selected } = &app.input_mode {
        draw_killall_confirm_modal(f, area, *selected, &app.keybindings);
    } else if let Some(task) = app.data_task.as_ref() {
        draw_data_task_modal(f, area, task);
    } else if let InputMode::DeleteConfirm {
        info,
        removed_index: _,
        selected,
    } = &app.input_mode
    {
        draw_delete_confirm_modal(f, area, info, *selected, &app.keybindings);
    } else if let InputMode::CreateFolderConfirm {
        info,
        path,
        cols: _,
        rows: _,
        launch_mode: _,
        selected,
    } = &app.input_mode
    {
        draw_create_folder_confirm_modal(f, area, info, path, *selected, &app.keybindings);
    } else if let InputMode::RestoreDataConfirm {
        info,
        snapshot,
        cols: _,
        rows: _,
        launch_mode: _,
        selected,
    } = &app.input_mode
    {
        draw_restore_data_confirm_modal(f, area, info, snapshot, *selected, &app.keybindings);
    } else if let InputMode::SearchChoice { selected } = &app.input_mode {
        draw_search_choice_modal(f, area, *selected, &app.keybindings);
    } else if let InputMode::Filter { draft, cursor } = &app.input_mode {
        draw_filter_modal(
            f,
            area,
            draft,
            *cursor,
            app.search_pending.as_ref(),
            &app.keybindings,
        );
    } else if let InputMode::AiSearch { draft, cursor } = &app.input_mode {
        draw_ai_search_modal(
            f,
            area,
            draft,
            *cursor,
            app.ai_search_pending.as_ref(),
            &app.keybindings,
        );
    } else if let InputMode::AgentLaunch { source, selected } = &app.input_mode {
        draw_agent_launch_modal(
            f,
            area,
            source,
            *selected,
            &app.settings.cokacmux.agent_programs,
            &app.keybindings,
        );
    } else if let InputMode::CloneOptions {
        source,
        target,
        target_options: _,
        selected,
        folder_data,
        context_mode,
    } = &app.input_mode
    {
        draw_clone_options_modal(
            f,
            area,
            source,
            *target,
            *selected,
            folder_data,
            *context_mode,
            &app.keybindings,
        );
    } else if let InputMode::NewSession {
        selected,
        kind,
        cwd,
        cwd_cursor,
        cwd_completion,
        provider,
        provider_options,
        launch_mode,
    } = &app.input_mode
    {
        draw_new_session_modal(
            f,
            area,
            *selected,
            *kind,
            cwd,
            *cwd_cursor,
            cwd_completion,
            *provider,
            provider_options,
            *launch_mode,
            &app.settings.cokacmux,
            &app.keybindings,
        );
    } else if let InputMode::TitleEdit {
        source,
        draft,
        cursor,
    } = &app.input_mode
    {
        let ai_title_pending = app
            .ai_title_pending
            .as_ref()
            .filter(|pending| pending.key == AgentKey::new(source));
        draw_title_edit_modal(
            f,
            area,
            source,
            draft,
            *cursor,
            ai_title_pending,
            &app.keybindings,
        );
    } else if let InputMode::Settings {
        state,
        return_to: _,
    } = &app.input_mode
    {
        draw_settings_modal(f, area, state, &app.keybindings);
    } else if let InputMode::Notice { title, message } = &app.input_mode {
        draw_notice_modal(f, area, title, message);
    } else {
        return false;
    }
    true
}

fn draw_notice_modal(f: &mut ratatui::Frame, area: Rect, title: &str, message: &str) {
    let sizing_lines = vec![
        Line::from(Span::styled(
            message.to_string(),
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        )),
        Line::from(""),
        Line::from(Span::styled("[ OK ]", theme_selected_style())),
    ];
    let modal_area = modal_area_for_wrapped_lines(area, title, &sizing_lines, 40, 92, 5, 12);
    let content_width = modal_area.width.saturating_sub(2) as usize;
    let content_height = modal_area.height.saturating_sub(2) as usize;
    let lines = notice_modal_lines(message, content_width, content_height);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title(title.to_string());
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(Clear, modal_area);
    f.render_widget(p, modal_area);
}

fn notice_modal_lines(
    message: &str,
    content_width: usize,
    content_height: usize,
) -> Vec<Line<'static>> {
    if content_height == 0 {
        return Vec::new();
    }
    let ok_line = notice_ok_button_line(content_width);
    if content_height == 1 {
        return vec![ok_line];
    }
    let reserve_blank_row = content_height >= 3;
    let reserved_rows = if reserve_blank_row { 2 } else { 1 };
    let max_message_rows = content_height.saturating_sub(reserved_rows).max(1);
    let mut lines = notice_message_lines(message, content_width, max_message_rows);
    if reserve_blank_row {
        lines.push(Line::from(""));
    }
    lines.push(ok_line);
    lines
}

fn notice_message_lines(
    message: &str,
    content_width: usize,
    max_rows: usize,
) -> Vec<Line<'static>> {
    let width = content_width.max(1);
    let mut rows = wrap_preview_lines(&sanitize_for_single_line(message), width);
    let truncated = rows.len() > max_rows;
    rows.truncate(max_rows.max(1));
    if truncated {
        if let Some(last) = rows.last_mut() {
            *last = ellipsize_width(last, width);
        }
    }
    rows.into_iter()
        .map(|row| {
            Line::from(Span::styled(
                row,
                Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
            ))
        })
        .collect()
}

fn ellipsize_width(text: &str, width: usize) -> String {
    if width == 0 {
        return String::new();
    }
    let mut base = truncate_width(text, width);
    while UnicodeWidthStr::width(base.as_str()).saturating_add(1) > width && !base.is_empty() {
        base.pop();
    }
    format!("{}…", base)
}

fn notice_ok_button_line(content_width: usize) -> Line<'static> {
    let button = "[ OK ]";
    let button_width = UnicodeWidthStr::width(button);
    let padding = " ".repeat(content_width.saturating_sub(button_width) / 2);
    Line::from(vec![
        Span::styled(padding, theme_alt_style()),
        Span::styled(button, theme_selected_style()),
    ])
}

fn draw_data_task_modal(f: &mut ratatui::Frame, area: Rect, task: &DataTaskPending) {
    let elapsed = task.started_at.elapsed();
    let status = task
        .notice
        .as_deref()
        .or(task.progress_message.as_deref())
        .unwrap_or(&task.label);
    let mut lines: Vec<Line<'static>> = vec![
        Line::from(Span::styled(
            format!(
                "{} {}",
                startup_spinner_frame(elapsed),
                truncate_width(&task.label, 58)
            ),
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            format!("Status: {}", truncate_width(status, 60)),
            Style::default().fg(THEME_ACCENT).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            format!("Elapsed: {}s", elapsed.as_secs()),
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )),
    ];

    if let Some(stats) = task.progress_stats.as_ref() {
        lines.push(Line::from(Span::styled(
            format!("Copied: {}", copy_stats_summary(stats)),
            Style::default().fg(THEME_FG).bg(THEME_BG_ALT),
        )));
    }
    if let Some(total) = task.progress_total.as_ref() {
        let percent = copy_percent_summary(task.progress_stats.as_ref(), Some(total))
            .unwrap_or_else(|| "0%".to_string());
        let copied = task
            .progress_stats
            .as_ref()
            .map(copy_stats_summary)
            .unwrap_or_else(|| "0 files, 0 dirs, 0 symlinks, 0 bytes".to_string());
        let total = copy_stats_summary(total);
        lines.push(Line::from(Span::styled(
            format!(
                "Progress: {}",
                truncate_width(&format!("{copied} of {total} ({percent})"), 58)
            ),
            Style::default().fg(THEME_FG).bg(THEME_BG_ALT),
        )));
    }
    if let Some(path) = task.progress_path.as_deref() {
        lines.push(Line::from(Span::styled(
            format!("Current: {}", truncate_width(path, 58)),
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )));
    }

    lines.push(Line::from(""));
    let help_items = match task.kind {
        DataTaskKind::Clone if task.cancel_requested => [direct_help_item(
            "Esc",
            "pressed · cancelling and rolling back when safe",
        )],
        DataTaskKind::Clone => [direct_help_item(
            "Esc",
            "cancel · all other actions locked until clone completes",
        )],
        DataTaskKind::Restore => [direct_help_item(
            "Wait",
            "restore must finish before other actions",
        )],
    };
    lines.push(modal_help_line(&help_items));

    let title = task.kind.modal_title();
    let modal_area = modal_area_for_wrapped_lines(area, title, &lines, 44, 86, 7, 12);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title(title);
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: true });
    f.render_widget(Clear, modal_area);
    f.render_widget(p, modal_area);
}

