fn draw_fixed_modal_lines(
    f: &mut ratatui::Frame,
    modal_area: Rect,
    title: &'static str,
    lines: Vec<Line<'static>>,
) {
    f.render_widget(ratatui::widgets::Clear, modal_area);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title(title);
    f.render_widget(block, modal_area);

    let inner = Rect {
        x: modal_area.x.saturating_add(1),
        y: modal_area.y.saturating_add(1),
        width: modal_area.width.saturating_sub(2),
        height: modal_area.height.saturating_sub(2),
    };
    for (idx, line) in lines.into_iter().enumerate() {
        if idx >= inner.height as usize {
            break;
        }
        f.render_widget(
            line,
            Rect::new(inner.x, inner.y.saturating_add(idx as u16), inner.width, 1),
        );
    }
}

fn draw_ai_search_pending_overlay(
    f: &mut ratatui::Frame,
    area: Rect,
    pending: Option<&AiSearchPending>,
) -> bool {
    let Some(pending) = pending else {
        return false;
    };
    let modal_area = ai_search_pending_overlay_area(area);
    let content_width = modal_area.width.saturating_sub(2).max(1) as usize;
    let lines = ai_search_pending_overlay_lines(pending, content_width);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("AI search");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
    true
}

fn ai_search_pending_overlay_area(area: Rect) -> Rect {
    let available_width = modal_available_width(area).max(1);
    let min_width = 48.min(available_width);
    let width = available_width
        .min(AI_SEARCH_PENDING_OVERLAY_MAX_WIDTH)
        .max(min_width);
    let height = modal_height(area, 6, 8, 10);
    centered_rect_fixed(width, height, area)
}

fn ai_search_pending_overlay_lines(
    pending: &AiSearchPending,
    content_width: usize,
) -> Vec<Line<'static>> {
    let elapsed = pending.started_at.elapsed();
    let headline = if pending.cancel_requested {
        "Cancelling AI search"
    } else {
        "AI search running"
    };
    let phase = pending.phase.label();
    let provider = pending.provider.as_str();
    let query_width = content_width.saturating_sub(8).max(8);
    let summary_width = content_width.max(1);
    let query = truncate_width(&pending.query, query_width);
    let summary = truncate_width(
        &ai_search_progress_summary(pending).unwrap_or_default(),
        summary_width,
    );
    vec![
        Line::from(vec![
            Span::styled(
                startup_spinner_frame(elapsed),
                Style::default()
                    .fg(THEME_SHORTCUT)
                    .bg(THEME_BG_ALT)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::raw(" "),
            Span::styled(
                headline.to_string(),
                Style::default()
                    .fg(THEME_FG_STRONG)
                    .bg(THEME_BG_ALT)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                format!("  {}s", elapsed.as_secs()),
                Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
            ),
        ]),
        Line::from(vec![
            Span::styled(
                provider.to_string(),
                Style::default()
                    .fg(provider_color(pending.provider))
                    .bg(THEME_BG_ALT),
            ),
            Span::styled(
                format!("  {}", phase),
                Style::default().fg(THEME_ACCENT).bg(THEME_BG_ALT),
            ),
        ]),
        Line::from(vec![
            Span::styled(
                "Prompt ",
                Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
            ),
            Span::styled(query, Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT)),
        ]),
        ai_search_progress_bar_line(pending, content_width),
        Line::from(Span::styled(
            summary,
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )),
        modal_help_line(&[direct_help_item("Esc", "cancel · input locked")]),
    ]
}

fn ai_search_progress_bar_line(pending: &AiSearchPending, content_width: usize) -> Line<'static> {
    progress_bar_line(pending.indexed, pending.total, content_width)
}

fn search_progress_bar_line(pending: &SearchPending, content_width: usize) -> Line<'static> {
    progress_bar_line(pending.processed, pending.total, content_width)
}

fn progress_bar_line(processed: usize, total: usize, content_width: usize) -> Line<'static> {
    let percent = progress_percent(processed, total).unwrap_or(0);
    let suffix = format!(" {:>3}%", percent);
    let suffix_width = UnicodeWidthStr::width(suffix.as_str());
    let bar_width = content_width.saturating_sub(suffix_width);
    let filled = bar_width
        .saturating_mul(processed.min(total))
        .saturating_add(total / 2)
        .checked_div(total)
        .unwrap_or(0)
        .min(bar_width);
    let empty = bar_width.saturating_sub(filled);
    Line::from(vec![
        Span::styled(
            "━".repeat(filled),
            Style::default().fg(THEME_POSITIVE).bg(THEME_BG_ALT),
        ),
        Span::styled(
            "─".repeat(empty),
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        ),
        Span::styled(
            suffix,
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        ),
    ])
}

fn draw_title_edit_modal(
    f: &mut ratatui::Frame,
    area: Rect,
    source: &SessionInfo,
    draft: &str,
    cursor: usize,
    ai_title_pending: Option<&AiTitlePending>,
    keybindings: &KeyBindings,
) {
    let session_line = format!(
        "{} session {}",
        source.provider.as_str(),
        truncate_width(&source.session_id, 24)
    );
    let pending_status = ai_title_pending.map(title_edit_ai_title_pending_text);
    let help_items = title_edit_help_items(keybindings);
    let help = pending_status
        .clone()
        .unwrap_or_else(|| help_text_from_items(&help_items));
    let desired_width = UnicodeWidthStr::width(session_line.as_str())
        .max(UnicodeWidthStr::width(draft).saturating_add(1))
        .max(UnicodeWidthStr::width(help.as_str()));
    let provisional_area =
        modal_area_from_content_rows(area, "Edit title", desired_width, 3, 44, 84, 5, 10);
    let input_width = provisional_area.width.saturating_sub(4) as usize;
    let input = if ai_title_pending.is_none() {
        Some(input_viewport(draft, cursor, input_width))
    } else {
        None
    };
    let input_text = input
        .as_ref()
        .map(|input| modal_input_display_text(&input.text, input_width))
        .unwrap_or_else(|| title_edit_readonly_display(draft, input_width));
    let mut lines = vec![Line::from(session_line)];
    let input_style = if ai_title_pending.is_some() {
        Style::default().fg(THEME_FG_DIM).bg(THEME_STATUS_BG)
    } else {
        Style::default()
            .fg(THEME_SELECTED_TEXT)
            .bg(THEME_SELECTED_BG)
    };
    let help_style = if ai_title_pending.is_some() {
        Style::default()
            .fg(THEME_ACCENT)
            .bg(THEME_BG_ALT)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT)
    };
    lines.push(Line::from(Span::styled(input_text, input_style)));
    if let Some(help) = pending_status {
        lines.push(Line::from(Span::styled(help, help_style)));
    } else {
        lines.push(modal_help_line(&help_items));
    }
    let modal_area = modal_area_for_wrapped_lines(area, "Edit title", &lines, 44, 84, 5, 10);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let title = if ai_title_pending.is_some() {
        "Edit title · AI running"
    } else {
        "Edit title"
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(if ai_title_pending.is_some() {
            THEME_ACCENT
        } else {
            THEME_BORDER_ACTIVE
        }))
        .style(theme_alt_style())
        .title(title);
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
    if let Some(input) = input {
        set_modal_input_cursor(f, modal_area, 1, input.cursor_col);
    }
}

fn draw_settings_modal(
    f: &mut ratatui::Frame,
    area: Rect,
    state: &SettingsState,
    keybindings: &KeyBindings,
) {
    let provisional_area = modal_area_from_content_rows(
        area,
        "Settings",
        104,
        SETTINGS_MODAL_CONTENT_ROWS,
        72,
        120,
        12,
        22,
    );
    let inner_width = provisional_area.width.saturating_sub(2) as usize;
    let (content_lines, cursor) = settings_modal_lines(state, inner_width);
    let modal_area = modal_area_from_content_rows(
        area,
        "Settings",
        104,
        SETTINGS_MODAL_CONTENT_ROWS,
        72,
        120,
        12,
        22,
    );
    let inner_height = modal_area.height.saturating_sub(2) as usize;
    let help_row = inner_height.saturating_sub(1);
    let help_line = modal_help_line(&settings_help_items(state, keybindings));
    let mut lines = Vec::with_capacity(inner_height);
    for row in 0..inner_height {
        if row == help_row {
            lines.push(help_line.clone());
        } else {
            lines.push(
                content_lines
                    .get(row)
                    .cloned()
                    .unwrap_or_else(|| Line::from("")),
            );
        }
    }
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("Settings");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
    if let Some((row, col)) = cursor {
        if row < help_row {
            set_modal_input_cursor(f, modal_area, row, col);
        }
    }
}

fn settings_modal_lines(
    state: &SettingsState,
    inner_width: usize,
) -> (Vec<Line<'static>>, Option<(usize, usize)>) {
    let mut lines = vec![
        settings_title_line(state),
        settings_tabs_line(state.section),
        Line::from(""),
    ];
    let mut cursor = None;
    match state.section {
        SettingsSection::General => settings_general_lines(state, inner_width, &mut lines),
        SettingsSection::Ai => settings_ai_lines(state, inner_width, &mut lines),
        SettingsSection::Agents => {
            cursor = settings_agents_lines(state, inner_width, &mut lines);
        }
        SettingsSection::Keybindings => settings_keybindings_lines(state, inner_width, &mut lines),
        SettingsSection::Data => settings_data_lines(state, inner_width, &mut lines),
    }
    (lines, cursor)
}

fn settings_tabs_line(active: SettingsSection) -> Line<'static> {
    let mut spans = Vec::new();
    for (index, section) in SETTINGS_SECTIONS.iter().copied().enumerate() {
        if index > 0 {
            spans.push(Span::raw("  "));
        }
        let style = if section == active {
            theme_selected_style()
        } else {
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT)
        };
        spans.push(Span::styled(format!(" {} ", section.label()), style));
    }
    Line::from(spans)
}

fn settings_title_line(state: &SettingsState) -> Line<'static> {
    let mut spans = vec![Span::styled(
        "Configure cokacmux",
        Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
    )];
    if state.is_dirty() {
        spans.push(Span::styled(
            "  ! unsaved",
            Style::default().fg(THEME_WARNING).bg(THEME_BG_ALT),
        ));
    }
    Line::from(spans)
}

fn settings_general_lines(
    state: &SettingsState,
    inner_width: usize,
    lines: &mut Vec<Line<'static>>,
) {
    let draft = &state.draft;
    lines.push(settings_row_line(
        state.selected == SETTINGS_GENERAL_SESSION_VIEW,
        SettingsRowKind::Change,
        "Session view",
        draft.session_view.label(),
        inner_width,
    ));
    lines.push(settings_row_line(
        state.selected == SETTINGS_GENERAL_AGENT_SIDEBAR_VISIBLE,
        SettingsRowKind::Change,
        "Agent sidebar",
        if draft.agent_sidebar_visible {
            "shown"
        } else {
            "hidden"
        },
        inner_width,
    ));
}

fn settings_ai_lines(state: &SettingsState, inner_width: usize, lines: &mut Vec<Line<'static>>) {
    lines.push(settings_heading_line("Choose AI agent", inner_width));
    for (index, provider) in AI_TITLE_PROVIDER_OPTIONS.iter().enumerate() {
        lines.push(ai_title_provider_option_line(
            index,
            *provider,
            state.selected == index,
            state.draft.ai_provider == *provider,
            inner_width,
        ));
    }
}

fn settings_agents_lines(
    state: &SettingsState,
    inner_width: usize,
    lines: &mut Vec<Line<'static>>,
) -> Option<(usize, usize)> {
    let mut cursor = None;
    for (row, label, field) in [
        (
            SETTINGS_AGENTS_CODEX,
            "Codex program",
            SettingsTextField::AgentProgram(Provider::Codex),
        ),
        (
            SETTINGS_AGENTS_CLAUDE,
            "Claude program",
            SettingsTextField::AgentProgram(Provider::Claude),
        ),
        (
            SETTINGS_AGENTS_OPENCODE,
            "OpenCode program",
            SettingsTextField::AgentProgram(Provider::OpenCode),
        ),
        (
            SETTINGS_AGENTS_PI,
            "Pi program",
            SettingsTextField::AgentProgram(Provider::Pi),
        ),
        (
            SETTINGS_AGENTS_GJC,
            "GJC program",
            SettingsTextField::AgentProgram(Provider::Gjc),
        ),
        (
            SETTINGS_AGENTS_COKACDIR,
            "cokacdir program",
            SettingsTextField::CokacdirProgram,
        ),
    ] {
        let line_index = lines.len();
        let (line, row_cursor) = settings_text_row_line(
            state,
            row,
            label,
            field,
            state.text_status(field),
            inner_width,
        );
        if let Some(col) = row_cursor {
            cursor = Some((line_index, col));
        }
        lines.push(line);
    }
    cursor
}

fn settings_keybindings_lines(
    state: &SettingsState,
    inner_width: usize,
    lines: &mut Vec<Line<'static>>,
) {
    lines.push(settings_row_line(
        state.selected == SETTINGS_KEYBINDINGS_FILE,
        SettingsRowKind::ReadOnly,
        "Keybinding file",
        &optional_path_label(keybinding_path()),
        inner_width,
    ));
    lines.push(settings_row_line(
        state.selected == SETTINGS_KEYBINDINGS_RELOAD,
        SettingsRowKind::ReadOnly,
        "Live reload",
        "enabled; keybinding.json changes are watched",
        inner_width,
    ));
}

fn settings_data_lines(state: &SettingsState, inner_width: usize, lines: &mut Vec<Line<'static>>) {
    lines.push(settings_row_line(
        state.selected == SETTINGS_DATA_SETTINGS_FILE,
        SettingsRowKind::ReadOnly,
        "Settings file",
        &optional_path_label(settings_path()),
        inner_width,
    ));
    lines.push(settings_row_line(
        state.selected == SETTINGS_DATA_KEYBINDING_FILE,
        SettingsRowKind::ReadOnly,
        "Keybinding file",
        &optional_path_label(keybinding_path()),
        inner_width,
    ));
    lines.push(settings_row_line(
        state.selected == SETTINGS_DATA_AI_SEARCHDATA,
        SettingsRowKind::ReadOnly,
        "AI searchdata",
        &ai_search_data_dir().map_or_else(|e| e, |path| display_cwd_path(&path)),
        inner_width,
    ));
}

fn settings_row_line(
    selected: bool,
    kind: SettingsRowKind,
    label: &str,
    value: &str,
    inner_width: usize,
) -> Line<'static> {
    let marker_width = UnicodeWidthStr::width(selection_marker(selected));
    let label_width = 22.min(inner_width.saturating_sub(marker_width + 4));
    let value_width = inner_width.saturating_sub(marker_width + label_width + 2);
    let text = format!(
        "{}{}  {}",
        selection_marker(selected),
        fit_width(label, label_width, Align::Left),
        truncate_width(value, value_width)
    );
    let style = settings_row_style(selected, kind);
    Line::from(Span::styled(text, style))
}

fn settings_heading_line(label: &str, inner_width: usize) -> Line<'static> {
    Line::from(Span::styled(
        fit_width(label, inner_width, Align::Left),
        Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
    ))
}

fn settings_row_style(selected: bool, kind: SettingsRowKind) -> Style {
    match (selected, kind) {
        (true, SettingsRowKind::ReadOnly) => Style::default()
            .fg(THEME_FG_DIM)
            .bg(THEME_STATUS_BG)
            .add_modifier(Modifier::BOLD),
        (true, _) => theme_selected_style(),
        (false, SettingsRowKind::ReadOnly) => Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        (false, _) => theme_alt_style(),
    }
}

fn settings_status_style(level: SettingsStatusLevel, selected: bool) -> Style {
    let bg = if selected {
        THEME_SELECTED_BG
    } else {
        THEME_BG_ALT
    };
    let fg = match level {
        SettingsStatusLevel::Ok => THEME_POSITIVE,
        SettingsStatusLevel::Warning => THEME_WARNING,
        SettingsStatusLevel::Error => THEME_ERROR,
    };
    Style::default().fg(fg).bg(bg)
}

fn settings_text_row_line(
    state: &SettingsState,
    row: usize,
    label: &str,
    field: SettingsTextField,
    status: SettingsTextStatus,
    inner_width: usize,
) -> (Line<'static>, Option<usize>) {
    let selected = state.selected == row;
    let marker_width = UnicodeWidthStr::width(selection_marker(selected));
    let label_width = 22.min(inner_width.saturating_sub(marker_width + 4));
    let status_width = 28.min(inner_width.saturating_sub(marker_width + label_width + 4) / 2);
    let value_width = inner_width
        .saturating_sub(marker_width + label_width + status_width + 4)
        .max(1);
    let editing = state.editing.as_ref().filter(|edit| edit.field == field);
    let (value_text, cursor_col) = if let Some(edit) = editing {
        let input = input_viewport(
            state.draft.text_field_value(field),
            edit.cursor,
            value_width,
        );
        (
            input.text,
            Some(marker_width + label_width + 2 + input.cursor_col),
        )
    } else {
        (
            truncate_width(
                &settings_text_display_value(&state.draft, field),
                value_width,
            ),
            None,
        )
    };
    let row_style = settings_row_style(selected, SettingsRowKind::Text);
    let mut spans = vec![Span::styled(
        format!(
            "{}{}  {}",
            selection_marker(selected),
            fit_width(label, label_width, Align::Left),
            value_text
        ),
        row_style,
    )];
    if editing.is_none() && status_width > 0 {
        spans.push(Span::styled("  ", row_style));
        spans.push(Span::styled(
            fit_width(&status.text, status_width, Align::Left),
            settings_status_style(status.level, selected),
        ));
    }
    (Line::from(spans), cursor_col)
}

fn settings_text_display_value(draft: &SettingsDraft, field: SettingsTextField) -> String {
    let value = draft.text_field_value(field).trim();
    if value.is_empty() {
        format!("(default: {})", settings_text_default_program(field))
    } else {
        value.to_string()
    }
}

fn settings_text_default_program(field: SettingsTextField) -> &'static str {
    match field {
        SettingsTextField::AgentProgram(provider) => default_agent_program(provider),
        SettingsTextField::CokacdirProgram => COKACDIR_PROGRAM_NAME,
    }
}

#[derive(Debug, Clone)]
struct SettingsTextStatus {
    text: String,
    level: SettingsStatusLevel,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SettingsStatusLevel {
    Ok,
    Warning,
    Error,
}

impl SettingsTextStatus {
    fn ok(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            level: SettingsStatusLevel::Ok,
        }
    }

    fn warning(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            level: SettingsStatusLevel::Warning,
        }
    }

    fn error(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            level: SettingsStatusLevel::Error,
        }
    }
}

fn settings_text_status(draft: &SettingsDraft, field: SettingsTextField) -> SettingsTextStatus {
    match field {
        SettingsTextField::AgentProgram(provider) => {
            match resolve_agent_program_for_provider(provider, &draft.agent_programs) {
                Some(path) => SettingsTextStatus::ok(format!("ok: {}", display_cwd_path(&path))),
                None => SettingsTextStatus::error("not found"),
            }
        }
        SettingsTextField::CokacdirProgram => {
            let settings = CokacmuxSettings {
                cokacdir_program: Some(draft.cokacdir_program.clone()),
                ..Default::default()
            };
            match resolve_cokacdir_program(&settings) {
                Some(path) => SettingsTextStatus::ok(format!("ok: {}", display_cwd_path(&path))),
                None if draft.cokacdir_program.trim().is_empty() => {
                    SettingsTextStatus::warning("auto-download")
                }
                None => SettingsTextStatus::error("not found"),
            }
        }
    }
}

fn settings_help_items(state: &SettingsState, keybindings: &KeyBindings) -> Vec<HelpItem> {
    if state.editing.is_some() {
        return vec![
            direct_help_item("type", "path"),
            direct_help_item("←/→", "cursor"),
            help_item(
                keybindings,
                KeyAction::AiTitleSettingsSave,
                "Enter",
                "keep edit",
            ),
            help_item(
                keybindings,
                KeyAction::AiTitleSettingsCancel,
                "Esc",
                "discard edit",
            ),
        ];
    }
    let mut items = vec![
        direct_help_item("←/→", "section"),
        help_pair_item(
            keybindings,
            KeyAction::AiTitleSettingsPrev,
            KeyAction::AiTitleSettingsNext,
            "↑",
            "↓",
            "move",
        ),
    ];
    match state.selected_row_kind() {
        SettingsRowKind::Text if state.edit_finished => {
            items.push(help_item(
                keybindings,
                KeyAction::AiTitleSettingsSave,
                "Enter",
                "save",
            ));
            items.push(direct_help_item("type", "edit again"));
        }
        SettingsRowKind::Text => {
            items.push(help_item(
                keybindings,
                KeyAction::AiTitleSettingsSave,
                "Enter",
                "edit path",
            ));
        }
        SettingsRowKind::ReadOnly => {
            items.push(direct_help_item("read-only", "field"));
            items.push(help_item(
                keybindings,
                KeyAction::AiTitleSettingsSave,
                "Enter",
                "save",
            ));
        }
        SettingsRowKind::Select => {
            items.push(direct_help_item("Space", "select"));
            items.push(help_item(
                keybindings,
                KeyAction::AiTitleSettingsSave,
                "Enter",
                "save",
            ));
        }
        SettingsRowKind::Change => {
            items.push(direct_help_item("Space", "change"));
            items.push(help_item(
                keybindings,
                KeyAction::AiTitleSettingsSave,
                "Enter",
                "save",
            ));
        }
    }
    items.push(help_item(
        keybindings,
        KeyAction::AiTitleSettingsCancel,
        "Esc",
        "cancel",
    ));
    if state.is_dirty() {
        items.push(direct_help_item("!", "unsaved"));
    }
    items
}

fn optional_path_label(path: Option<PathBuf>) -> String {
    path.map(|path| display_cwd_path(&path))
        .unwrap_or_else(|| "unavailable".to_string())
}

fn ai_title_provider_option_line(
    index: usize,
    provider: Option<Provider>,
    focused: bool,
    current: bool,
    inner_width: usize,
) -> Line<'static> {
    let label = match provider {
        Some(provider) => provider.as_str().to_string(),
        None => "None (disabled)".to_string(),
    };
    let current_label = if current { " current" } else { "" };
    let text = format!(
        "{}{} {}{}",
        selection_marker(focused),
        index + 1,
        label,
        current_label
    );
    let style = if focused {
        theme_selected_style()
    } else if current {
        Style::default()
            .fg(provider.map(provider_color).unwrap_or(THEME_POSITIVE))
            .bg(THEME_BG_ALT)
            .add_modifier(Modifier::BOLD)
    } else {
        let fg = provider.map(provider_color).unwrap_or(THEME_FG_STRONG);
        Style::default().fg(fg).bg(THEME_BG_ALT)
    };
    Line::from(Span::styled(
        fit_width(&text, inner_width, Align::Left),
        style,
    ))
}

fn draw_agent_launch_modal(
    f: &mut ratatui::Frame,
    area: Rect,
    source: &SessionInfo,
    selected: usize,
    agent_programs: &AgentProgramSettings,
    keybindings: &KeyBindings,
) {
    let intro = format!(
        "Start/attach {} session {}",
        source.provider.as_str(),
        truncate_width(&source.session_id, 24)
    );
    let help_items = agent_launch_help_items(keybindings);
    let help = help_text_from_items(&help_items);
    let option_width = AGENT_LAUNCH_MODE_OPTIONS
        .iter()
        .copied()
        .map(|launch_mode| {
            let label = launch_mode.label();
            let command =
                agent_launch_spec_with_programs(source, launch_mode, agent_programs).command_line();
            UnicodeWidthStr::width(label)
                .saturating_add(UnicodeWidthStr::width(command.as_str()).min(42))
                .saturating_add(8)
        })
        .max()
        .unwrap_or(0);
    let desired_width = UnicodeWidthStr::width(intro.as_str())
        .max(UnicodeWidthStr::width(help.as_str()))
        .max(option_width);
    let provisional_area = modal_area_from_content_rows(
        area,
        "Agent launch",
        desired_width,
        AGENT_LAUNCH_MODE_OPTIONS.len().saturating_add(4),
        54,
        96,
        8,
        12,
    );
    let inner_width = provisional_area.width.saturating_sub(2) as usize;
    let label_width = 25.min(inner_width.saturating_sub(12));
    let command_width = inner_width.saturating_sub(7 + label_width);
    let mut lines = vec![Line::from(intro), Line::from("")];

    for (idx, launch_mode) in AGENT_LAUNCH_MODE_OPTIONS.iter().copied().enumerate() {
        let is_selected = idx == selected;
        let style = if is_selected {
            theme_selected_style()
        } else {
            theme_alt_style()
        };
        let label = launch_mode.label();
        let command =
            agent_launch_spec_with_programs(source, launch_mode, agent_programs).command_line();
        lines.push(Line::from(Span::styled(
            format!(
                "{}{}. {}  {}",
                selection_marker(is_selected),
                idx + 1,
                fit_width(label, label_width, Align::Left),
                truncate_width(&command, command_width)
            ),
            style,
        )));
    }

    lines.push(Line::from(""));
    lines.push(modal_help_line(&help_items));

    let modal_area = modal_area_for_wrapped_lines(area, "Agent launch", &lines, 54, 96, 8, 12);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("Agent launch");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
}

// Keep modal rendering inputs explicit at this leaf UI boundary.
#[allow(clippy::too_many_arguments)]
fn draw_clone_options_modal(
    f: &mut ratatui::Frame,
    area: Rect,
    source: &SessionInfo,
    target: Provider,
    selected: usize,
    folder_data: &CloneFolderDataAvailability,
    context_mode: session::clone::CloneContextMode,
    keybindings: &KeyBindings,
) {
    let intro = format!(
        "Clone {} session {}",
        source.provider.as_str(),
        truncate_width(&source.session_id, 24)
    );
    let target_kind = if target == source.provider {
        "native copy"
    } else {
        "2-message context handoff"
    };
    let target_line = format!("Target: {} ({})", target.as_str(), target_kind);
    let data_line = clone_options_data_line(folder_data);
    let context_line = clone_options_context_line(source.provider, target, context_mode);
    let help_items = clone_options_help_items(keybindings);
    let lines = vec![
        Line::from(Span::styled(
            intro,
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            target_line,
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )),
        clone_options_data_status_line(folder_data, data_line),
        clone_options_context_status_line(source.provider, target, context_line),
        Line::from(""),
        clone_options_button_line(selected, folder_data, target == source.provider),
        modal_help_line(&help_items),
    ];
    let modal_area = modal_area_for_wrapped_lines(area, "Clone session", &lines, 58, 94, 8, 12);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("Clone session");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
}

fn clone_options_data_line(folder_data: &CloneFolderDataAvailability) -> String {
    match folder_data {
        CloneFolderDataAvailability::Available(path) => {
            format!(
                "Folder data: {}",
                truncate_width(&display_cwd_path(path), 72)
            )
        }
        CloneFolderDataAvailability::Unavailable(reason) => {
            format!("Folder data unavailable: {}", truncate_width(reason, 62))
        }
    }
}

fn clone_options_data_status_line(
    folder_data: &CloneFolderDataAvailability,
    data_line: String,
) -> Line<'static> {
    let style = match folder_data {
        CloneFolderDataAvailability::Available(_) => {
            Style::default().fg(THEME_ACCENT).bg(THEME_BG_ALT)
        }
        CloneFolderDataAvailability::Unavailable(_) => {
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT)
        }
    };
    Line::from(Span::styled(data_line, style))
}

fn clone_options_context_line(
    source_provider: Provider,
    target_provider: Provider,
    context_mode: session::clone::CloneContextMode,
) -> String {
    if source_provider == target_provider {
        "Context mode: not used for native copy".to_string()
    } else {
        format!("Context mode: {}", clone_context_mode_label(context_mode))
    }
}

fn clone_options_context_status_line(
    source_provider: Provider,
    target_provider: Provider,
    context_line: String,
) -> Line<'static> {
    let style = if source_provider == target_provider {
        Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT)
    } else {
        Style::default().fg(THEME_ACCENT).bg(THEME_BG_ALT)
    };
    Line::from(Span::styled(context_line, style))
}

fn clone_options_button_line(
    selected: usize,
    folder_data: &CloneFolderDataAvailability,
    same_provider: bool,
) -> Line<'static> {
    let folder_data_enabled = matches!(folder_data, CloneFolderDataAvailability::Available(_));
    let session_label = if same_provider {
        "1 Native copy"
    } else {
        "1 Context"
    };
    let data_label = if same_provider {
        "2 Native + data"
    } else {
        "2 Context + data"
    };
    Line::from(vec![
        clone_options_button_span(session_label, selected == CLONE_OPTION_SESSION_ONLY, true),
        Span::raw("  "),
        clone_options_button_span(
            data_label,
            selected == CLONE_OPTION_FOLDER_DATA,
            folder_data_enabled,
        ),
        Span::raw("  "),
        clone_options_button_span("3 Cancel", selected == CLONE_OPTION_CANCEL, true),
    ])
}

fn clone_options_button_span(label: &str, selected: bool, enabled: bool) -> Span<'static> {
    let text = format!("{}{}", selection_marker(selected), label);
    let style = if selected && enabled {
        theme_selected_style()
    } else if selected {
        theme_selected_style().fg(THEME_FG_DIM)
    } else if enabled {
        Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT)
    } else {
        Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT)
    };
    Span::styled(text, style)
}

// Keep new-session draft fields explicit at this leaf UI boundary.
#[allow(clippy::too_many_arguments)]
fn draw_new_session_modal(
    f: &mut ratatui::Frame,
    area: Rect,
    selected: usize,
    kind: NewSessionKind,
    cwd: &str,
    cwd_cursor: usize,
    cwd_completion: &NewSessionPathCompletion,
    provider: Provider,
    provider_options: &[Provider],
    launch_mode: AgentLaunchMode,
    settings: &CokacmuxSettings,
    keybindings: &KeyBindings,
) {
    let selected = clamp_new_session_field(selected, kind);
    let completion_visible =
        selected == NEW_SESSION_FIELD_CWD && new_session_completion_is_visible(cwd_completion);
    let help_items = new_session_help_items(selected, completion_visible, keybindings);
    let preview_command =
        new_session_preview_command(kind, cwd, provider, provider_options, launch_mode, settings);
    let desired_width = NEW_SESSION_MODAL_STABLE_CONTENT_WIDTH;
    let base_content_rows: usize = if kind == NewSessionKind::CodingAgent {
        8
    } else {
        6
    };
    // Path suggestions are drawn as an overlay, so they do not reserve rows in
    // the modal's content flow.
    let content_rows = base_content_rows;
    let min_height = content_rows.saturating_add(2) as u16;
    let provisional_area = modal_area_from_content_rows(
        area,
        "New session",
        desired_width,
        content_rows,
        56,
        98,
        min_height,
        NEW_SESSION_MODAL_MAX_HEIGHT,
    );
    let inner_width = provisional_area.width.saturating_sub(2) as usize;
    let label_width = 12usize.min(inner_width.saturating_sub(8));
    let value_width = inner_width.saturating_sub(label_width + 5);
    let mut lines = vec![Line::from(Span::styled(
        "Choose what to start",
        Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
    ))];

    lines.push(new_session_field_line(
        selected == NEW_SESSION_FIELD_KIND,
        "Type",
        kind.label().to_string(),
        label_width,
        value_width,
    ));
    let cwd_input = if selected == NEW_SESSION_FIELD_CWD {
        Some(input_viewport(cwd, cwd_cursor, value_width))
    } else {
        None
    };
    let cwd_value = if let Some(input) = cwd_input.as_ref() {
        input.text.clone()
    } else {
        fit_width(cwd, value_width, Align::Left)
    };
    lines.push(new_session_text_input_field_line(
        selected == NEW_SESSION_FIELD_CWD,
        "Folder",
        cwd_value,
        label_width,
        value_width,
    ));
    if kind == NewSessionKind::CodingAgent {
        let provider_label = if provider_options.is_empty() {
            "none installed".to_string()
        } else {
            provider.as_str().to_string()
        };
        lines.push(new_session_field_line(
            selected == NEW_SESSION_FIELD_PROVIDER,
            "Agent",
            provider_label,
            label_width,
            value_width,
        ));
        lines.push(new_session_field_line(
            selected == NEW_SESSION_FIELD_PERMISSIONS,
            "Permissions",
            launch_mode.label().to_string(),
            label_width,
            value_width,
        ));
    }

    lines.push(Line::from(Span::styled(
        truncate_width(&preview_command, inner_width),
        Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
    )));
    lines.push(Line::from(""));
    lines.push(help_line_from_items_with_bg(
        &help_items,
        inner_width,
        THEME_BG_ALT,
    ));

    let modal_area = modal_area_for_wrapped_lines_with_content_width(
        area,
        "New session",
        &lines,
        desired_width,
        56,
        98,
        min_height,
        NEW_SESSION_MODAL_MAX_HEIGHT,
    );
    let completion_overlay = if completion_visible {
        let line_budget = cwd_completion
            .suggestions
            .len()
            .min(NEW_SESSION_PATH_COMPLETION_MAX_ITEMS);
        let overlay_area = new_session_path_completion_overlay_area(modal_area, line_budget);
        let root_anchor = new_session_completion_anchors_at_root(cwd, cwd_cursor);
        let value_indent = cwd_input
            .as_ref()
            .map(|input| new_session_completion_value_indent(cwd, cwd_cursor, input))
            .unwrap_or(0)
            .saturating_sub(usize::from(root_anchor))
            .min(value_width);
        let lines = new_session_path_completion_lines(
            cwd_completion,
            label_width,
            value_width,
            value_indent,
            root_anchor,
            overlay_area.height as usize,
        );
        Some((overlay_area, lines))
    } else {
        None
    };
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("New session");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
    if let Some((overlay_area, completion_overlay_lines)) = completion_overlay {
        if overlay_area.height > 0 && overlay_area.width > 0 && !completion_overlay_lines.is_empty()
        {
            f.render_widget(ratatui::widgets::Clear, overlay_area);
            fill_area(f.buffer_mut(), overlay_area, theme_alt_style());
            f.render_widget(
                Paragraph::new(completion_overlay_lines)
                    .style(theme_alt_style())
                    .wrap(Wrap { trim: false }),
                overlay_area,
            );
        }
    }
    if let Some(input) = cwd_input {
        let cursor_col = UnicodeWidthStr::width(selection_marker(true))
            .saturating_add(label_width)
            .saturating_add(1)
            .saturating_add(input.cursor_col);
        set_modal_input_cursor(f, modal_area, 2, cursor_col);
    }
}

fn new_session_path_completion_overlay_area(modal_area: Rect, line_count: usize) -> Rect {
    let inner_height = modal_area.height.saturating_sub(2);
    let available_height = inner_height.saturating_sub(NEW_SESSION_PATH_COMPLETION_OVERLAY_ROW);
    let height = usize_to_u16_saturating(line_count).min(available_height);
    Rect::new(
        modal_area.x.saturating_add(1),
        modal_area
            .y
            .saturating_add(1)
            .saturating_add(NEW_SESSION_PATH_COMPLETION_OVERLAY_ROW),
        modal_area.width.saturating_sub(2),
        height,
    )
}

fn new_session_field_line(
    selected: bool,
    label: &str,
    value: String,
    label_width: usize,
    value_width: usize,
) -> Line<'static> {
    new_session_field_line_with_value_focus(selected, label, value, label_width, value_width, true)
}

fn new_session_text_input_field_line(
    selected: bool,
    label: &str,
    value: String,
    label_width: usize,
    value_width: usize,
) -> Line<'static> {
    new_session_field_line_with_value_focus(selected, label, value, label_width, value_width, false)
}

fn new_session_field_line_with_value_focus(
    selected: bool,
    label: &str,
    value: String,
    label_width: usize,
    value_width: usize,
    focus_value: bool,
) -> Line<'static> {
    let marker_style = if selected {
        Style::default()
            .fg(THEME_ACCENT)
            .bg(THEME_BG_ALT)
            .add_modifier(Modifier::BOLD)
    } else {
        theme_alt_style()
    };
    let label_style = Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT);
    let separator_style = theme_alt_style();
    let mut spans = vec![
        Span::styled(selection_marker(selected), marker_style),
        Span::styled(fit_width(label, label_width, Align::Left), label_style),
        Span::styled(" ", separator_style),
    ];
    spans.extend(new_session_field_value_spans(
        &value,
        selected && focus_value,
        value_width,
    ));
    Line::from(spans)
}

fn new_session_field_value_spans(
    value: &str,
    selected: bool,
    value_width: usize,
) -> Vec<Span<'static>> {
    let display_value = fit_width(value, value_width, Align::Left);
    if !selected {
        return vec![Span::styled(display_value, theme_alt_style())];
    }

    let leading_end = display_value
        .char_indices()
        .find_map(|(index, ch)| (ch != ' ').then_some(index))
        .unwrap_or(display_value.len());
    let content_end = display_value.trim_end_matches(' ').len();
    let mut spans = Vec::new();
    if leading_end > 0 {
        spans.push(Span::styled(
            display_value[..leading_end].to_string(),
            theme_alt_style(),
        ));
    }
    if content_end > leading_end {
        spans.push(Span::styled(
            display_value[leading_end..content_end].to_string(),
            theme_selected_style(),
        ));
    }
    if content_end < display_value.len() {
        spans.push(Span::styled(
            display_value[content_end..].to_string(),
            theme_alt_style(),
        ));
    }
    if spans.is_empty() {
        spans.push(Span::styled(display_value, theme_alt_style()));
    }
    spans
}

fn new_session_path_completion_lines(
    completion: &NewSessionPathCompletion,
    label_width: usize,
    value_width: usize,
    value_indent: usize,
    root_anchor: bool,
    max_items: usize,
) -> Vec<Line<'static>> {
    let total = completion.suggestions.len();
    if !completion.visible || total == 0 || max_items == 0 {
        return Vec::new();
    }

    let max_visible = total.min(max_items);
    let selected = completion.selected_index.min(total.saturating_sub(1));
    let scroll_offset = if total <= max_visible || selected < max_visible / 2 {
        0
    } else if selected >= total.saturating_sub(max_visible / 2) {
        total.saturating_sub(max_visible)
    } else {
        selected.saturating_sub(max_visible / 2)
    };

    completion
        .suggestions
        .iter()
        .enumerate()
        .skip(scroll_offset)
        .take(max_visible)
        .map(|(index, suggestion)| {
            let selected = index == completion.selected_index;
            let mut value = suggestion.clone();
            if root_anchor {
                value = format!("{}{}", std::path::MAIN_SEPARATOR, value);
            }
            let visible_width = value_width.saturating_sub(value_indent);
            let value = format!(
                "{}{}",
                " ".repeat(value_indent),
                fit_width(&value, visible_width, Align::Left)
            );
            new_session_field_line(selected, "", value, label_width, value_width)
        })
        .collect()
}

fn new_session_completion_value_indent(
    cwd: &str,
    cwd_cursor: usize,
    input: &InputViewport,
) -> usize {
    let context = new_session_path_completion_context(cwd, cwd_cursor);
    let display = sanitize_for_single_line(cwd);
    let visible_start = clamp_to_char_boundary(&display, input.visible_start.min(display.len()));
    let replace_start = clamp_to_char_boundary(&display, context.replace_start.min(display.len()));
    if replace_start <= visible_start {
        return 0;
    }

    UnicodeWidthStr::width(&display[visible_start..replace_start])
}

fn new_session_completion_anchors_at_root(cwd: &str, cwd_cursor: usize) -> bool {
    let context = new_session_path_completion_context(cwd, cwd_cursor);
    context.replace_start > 0
        && context.base_dir.has_root()
        && context.base_dir.components().count() <= 1
}

fn new_session_preview_command(
    kind: NewSessionKind,
    cwd: &str,
    provider: Provider,
    provider_options: &[Provider],
    launch_mode: AgentLaunchMode,
    settings: &CokacmuxSettings,
) -> String {
    match kind {
        NewSessionKind::Terminal => {
            let info = SessionInfo {
                provider: Provider::Claude,
                session_id: "preview".into(),
                cwd: cwd.to_string(),
                source: PathBuf::from(SHELL_SESSION_SOURCE_MARKER),
                updated_at_epoch_s: 0,
                title: None,
                relation: None,
            };
            shell_launch_spec(&info).command_line()
        }
        NewSessionKind::CokacDir => {
            let info = SessionInfo {
                provider: Provider::Claude,
                session_id: "preview".into(),
                cwd: cwd.to_string(),
                source: PathBuf::from(COKACDIR_SESSION_SOURCE_MARKER),
                updated_at_epoch_s: 0,
                title: None,
                relation: None,
            };
            cokacdir_launch_spec(&info, settings).command_line()
        }
        NewSessionKind::CodingAgent => {
            if provider_options.is_empty() {
                return "no installed coding agents".to_string();
            }
            if !provider_options.contains(&provider) {
                return format!("{} agent is not installed", provider.as_str());
            }
            let info = SessionInfo {
                provider,
                session_id: "preview".into(),
                cwd: cwd.to_string(),
                source: PathBuf::from(NEW_AGENT_SESSION_SOURCE_MARKER),
                updated_at_epoch_s: 0,
                title: None,
                relation: None,
            };
            new_agent_launch_spec_with_programs(&info, launch_mode, &settings.agent_programs)
                .command_line()
        }
    }
}

fn new_session_launch_target_label(kind: NewSessionKind, provider: Provider) -> String {
    match kind {
        NewSessionKind::Terminal => "terminal".to_string(),
        NewSessionKind::CokacDir => "cokacdir".to_string(),
        NewSessionKind::CodingAgent => format!("{} agent", provider.as_str()),
    }
}

