fn age_label(epoch_s: u64) -> String {
    if epoch_s == 0 {
        return "?".into();
    }
    let now = chrono::Utc::now().timestamp() as u64;
    let secs = now.saturating_sub(epoch_s);
    if secs < 60 {
        format!("{}s", secs)
    } else if secs < 3600 {
        format!("{}m", secs / 60)
    } else if secs < 86_400 {
        format!("{}h", secs / 3600)
    } else if secs < 86_400 * 30 {
        format!("{}d", secs / 86_400)
    } else {
        format!("{}w", secs / 604_800)
    }
}

fn tree_session_label(depth: usize, session_id: &str) -> String {
    let session_id = session_id_display_label(session_id);
    if depth == 0 {
        session_id
    } else {
        format!("{}└ {}", "  ".repeat(depth.saturating_sub(1)), session_id)
    }
}

fn session_id_display_label(session_id: &str) -> String {
    truncate_width(session_id_display_part(session_id), SESSION_DISPLAY_WIDTH)
}

fn session_id_display_part(session_id: &str) -> &str {
    session_id
        .rsplit('-')
        .find(|part| !part.is_empty())
        .unwrap_or(session_id)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct InputViewport {
    text: String,
    cursor_col: usize,
    visible_start: usize,
}

fn input_viewport(value: &str, cursor: usize, width: usize) -> InputViewport {
    if width == 0 {
        return InputViewport {
            text: String::new(),
            cursor_col: 0,
            visible_start: 0,
        };
    }

    let display = sanitize_for_single_line(value);
    let cursor = clamp_to_char_boundary(&display, cursor.min(display.len()));
    let before = &display[..cursor];
    let after = &display[cursor..];
    let before_width = UnicodeWidthStr::width(before);

    if before_width < width {
        let after_visible = prefix_width(after, width - before_width);
        return InputViewport {
            text: fit_width(&format!("{}{}", before, after_visible), width, Align::Left),
            cursor_col: before_width,
            visible_start: 0,
        };
    }

    let (before_visible, visible_start) = suffix_width_with_start(before, width.saturating_sub(1));
    let cursor_col = UnicodeWidthStr::width(before_visible.as_str());
    let after_visible = prefix_width(after, width.saturating_sub(cursor_col));
    InputViewport {
        text: fit_width(
            &format!("{}{}", before_visible, after_visible),
            width,
            Align::Left,
        ),
        cursor_col,
        visible_start,
    }
}

fn title_edit_readonly_display(draft: &str, width: usize) -> String {
    fit_width(draft, width, Align::Left)
}

fn modal_input_display_text(text: &str, width: usize) -> String {
    fit_width(text, width, Align::Left)
}

