    #[cfg(unix)]
    #[test]
    fn bounded_command_output_captures_both_streams() {
        let mut command = Command::new("sh");
        command.args(["-c", "printf stdout-value; printf stderr-value >&2"]);
        let output = command_output_with_timeout(command, Duration::from_secs(2))
            .unwrap()
            .expect("short command should finish");

        assert!(output.status.success());
        assert_eq!(String::from_utf8_lossy(&output.stdout), "stdout-value");
        assert_eq!(String::from_utf8_lossy(&output.stderr), "stderr-value");
    }

    #[cfg(unix)]
    #[test]
    fn bounded_command_timeout_terminates_its_process_group() {
        let dir = tempfile::tempdir().unwrap();
        let pid_path = dir.path().join("descendant.pid");
        let script = format!(
            "sleep 30 & child=$!; printf '%s' \"$child\" > {}; wait",
            shell_single_quote(&pid_path.display().to_string())
        );
        let mut command = Command::new("sh");
        command.args(["-c", &script]);

        let started = Instant::now();
        let output = command_output_with_timeout(command, Duration::from_millis(150)).unwrap();
        assert!(output.is_none());
        assert!(started.elapsed() < Duration::from_secs(3));

        let descendant_pid = fs::read_to_string(&pid_path)
            .unwrap()
            .parse::<u32>()
            .unwrap();
        let deadline = Instant::now() + Duration::from_secs(2);
        while process_is_alive(descendant_pid) && Instant::now() < deadline {
            thread::sleep(Duration::from_millis(10));
        }
        assert!(!process_is_alive(descendant_pid));
    }

    #[test]
    fn bounded_thread_join_detaches_instead_of_blocking_shutdown() {
        let (release_tx, release_rx) = mpsc::channel::<()>();
        let (done_tx, done_rx) = mpsc::channel::<()>();
        let handle = thread::spawn(move || {
            let _ = release_rx.recv();
            let _ = done_tx.send(());
        });

        let started = Instant::now();
        assert!(join_unit_thread_bounded(handle, Duration::from_millis(50)).is_none());
        assert!(started.elapsed() < Duration::from_secs(1));

        // Release the detached test thread so the test itself leaves no
        // background work behind.
        release_tx.send(()).unwrap();
        done_rx.recv_timeout(Duration::from_secs(1)).unwrap();
    }

