        let dir = tempfile::tempdir().unwrap();
        let runtime_dir = dir.path().join("agents");
        ensure_private_agent_runtime_dir(&runtime_dir).unwrap();
        let key = AgentKey::new(&session_info(Provider::Codex, "late-meta-rebind", "/repo"));
