    #[cfg(unix)]
    #[test]
    fn live_daemon_repairs_deleted_or_corrupted_auth_token() {
        let dir = tempfile::tempdir().unwrap();
        let runtime_dir = dir.path().join("agents");
        ensure_private_agent_runtime_dir(&runtime_dir).unwrap();
        let key = AgentKey::new(&session_info(Provider::Codex, "auth-repair", "/repo"));
        let socket_path = runtime_dir.join("auth-repair.sock");
        let auth_path = runtime_dir.join("auth-repair.auth");
        let (listener, publication) = bind_agent_listener(&key, &socket_path).unwrap();
        let expected = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";

        write_private_runtime_file_new(&auth_path, b"ffffffffffffffffffffffffffffffff\n").unwrap();
        assert!(!agent_auth_token_file_matches(&auth_path, expected));
        repair_agent_auth_token_if_endpoint_owned_at(
            &socket_path,
            &auth_path,
            &publication,
            expected,
        )
        .unwrap();
        assert_eq!(
            read_agent_auth_token_at(&runtime_dir, "auth-repair").as_deref(),
            Some(expected)
        );
        assert!(agent_auth_token_file_matches(&auth_path, expected));

        fs::remove_file(&auth_path).unwrap();
        repair_agent_auth_token_if_endpoint_owned_at(
            &socket_path,
            &auth_path,
            &publication,
            expected,
        )
        .unwrap();
        assert_eq!(
            read_agent_auth_token_at(&runtime_dir, "auth-repair").as_deref(),
            Some(expected)
        );
        drop(listener);
    }

    #[test]
    fn cli_command_terminal_source_round_trips() {
        let program = std::env::current_exe().unwrap().display().to_string();
        let argv = vec![program.clone(), "--version".to_string()];
        let info = cli_command_session_info("web".into(), "/repo".into(), argv.clone())
            .expect("command session info should encode source");

        assert!(is_cli_command_session_info(&info));
        assert!(is_plain_pty_tool_session_info(&info));
        assert_eq!(
            auxiliary_kind_for_session_info(&info),
            Some(AgentAuxKind::Terminal)
        );
        assert_eq!(agent_info_kind(&info), "terminal");
        assert_eq!(info.title.as_deref(), Some("web"));

        let source = cli_command_session_source(&info).expect("source should decode");
        assert_eq!(source.name.as_deref(), Some("web"));
        assert_eq!(source.argv, argv);

        let spec = cli_command_launch_spec(&info);
        assert_eq!(spec.program, program);
        assert_eq!(spec.args, vec!["--version".to_string()]);
        assert_eq!(spec.cwd, Some(PathBuf::from("/repo")));
    }

