    #[test]
    fn authenticated_request_preserves_legacy_flat_wire_shape() {
        let envelope = AuthenticatedAgentDaemonRequest {
            auth: Some("0123456789abcdef0123456789abcdef".into()),
            request: AgentDaemonRequest::Resize { cols: 91, rows: 27 },
        };
        let value = serde_json::to_value(&envelope).unwrap();
        assert_eq!(
            value.get("type").and_then(|value| value.as_str()),
            Some("resize")
        );
        assert_eq!(value.get("cols").and_then(|value| value.as_u64()), Some(91));
        assert_eq!(value.get("rows").and_then(|value| value.as_u64()), Some(27));
        assert_eq!(
            value.get("auth").and_then(|value| value.as_str()),
            Some("0123456789abcdef0123456789abcdef")
        );
        assert!(value.get("request").is_none());

        // Serde's default unknown-field behavior keeps a new authenticated
        // client readable by the previous raw-request daemon.
        let legacy: AgentDaemonRequest = serde_json::from_value(value.clone()).unwrap();
        assert!(matches!(
            legacy,
            AgentDaemonRequest::Resize { cols: 91, rows: 27 }
        ));
        let decoded: AuthenticatedAgentDaemonRequest = serde_json::from_value(value).unwrap();
        assert_eq!(
            decoded.auth.as_deref(),
            Some("0123456789abcdef0123456789abcdef")
        );
        assert!(matches!(
            decoded.request,
            AgentDaemonRequest::Resize { cols: 91, rows: 27 }
        ));

        let legacy_wire = serde_json::json!({"type": "identify"});
        let decoded: AuthenticatedAgentDaemonRequest = serde_json::from_value(legacy_wire).unwrap();
        assert!(decoded.auth.is_none());
        assert!(matches!(decoded.request, AgentDaemonRequest::Identify));
    }

