    #[test]
    fn agent_client_confirms_attach_challenge_before_accepting_attached() {
        let info = session_info(
            Provider::Codex,
            &format!("attach-challenge-client-{}", uuid::Uuid::now_v7()),
            "/repo",
        );
        let server_info = info.clone();
        let (client_stream, mut server_stream) = AgentStream::pair().unwrap();
        let server_reader = server_stream.try_clone().unwrap();
        let server = thread::spawn(move || {
            let mut reader = BufReader::new(server_reader);
            let mut line = String::new();
            reader.read_line(&mut line).unwrap();
            let attach: AuthenticatedAgentDaemonRequest =
                serde_json::from_str(line.trim_end()).unwrap();
            let client_instance_id = match attach.request {
                AgentDaemonRequest::Attach {
                    attach_confirmation: true,
                    client_instance_id,
                    ..
                } => client_instance_id,
                other => panic!("expected challenge-capable Attach, got {other:?}"),
            };
            write_json_line(
                &mut server_stream,
                &AgentDaemonEvent::AttachChallenge {
                    provider: server_info.provider,
                    session_id: server_info.session_id.clone(),
                    nonce: "server-issued-nonce".to_string(),
                },
            )
            .unwrap();

            line.clear();
            reader.read_line(&mut line).unwrap();
            let confirmation: AuthenticatedAgentDaemonRequest =
                serde_json::from_str(line.trim_end()).unwrap();
            assert!(matches!(
                confirmation.request,
                AgentDaemonRequest::AttachConfirmed {
                    nonce,
                    client_instance_id: confirmed_instance,
                } if nonce == "server-issued-nonce"
                    && confirmed_instance == client_instance_id
            ));
            write_json_line(
                &mut server_stream,
                &AgentDaemonEvent::Attached {
                    provider: server_info.provider,
                    session_id: server_info.session_id,
                    command: "fake-agent".to_string(),
                    daemon_pid: std::process::id(),
                    daemon_pid_start_ticks: process_start_ticks(std::process::id()),
                    child_pid: None,
                    snapshot_event: true,
                    last_screen_change_epoch_ms: 0,
                    last_output_epoch_ms: 0,
                    last_input_epoch_ms: 0,
                    bracketed_paste_mode: false,
                    input_acknowledgements: true,
                },
            )
            .unwrap();
        });
        let (main_tx, _main_rx) = mpsc::channel();

        let client = AgentClient::attach_stream(
            info,
            client_stream,
            80,
            24,
            main_tx,
            9_001,
            AgentLaunchMode::Normal,
        )
        .unwrap();

        assert_eq!(client.command_line, "fake-agent");
        assert!(client.input_acknowledgements);
        server.join().unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn daemon_request_reader_bounds_pre_auth_frame_and_per_tick_work() {
        let (left, mut right) = AgentStream::pair().unwrap();
        let mut conn = DaemonConnection::new(left).unwrap();
        conn.read_buf = vec![b'x'; DAEMON_REQUEST_FRAME_MAX_BYTES];
        conn.read_frame_len = DAEMON_REQUEST_FRAME_MAX_BYTES;
        right.write_all(b"x").unwrap();
        assert_eq!(
            conn.read_requests().unwrap_err().kind(),
            ErrorKind::InvalidData
        );

        let (left, mut right) = AgentStream::pair().unwrap();
        let mut conn = DaemonConnection::new(left).unwrap();
        right
            .write_all(&vec![b'x'; DAEMON_REQUEST_READ_BUDGET_BYTES + 8 * 1024])
            .unwrap();
        assert!(conn.read_requests().unwrap().is_empty());
        assert_eq!(conn.read_buf.len(), DAEMON_REQUEST_READ_BUDGET_BYTES);

        let (left, mut right) = AgentStream::pair().unwrap();
        let mut conn = DaemonConnection::new(left).unwrap();
        let prefix = br#"{"type":"identify","padding":""#;
        let suffix = br#""}"#;
        let padding_len = DAEMON_REQUEST_FRAME_MAX_BYTES - prefix.len() - suffix.len();
        conn.read_buf.extend_from_slice(prefix);
        conn.read_buf.extend(std::iter::repeat_n(b'x', padding_len));
        conn.read_buf.extend_from_slice(suffix);
        conn.read_frame_len = conn.read_buf.len();
        assert_eq!(conn.read_frame_len, DAEMON_REQUEST_FRAME_MAX_BYTES);
        right.write_all(b"\n{\"type\":\"identify\"}\n").unwrap();
        let requests = conn.read_requests().unwrap();
        assert_eq!(requests.len(), 2);
        assert!(requests
            .iter()
            .all(|request| matches!(request, AgentDaemonRequest::Identify)));
    }

