    #[test]
    fn clone_report_builds_removable_session_info_and_preserves_native_relation() {
        let mut source = session_info(Provider::Codex, "source-id", "/repo");
        source.title = Some("Source title".to_string());
        source.relation = Some(SessionRelation::SpawnedAgent {
            parent_session_id: "parent-id".to_string(),
            depth: Some(1),
        });
        let artifact = PathBuf::from("/tmp/cokacmux-clone.jsonl");
        let report = session::clone::CloneReport {
            source_provider: Provider::Codex,
            source_session_id: "source-id".to_string(),
            new_session_id: "clone-id".to_string(),
            target_provider: Provider::Claude,
            new_cwd: "/repo-clone".to_string(),
            artifact: session::clone::ArtifactPath::File(artifact.clone()),
        };

        let clone_info = session_info_from_clone_report(&source, &report);

        assert_eq!(clone_info.provider, Provider::Claude);
        assert_eq!(clone_info.session_id, "clone-id");
        assert_eq!(clone_info.cwd, "/repo-clone");
        assert_eq!(clone_info.source, artifact);
        assert_eq!(clone_info.title.as_deref(), Some("Source title"));
        assert_eq!(clone_info.relation, None);

        let mut native_report = report;
        native_report.target_provider = Provider::Codex;
        native_report.new_session_id = "native-clone-id".to_string();
        let native_clone_info = session_info_from_clone_report(&source, &native_report);

        assert_eq!(native_clone_info.relation, source.relation);
    }

    #[test]
    fn clone_cancelled_before_session_creation_reports_no_cloned_session_removed() {
        let mut app = app_for_key_tests();
        app.data_task = Some(DataTaskPending::new(
            7,
            DataTaskKind::Clone,
            "cloning codex session + folder data".to_string(),
        ));
        let source = session_info(Provider::Codex, "source-id", "/repo");

        app.on_clone_worker_result(CloneWorkerResult {
            seq: 7,
            outcome: CloneWorkerOutcome::Cancelled {
                source,
                target: Provider::Claude,
                target_session_id: None,
                deleted_file: None,
                deleted_rows: 0,
                cleanup_error: None,
            },
        });

        assert!(app
            .status
            .contains("cancelled before cloned session was created"));
        assert!(!app.status.contains("cloned session removed"));
    }

