    #[test]
    fn error_status_opens_notice_dialog() {
        for status in [
            "search failed: disk read failed",
            "list error: permission denied",
            "cannot switch to live pi agent abc; event loop is not ready",
            "blocked: codex agent active at /repo",
            "pi agent is not installed.",
        ] {
            let backend = ratatui::backend::TestBackend::new(100, 24);
            let mut terminal = ratatui::Terminal::new(backend).unwrap();
            let mut app = app_for_key_tests();
            app.sessions
                .push(session_info(Provider::Codex, "error-notice", "/repo"));
            app.status = status.to_string();

            terminal.draw(|f| ui(f, &mut app)).unwrap();

            let rendered = buffer_text(terminal.backend().buffer());
            assert!(rendered.contains(status), "{rendered}");
            assert!(rendered.contains("[ OK ]"), "{rendered}");
            match &app.input_mode {
                InputMode::Notice { title, message } => {
                    assert_eq!(title, "Error");
                    assert_eq!(message, status);
                }
                other => panic!("expected error notice for {status}, got {other:?}"),
            }
        }
    }

    #[test]
    fn same_error_status_can_open_notice_again_after_dismiss() {
        let backend = ratatui::backend::TestBackend::new(100, 24);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        let mut app = app_for_key_tests();
        app.sessions
            .push(session_info(Provider::Codex, "repeat-error", "/repo"));
        app.status = "search failed: disk read failed".to_string();

        terminal.draw(|f| ui(f, &mut app)).unwrap();
        assert!(matches!(app.input_mode, InputMode::Notice { .. }));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::Normal));

        terminal.draw(|f| ui(f, &mut app)).unwrap();
        assert!(matches!(app.input_mode, InputMode::Normal));
        let rendered = buffer_text(terminal.backend().buffer());
        assert!(!rendered.contains("search failed: disk read failed"));
        assert!(!rendered.contains("[ OK ]"));

        app.status = "search failed: disk read failed".to_string();
        terminal.draw(|f| ui(f, &mut app)).unwrap();
        assert!(matches!(app.input_mode, InputMode::Notice { .. }));
        let rendered = buffer_text(terminal.backend().buffer());
        assert!(rendered.contains("search failed: disk read failed"));
        assert!(rendered.contains("[ OK ]"));
    }

    #[test]
    fn cokacdir_start_failure_keeps_notice_dialog_open() {
        let dir = tempfile::tempdir().unwrap();
        let cwd = dir.path().display().to_string();
        let missing_program = dir.path().join(cokacdir_local_filename());
        let mut app = app_for_key_tests();
        let (tx, rx) = mpsc::channel::<MainEvent>();
        app.main_tx = Some(tx);
        app.settings.cokacmux.cokacdir_program = Some(missing_program.display().to_string());
        app.input_mode = InputMode::NewSession {
            selected: NEW_SESSION_FIELD_KIND,
            kind: NewSessionKind::CokacDir,
            cwd: cwd.clone(),
            cwd_cursor: cwd.len(),
            cwd_completion: NewSessionPathCompletion::default(),
            provider: Provider::Codex,
            provider_options: vec![Provider::Codex],
            launch_mode: AgentLaunchMode::Normal,
        };

        let keybindings = app.keybindings.clone();
        handle_new_session_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            80,
            24,
            &keybindings,
        );

        // The cokacdir program check runs in the attach worker's prepare
        // stage; cwd normalization is prepared first, then the attach result
        // opens the failure dialog.
        assert!(matches!(app.input_mode, InputMode::Normal));
        assert!(app.new_session_launch.is_some());
        pump_new_session_prepare_result(&mut app, &rx);
        pump_attach_result(&mut app, &rx);

        match &app.input_mode {
            InputMode::Notice { title, message } => {
                assert_eq!(title, "cokacdir failed");
                assert!(message.contains("configured cokacdir_program"));
                assert!(message.contains(&missing_program.display().to_string()));
            }
            other => panic!("expected notice dialog, got {other:?}"),
        }
    }

    #[test]
    fn ctrl_f_cokacdir_panel_attach_runs_cokacdir_prechecks() {
        let dir = tempfile::tempdir().unwrap();
        let cwd = dir.path().display().to_string();
        let missing_program = dir.path().join(cokacdir_local_filename());
        let mut app = app_for_key_tests();
        app.show_sessions_view = false;
        app.settings.cokacmux.cokacdir_program = Some(missing_program.display().to_string());
        let active_info = session_info(Provider::Codex, "active-codex", &cwd);
        let active_key = AgentKey::new(&active_info);
        app.set_active_agent(inert_agent_client_for_tests(active_info, 1));
        app.attach_in_flight = Some(AttachInFlight {
            seq: 1,
            key: active_key.clone(),
            target: AttachTarget::MainAgent,
            started_at: Instant::now(),
        });

        handle_agent_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::CONTROL),
            160,
            30,
        );

        let queued = app
            .queued_attach
            .as_ref()
            .expect("Ctrl+F should queue cokacdir attach while another attach is in flight");
        assert!(
            queued.run_prechecks,
            "right cokacdir attach must run prepare/prechecks before spawn"
        );
        assert!(is_cokacdir_session_info(&queued.info));
        assert_eq!(
            queued.ctx.status_prepare_err_prefix,
            "right cokacdir prepare failed: "
        );
        match &queued.ctx.target {
            AttachTarget::Auxiliary { kind, parent } => {
                assert_eq!(*kind, AgentAuxKind::Cokacdir);
                assert_eq!(parent, &active_key);
            }
            other => panic!("expected cokacdir auxiliary attach, got {other:?}"),
        }
    }

    #[test]
    fn keybinding_file_change_reloads_via_watcher_check() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("keybinding.json");
        fs::write(
            &path,
            r#"{"sessions":{"launch_agent":["x"],"toggle_view":["z"]}}"#,
        )
        .unwrap();

        let mut app = app_for_key_tests();
        app.sessions
            .push(session_info(Provider::Codex, "codex-id", "/repo"));
        app.list_state.select(Some(0));

        let mut known_mtime = None;
        let reload = check_keybindings_reload(Some(&path), &mut known_mtime)
            .expect("changed file should produce a reload");
        app.on_keybindings_reloaded(reload);
        assert!(known_mtime.is_some());

        // The default binding no longer launches; the custom one does.
        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('e'), KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::Normal));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::AgentLaunch { .. }));

        // Unchanged file produces no further reloads.
        assert!(check_keybindings_reload(Some(&path), &mut known_mtime).is_none());
    }

    #[test]
    fn deleted_keybinding_file_is_recreated_by_watcher_check() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("keybinding.json");
        fs::write(&path, r#"{"sessions":{"launch_agent":["x"]}}"#).unwrap();
        let (keybindings, mut known_mtime) = KeyBindings::load_with_mtime(Some(&path));
        fs::remove_file(&path).unwrap();

        let mut app = app_for_key_tests();
        app.keybindings = keybindings;
        app.sessions
            .push(session_info(Provider::Codex, "codex-id", "/repo"));
        app.list_state.select(Some(0));

        let reload = check_keybindings_reload(Some(&path), &mut known_mtime)
            .expect("missing file should be recreated and reloaded");
        app.on_keybindings_reloaded(reload);

        assert!(path.exists());
        // Recreated defaults restore the default launch binding.
        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('e'), KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::AgentLaunch { .. }));
    }

    #[test]
    fn keybinding_reload_failure_keeps_previous_bindings() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("keybinding.json");
        fs::write(&path, r#"{"sessions":{"launch_agent":["x"]}}"#).unwrap();
        let (keybindings, _) = KeyBindings::load_with_mtime(Some(&path));

        fs::write(&path, "{ invalid json").unwrap();

        let mut app = app_for_key_tests();
        app.keybindings = keybindings;
        app.sessions
            .push(session_info(Provider::Codex, "codex-id", "/repo"));
        app.list_state.select(Some(0));

        let mut known_mtime = None;
        let reload = check_keybindings_reload(Some(&path), &mut known_mtime)
            .expect("invalid file should still produce a status-only reload");
        assert!(reload.keybindings.is_none());
        app.on_keybindings_reloaded(reload);

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE),
            100,
            80,
            20,
        );

        assert!(matches!(app.input_mode, InputMode::AgentLaunch { .. }));
    }

