    #[cfg(unix)]
    fn write_executable_test_script(dir: &Path, name: &str, body: &str) -> PathBuf {
        let path = dir.join(name);
        fs::write(&path, body).unwrap();
        let mut perms = fs::metadata(&path).unwrap().permissions();
        perms.set_mode(0o755);
        fs::set_permissions(&path, perms).unwrap();
        path
    }

    fn test_message(index: u32, role: cokacmux::Role, text: &str) -> cokacmux::UMessage {
        cokacmux::UMessage {
            id: format!("m{index}"),
            parent_id: None,
            index,
            timestamp: None,
            role,
            model: None,
            usage: None,
            stop_reason: None,
            content: vec![cokacmux::ContentBlock::text(text)],
            flags: cokacmux::MessageFlags::default(),
            provenance: cokacmux::Provenance {
                source_event_type: "test".into(),
                raw: serde_json::Value::Null,
            },
            extras: Default::default(),
        }
    }

    #[test]
    fn ctrl_f_opens_search_choice_without_live_filtering() {
        let mut app = app_for_key_tests();
        app.text_filter = "old".to_string();
        app.sessions
            .push(session_info(Provider::Codex, "old-session", "/repo"));
        app.sessions
            .push(session_info(Provider::Codex, "new-session", "/repo"));
        app.list_state.select(Some(0));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::CONTROL),
            100,
            80,
            20,
        );

        match &app.input_mode {
            InputMode::SearchChoice { selected } => {
                assert_eq!(*selected, SEARCH_CHOICE_TEXT);
            }
            other => panic!("expected search choice mode, got {:?}", other),
        }

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            100,
            80,
            20,
        );

        match &app.input_mode {
            InputMode::Filter { draft, cursor } => {
                assert_eq!(draft, "old");
                assert_eq!(*cursor, "old".len());
            }
            other => panic!("expected filter mode, got {:?}", other),
        }

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE),
            100,
            80,
            20,
        );

        assert_eq!(app.text_filter, "old");
        match &app.input_mode {
            InputMode::Filter { draft, .. } => assert_eq!(draft, "oldx"),
            other => panic!("expected filter mode, got {:?}", other),
        }
    }

