    #[test]
    fn search_result_applies_pending_query_and_closes_dialog() {
        let mut app = app_for_key_tests();
        let info = session_info(Provider::Codex, "sid", "/repo");
        app.sessions.push(info.clone());
        app.input_mode = InputMode::Filter {
            draft: "needle".to_string(),
            cursor: "needle".len(),
        };
        app.search_pending = Some(SearchPending {
            seq: 7,
            query: "needle".to_string(),
            started_at: Instant::now(),
            processed: 0,
            total: 0,
            hits: 0,
            load_errors: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        });

        app.on_search_result(SearchWorkerResult {
            seq: 7,
            query: "needle".to_string(),
            hits: Ok(vec![session::SearchHit {
                info: info.clone(),
                matches: 1,
                snippet: "needle".to_string(),
            }]),
            queued_at_epoch_ms: current_epoch_ms(),
        });

        assert!(matches!(app.input_mode, InputMode::Normal));
        assert!(app.search_pending.is_none());
        assert_eq!(app.text_filter, "needle");
        assert!(app.text_filter_matches.contains(&AgentKey::new(&info)));
    }

    #[test]
    fn search_progress_updates_matching_pending_search() {
        let mut app = app_for_key_tests();
        app.search_pending = Some(SearchPending {
            seq: 7,
            query: "needle".to_string(),
            started_at: Instant::now(),
            processed: 0,
            total: 8,
            hits: 0,
            load_errors: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        });

        app.on_search_progress(SearchProgressEvent {
            seq: 7,
            query: "needle".to_string(),
            processed: 3,
            total: 8,
            hits: 2,
            load_errors: 1,
            queued_at_epoch_ms: current_epoch_ms(),
        });

        let pending = app.search_pending.as_ref().unwrap();
        assert_eq!(pending.processed, 3);
        assert_eq!(pending.total, 8);
        assert_eq!(pending.hits, 2);
        assert_eq!(pending.load_errors, 1);

        app.on_search_progress(SearchProgressEvent {
            seq: 8,
            query: "needle".to_string(),
            processed: 8,
            total: 8,
            hits: 8,
            load_errors: 0,
            queued_at_epoch_ms: current_epoch_ms(),
        });

        let pending = app.search_pending.as_ref().unwrap();
        assert_eq!(pending.processed, 3);
        assert_eq!(pending.hits, 2);

        app.on_search_progress(SearchProgressEvent {
            seq: 7,
            query: "needle".to_string(),
            processed: 9,
            total: 9,
            hits: 9,
            load_errors: 0,
            queued_at_epoch_ms: current_epoch_ms(),
        });

        let pending = app.search_pending.as_ref().unwrap();
        assert_eq!(pending.total, 8);
        assert_eq!(pending.processed, 3);
        assert_eq!(pending.hits, 2);
    }

    #[test]
    fn esc_clears_text_search_results_to_full_list() {
        let mut app = app_for_key_tests();
        let first = session_info(Provider::Codex, "needle-session", "/repo/one");
        let second = session_info(Provider::Claude, "other-session", "/repo/two");
        app.sessions = vec![first.clone(), second.clone()].into();
        app.text_filter = "needle".to_string();
        app.text_filter_matches.insert(AgentKey::new(&first));
        app.focus = FocusPane::Preview;
        app.list_state.select(Some(0));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
            100,
            80,
            20,
        );

        assert!(!app.should_quit);
        assert!(app.text_filter.is_empty());
        assert!(app.text_filter_matches.is_empty());
        assert!(app.ai_search_results.is_none());
        assert_eq!(app.focus, FocusPane::Sessions);
        assert_eq!(app.visible().len(), 2);
        assert_eq!(app.list_state.selected(), Some(0));
        assert_eq!(app.status, "search cleared: 2 sessions");
    }

