    #[test]
    fn cwd_lock_publish_hides_file_until_json_is_complete() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("cwd-test.lock");
        let content = br#"{"version":1,"session_id":"complete"}"#.to_vec();
        let (ready_tx, ready_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let worker_path = path.clone();
        let worker_content = content.clone();
        let worker = thread::spawn(move || {
            publish_coding_agent_cwd_lock_with(&worker_path, &worker_content, || {
                ready_tx.send(()).unwrap();
                release_rx.recv().unwrap();
            })
        });

        ready_rx.recv_timeout(Duration::from_secs(1)).unwrap();
        assert!(
            !path.exists(),
            "the final lock path must not expose a partial JSON write"
        );
        release_tx.send(()).unwrap();
        worker.join().unwrap().unwrap();

        assert_eq!(fs::read(&path).unwrap(), [content, b"\n".to_vec()].concat());
    }

