    #[derive(Debug)]
    struct NeverExitingPtyChild {
        pid: u32,
        try_wait_calls: Arc<AtomicUsize>,
        kill_calls: Arc<AtomicUsize>,
        fail_initial_try_wait: bool,
    }

    #[derive(Debug)]
    struct NeverExitingPtyChildKiller {
        kill_calls: Arc<AtomicUsize>,
    }

    impl portable_pty::ChildKiller for NeverExitingPtyChildKiller {
        fn kill(&mut self) -> io::Result<()> {
            self.kill_calls.fetch_add(1, Ordering::Relaxed);
            Err(io::Error::new(
                ErrorKind::PermissionDenied,
                "simulated child kill failure",
            ))
        }

        fn clone_killer(&self) -> Box<dyn portable_pty::ChildKiller + Send + Sync> {
            Box::new(Self {
                kill_calls: Arc::clone(&self.kill_calls),
            })
        }
    }

    impl portable_pty::ChildKiller for NeverExitingPtyChild {
        fn kill(&mut self) -> io::Result<()> {
            self.kill_calls.fetch_add(1, Ordering::Relaxed);
            Err(io::Error::new(
                ErrorKind::PermissionDenied,
                "simulated child kill failure",
            ))
        }

        fn clone_killer(&self) -> Box<dyn portable_pty::ChildKiller + Send + Sync> {
            Box::new(NeverExitingPtyChildKiller {
                kill_calls: Arc::clone(&self.kill_calls),
            })
        }
    }

    impl Child for NeverExitingPtyChild {
        fn try_wait(&mut self) -> io::Result<Option<portable_pty::ExitStatus>> {
            let call = self.try_wait_calls.fetch_add(1, Ordering::Relaxed);
            if call == 0 && self.fail_initial_try_wait {
                return Err(io::Error::other("simulated initial try_wait failure"));
            }
            Ok(None)
        }

        fn wait(&mut self) -> io::Result<portable_pty::ExitStatus> {
            panic!("setup-failure cleanup must not call blocking Child::wait")
        }

        fn process_id(&self) -> Option<u32> {
            Some(self.pid)
        }
    }

    #[test]
    fn spawn_setup_failure_cleanup_is_bounded_when_all_termination_fails() {
        let try_wait_calls = Arc::new(AtomicUsize::new(0));
        let kill_calls = Arc::new(AtomicUsize::new(0));
        let mut child = NeverExitingPtyChild {
            pid: u32::MAX,
            try_wait_calls: Arc::clone(&try_wait_calls),
            kill_calls: Arc::clone(&kill_calls),
            fail_initial_try_wait: false,
        };
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "bounded-spawn-setup-cleanup".into(),
        };
        let expected_start_ticks = Some(987_654_321);
        let group_calls = Arc::new(AtomicUsize::new(0));
        let closure_group_calls = Arc::clone(&group_calls);
        let started = Instant::now();

        terminate_spawned_agent_child_on_setup_failure_with(
            &mut child,
            &key,
            "test_bounded_spawn_setup_cleanup",
            expected_start_ticks,
            Duration::from_millis(20),
            move |pid, token| {
                assert_eq!(pid, u32::MAX);
                assert_eq!(token, expected_start_ticks);
                closure_group_calls.fetch_add(1, Ordering::Relaxed);
                false
            },
        );

        assert!(started.elapsed() < Duration::from_secs(1));
        assert_eq!(group_calls.load(Ordering::Relaxed), 1);
        assert_eq!(kill_calls.load(Ordering::Relaxed), 1);
        assert!(try_wait_calls.load(Ordering::Relaxed) >= 3);
    }

    #[test]
    fn spawn_setup_failure_cleanup_skips_numeric_kill_when_identity_poll_fails() {
        let try_wait_calls = Arc::new(AtomicUsize::new(0));
        let kill_calls = Arc::new(AtomicUsize::new(0));
        let mut child = NeverExitingPtyChild {
            pid: u32::MAX,
            try_wait_calls: Arc::clone(&try_wait_calls),
            kill_calls: Arc::clone(&kill_calls),
            fail_initial_try_wait: true,
        };
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "identity-safe-spawn-setup-cleanup".into(),
        };
        let group_calls = Arc::new(AtomicUsize::new(0));
        let closure_group_calls = Arc::clone(&group_calls);

        terminate_spawned_agent_child_on_setup_failure_with(
            &mut child,
            &key,
            "test_identity_safe_spawn_setup_cleanup",
            Some(123),
            Duration::ZERO,
            move |_pid, _token| {
                closure_group_calls.fetch_add(1, Ordering::Relaxed);
                false
            },
        );

        assert_eq!(group_calls.load(Ordering::Relaxed), 0);
        assert_eq!(kill_calls.load(Ordering::Relaxed), 1);
        assert!(try_wait_calls.load(Ordering::Relaxed) >= 3);
    }

    #[cfg(unix)]
    #[test]
    fn std_child_bounded_wait_returns_without_waiting_for_process_exit() {
        let sleep = Path::new("/bin/sleep");
        if !sleep.is_file() {
            return;
        }
        let mut child = Command::new(sleep).arg("5").spawn().unwrap();
        let started = Instant::now();

        let status = wait_for_std_child_exit_bounded(&mut child, Duration::from_millis(20))
            .expect("bounded wait should poll successfully");

        assert!(status.is_none());
        assert!(started.elapsed() < Duration::from_secs(1));
        let _ = child.kill();
        let _ = child.wait();
    }

    #[cfg(unix)]
    #[test]
    fn spawn_setup_failure_cleanup_terminates_started_pty_child() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let pty_system = NativePtySystem::default();
        let pair = pty_system
            .openpty(PtySize {
                rows: 24,
                cols: 80,
                pixel_width: 0,
                pixel_height: 0,
            })
            .unwrap();
        let mut command = CommandBuilder::new(shell);
        command.args(["-c", "trap '' TERM; while :; do sleep 1; done"]);
        let mut child = pair.slave.spawn_command(command).unwrap();
        let child_pid = child.process_id().expect("pty child should have pid");
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "spawn-setup-cleanup".into(),
        };

        terminate_spawned_agent_child_on_setup_failure(
            child.as_mut(),
            &key,
            "test_spawn_setup_cleanup",
            process_start_ticks(child_pid),
        );

        assert!(
            !process_is_alive(child_pid),
            "spawn setup failure cleanup left the PTY child alive"
        );
    }

