    #[test]
    fn ctrl_n_opens_new_session_dialog_from_selected_session() {
        let mut app = app_for_key_tests();
        app.sessions
            .push(session_info(Provider::OpenCode, "opencode-id", "/repo"));
        app.list_state.select(Some(0));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('n'), KeyModifiers::CONTROL),
            100,
            80,
            20,
        );

        match &app.input_mode {
            InputMode::NewSession {
                selected,
                kind,
                cwd,
                cwd_cursor,
                cwd_completion,
                provider,
                provider_options,
                launch_mode,
            } => {
                assert_eq!(*selected, NEW_SESSION_FIELD_KIND);
                assert_eq!(*kind, NewSessionKind::Terminal);
                assert_eq!(cwd, "/repo");
                assert_eq!(*cwd_cursor, "/repo".len());
                assert!(!cwd_completion.visible);
                let expected_provider = if provider_options.is_empty()
                    || provider_options.contains(&Provider::OpenCode)
                {
                    Provider::OpenCode
                } else {
                    provider_options[0]
                };
                assert_eq!(*provider, expected_provider);
                assert_eq!(*launch_mode, AgentLaunchMode::Normal);
            }
            other => panic!("expected new session mode, got {:?}", other),
        }
    }

    #[test]
    fn new_session_enter_shows_prepare_spinner_before_attach_result() {
        let dir = tempfile::tempdir().unwrap();
        let cwd = dir.path().display().to_string();
        let mut app = app_for_key_tests();
        let (tx, _rx) = mpsc::channel::<MainEvent>();
        app.main_tx = Some(tx);
        app.input_mode = InputMode::NewSession {
            selected: NEW_SESSION_FIELD_KIND,
            kind: NewSessionKind::Terminal,
            cwd: cwd.clone(),
            cwd_cursor: cwd.len(),
            cwd_completion: NewSessionPathCompletion::default(),
            provider: Provider::Codex,
            provider_options: Vec::new(),
            launch_mode: AgentLaunchMode::Normal,
        };

        let keybindings = app.keybindings.clone();
        handle_new_session_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            80,
            24,
            &keybindings,
        );

        assert!(matches!(app.input_mode, InputMode::Normal));
        assert!(app.attach_in_flight.is_none());
        let pending = app
            .new_session_launch
            .as_ref()
            .expect("Enter should immediately show a new-session spinner");
        assert_eq!(pending.kind, NewSessionKind::Terminal);
        assert_eq!(pending.stage, NewSessionLaunchStage::Preparing);
        assert_eq!(pending.raw_cwd, cwd);
        assert!(app.display_status().contains("Preparing terminal"));
    }

