    #[test]
    fn restore_worker_blocks_if_same_cwd_lock_became_live() {
        let dir = tempfile::tempdir().unwrap();
        let canonical = dir.path().canonicalize().unwrap().display().to_string();
        let alias = dir.path().join(".").display().to_string();
        let snapshot_path = dir.path().join("snapshot-data");
        let live = session_info(Provider::Claude, "live-claude", &canonical);
        let target = session_info(Provider::Codex, "clone-codex", &alias);
        let _guard = acquire_coding_agent_cwd_restore_lock(&live)
            .unwrap()
            .expect("same-cwd restore lock should be acquired");
        let mut app = app_for_key_tests();
        let (tx, rx) = mpsc::channel::<MainEvent>();
        app.main_tx = Some(tx);
        app.input_mode = InputMode::RestoreDataConfirm {
            info: target,
            snapshot: session_data_snapshot(
                Provider::Codex,
                "clone-codex",
                "/source-project",
                snapshot_path.clone(),
            ),
            cols: 80,
            rows: 20,
            launch_mode: AgentLaunchMode::Normal,
            selected: RESTORE_DATA_OPTION_RESTORE,
        };

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('1'), KeyModifiers::NONE),
            100,
            80,
            20,
        );

        assert!(matches!(app.input_mode, InputMode::Normal));
        assert!(app.data_task.is_some());
        assert!(app.status.starts_with("restoring folder data for"));
        let result = loop {
            match rx.recv_timeout(Duration::from_secs(5)).unwrap() {
                MainEvent::RestoreResult(result) => break result,
                _ => continue,
            }
        };
        app.on_restore_worker_result(result);
        assert!(app.data_task.is_none());
        assert!(app.active_agent.is_none());
        assert!(app
            .status
            .starts_with("restore folder data for clone-codex failed:"));
        assert!(app.status.contains("already reserved") || app.status.contains("already uses"));
        assert!(!snapshot_path.exists());
    }

