    #[test]
    fn scope_toggle_hides_subagents_moves_to_parent_and_cancels_searches() {
        let mut app = app_for_key_tests();
        app.session_view = SessionViewMode::List;
        app.session_scope = SessionScope::All;
        let root = session_info(Provider::Codex, "root", "/repo");
        let mut child = session_info(Provider::Codex, "child", "/repo");
        child.relation = Some(SessionRelation::SpawnedAgent {
            parent_session_id: root.session_id.clone(),
            depth: Some(1),
        });
        app.sessions = vec![root.clone(), child.clone()].into();
        app.text_filter = "repo".to_string();
        app.text_filter_matches.insert(AgentKey::new(&child));
        let text_cancel = Arc::new(AtomicBool::new(false));
        app.search_pending = Some(SearchPending {
            seq: 1,
            query: "repo".to_string(),
            started_at: Instant::now(),
            processed: 0,
            total: 2,
            hits: 0,
            load_errors: 0,
            cancel: text_cancel.clone(),
        });
        let ai_cancel = Arc::new(AtomicBool::new(false));
        app.ai_search_pending = Some(ai_search_pending_for_test(ai_cancel.clone()));
        app.ai_search_results = Some(AiSearchResults {
            query: "repo".to_string(),
            hits: vec![
                AiSearchHit {
                    key: AgentKey::new(&root),
                    score: 0.8,
                    reason: "root".to_string(),
                },
                AiSearchHit {
                    key: AgentKey::new(&child),
                    score: 0.9,
                    reason: "child".to_string(),
                },
            ],
        });
        app.list_state.select(Some(1));

        app.toggle_session_scope();

        assert_eq!(app.session_scope, SessionScope::TopLevel);
        assert_eq!(
            app.current().map(|info| info.session_id.as_str()),
            Some("root")
        );
        assert!(app.text_filter.is_empty());
        assert!(app.text_filter_matches.is_empty());
        assert!(app.search_pending.is_none());
        assert!(app.ai_search_pending.is_none());
        assert_eq!(app.ai_search_draining_seq, Some(7));
        assert!(app.ai_search_results.is_none());
        assert!(text_cancel.load(Ordering::Relaxed));
        assert!(ai_cancel.load(Ordering::Relaxed));
        assert_eq!(app.hidden_non_root_session_count(), 1);

        app.start_ai_search("new query".to_string());
        assert!(app.ai_search_pending.is_none());
        assert!(app.status.contains("still cancelling"));

        app.on_ai_search_worker_result(AiSearchWorkerResult {
            seq: 7,
            query: "release".to_string(),
            provider: Provider::Codex,
            outcome: Err(AI_SEARCH_CANCELLED_ERROR.to_string()),
            elapsed_ms: 1,
            queued_at_epoch_ms: current_epoch_ms(),
        });
        assert!(app.ai_search_draining_seq.is_none());
        assert!(app.ai_search_pending.is_none());
        assert!(app.ai_search_results.is_none());
    }

