        assert!(binary_version_output_identifies(
            "cokacdir 1.2.3",
            "cokacdir"
        ));
        assert!(binary_version_output_identifies(
            "  cokacdir\t1.2.3",
            "cokacdir"
        ));
        assert!(binary_version_output_identifies("cokacdir", "cokacdir"));
        assert!(!binary_version_output_identifies(
            "cokacdirx 1.2.3",
            "cokacdir"
        ));
