    #[cfg(unix)]
    #[test]
    fn runtime_discovery_finds_exact_orphan_without_previous_cache() {
        let mut child = match Command::new("sleep")
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => return,
        };
        let child_pid = child.id();
        let Some(child_start_token) = process_start_ticks(child_pid) else {
            let _ = child.kill();
            let _ = child.wait();
            return;
        };
        let dir = tempfile::tempdir().unwrap();
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "exact-orphan".into(),
        };
        let stem = agent_file_stem(&key);
        let meta_path = dir.path().join(format!("{stem}.json"));
        let socket_path = agent_runtime_stem_endpoint_path(dir.path(), &stem);
        fs::write(
            &meta_path,
            serde_json::json!({
                "pid": 3_000_000_000_u32,
                "child_pid": child_pid,
                "child_pid_start_ticks": child_start_token,
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "cwd": "/repo",
                "source": "/tmp/rollout.jsonl",
                "updated_at_epoch_s": current_epoch_s(),
            })
            .to_string(),
        )
        .unwrap();

        let scan = discover_live_shell_scan_at(dir.path());
        let state = read_agent_runtime_state_at_for_key(
            Some(&key),
            &meta_path,
            &socket_path,
            std::process::id(),
        );
        let _ = child.kill();
        let _ = child.wait();

        assert!(scan.complete);
        assert_eq!(scan.live_shells.len(), 1);
        assert_eq!(AgentKey::new(&scan.live_shells[0]), key);
        assert_eq!(state, AgentListState::Orphaned { child_pid });
    }

