    #[test]
    fn daemon_ready_tcp_listener_reads_delayed_ready_line() {
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "ready-session".into(),
        };
        let listener = bind_agent_daemon_ready_listener().unwrap();
        let addr = listener.local_addr().unwrap();
        let writer_key = key.clone();
        let writer = thread::spawn(move || {
            let stream = std::net::TcpStream::connect(addr).unwrap();
            thread::sleep(Duration::from_millis(50));
            notify_agent_daemon_ready_to_writer(stream, &writer_key, Path::new("/tmp/ready.sock"))
                .unwrap();
        });

        let started = Instant::now();
        let stream = loop {
            match listener.accept() {
                Ok((stream, _addr)) => break stream,
                Err(e) if e.kind() == ErrorKind::WouldBlock => {
                    assert!(
                        started.elapsed() < Duration::from_secs(1),
                        "listener did not accept readiness connection"
                    );
                    thread::sleep(Duration::from_millis(10));
                }
                Err(e) => panic!("listener accept failed: {e}"),
            }
        };
        prepare_agent_daemon_ready_stream(&stream, Duration::from_secs(1)).unwrap();

        let ready = read_agent_daemon_ready(stream, &key).unwrap();
        writer.join().unwrap();

        assert_eq!(ready.provider, Provider::Codex);
        assert_eq!(ready.session_id, "ready-session");
        assert_eq!(ready.socket, "/tmp/ready.sock");
    }

    #[test]
    fn runtime_refresh_without_discovery_preserves_cached_live_shell() {
        let live = new_agent_info(Provider::Codex, "/repo");
        let key = AgentKey::new(&live);
        let mut previous_states = HashMap::new();
        previous_states.insert(
            key.clone(),
            AgentListState::Live {
                activity: AgentActivity::Quiet,
            },
        );

        let result = compute_agent_runtime_refresh(AgentRuntimeRefreshRequest {
            seq: 1,
            current_pid: std::process::id(),
            discover_live_shells: false,
            previous_states,
            previous_live_shells: vec![live.clone()],
            active_info: None,
            show_sessions_view: false,
            provider_session_count: 0,
            session_keys: Vec::new(),
            new_agent_backing_aliases: HashMap::new(),
            new_agent_backing_probe_after: HashMap::new(),
        });

        assert_eq!(result.live_shells.len(), 1);
        assert_eq!(AgentKey::new(&result.live_shells[0]), key);
        // The shell entry itself is preserved on the no-discovery path, but
        // its cached state is NOT restored: this synthetic agent has no meta
        // file, which is the definitive death signal (a self-exited agent
        // must leave the switchable list promptly instead of lingering as a
        // ghost until discovery strikes expire).
        assert_eq!(result.agent_states.get(&key).copied(), None);
    }

