    #[test]
    fn stalled_runtime_refresh_restarts_and_ignores_abandoned_result() {
        let mut app = app_for_key_tests();
        let cached = shell_session_info_for_cwd("/repo/watchdog-runtime".into());
        let cached_key = AgentKey::new(&cached);
        let cached_state = AgentListState::Live {
            activity: AgentActivity::Busy,
        };
        app.live_shells = vec![cached.clone()];
        app.agent_states.insert(cached_key.clone(), cached_state);

        let (old_tx, _old_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        app.runtime_tx = Some(old_tx);
        app.runtime_refresh_seq = 41;
        app.runtime_refresh_pending = true;
        app.runtime_refresh_started_at = Some(Instant::now() - Duration::from_millis(30_000));
        assert!(
            app.expire_stalled_runtime_refresh(Duration::from_millis(
                BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS,
            ))
            .is_none(),
            "an ordinary 30-second low-spec stall must not spawn duplicate work"
        );
        app.runtime_refresh_started_at = Some(
            Instant::now() - Duration::from_millis(BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS + 1),
        );
        app.runtime_refresh_pending_discover_live_shells = false;
        app.runtime_refresh_queued = true;
        app.runtime_refresh_queued_discover_live_shells = true;

        let retry_discovery = app
            .expire_stalled_runtime_refresh(Duration::from_millis(
                BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS,
            ))
            .expect("stalled runtime refresh should expire");
        assert!(
            retry_discovery,
            "queued discovery intent must survive expiry"
        );
        assert!(!app.runtime_refresh_pending);
        assert!(app.runtime_tx.is_none());
        assert_eq!(app.live_shells.len(), 1);
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));

        let (main_tx, _main_rx) = mpsc::channel::<MainEvent>();
        let (replacement_tx, replacement_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        app.main_tx = Some(main_tx);
        assert!(app.try_restart_agent_runtime_worker_with(|_| Ok(replacement_tx)));
        app.refresh_agent_runtime_states_with_discovery(retry_discovery);

        let retry = replacement_rx
            .try_recv()
            .expect("replacement worker should receive a fresh request");
        assert_eq!(retry.seq, 42);
        assert!(retry.discover_live_shells);
        assert!(app.runtime_refresh_pending);

        app.on_runtime_state_result(AgentRuntimeRefreshResult {
            seq: 41,
            discover_live_shells: false,
            live_shells: Vec::new(),
            agent_states: HashMap::new(),
            new_agent_backing_aliases: HashMap::new(),
            new_agent_backing_probe_after: HashMap::new(),
        });
        assert!(
            app.runtime_refresh_pending,
            "late result from abandoned worker must not clear the retry"
        );
        assert_eq!(app.live_shells.len(), 1);
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));

        app.on_runtime_state_result(AgentRuntimeRefreshResult {
            seq: retry.seq,
            discover_live_shells: true,
            live_shells: vec![cached],
            agent_states: HashMap::from([(cached_key.clone(), cached_state)]),
            new_agent_backing_aliases: HashMap::new(),
            new_agent_backing_probe_after: HashMap::new(),
        });
        assert!(!app.runtime_refresh_pending);
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));
    }

    #[test]
    fn disconnected_runtime_worker_allows_a_later_refresh_attempt() {
        let mut app = app_for_key_tests();
        let cached = shell_session_info_for_cwd("/repo/worker-disconnected".into());
        let cached_key = AgentKey::new(&cached);
        let cached_state = AgentListState::Live {
            activity: AgentActivity::Quiet,
        };
        app.live_shells = vec![cached];
        app.agent_states.insert(cached_key.clone(), cached_state);

        let (stopped_tx, stopped_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        drop(stopped_rx);
        app.runtime_tx = Some(stopped_tx);
        app.refresh_agent_runtime_states();

        assert!(!app.runtime_refresh_pending);
        assert!(app.runtime_tx.is_none());
        assert!(app.runtime_worker_restart_after.is_some());
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));

        let (main_tx, _main_rx) = mpsc::channel::<MainEvent>();
        let (replacement_tx, replacement_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        app.main_tx = Some(main_tx);
        assert!(app.try_restart_agent_runtime_worker_with(|_| Ok(replacement_tx)));
        app.refresh_agent_runtime_states();

        let retry = replacement_rx
            .try_recv()
            .expect("a later refresh should reach the replacement worker");
        assert_eq!(retry.seq, 2);
        assert!(app.runtime_refresh_pending);
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));
    }

    #[test]
    fn runtime_watchdog_bounds_replacements_until_late_result_reclaims_capacity() {
        let mut app = app_for_key_tests();
        let cached = shell_session_info_for_cwd("/repo/runtime-capacity".into());
        let cached_key = AgentKey::new(&cached);
        let cached_state = AgentListState::Live {
            activity: AgentActivity::Busy,
        };
        app.live_shells = vec![cached.clone()];
        app.agent_states.insert(cached_key.clone(), cached_state);
        let (main_tx, _main_rx) = mpsc::channel::<MainEvent>();
        app.main_tx = Some(main_tx);

        let (first_tx, _first_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        app.runtime_tx = Some(first_tx);
        app.runtime_refresh_seq = 1;
        app.runtime_refresh_pending = true;
        app.runtime_refresh_started_at = Some(
            Instant::now() - Duration::from_millis(BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS + 1),
        );
        let retry_discovery = app
            .expire_stalled_runtime_refresh(Duration::from_millis(
                BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS,
            ))
            .unwrap();
        assert_eq!(app.runtime_abandoned_worker_seqs, HashSet::from([1]));

        let (second_tx, second_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        assert!(app.try_restart_agent_runtime_worker_with(|_| Ok(second_tx)));
        app.refresh_agent_runtime_states_with_discovery(retry_discovery);
        let second = second_rx.try_recv().unwrap();
        assert_eq!(second.seq, 2);

        app.runtime_refresh_started_at = Some(
            Instant::now() - Duration::from_millis(BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS + 1),
        );
        app.expire_stalled_runtime_refresh(Duration::from_millis(
            BACKGROUND_REFRESH_WATCHDOG_TIMEOUT_MS,
        ))
        .unwrap();
        assert_eq!(
            app.runtime_abandoned_worker_seqs.len(),
            BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND
        );

        let spawn_called = std::cell::Cell::new(false);
        let (unexpected_tx, _unexpected_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        assert!(!app.try_restart_agent_runtime_worker_with(|_| {
            spawn_called.set(true);
            Ok(unexpected_tx)
        }));
        assert!(
            !spawn_called.get(),
            "capacity exhaustion must prevent creation of a third worker"
        );
        assert!(!app.runtime_refresh_pending);
        assert_eq!(app.live_shells.len(), 1);
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));

        app.on_runtime_state_result(AgentRuntimeRefreshResult {
            seq: 1,
            discover_live_shells: false,
            live_shells: Vec::new(),
            agent_states: HashMap::new(),
            new_agent_backing_aliases: HashMap::new(),
            new_agent_backing_probe_after: HashMap::new(),
        });
        assert_eq!(app.runtime_abandoned_worker_seqs, HashSet::from([2]));
        assert_eq!(app.live_shells.len(), 1);
        assert_eq!(app.agent_states.get(&cached_key), Some(&cached_state));

        let (third_tx, third_rx) = mpsc::channel::<AgentRuntimeRefreshRequest>();
        assert!(app.try_restart_agent_runtime_worker_with(|_| Ok(third_tx)));
        app.refresh_agent_runtime_states();
        let third = third_rx.try_recv().unwrap();
        assert_eq!(third.seq, 3);
        assert!(app.runtime_refresh_pending);
        assert_eq!(
            app.runtime_abandoned_worker_seqs.len() + usize::from(app.runtime_refresh_pending),
            BACKGROUND_REFRESH_MAX_OUTSTANDING_PER_KIND
        );
    }

