    #[cfg(unix)]
    #[test]
    fn reused_pid_agent_meta_preserves_matching_child() {
        let mut child = match Command::new("sleep")
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => return,
        };
        let child_pid = child.id();
        let dir = tempfile::tempdir().unwrap();
        let meta = dir.path().join("agent.json");
        let socket = dir.path().join("agent.sock");
        let scrollback = dir.path().join("scrollback");
        let pty_log = scrollback.join("agent.ptylog");
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "reused-pid-child-session".into(),
        };

        fs::write(
            &meta,
            serde_json::json!({
                "pid": std::process::id(),
                "child_pid": child_pid,
                "child_pid_start_ticks": process_start_ticks(child_pid),
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "updated_at_epoch_s": current_epoch_s(),
            })
            .to_string(),
        )
        .unwrap();
        fs::write(&socket, "").unwrap();
        fs::create_dir_all(&scrollback).unwrap();
        fs::write(&pty_log, b"OLD\n").unwrap();

        let state =
            read_agent_runtime_state_at_for_key(Some(&key), &meta, &socket, std::process::id());
        let meta_exists = meta.exists();
        let socket_exists = socket.exists();
        let pty_log_exists = pty_log.exists();
        let child_still_running = child.try_wait().unwrap().is_none();
        let _ = child.kill();
        let _ = child.wait();

        assert_eq!(state, AgentListState::Orphaned { child_pid });
        assert!(
            meta_exists,
            "runtime-state cleanup must preserve metadata for an exact live child"
        );
        assert!(
            socket_exists,
            "runtime-state cleanup must preserve the runtime socket marker for an exact live child"
        );
        assert!(
            pty_log_exists,
            "runtime-state cleanup must preserve the PTY log when it preserves an exact child"
        );
        assert!(
            child_still_running,
            "runtime-state cleanup must not terminate an exact child without an explicit kill"
        );
    }

    #[cfg(unix)]
    #[test]
    fn stale_agent_meta_lists_surviving_child_process_group_as_lost() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let descendant_ready_path = dir.path().join("descendant.ready");
        let leader_exit_path = dir.path().join("leader.exit");
        let mut command = Command::new(shell);
        command
            .args([
                "-c",
                r#"trap '' HUP; sh -c 'trap "" HUP TERM; while :; do sleep 1; done' & echo $! > "$DESCENDANT_READY_FILE"; while [ ! -e "$LEADER_EXIT_FILE" ]; do sleep 0.05; done"#,
            ])
            .env("DESCENDANT_READY_FILE", &descendant_ready_path)
            .env("LEADER_EXIT_FILE", &leader_exit_path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        unsafe {
            command.pre_exec(|| {
                if libc::setsid() == -1 {
                    Err(io::Error::last_os_error())
                } else {
                    Ok(())
                }
            });
        }
        let mut child = command.spawn().unwrap();
        let child_pid = child.id();
        let Some(child_start_ticks) = process_start_ticks(child_pid) else {
            let _ = unsafe { libc::kill(-(child_pid as i32), libc::SIGKILL) };
            let _ = child.wait();
            return;
        };
        let ready_deadline = Instant::now() + Duration::from_secs(2);
        while !descendant_ready_path.exists() && Instant::now() < ready_deadline {
            thread::sleep(Duration::from_millis(10));
        }
        if !descendant_ready_path.exists() {
            let _ = unsafe { libc::kill(-(child_pid as i32), libc::SIGKILL) };
            let _ = child.wait();
            panic!("descendant did not start");
        }
        fs::write(&leader_exit_path, b"exit").unwrap();
        assert_process_exits(&mut child, "session leader did not exit");
        assert!(
            agent_child_process_group_has_live_member(child_pid),
            "test descendant did not remain in the leader's process group"
        );

        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "surviving-child-group-session".into(),
        };
        let meta_path = dir.path().join(format!("{}.json", agent_file_stem(&key)));
        let socket_path = agent_runtime_stem_endpoint_path(dir.path(), &agent_file_stem(&key));
        fs::write(
            &meta_path,
            serde_json::json!({
                "pid": 3_000_000_000_u32,
                "child_pid": child_pid,
                "child_pid_start_ticks": child_start_ticks,
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "updated_at_epoch_s": current_epoch_s(),
            })
            .to_string(),
        )
        .unwrap();

        let discovered = discover_live_shell_infos_at_with_liveness(dir.path(), |_, _, _| None);
        let state = read_agent_runtime_state_at_for_key(
            Some(&key),
            &meta_path,
            &socket_path,
            std::process::id(),
        );
        let killall = kill_all_agent_daemons_at(dir.path(), std::process::id());
        let meta_preserved = meta_path.exists();
        let group_preserved = agent_child_process_group_has_live_member(child_pid);
        if !terminate_verified_unix_process_group_after_leader_exit(
            child_pid,
            "test_orphaned_group_cleanup",
        ) {
            let _ = unsafe { libc::kill(-(child_pid as i32), libc::SIGKILL) };
        }

        assert_eq!(
            state,
            AgentListState::OrphanedGroup {
                child_pgid: child_pid
            }
        );
        assert!(
            meta_preserved,
            "runtime metadata must remain while a recorded child group survives"
        );
        assert!(
            group_preserved && killall.skipped_unverified > 0,
            "stale metadata alone must not authorize signalling a surviving process group"
        );
        assert!(
            discovered.iter().any(|info| AgentKey::new(info) == key),
            "cold discovery must retain a session whose child process group survives"
        );
    }

    #[cfg(unix)]
    #[test]
    fn stale_agent_meta_with_wrong_child_start_token_is_not_orphaned() {
        let mut child = match Command::new("sleep")
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => return,
        };
        let child_pid = child.id();
        let Some(actual_start_token) = process_start_ticks(child_pid) else {
            let _ = child.kill();
            let _ = child.wait();
            return;
        };
        let dir = tempfile::tempdir().unwrap();
        let meta = dir.path().join("agent.json");
        let socket = dir.path().join("agent.sock");
        let key = AgentKey {
            provider: Provider::Codex,
            session_id: "wrong-child-token-session".into(),
        };
        fs::write(
            &meta,
            serde_json::json!({
                "pid": 3_000_000_000_u32,
                "child_pid": child_pid,
                "child_pid_start_ticks": actual_start_token.wrapping_add(1),
                "provider": key.provider.as_str(),
                "session_id": &key.session_id,
                "updated_at_epoch_s": current_epoch_s(),
            })
            .to_string(),
        )
        .unwrap();

        let state =
            read_agent_runtime_state_at_for_key(Some(&key), &meta, &socket, std::process::id());
        let meta_exists = meta.exists();
        let child_still_running = child.try_wait().unwrap().is_none();
        let _ = child.kill();
        let _ = child.wait();

        assert_eq!(state, AgentListState::Idle);
        assert!(
            !meta_exists,
            "a PID with a different start token must not preserve stale metadata"
        );
        assert!(
            child_still_running,
            "mismatched metadata must never terminate an unrelated PID"
        );
    }

