    #[cfg(windows)]
    #[test]
    fn windows_batch_agent_command_runs_script_path_with_spaces() {
        let dir = tempfile::tempdir().unwrap();
        let script_dir = dir.path().join("tools with spaces");
        fs::create_dir(&script_dir).unwrap();
        let shim = script_dir.join("codex.cmd");
        fs::write(&shim, "@echo off\r\necho OK %~1 %~2\r\n").unwrap();

        let argv = windows_agent_command_argv(shim, &["ARG ONE".into(), "ARG_TWO".into()]);
        let output = Command::new(&argv[0]).args(&argv[1..]).output().unwrap();

        assert!(
            output.status.success(),
            "batch command failed: stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(String::from_utf8_lossy(&output.stdout).contains("OK ARG ONE ARG_TWO"));
    }

    #[cfg(windows)]
    #[test]
    fn windows_npm_cmd_shim_runs_node_script_directly() {
        let dir = tempfile::tempdir().unwrap();
        let script = dir
            .path()
            .join("node_modules")
            .join("@openai")
            .join("codex")
            .join("bin")
            .join("codex.js");
        fs::create_dir_all(script.parent().unwrap()).unwrap();
        fs::write(&script, "console.log('codex')\n").unwrap();
        let node = dir.path().join("node.exe");
        fs::write(&node, "").unwrap();
        let shim = dir.path().join("codex.cmd");
        fs::write(
            &shim,
            r#"@ECHO off
IF EXIST "%~dp0\node.exe" (
  SET "_prog=%~dp0\node.exe"
) ELSE (
  SET "_prog=node"
)
"%_prog%" "%~dp0\node_modules\@openai\codex\bin\codex.js" %*
"#,
        )
        .unwrap();

        let argv = windows_agent_command_argv(shim, &["resume".into(), "sid".into()]);

        assert_eq!(argv[0], node.into_os_string());
        assert_eq!(argv[1], script.into_os_string());
        assert_eq!(argv[2], OsString::from("resume"));
    }

