    #[test]
    fn ctrl_q_quits_from_session_input_modes() {
        let ctrl_q = KeyEvent::new(KeyCode::Char('q'), KeyModifiers::CONTROL);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::Filter {
            draft: "query".to_string(),
            cursor: "query".len(),
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::CreateFolderConfirm {
            info: session_info(Provider::Codex, "codex-id", "/repo"),
            path: PathBuf::from("/repo"),
            cols: 80,
            rows: 20,
            launch_mode: AgentLaunchMode::Normal,
            selected: CREATE_FOLDER_OPTION_CANCEL,
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::RestoreDataConfirm {
            info: session_info(Provider::Codex, "codex-id", "/repo"),
            snapshot: session_data_snapshot(
                Provider::Codex,
                "codex-id",
                "/repo",
                PathBuf::from("/tmp/cokacmux-snapshot"),
            ),
            cols: 80,
            rows: 20,
            launch_mode: AgentLaunchMode::Normal,
            selected: RESTORE_DATA_OPTION_SKIP,
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::DeleteConfirm {
            info: session_info(Provider::Codex, "codex-id", "/repo"),
            removed_index: Some(0),
            selected: DELETE_OPTION_CANCEL,
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::KillAllConfirm {
            selected: KILLALL_OPTION_CANCEL,
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::AgentLaunch {
            selected: 0,
            source: session_info(Provider::Codex, "codex-id", "/repo"),
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::CloneOptions {
            source: session_info(Provider::Codex, "codex-id", "/repo"),
            target: Provider::Codex,
            target_options: clone_target_provider_options(),
            selected: CLONE_OPTION_SESSION_ONLY,
            folder_data: CloneFolderDataAvailability::Available(PathBuf::from("/repo")),
            context_mode: session::clone::CloneContextMode::Inline,
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);

        let mut app = app_for_key_tests();
        app.input_mode = InputMode::TitleEdit {
            source: session_info(Provider::Codex, "codex-id", "/repo"),
            draft: "Title".to_string(),
            cursor: "Title".len(),
        };
        handle_key(&mut app, ctrl_q, 80, 50, 20);
        assert!(app.should_quit);
    }

