    #[test]
    fn agent_scrollback_keys_accept_dedicated_navigation() {
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::Up, KeyModifiers::SHIFT)),
            Some(AgentScrollAction::Lines(1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::Down, KeyModifiers::SHIFT)),
            Some(AgentScrollAction::Lines(-1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(
                KeyCode::Up,
                KeyModifiers::SHIFT | KeyModifiers::ALT
            )),
            Some(AgentScrollAction::Pages(1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(
                KeyCode::Down,
                KeyModifiers::SHIFT | KeyModifiers::ALT
            )),
            Some(AgentScrollAction::Pages(-1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(
                KeyCode::PageUp,
                KeyModifiers::SHIFT | KeyModifiers::ALT
            )),
            Some(AgentScrollAction::Pages(1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(
                KeyCode::PageDown,
                KeyModifiers::SHIFT | KeyModifiers::ALT
            )),
            Some(AgentScrollAction::Pages(-1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::Home, KeyModifiers::ALT)),
            Some(AgentScrollAction::Top)
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::End, KeyModifiers::SHIFT)),
            Some(AgentScrollAction::Bottom)
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::PageUp, KeyModifiers::CONTROL)),
            None
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::PageUp, KeyModifiers::SHIFT)),
            None
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::PageUp, KeyModifiers::ALT)),
            Some(AgentScrollAction::Pages(1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(KeyCode::PageDown, KeyModifiers::ALT)),
            Some(AgentScrollAction::Pages(-1))
        );
        assert_eq!(
            is_agent_scrollback_key(KeyEvent::new(
                KeyCode::Up,
                KeyModifiers::CONTROL | KeyModifiers::SHIFT
            )),
            None
        );
    }

    #[test]
    fn codex_child_scroll_uses_child_keymap_without_ctrl_t_toggle() {
        let original = KeyEvent::new(KeyCode::Up, KeyModifiers::SHIFT | KeyModifiers::ALT);

        assert_eq!(
            codex_child_scroll_delegated_keys(AgentScrollAction::Pages(1), original, false),
            Some(vec![original, original])
        );
        assert_eq!(
            codex_child_scroll_delegated_keys(AgentScrollAction::Pages(1), original, true),
            Some(vec![original])
        );
        assert_eq!(
            codex_child_scroll_delegated_keys(AgentScrollAction::Lines(0), original, false),
            None
        );

        assert_eq!(
            codex_transcript_scroll_key(AgentScrollAction::Lines(1)).map(|key| key.code),
            Some(KeyCode::Up)
        );
        assert_eq!(
            codex_transcript_scroll_key(AgentScrollAction::Lines(-1)).map(|key| key.code),
            Some(KeyCode::Down)
        );
        assert_eq!(
            codex_transcript_scroll_key(AgentScrollAction::Pages(1)).map(|key| key.code),
            Some(KeyCode::PageUp)
        );
        assert_eq!(
            codex_transcript_scroll_key(AgentScrollAction::Pages(-1)).map(|key| key.code),
            Some(KeyCode::PageDown)
        );
        assert_eq!(
            codex_transcript_scroll_key(AgentScrollAction::Top).map(|key| key.code),
            Some(KeyCode::Home)
        );
        assert_eq!(
            codex_transcript_scroll_key(AgentScrollAction::Bottom).map(|key| key.code),
            Some(KeyCode::End)
        );
    }

