        assert!(app.agent_aux.is_none());
        assert_eq!(app.hidden_agent_aux.len(), 1);
        assert_eq!(app.hidden_agent_aux[0].kind, AgentAuxKind::Terminal);
        assert_eq!(app.hidden_agent_aux[0].parent, parent);
