    #[test]
    fn discovery_unknown_never_prunes_and_definitive_absence_does() {
        let mut app = app_for_key_tests();
        let ghost = session_info(Provider::Claude, "ghost-shell", "/repo");
        let ghost_key = AgentKey::new(&ghost);
        let quiet = AgentListState::Live {
            activity: AgentActivity::Quiet,
        };
        app.live_shells = vec![ghost.clone()];
        app.agent_states.insert(ghost_key.clone(), quiet);

        let empty_scan = |seq: u64, scan_complete: bool, uncertain_stems: HashSet<String>| {
            LiveShellDiscoveryResult {
                seq,
                baseline_keys: HashSet::from([ghost_key.clone()]),
                live_shells: Vec::new(),
                scan_complete,
                uncertain_stems,
                started_at_epoch_ms: current_epoch_ms(),
                queued_at_epoch_ms: current_epoch_ms(),
                elapsed_ms: 1,
            }
        };

        // No number of partial scan failures can become proof of death.
        for seq in 1..=8 {
            app.live_shell_discovery_seq = seq;
            app.live_shell_discovery_pending = true;
            app.on_live_shell_discovery_result(empty_scan(seq, false, HashSet::new()));
            assert_eq!(
                app.live_shells.len(),
                1,
                "unknown scan {} must preserve",
                seq
            );
        }

        // A complete directory scan is still inconclusive for a stem whose
        // runtime file existed but could not be parsed/identified.
        let uncertain_seq = 9;
        app.live_shell_discovery_seq = uncertain_seq;
        app.live_shell_discovery_pending = true;
        app.on_live_shell_discovery_result(empty_scan(
            uncertain_seq,
            true,
            HashSet::from([agent_file_stem(&ghost_key)]),
        ));
        assert_eq!(app.live_shells.len(), 1, "uncertain stem must preserve");

        // Only a complete scan with no runtime file or uncertain observation
        // for this key is definitive absence and may prune it.
        let prune_seq = 10;
        app.live_shell_discovery_seq = prune_seq;
        app.live_shell_discovery_pending = true;
        app.on_live_shell_discovery_result(empty_scan(prune_seq, true, HashSet::new()));
        assert!(
            app.live_shells.is_empty(),
            "definitively absent runtime survived a complete scan"
        );
        assert!(!app.agent_states.contains_key(&ghost_key));
    }

    fn large_output_with_tail_marker() -> Vec<u8> {
        let mut out = Vec::new();
        for line in 0..10_000 {
            out.extend_from_slice(format!("BUFFERED-LINE-{line:05}\r\n").as_bytes());
        }
        out.extend_from_slice(b"COKACMUX_TAIL_MARKER\r\n");
        out
    }

    fn active_agent_visible_text(app: &mut App) -> String {
        let agent = app.active_agent.as_mut().unwrap();
        parser_visible_plain_lines(&mut agent.parser, 0).join("\n")
    }

    fn active_agent_has_pending_output(app: &App) -> bool {
        app.active_agent
            .as_ref()
            .is_some_and(AgentClient::has_pending_output)
    }

    #[test]
    fn agent_output_buffer_byte_count_tracks_incremental_drain() {
        let output_buffer = Arc::new(Mutex::new(AgentOutputBuffer::default()));
        let (tx, _rx) = mpsc::channel::<MainEvent>();
        queue_agent_output(
            &output_buffer,
            &tx,
            1,
            AgentOutputKind::Output,
            vec![b'x'; 100],
        )
        .unwrap();
        assert_eq!(lock_agent_output_buffer(&output_buffer).queued_bytes, 100);

        let (first, has_more) = take_agent_output_chunk(&output_buffer, 40);
        assert_eq!(first.unwrap().data.len(), 40);
        assert!(has_more);
        assert_eq!(lock_agent_output_buffer(&output_buffer).queued_bytes, 60);

        let (last, has_more) = take_agent_output_chunk(&output_buffer, 100);
        assert_eq!(last.unwrap().data.len(), 60);
        assert!(!has_more);
        assert_eq!(lock_agent_output_buffer(&output_buffer).queued_bytes, 0);
    }

    fn drain_active_agent_output_until_idle(app: &mut App, reader_id: u64) {
        for _ in 0..100 {
            if !active_agent_has_pending_output(app) {
                return;
            }
            app.on_agent_output_available(reader_id);
        }
        panic!("active agent output did not drain within the iteration limit");
    }

    #[cfg(unix)]
    #[test]
    fn terminal_event_defers_large_pending_output_and_preserves_tail() {
        let reader_id = 19;
        let mut app = app_for_key_tests();
        app.active_agent = Some(buffered_output_test_client("large-output-exit", reader_id));

        let (tx, _rx) = mpsc::channel::<MainEvent>();
        let output_buffer = app.active_agent.as_ref().unwrap().output_buffer.clone();
        queue_agent_output(
            &output_buffer,
            &tx,
            reader_id,
            AgentOutputKind::Output,
            large_output_with_tail_marker(),
        )
        .unwrap();

        app.on_agent_output_available(reader_id);
        assert!(!active_agent_visible_text(&mut app).contains("COKACMUX_TAIL_MARKER"));

        app.on_agent_event(
            reader_id,
            AgentDaemonEvent::Exited {
                status: "done".into(),
            },
        );

        assert_eq!(
            app.active_agent.as_ref().unwrap().exited.as_deref(),
            Some("done")
        );
        assert!(active_agent_has_pending_output(&app));
        assert!(!active_agent_visible_text(&mut app).contains("COKACMUX_TAIL_MARKER"));

        drain_active_agent_output_until_idle(&mut app, reader_id);
        let text = active_agent_visible_text(&mut app);
        assert!(
            text.contains("COKACMUX_TAIL_MARKER"),
            "terminal output tail should survive incremental exit draining: {:?}",
            text
        );
        app.poll_agent_sessions();
        assert!(app.active_agent.is_none());
    }

