    #[test]
    fn attach_stream_waits_for_attached_acknowledgement() {
        let (client_stream, mut daemon_stream) = agent_stream_pair_for_tests().unwrap();
        let mut daemon_reader = BufReader::new(daemon_stream.try_clone().unwrap());
        let (main_tx, _main_rx) = mpsc::channel::<MainEvent>();
        let (result_tx, result_rx) = mpsc::channel();
        let info = session_info(Provider::Claude, "attach-ack", "/repo");

        let worker = thread::spawn(move || {
            let result = AgentClient::attach_stream(
                info,
                client_stream,
                80,
                12,
                main_tx,
                25,
                AgentLaunchMode::Normal,
            );
            let _ = result_tx.send(result);
        });

        let mut request_line = String::new();
        daemon_reader.read_line(&mut request_line).unwrap();
        let request: AgentDaemonRequest = serde_json::from_str(request_line.trim()).unwrap();
        assert!(matches!(request, AgentDaemonRequest::Attach { .. }));
        assert!(
            matches!(
                result_rx.recv_timeout(Duration::from_millis(75)),
                Err(mpsc::RecvTimeoutError::Timeout)
            ),
            "writing Attach bytes must not be reported as attach success"
        );

        write_json_line(
            &mut daemon_stream,
            &AgentDaemonEvent::Attached {
                provider: Provider::Claude,
                session_id: "attach-ack".into(),
                command: "acknowledged-command".into(),
                daemon_pid: 123,
                daemon_pid_start_ticks: Some(4567),
                child_pid: Some(456),
                snapshot_event: true,
                last_screen_change_epoch_ms: 10,
                last_output_epoch_ms: 11,
                last_input_epoch_ms: 12,
                bracketed_paste_mode: false,
                input_acknowledgements: true,
            },
        )
        .unwrap();

        let mut client = result_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("attach worker should finish after Attached")
            .expect("matching Attached acknowledgement should succeed");
        assert_eq!(client.command_line, "acknowledged-command");
        assert_eq!(client.last_output_epoch_ms, 11);
        client.exited = Some("test cleanup".into());
        drop(client);
        worker.join().unwrap();
    }

    #[test]
    fn attach_stream_acknowledgement_wait_is_bounded_and_non_destructive() {
        let (client_stream, daemon_stream) = agent_stream_pair_for_tests().unwrap();
        let mut daemon_reader = BufReader::new(daemon_stream.try_clone().unwrap());
        let (main_tx, _main_rx) = mpsc::channel::<MainEvent>();
        let (result_tx, result_rx) = mpsc::channel();
        let info = session_info(Provider::Claude, "attach-ack-timeout", "/repo");

        let worker = thread::spawn(move || {
            let result = AgentClient::attach_stream(
                info,
                client_stream,
                80,
                12,
                main_tx,
                26,
                AgentLaunchMode::Normal,
            );
            let _ = result_tx.send(result.map(|_| ()));
        });

        let mut request_line = String::new();
        daemon_reader.read_line(&mut request_line).unwrap();
        let request: AgentDaemonRequest = serde_json::from_str(request_line.trim()).unwrap();
        assert!(matches!(request, AgentDaemonRequest::Attach { .. }));

        let started = Instant::now();
        let result = result_rx
            .recv_timeout(Duration::from_millis(AGENT_ATTACH_ACK_TIMEOUT_MS + 1_000))
            .expect("attach acknowledgement wait must finish at its I/O bound");
        let error = result.expect_err("a daemon that never acknowledges must not attach");
        let io_error = error
            .downcast_ref::<io::Error>()
            .expect("attach timeout should retain its io error kind");
        assert_eq!(io_error.kind(), ErrorKind::TimedOut);
        assert!(started.elapsed() < Duration::from_millis(AGENT_ATTACH_ACK_TIMEOUT_MS + 1_000));

        // No process termination or runtime deletion is part of this path;
        // the peer is still an ordinary open stream until the test drops it.
        assert!(daemon_stream.peer_addr().is_ok());
        drop(daemon_stream);
        worker.join().unwrap();
    }

