    #[cfg(unix)]
    #[test]
    fn live_pty_output_round_trips_through_scrollback_log_and_snapshot() {
        let shell = PathBuf::from("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let session_id = format!("pty-e2e-{}", uuid::Uuid::now_v7());
        let mut info = session_info(
            Provider::Claude,
            &session_id,
            &dir.path().display().to_string(),
        );
        info.source = PathBuf::from(SHELL_SESSION_SOURCE_MARKER);

        let key = AgentKey::new(&info);
        let pty_log_path = agent_pty_log_path(&key).unwrap();
        let _ = remove_agent_pty_log(&key);
        let spec = AgentLaunchSpec {
            program: shell.display().to_string(),
            args: Vec::new(),
            env: Vec::new(),
            cwd: Some(dir.path().to_path_buf()),
        };

        let mut agent =
            AgentSession::spawn_with_spec(info.clone(), spec, 40, 6, AgentLaunchMode::Normal)
                .unwrap();
        agent.send_bytes(
            b"i=1; while [ \"$i\" -le 40 ]; do printf 'COKPTY%03d\\n' \"$i\"; i=$((i + 1)); done\n",
        )
        .unwrap();
        assert!(
            drain_agent_until(&mut agent, Duration::from_secs(5), |agent| {
                parser_snapshot_text(&mut agent.parser).contains("COKPTY040")
            }),
            "PTY child output did not reach the parser"
        );

        // Stopping the disk writer drains every queued append and closes
        // the log file, so the read below sees all output.
        agent.shutdown_disk_writer();
        let log_bytes = fs::read(&pty_log_path).unwrap();
        let log_text = String::from_utf8_lossy(&log_bytes);
        assert!(
            log_text.contains("COKPTY001"),
            "ptylog lost earliest output"
        );
        assert!(log_text.contains("COKPTY040"), "ptylog lost latest output");

        let snapshot_text = parser_snapshot_text(&mut agent.parser);
        assert!(
            snapshot_text.contains("COKPTY001") && snapshot_text.contains("COKPTY040"),
            "live parser snapshot did not preserve full scrollback: {:?}",
            snapshot_text
        );

        agent.parser.screen_mut().set_scrollback(usize::MAX);
        let top_offset = agent.parser.screen().scrollback();
        assert!(top_offset > 0, "PTY output should create scrollback");
        let top_lines = parser_visible_plain_lines(&mut agent.parser, top_offset);
        assert!(
            top_lines.iter().any(|line| line.contains("COKPTY001")),
            "scrolling to top did not reveal earliest output: {:?}",
            top_lines
        );
        agent.parser.screen_mut().set_scrollback(0);
        assert_eq!(agent.parser.screen().scrollback(), 0);

        agent.parser = vt100::Parser::new(
            agent.pty_size.rows,
            agent.pty_size.cols,
            AGENT_SCROLLBACK_LINES,
        );
        agent.screen_history = ScreenHistory::default();
        agent.screen_hash = screen_activity_hash(agent.parser.screen());
        agent.rehydrate_parser_from_pty_log();
        let replay_text = parser_snapshot_text(&mut agent.parser);
        assert!(
            replay_text.contains("COKPTY001") && replay_text.contains("COKPTY040"),
            "ptylog replay did not restore full scrollback: {:?}",
            replay_text
        );

        let snapshot = agent.screen_snapshot_bytes(true);
        let mut restored = vt100::Parser::new(
            agent.pty_size.rows,
            agent.pty_size.cols,
            AGENT_SCROLLBACK_LINES,
        );
        safe_parser_process(&mut restored, &snapshot);
        let restored_text = parser_snapshot_text(&mut restored);
        assert!(
            restored_text.contains("COKPTY001") && restored_text.contains("COKPTY040"),
            "snapshot event did not transfer full scrollback: {:?}",
            restored_text
        );

        agent.send_bytes(b"exit\n").unwrap();
        let _ = drain_agent_until(&mut agent, Duration::from_millis(500), |_| false);
        let _ = agent.child.kill();
        let _ = agent.child.wait();
        let reader_close_deadline = Instant::now() + Duration::from_secs(2);
        let mut output_reader_closed = false;
        while Instant::now() < reader_close_deadline {
            let drain = agent.drain_output_chunks();
            output_reader_closed |= drain.output_closed;
            if output_reader_closed {
                break;
            }
            thread::sleep(Duration::from_millis(10));
        }
        assert!(
            output_reader_closed,
            "PTY output reader did not report channel closure after child exit"
        );
        agent.shutdown_disk_writer();
        let _ = remove_agent_pty_log(&key);
    }

    #[cfg(unix)]
    #[test]
    fn pty_input_backpressure_preserves_accepted_fifo_without_blocking_daemon() {
        let sleep = PathBuf::from("/bin/sleep");
        if !sleep.is_file() {
            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let session_id = format!("pty-input-backpressure-{}", uuid::Uuid::now_v7());
        let mut info = session_info(
            Provider::Claude,
            &session_id,
            &dir.path().display().to_string(),
        );
        info.source = PathBuf::from(SHELL_SESSION_SOURCE_MARKER);
        let key = AgentKey::new(&info);
        let spec = AgentLaunchSpec {
            program: sleep.display().to_string(),
            args: vec!["30".to_string()],
            env: Vec::new(),
            cwd: Some(dir.path().to_path_buf()),
        };
        let mut agent =
            AgentSession::spawn_with_spec(info, spec, 40, 6, AgentLaunchMode::Normal).unwrap();
        let chunk = vec![b'x'; AGENT_INPUT_REQUEST_CHUNK_BYTES];
        let started = Instant::now();
        for _ in 0..(DAEMON_PTY_INPUT_QUEUE_MAX_JOBS + 4) {
            agent
                .send_bytes(&chunk)
                .expect("accepted input must be retained under PTY backpressure");
        }

        assert!(started.elapsed() < Duration::from_secs(1));
        assert!(
            agent.input_backpressured(),
            "a non-reading child should fill the worker queue and retain later input"
        );
        assert!(agent.pending_input_bytes > 0);
        let _ = agent.child.kill();
        let _ = agent.child.wait();
        let _ = agent.shutdown_input_writer();
        let _ = agent.shutdown_disk_writer();
        let _ = remove_agent_pty_log(&key);
    }

    #[cfg(unix)]
    #[test]
    fn daemon_does_not_acknowledge_sequenced_input_at_queue_admission() {
        let sleep = PathBuf::from("/bin/sleep");
        if !sleep.is_file() {
            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let session_id = format!("pty-input-ack-boundary-{}", uuid::Uuid::now_v7());
        let mut info = session_info(
            Provider::Claude,
            &session_id,
            &dir.path().display().to_string(),
        );
        info.source = PathBuf::from(SHELL_SESSION_SOURCE_MARKER);
        let key = AgentKey::new(&info);
        let spec = AgentLaunchSpec {
            program: sleep.display().to_string(),
            args: vec!["30".to_string()],
            env: Vec::new(),
            cwd: Some(dir.path().to_path_buf()),
        };
        let mut agent =
            AgentSession::spawn_with_spec(info, spec, 40, 6, AgentLaunchMode::Normal).unwrap();
        let meta_path = dir.path().join("ack-boundary.json");
        let (server, mut peer) = AgentStream::pair().unwrap();
        let mut conn = DaemonConnection::new(server).unwrap();
        let mut attached_pid = Some(123);
        let mut attached_instance = Some("ack-boundary-client".to_string());
        let mut accepted = AcceptedAgentInputSequences::default();

        let outcome = handle_daemon_client_request(
            AgentDaemonRequest::Input {
                data: b"queued-not-yet-acknowledged".to_vec(),
                input_seq: Some(91),
            },
            &mut conn,
            &mut agent,
            &meta_path,
            &mut attached_pid,
            &mut attached_instance,
            &mut accepted,
        );

        assert!(matches!(outcome, DaemonRequestOutcome::Continue));
        assert!(!accepted.already_accepted("ack-boundary-client", 91));
        let early_event =
            read_agent_daemon_event_with_timeout(&mut peer, Duration::from_millis(20));
        assert!(matches!(
            early_event,
            Err(error) if matches!(error.kind(), ErrorKind::TimedOut | ErrorKind::WouldBlock)
        ));

        let mut client = Some(conn);
        let completion_deadline = Instant::now() + Duration::from_secs(2);
        while !accepted.already_accepted("ack-boundary-client", 91) {
            apply_daemon_pty_input_completions(
                &mut agent,
                &mut client,
                &mut attached_pid,
                &mut attached_instance,
                &mut accepted,
                &meta_path,
            );
            if accepted.already_accepted("ack-boundary-client", 91) {
                break;
            }
            assert!(
                Instant::now() < completion_deadline,
                "PTY input writer did not report completion"
            );
            thread::sleep(Duration::from_millis(10));
        }
        let acknowledged =
            read_agent_daemon_event_with_timeout(&mut peer, Duration::from_secs(1)).unwrap();
        assert!(matches!(
            acknowledged,
            AgentDaemonEvent::InputAccepted { input_seq: 91 }
        ));

        let _ = agent.child.kill();
        let _ = agent.child.wait();
        let _ = agent.shutdown_input_writer();
        let _ = agent.shutdown_disk_writer();
        let _ = remove_agent_pty_log(&key);
    }

    #[test]
    fn pty_input_writer_reports_acknowledgeable_completion_after_successful_write() {
        let (job_tx, job_rx) = mpsc::channel();
        let (completion_tx, completion_rx) = mpsc::channel();
        let acknowledgement = DaemonPtyInputAcknowledgement {
            client_instance_id: "client-success".into(),
            input_seq: 41,
        };
        job_tx
            .send(DaemonPtyInputJob {
                bytes: b"written".to_vec(),
                acknowledgement: Some(acknowledgement.clone()),
            })
            .unwrap();
        drop(job_tx);
        let failed = Arc::new(AtomicBool::new(false));

        run_daemon_pty_input_writer(
            job_rx,
            completion_tx,
            Box::new(std::io::Cursor::new(Vec::<u8>::new())),
            Provider::Claude,
            "writer-success".into(),
            Arc::clone(&failed),
        );

        match completion_rx.try_recv().unwrap() {
            DaemonPtyInputCompletion::Written(completed) => {
                assert_eq!(completed, acknowledgement)
            }
            DaemonPtyInputCompletion::Failed(_) => panic!("successful write reported failure"),
        }
        assert!(!failed.load(Ordering::Acquire));
    }

    #[test]
    fn pty_input_writer_never_reports_failed_write_as_accepted() {
        struct RejectingWriter;

        impl Write for RejectingWriter {
            fn write(&mut self, _buf: &[u8]) -> io::Result<usize> {
                Err(io::Error::new(ErrorKind::BrokenPipe, "rejected"))
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let (job_tx, job_rx) = mpsc::channel();
        let (completion_tx, completion_rx) = mpsc::channel();
        let acknowledgement = DaemonPtyInputAcknowledgement {
            client_instance_id: "client-failure".into(),
            input_seq: 42,
        };
        job_tx
            .send(DaemonPtyInputJob {
                bytes: b"lost".to_vec(),
                acknowledgement: Some(acknowledgement.clone()),
            })
            .unwrap();
        drop(job_tx);
        let failed = Arc::new(AtomicBool::new(false));

        run_daemon_pty_input_writer(
            job_rx,
            completion_tx,
            Box::new(RejectingWriter),
            Provider::Claude,
            "writer-failure".into(),
            Arc::clone(&failed),
        );

        match completion_rx.try_recv().unwrap() {
            DaemonPtyInputCompletion::Failed(completed) => {
                assert_eq!(completed, acknowledgement)
            }
            DaemonPtyInputCompletion::Written(_) => panic!("failed write was reported accepted"),
        }
        assert!(failed.load(Ordering::Acquire));
    }

