        fs::write(&corrupt_pty, b"OLD\n").unwrap();
        fs::write(&corrupt_without_endpoint, b"not json either").unwrap();
        fs::write(&corrupt_without_endpoint_pty, b"KEEP\n").unwrap();
        fs::write(&orphan_socket, b"").unwrap();
        fs::write(&orphan_marker, b"tcp 127.0.0.1:1\n").unwrap();
        fs::write(&orphan_pty, b"OLD\n").unwrap();
        fs::write(&safe_temp, b"partial").unwrap();
        fs::write(dir.path().join("cwd-invalid.lock"), b"not json").unwrap();

        let report = cleanup_stale_agent_runtime_files_at(dir.path(), "test_idle_runtime_sweep");

